async def ready_handler(request):
    if extension_host.available("company"):
        from systems_cockpit import ready_handler as company_ready
        return await company_ready(request)
    payload = {"ok": True, "edition": extension_host.edition(), "version": VERSION}
    desktop_instance = os.environ.get("IVE_DESKTOP_INSTANCE")
    if desktop_instance:
        from resource_path import project_root
        payload["desktop_instance"] = desktop_instance
        try:
            payload["bundle"] = json.loads((project_root() / "bundle-info.json").read_text())
        except (OSError, ValueError):
            payload["bundle"] = {"version": VERSION, "frozen": False}
    return web.json_response(payload)

