ws_clients: set[web.WebSocketResponse] = set()


class QueuedWebSocket:
    def __init__(self, ws: web.WebSocketResponse):
        self.ws = ws
        self.queue = asyncio.Queue(maxsize=2000)
        self.task = asyncio.create_task(self._send_loop())
        self.orig_send_str = ws.send_str
        ws.send_str = self.send_str
        ws.send_json = self.send_json
        ws._queued_ws = self

    async def _send_loop(self):
        try:
            while True:
                data, args, kwargs = await self.queue.get()
                try:
                    if self.ws.closed:
                        break
                    await self.orig_send_str(data, *args, **kwargs)
                except (ConnectionResetError, ConnectionError, RuntimeError, asyncio.CancelledError) as e:
                    logger.debug(f"QueuedWebSocket write failed: {e}")
                    break
                except Exception as e:
                    logger.exception("QueuedWebSocket write error")
                    break
                finally:
                    self.queue.task_done()
        except asyncio.CancelledError:
            pass
        finally:
            ws_clients.discard(self.ws)
            if not self.ws.closed:
                try:
                    await self.ws.close()
                except Exception:
                    logger.debug("QueuedWebSocket close failed", exc_info=True)

    async def send_str(self, data: str, *args, **kwargs):
        try:
            self.queue.put_nowait((data, args, kwargs))
        except asyncio.QueueFull:
            logger.warning("WebSocket queue full (slow client), closing connection")
            self.task.cancel()
            ws_clients.discard(self.ws)
            if not self.ws.closed:
                await self.ws.close()

    async def send_json(self, data: dict, compress=None, *, dumps=json.dumps):
        # aiohttp's native send_json delegates to self.send_str. Calling the
        # saved method after monkey-patching send_str therefore queued JSON a
        # second time and let newer string frames overtake it. Serialize now
        # and put exactly one string frame on the shared FIFO.
        await self.send_str(dumps(data), compress=compress)

    def close_task(self):
        self.task.cancel()


# ─── Multiplayer presence ────────────────────────────────────────────────
# Maps client_id -> { ws, name, color, viewing_session }
ws_peers: dict[str, dict] = {}

# Tracks which Playwright preview ids each WS is subscribed to, so we can
# unsubscribe everything on disconnect (otherwise headless pages leak).
ws_preview_subs: dict[int, set[str]] = {}


def _ws_subscriber_id(ws) -> str:
    """Pick a stable subscriber id for a ws — prefer the multiplayer
    client_id from `hello`, fall back to the ws object id."""
    for cid, info in ws_peers.items():
        if info.get("ws") is ws:
            return cid
    return f"ws-{id(ws)}"


def _request_remote_ip(request: web.Request) -> str | None:
    """Best-effort real client IP for owner-only multiplayer controls."""
    return _auth_context.client_ip(request, _proxy_trust_config())


def _utc_now_iso() -> str:
    return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"


def _runtime_peer_payload(client_id: str, info: dict) -> dict:
    ws = info.get("ws")
    actor_kind = getattr(ws, "_ive_actor_kind", None) if ws else None
    actor_label = getattr(ws, "_ive_actor_label", None) if ws else None
    return {
        "client_id": client_id,
        "name": info.get("name") or "Anonymous",
        "color": info.get("color") or "#6366f1",
        "viewing_session": info.get("viewing_session"),
        "actor_kind": actor_kind,
        "actor_id": getattr(ws, "_ive_actor_id", None) if ws else None,
        "mode": getattr(ws, "_ive_mode", None) if ws else None,
        "label": actor_label or ("Owner" if actor_kind in ("localhost", "owner_legacy", "owner_device") else None),
        "expires_at": getattr(ws, "_ive_expires_at", None) if ws else None,
        "is_owner": bool(getattr(ws, "_ive_is_owner", False)) if ws else False,
        "remote_ip": getattr(ws, "_ive_remote_ip", None) if ws else None,
        "user_agent": getattr(ws, "_ive_user_agent", None) if ws else None,
        "connected_at": getattr(ws, "_ive_connected_at", None) if ws else None,
    }


