from pathlib import Path as _Path


def _get_project_dir(workspace_path: str) -> _Path:
    """Get the Claude Code project directory for a workspace path."""
    return _get_project_dir_for_home(workspace_path, managed_home("claude"))


def _get_project_dir_for_home(workspace_path: str, home: _Path) -> _Path:
    """Get the Claude Code project directory for a workspace path under a HOME.

    Always the name Claude writes today (every non-alphanumeric char -> '-'),
    so mirrors for --resume land where Claude looks.
    """
    return cli_data_dir("claude", home) / "projects" / claude_project_dirname(workspace_path)


def _account_cli_data_dirs(cli_type: str) -> list[_Path]:
    """CLI data dirs inside every IVE account HOME (e.g. account_homes/<id>/.codex).

    Transcripts written under one account must stay findable after the
    session switches account or runs without one, so all account homes are
    searched after the active and default homes.
    """
    dirs: list[_Path] = []
    try:
        homes = sorted(p for p in ACCOUNT_HOMES_DIR.iterdir() if p.is_dir())
    except OSError:
        return dirs
    for home in homes:
        data_dir = cli_data_dir(cli_type, home)
        if data_dir.is_dir():
            dirs.append(data_dir)
    return dirs


def _get_project_dirs(workspace_path: str, cli_home: str | _Path | None = None) -> list[_Path]:
    """Every Claude project dir that may hold this workspace's transcripts.

    Active HOME first, then host/default homes, then all account homes; per
    data dir Claude's real folder name first, legacy IVE encoding last.
    """
    names = claude_project_dirnames(workspace_path)
    # --worktree writes under its actual cwd, not the parent repository's
    # project directory. Limit discovery to this repo's encoded worktree root;
    # existing history remains readable even after a worktree is removed.
    from glob import escape as _glob_escape
    worktree_prefixes = claude_project_dirnames(str(_Path(workspace_path) / ".claude" / "worktrees"))
    data_dirs: list[_Path] = []
    if cli_home:
        data_dirs.append(cli_data_dir("claude", _Path(cli_home).expanduser()))
    data_dirs.extend(candidate_data_dirs("claude"))
    data_dirs.extend(_account_cli_data_dirs("claude"))

    seen: set[str] = set()
    project_dirs: list[_Path] = []
    for data_dir in data_dirs:
        projects = data_dir / "projects"
        candidates = [projects / name for name in names]
        for prefix in worktree_prefixes:
            candidates.extend(sorted(projects.glob(_glob_escape(prefix + "-") + "*")))
        for candidate in candidates:
            key = str(candidate)
            if key in seen:
                continue
            seen.add(key)
            project_dirs.append(candidate)
        # Over-long paths: Claude truncates + hashes; also accept any
        # truncated dir whose transcripts record this workspace as cwd.
        for candidate in claude_long_project_dirs(data_dir / "projects", workspace_path):
            key = str(candidate)
            if key not in seen:
                seen.add(key)
                project_dirs.append(candidate)
    return project_dirs


def _resume_file_rank(path: _Path) -> tuple[int, int]:
    try:
        stat = path.stat()
        return stat.st_mtime_ns, stat.st_size
    except OSError:
        return 0, 0


def _copy_if_fresher(src: _Path, dst: _Path) -> bool:
    """Copy a missing resume artifact or refresh a stale file mirror."""
    if not src.exists():
        return False
    try:
        dst.parent.mkdir(parents=True, exist_ok=True)
        if src.is_dir():
            if dst.exists():
                return False
            shutil.copytree(src, dst, symlinks=True)
        elif src.is_file():
            if dst.exists():
                try:
                    if src.samefile(dst):
                        return False
                except OSError:
                    pass
                if _resume_file_rank(src) <= _resume_file_rank(dst):
                    return False
            shutil.copy2(src, dst)
        else:
            return False
        return True
    except OSError as exc:
        logger.debug("Failed to mirror resume artifact %s -> %s: %s", src, dst, exc)
        return False


def _ensure_claude_resume_files(native_sid: str, workspace_path: str, cli_home: str | None) -> bool:
    """Make a stored Claude transcript visible to the HOME used for this PTY.

    Older sessions may have been detected from the user's real ~/.claude while
    current PTYs run with an IVE-managed HOME. Claude's --resume only searches
    the active config/home, so mirror the exact transcript lazily at restart.
    """
    if not native_sid or not workspace_path or not cli_home:
        return False

    active_home = _Path(cli_home).expanduser()
    active_data_dir = cli_data_dir("claude", active_home)
    target_project_file = (
        _get_project_dir_for_home(workspace_path, active_home) / f"{native_sid}.jsonl"
    )

    project_dirs: list[_Path] = [_get_project_dir_for_home(workspace_path, active_home)]
    project_dirs.extend(_get_project_dirs(workspace_path, active_home))
    seen: set[str] = set()
    candidates: list[_Path] = []
    for project_dir in project_dirs:
        key = str(project_dir)
        if key in seen:
            continue
        seen.add(key)
        candidate = project_dir / f"{native_sid}.jsonl"
        if candidate.is_file():
            candidates.append(candidate)
    if candidates:
        freshest = max(candidates, key=_resume_file_rank)
        if freshest != target_project_file and _copy_if_fresher(freshest, target_project_file):
            logger.info(
                "Refreshed Claude resume transcript %s in active HOME for session restart",
                native_sid,
            )

    # Claude also records session environment by native id. Missing this does
    # not always block resume, but mirroring it preserves the old cwd/env hints.
    target_env_file = active_data_dir / "session-env" / native_sid
    if not target_env_file.exists():
        data_dirs: list[_Path] = [active_data_dir]
        data_dirs.extend(candidate_data_dirs("claude"))
        data_dirs.extend(_account_cli_data_dirs("claude"))
        seen_dirs: set[str] = set()
        for data_dir in data_dirs:
            key = str(data_dir)
            if key in seen_dirs:
                continue
            seen_dirs.add(key)
            candidate = data_dir / "session-env" / native_sid
            if candidate == target_env_file:
                continue
            if _copy_if_fresher(candidate, target_env_file):
                break

    return target_project_file.exists()


def _ensure_codex_resume_files(native_sid: str, cli_home: str | None,
                               codex_home: str | None = None) -> bool:
    """Make a Codex rollout visible to the CODEX_HOME used for this PTY."""
    if not native_sid:
        return False

    if codex_home:
        active_data_dir = _Path(codex_home).expanduser()
    elif cli_home:
        active_data_dir = cli_data_dir("codex", _Path(cli_home).expanduser())
    else:
        return False

    source_file = _find_codex_session_file(native_sid)
    if not source_file or not source_file.exists():
        return False

    active_sessions_dir = active_data_dir / "sessions"
    target_file = active_sessions_dir / source_file.name
    for sessions_dir in _get_codex_sessions_dirs():
        try:
            rel = source_file.relative_to(sessions_dir)
            target_file = active_sessions_dir / rel
            break
        except ValueError:
            continue

    if source_file == target_file:
        return True

    copied = _copy_if_fresher(source_file, target_file)
    if copied:
        logger.info(
            "Refreshed Codex resume transcript %s in active CODEX_HOME",
            native_sid,
        )
    return target_file.exists()


def _ensure_antigravity_resume_files(native_sid: str, workspace_path: str,
                                     cli_home: str | None) -> bool:
    """Make an Antigravity conversation brain visible to the active HOME."""
    if not native_sid or not cli_home:
        return False

    active_data_dir = cli_data_dir("antigravity", _Path(cli_home).expanduser())
    target_brain_dir = active_data_dir / "brain" / native_sid
    if target_brain_dir.exists():
        return True

    source_brain_dir = None
    for agy_dir in _get_antigravity_cli_dirs():
        candidate = agy_dir / "brain" / native_sid
        if candidate.exists() and candidate != target_brain_dir:
            source_brain_dir = candidate
            break
    if not source_brain_dir:
        return False

    copied = _copy_if_fresher(source_brain_dir, target_brain_dir)
    if copied:
        logger.info(
            "Mirrored Antigravity conversation %s into active HOME",
            native_sid,
        )

    if copied and workspace_path:
        cache_file = active_data_dir / "cache" / "last_conversations.json"
        try:
            cache_file.parent.mkdir(parents=True, exist_ok=True)
            try:
                data = json.loads(cache_file.read_text())
            except (OSError, json.JSONDecodeError):
                data = {}
            if not isinstance(data, dict):
                data = {}
            data[os.path.abspath(workspace_path)] = native_sid
            cache_file.write_text(json.dumps(data, indent=2))
        except OSError as exc:
            logger.debug("Failed to update Antigravity conversation cache: %s", exc)

    return target_brain_dir.exists()


def _ensure_native_resume_files(cli_type: str | None, native_sid: str,
                                workspace_path: str, extra_env: dict[str, str]) -> bool:
    """Mirror native resume files into the CLI profile active for this PTY."""
    cli = (cli_type or "claude").lower()
    if cli == "claude":
        return _ensure_claude_resume_files(native_sid, workspace_path, extra_env.get("HOME"))
    if cli == "codex":
        config_env = get_profile("codex").config_dir_env
        return _ensure_codex_resume_files(
            native_sid,
            extra_env.get("HOME"),
            extra_env.get(config_env) if config_env else None,
        )
    if cli == "antigravity":
        return _ensure_antigravity_resume_files(
            native_sid,
            workspace_path,
            extra_env.get("HOME"),
        )
    return False


def _can_precheck_resume(profile_id: str, workspace_path: str,
                         extra_env: dict[str, str]) -> bool:
    """True when a missing-resume verdict is trustworthy for this CLI.

    Every ``_ensure_*_resume_files`` helper returns False both for "the
    transcript is gone" and for "I wasn't given enough to look" (no HOME, no
    workspace path). Only the first justifies nuking the stored pointer, so
    the inputs each helper actually needs are checked up front.
    """
    if profile_id == "claude":
        return bool(workspace_path and extra_env.get("HOME"))
    if profile_id == "codex":
        config_env = get_profile("codex").config_dir_env
        return bool((config_env and extra_env.get(config_env)) or extra_env.get("HOME"))
    if profile_id == "antigravity":
        return bool(extra_env.get("HOME"))
    if profile_id == "gemini":
        return bool(workspace_path)
    return False


async def _clear_stale_native_session_id(session_id: str) -> None:
    """NULL a dead resume pointer so later starts don't retry the corpse."""
    try:
        db = await get_db()
        try:
            await db.execute(
                "UPDATE sessions SET native_session_id = NULL WHERE id = ?",
                (session_id,),
            )
            await db.commit()
        finally:
            await db.close()
    except Exception as exc:
        logger.warning(
            "Could not clear stale native_session_id for session %s: %s",
            session_id[:8], exc,
        )


async def _apply_session_resume(session_obj, config: dict, session_id: str,
                                extra_env: dict[str, str]) -> str | None:
    """Set RESUME_ID for this spawn, or fall back to a fresh conversation.

    A ``native_session_id`` pointing at a transcript that no longer exists
    made ``claude --resume <id>`` print "No conversation found" and exit: the
    PTY looked started, terminal input landed on a corpse, and nothing
    surfaced the failure. Resume targets are file-backed for every CLI we
    drive, so pre-check here. When the transcript is missing from every known
    home, log loudly, clear the pointer (DB + the in-memory ``config`` so the
    caller re-runs native-session detection) and let this same start attempt
    spawn fresh.

    Returns the resume argument actually applied, or None for a fresh spawn.
    """
    native_sid = config.get("native_session_id")
    if not native_sid:
        return None

    profile_id = session_obj.profile.id
    workspace_path = config.get("workspace_path", "") or ""
    if profile_id == "claude" and config.get("_resume_worktree_path"):
        # get_session_config resolved this cwd from the exact saved history.
        # We are already in that worktree; --worktree would create another one.
        session_obj.set(Feature.WORKTREE, False)

    if not _can_precheck_resume(profile_id, workspace_path, extra_env):
        # Unknown CLI, or we lack the inputs to tell "gone" from "couldn't
        # look". Keep the historical behaviour rather than risk discarding a
        # live pointer.
        session_obj.set(Feature.RESUME_ID, native_sid)
        return native_sid

    if profile_id == "gemini":
        # Gemini resumes by index; the index is derived from an on-disk file.
        resume_arg = _resolve_gemini_resume_index(workspace_path, native_sid)
        found = bool(resume_arg)
    else:
        resume_arg = native_sid
        found = _ensure_native_resume_files(
            profile_id, native_sid, workspace_path, extra_env
        )

    if not found:
        logger.warning(
            "Session %s: %s resume target %r is missing from every known home — "
            "clearing sessions.native_session_id and starting a FRESH "
            "conversation in this same start attempt (a dead --resume exits "
            "immediately and silently swallows terminal input)",
            session_id[:8], profile_id, native_sid,
        )
        config["native_session_id"] = None
        await _clear_stale_native_session_id(session_id)
        return None

    session_obj.set(Feature.RESUME_ID, resume_arg)
    return resume_arg


async def _get_code_bash_allowlist() -> list[str]:
    """Owner-configured Bash glob allowlist for Code-mode joiners.

    Stored in app_settings as comma-separated key 'code_mode_bash_allowlist'.
    Empty (default) means Bash is fully off in Code mode.
    """
    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT value FROM app_settings WHERE key = 'code_mode_bash_allowlist'"
        )
        row = await cur.fetchone()
    finally:
        await db.close()
    if not row or not row["value"]:
        return []
    return [p.strip() for p in row["value"].split(",") if p.strip()]


def _snapshot_jsonl_files(workspace_path: str, cli_home: str | _Path | None = None) -> set[str]:
    """Get set of existing .jsonl filenames in the project directory."""
    files: set[str] = set()
    for project_dir in _get_project_dirs(workspace_path, cli_home):
        if project_dir.exists():
            files.update(str(f) for f in project_dir.glob("*.jsonl"))
    return files


def _get_gemini_chats_dir(workspace_path: str) -> _Path:
    """Get the Gemini CLI chats directory for a workspace path.

    Gemini uses SHA256(absolute_path) as the project dir name under ~/.gemini/tmp/.
    """
    import hashlib
    abs_path = os.path.abspath(workspace_path)
    project_hash = hashlib.sha256(abs_path.encode()).hexdigest()
    return _Path.home() / ".gemini" / "tmp" / project_hash / "chats"


def _resolve_gemini_native_id(workspace_path: str, hook_sid: str) -> str | None:
    """Map a Gemini hook session UUID to its chat file stem (``session-...``).

    Gemini hooks report the conversation UUID, but resume (by index) and the
    transcript lookup work on ``chats/<stem>.json``. Returns None until the
    chat file exists.
    """
    if not hook_sid or not workspace_path:
        return None
    if hook_sid.startswith("session-"):
        return hook_sid
    chats_dir = _get_gemini_chats_dir(workspace_path)
    try:
        files = sorted(chats_dir.glob("session-*.json"),
                       key=lambda f: f.stat().st_mtime, reverse=True)
    except OSError:
        return None
    pattern = re.compile(r'"sessionId"\s*:\s*"' + re.escape(hook_sid) + '"')
    for chat_file in files:
        try:
            with open(chat_file, "r", encoding="utf-8", errors="replace") as fh:
                head = fh.read(4096)
        except OSError:
            continue
        if pattern.search(head):
            return chat_file.stem
    return None


def _get_codex_sessions_dirs() -> list[_Path]:
    """Codex rollout roots: active/default CODEX_HOMEs, then every account's."""
    dirs: list[_Path] = []
    for data_dir in [*candidate_data_dirs("codex"), *_account_cli_data_dirs("codex")]:
        sessions_dir = data_dir / "sessions"
        if sessions_dir not in dirs:
            dirs.append(sessions_dir)
    return dirs


def _find_codex_session_file(native_sid: str) -> _Path | None:
    """Find a Codex rollout JSONL by native session id or filename stem."""
    if not native_sid:
        return None
    candidate = _Path(os.path.expanduser(native_sid))
    if candidate.is_file():
        return candidate

    patterns = []
    if native_sid.endswith(".jsonl"):
        patterns.append(native_sid)
    else:
        patterns.extend([f"{native_sid}.jsonl", f"*{native_sid}*.jsonl"])

    matches: list[_Path] = []
    for sessions_dir in _get_codex_sessions_dirs():
        if not sessions_dir.exists():
            continue
        for pattern in patterns:
            matches.extend(sessions_dir.rglob(pattern))
    return max(matches, key=_resume_file_rank) if matches else None


def _get_antigravity_cli_dirs(cli_home: str | _Path | None = None) -> list[_Path]:
    """Return candidate Antigravity CLI data dirs, IVE-managed first."""
    dirs: list[_Path] = []
    if cli_home:
        dirs.append(cli_data_dir("antigravity", _Path(cli_home).expanduser()))
    dirs.extend(candidate_data_dirs("antigravity"))

    seen: set[str] = set()
    unique: list[_Path] = []
    for data_dir in dirs:
        key = str(data_dir)
        if key in seen:
            continue
        seen.add(key)
        unique.append(data_dir)
    return unique


def _get_antigravity_cli_dir(cli_home: str | _Path | None = None) -> _Path:
    """Return the primary Antigravity CLI data dir used by managed IVE sessions."""
    for candidate in _get_antigravity_cli_dirs(cli_home):
        if candidate.exists():
            return candidate
    return cli_data_dir("antigravity", managed_home("antigravity"))


def _get_antigravity_last_conversations(cli_home: str | _Path | None = None) -> dict[str, str]:
    """Read Antigravity's workspace -> conversation cache."""
    merged: dict[str, str] = {}
    for agy_dir in reversed(_get_antigravity_cli_dirs(cli_home)):
        cache_file = agy_dir / "cache" / "last_conversations.json"
        try:
            data = json.loads(cache_file.read_text())
        except Exception:
            continue
        if isinstance(data, dict):
            merged.update({str(k): str(v) for k, v in data.items() if k and v})
    return merged


def _get_antigravity_conversation_for_workspace(
    workspace_path: str,
    cli_home: str | _Path | None = None,
) -> str | None:
    if not workspace_path:
        return None
    abs_path = os.path.abspath(workspace_path)
    conversations = _get_antigravity_last_conversations(cli_home)
    return conversations.get(abs_path) or conversations.get(workspace_path)


def _get_antigravity_transcript_path(
    native_sid: str,
    cli_home: str | _Path | None = None,
) -> _Path | None:
    if not native_sid:
        return None
    candidate = _Path(os.path.expanduser(native_sid))
    if candidate.is_file():
        return candidate
    for agy_dir in _get_antigravity_cli_dirs(cli_home):
        brain_dir = agy_dir / "brain" / native_sid
        transcript = brain_dir / ".system_generated" / "logs" / "transcript.jsonl"
        if transcript.exists():
            return transcript
        full_transcript = brain_dir / ".system_generated" / "logs" / "transcript_full.jsonl"
        if full_transcript.exists():
            return full_transcript
    return transcript


def _snapshot_codex_sessions() -> set[str]:
    files: set[str] = set()
    for sessions_dir in _get_codex_sessions_dirs():
        if sessions_dir.exists():
            files.update(str(f) for f in sessions_dir.rglob("*.jsonl"))
    return files


def _snapshot_antigravity_sessions(cli_home: str | _Path | None = None) -> set[str]:
    sessions: set[str] = set()
    for agy_dir in _get_antigravity_cli_dirs(cli_home):
        brain_dir = agy_dir / "brain"
        if brain_dir.exists():
            sessions.update(str(p) for p in brain_dir.iterdir() if p.is_dir())
    return sessions


def _get_native_transcript_path(cli_type: str | None, workspace_path: str | None,
                                native_sid: str | None,
                                cli_home: str | _Path | None = None) -> _Path | None:
    """Resolve a stored native session id to the CLI's transcript file."""
    if not native_sid:
        return None
    cli = (cli_type or "claude").lower()
    if cli == "gemini":
        if not workspace_path:
            return None
        return _get_gemini_chats_dir(workspace_path) / f"{native_sid}.json"
    if cli == "codex":
        return _find_codex_session_file(native_sid)
    if cli == "antigravity":
        return _get_antigravity_transcript_path(native_sid, cli_home)
    if not workspace_path:
        return None
    candidates = [project_dir / f"{native_sid}.jsonl"
                  for project_dir in _get_project_dirs(workspace_path, cli_home)]
    existing = [candidate for candidate in candidates if candidate.is_file()]
    if existing:
        # A prior resume may have mirrored the file. Never prefer an old
        # parent/account copy over the transcript the live worktree appends to.
        return max(existing, key=_resume_file_rank)
    return _get_project_dir(workspace_path) / f"{native_sid}.jsonl"


def _claude_resume_worktree(config: dict) -> str | None:
    """Recover only an existing, related worktree cwd from this exact history."""
    if (config.get("cli_type") or "claude") != "claude" or not config.get("worktree"):
        return None
    workspace_path, native_sid = config.get("workspace_path"), config.get("native_session_id")
    if not workspace_path or not native_sid:
        return None
    transcript = _get_native_transcript_path(
        "claude", workspace_path, native_sid, cli_home=_session_transcript_home(config),
    )
    if not transcript or not transcript.is_file():
        return None
    allowed_root = (_Path(workspace_path) / ".claude" / "worktrees").resolve()
    try:
        with transcript.open(encoding="utf-8") as source:
            for index, line in enumerate(source):
                if index >= 100:
                    break
                try:
                    entry = json.loads(line)
                except (ValueError, TypeError):
                    continue
                if not isinstance(entry, dict) or entry.get("sessionId") != native_sid:
                    continue
                cwd = entry.get("cwd")
                if not isinstance(cwd, str) or not cwd:
                    continue
                candidate = _Path(cwd).resolve()
                # Do not follow arbitrary transcript cwd changes outside the
                # repo, or resume from a deleted/replaced worktree location.
                if candidate.parent == allowed_root and candidate.is_dir() and (candidate / ".git").exists():
                    return str(candidate)
    except OSError:
        pass
    return None


def _get_native_transcript_dir(
    cli_type: str | None,
    workspace_path: str,
    cli_home: str | _Path | None = None,
) -> _Path:
    """Directory to scan for recent transcript files for a CLI/workspace."""
    cli = (cli_type or "claude").lower()
    if cli == "gemini":
        return _get_gemini_chats_dir(workspace_path)
    if cli == "codex":
        return _get_codex_sessions_dirs()[0]
    if cli == "antigravity":
        return _get_antigravity_cli_dir(cli_home) / "brain"
    return _get_project_dir(workspace_path)


def _session_cli_home(cli_type: str | None, account_id: str | None) -> _Path | None:
    """Return the account-scoped HOME for CLIs whose transcripts live there."""
    cli = (cli_type or "claude").lower()
    if account_id and cli in {"claude", "antigravity"}:
        return managed_home(cli, account_id)
    return None


def _session_transcript_home(session: dict | None) -> _Path | None:
    """Return the HOME that should be searched for a session transcript."""
    if not session:
        return None
    cli = (session.get("cli_type") or "claude").lower()
    runtime_home = session.get("cli_runtime_home")
    if cli == "antigravity" and runtime_home:
        return _Path(runtime_home).expanduser()
    return _session_cli_home(cli, session.get("account_id"))


def _inactive_cli_response(cli_type: str | None) -> web.Response:
    allowed = ", ".join(profile.id for profile in active_profiles())
    return web.json_response(
        {"error": f"CLI '{cli_type}' is deprecated or unavailable. Choose one of: {allowed}"},
        status=400,
    )


def _profile_default_model_for_role(profile, session_type: str | None) -> str:
    role = session_type or "worker"
    if role in {"commander", "planner", "brainstormer", "architect"} and profile.default_commander_model:
        return profile.default_commander_model
    if role in {"tester", "test_worker", "documentor"} and profile.default_tester_model:
        return profile.default_tester_model
    return profile.default_model


def _model_for_storage(profile, model: str | None, session_type: str | None) -> str:
    if model in (None, ""):
        return _profile_default_model_for_role(profile, session_type) or ""
    return str(model)


async def _backfill_codex_default_model(codex_default: str) -> None:
    """Normalize legacy Codex rows that stored '' to mean CLI default."""
    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT COUNT(*) AS count FROM sessions "
            "WHERE cli_type = 'codex' AND (model IS NULL OR model = '')"
        )
        row = await cur.fetchone()
        count = int(row["count"] if row else 0)
        if not count:
            return
        await db.execute(
            "UPDATE sessions SET model = ? "
            "WHERE cli_type = 'codex' AND (model IS NULL OR model = '')",
            (codex_default,),
        )
        await db.commit()
        logger.info("Backfilled %d Codex session model(s) to %s", count, codex_default)
    finally:
        await db.close()


def _profile_option_valid(options: list, value: str | None, allow_empty: bool = True) -> bool:
    if value in (None, ""):
        return allow_empty
    ids = {str(item.get("id")) for item in options if isinstance(item, dict) and item.get("id") is not None}
    return not ids or str(value) in ids


def _effort_for_storage(profile, value) -> str | None:
    """Effort to store on a new session. None = the CLI's own default.

    No silent "high" any more: Claude's default is whatever the user's
    settings say (effort_defaults.py), and IVE now passes --effort whenever
    a level is stored, so a made-up "high" would really downgrade sessions.
    """
    levels = list(getattr(profile, "effort_levels", None) or [])
    if not levels or value in (None, ""):
        return None
    value = str(value).strip().lower()
    return value if value in levels else None


def _permission_mode_error(profile, mode) -> web.Response | None:
    """400 response when ``mode`` cannot be launched by ``profile``, else None.

    Without this, a stale Claude mode on a Codex session (e.g. "untrusted" or
    a typo) reaches the CLI argv and the PTY dies on start with a clap error.
    """
    from cli_profiles import permission_mode_error_payload
    payload = permission_mode_error_payload(profile, mode)
    return None if payload is None else web.json_response(payload, status=400)


def _snapshot_gemini_sessions(workspace_path: str) -> set[str]:
    """Get set of existing Gemini session .json filenames."""
    chats_dir = _get_gemini_chats_dir(workspace_path)
    if not chats_dir.exists():
        return set()
    return {f.name for f in chats_dir.glob("session-*.json")}


def _resolve_gemini_resume_index(workspace_path: str, stem: str) -> str | None:
    """Resolve a Gemini session filename stem to a --resume argument.

    Gemini --resume accepts 'latest' or an index (from --list-sessions).
    Indices shift as new sessions are added. We sort session files by mtime
    descending and find the index of our target file.

    Returns the index as a string, or None if not found.
    """
    chats_dir = _get_gemini_chats_dir(workspace_path)
    if not chats_dir.exists():
        return None
    target_file = chats_dir / f"{stem}.json"
    if not target_file.exists():
        return None
    # Sort by modification time, newest first (matches Gemini's --list-sessions order)
    files = sorted(chats_dir.glob("session-*.json"), key=lambda f: f.stat().st_mtime, reverse=True)
    for idx, f in enumerate(files):
        if f.name == target_file.name:
            return str(idx)
    return None


async def detect_gemini_session(session_id: str, workspace_path: str,
                                 pre_existing_files: set[str] | None = None):
    """Detect which Gemini session file belongs to this PTY.

    Similar to detect_claude_session but for Gemini's .json format.
    Stores the filename stem (e.g. 'session-2026-04-08T...') in native_session_id.
    Gemini may write the chat file only after the first prompt, so this polls
    fast at first, then backs off until the file appears or the PTY is gone.
    """
    target_file = None
    if pre_existing_files is None:
        # Without a pre-start snapshot there is nothing to diff against.
        return
    generation = _begin_native_detection(session_id)
    for elapsed, delay in _native_detection_delays():
        await _asyncio.sleep(delay)
        if await _native_detection_should_stop(session_id, generation, elapsed, "Gemini"):
            return

        chats_dir = _get_gemini_chats_dir(workspace_path)
        if not chats_dir.exists():
            continue

        if pre_existing_files is not None:
            current = {f.name for f in chats_dir.glob("session-*.json")}
            new_files = current - pre_existing_files
            if new_files:
                claimed = await _claimed_native_ids(session_id)
                new_files = {f for f in new_files if _Path(f).stem not in claimed}
            if len(new_files) == 1:
                target_file = chats_dir / new_files.pop()
            elif len(new_files) > 1:
                candidates = [chats_dir / f for f in new_files]
                target_file = max(candidates, key=lambda f: f.stat().st_mtime)

        if target_file:
            break

    if not target_file:
        logger.info(f"Gemini session {session_id[:8]}: file detection failed after retries")
        return

    # Read the session ID and slug from the file
    try:
        data = json.loads(target_file.read_text())
        gemini_sid = data.get("sessionId", target_file.stem)
    except Exception as e:
        logger.debug("Gemini session file parse fallback: %s", e)
        gemini_sid = target_file.stem

    # Store the filename stem (used for --resume later)
    file_stem = target_file.stem

    db = await get_db()
    try:
        await db.execute(
            "UPDATE sessions SET native_session_id = ? WHERE id = ?",
            (file_stem, session_id),
        )
        await db.commit()
    finally:
        await db.close()

    logger.info(f"Detected Gemini session: {session_id[:8]} → {file_stem}")


def _read_codex_session_meta(path: _Path) -> dict:
    try:
        with open(path, "r") as f:
            for line in f:
                if not line.strip():
                    continue
                entry = json.loads(line)
                if entry.get("type") == "session_meta" and isinstance(entry.get("payload"), dict):
                    return entry["payload"]
    except Exception:
        return {}
    return {}


# ── Native transcript detection polling ─────────────────────────────────
# Codex (0.161+) and Gemini create their transcript file lazily, only once the
# first prompt is sent, which can be minutes after the PTY starts. Detection
# therefore polls fast for a short window, then backs off and keeps polling
# until the file appears, the PTY is gone, or a generous cap is reached.
_NATIVE_DETECT_FAST_WINDOW = 20.0
_NATIVE_DETECT_FAST_INTERVAL = 2.0
_NATIVE_DETECT_SLOW_INTERVAL = 5.0
_NATIVE_DETECT_MAX_SECONDS = 2 * 60 * 60
# Newest detection task per session; older tasks for the same session stop.
_native_detect_generation: dict[str, int] = {}
# Live Codex detectors: session_id -> (abs workspace, detector start epoch).
_codex_detect_active: dict[str, tuple[str, float]] = {}
_CODEX_TS_SKEW = 5.0
_codex_self_heal_last: dict[str, float] = {}
_CODEX_SELF_HEAL_THROTTLE = 15.0


def _native_detection_delays():
    """Yield sleep intervals: fast first, then backed off, up to the cap."""
    elapsed = 0.0
    while elapsed < _NATIVE_DETECT_MAX_SECONDS:
        delay = (_NATIVE_DETECT_FAST_INTERVAL if elapsed < _NATIVE_DETECT_FAST_WINDOW
                 else _NATIVE_DETECT_SLOW_INTERVAL)
        elapsed += delay
        yield elapsed, delay


def _begin_native_detection(session_id: str) -> int:
    gen = _native_detect_generation.get(session_id, 0) + 1
    _native_detect_generation[session_id] = gen
    return gen


async def _native_detection_should_stop(session_id: str, generation: int,
                                        elapsed: float, label: str) -> bool:
    """True when detection for this session is done or pointless.

    Stops when the native id is already set (hooks or another path resolved
    it), the session row is gone, a newer detection task superseded this one,
    or -- after the fast window -- the PTY is no longer alive.
    """
    if _native_detect_generation.get(session_id, generation) != generation:
        return True
    db_check = await get_db()
    try:
        cur = await db_check.execute(
            "SELECT native_session_id FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
    finally:
        await db_check.close()
    if not row:
        return True
    if row["native_session_id"]:
        logger.info("%s session %s: native ID already resolved", label, session_id[:8])
        return True
    if elapsed > _NATIVE_DETECT_FAST_WINDOW and not pty_mgr.is_alive(session_id):
        logger.info("%s session %s: PTY gone, stopping detection", label, session_id[:8])
        return True
    return False


def _parse_utc_ts(value) -> float | None:
    """Parse an ISO-8601 or SQLite 'YYYY-MM-DD HH:MM:SS' (UTC) timestamp."""
    if not value or not isinstance(value, str):
        return None
    text = value.strip().replace("Z", "+00:00")
    if " " in text and "T" not in text:
        text = text.replace(" ", "T", 1)
    try:
        parsed = datetime.datetime.fromisoformat(text)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=datetime.timezone.utc)
    return parsed.timestamp()


def _read_codex_session_meta_head(path: _Path, max_lines: int = 5) -> dict:
    """Cheap variant of _read_codex_session_meta: only scan the first lines."""
    try:
        with open(path, "r") as f:
            for idx, line in enumerate(f):
                if idx >= max_lines:
                    break
                if not line.strip():
                    continue
                entry = json.loads(line)
                if entry.get("type") == "session_meta" and isinstance(entry.get("payload"), dict):
                    return entry["payload"]
    except Exception:
        return {}
    return {}


def _codex_meta_matches_workspace(meta: dict, workspace_path: str) -> bool:
    cwd = meta.get("cwd")
    if not cwd:
        return False
    try:
        return os.path.abspath(cwd) == os.path.abspath(workspace_path)
    except Exception:
        return cwd == workspace_path


def _codex_meta_is_root_thread(meta: dict) -> bool:
    """False for subagent / guardian-review rollouts codex-tui writes beside
    the user's thread (same cwd). Older rollouts without these fields count
    as root threads."""
    sid, tid = meta.get("session_id"), meta.get("id")
    if sid and tid and str(sid) != str(tid):
        return False
    thread_source = meta.get("thread_source")
    if thread_source not in (None, "") and str(thread_source).strip().lower() != "user":
        return False
    source = meta.get("source")
    if isinstance(source, dict) and ("subagent" in source or "guardian_review" in source):
        return False
    return True


def _codex_meta_ts(meta: dict, path: _Path) -> float | None:
    ts = _parse_utc_ts(meta.get("timestamp"))
    if ts is not None:
        return ts
    try:
        return path.stat().st_mtime
    except OSError:
        return None


def _codex_rollout_claimed(path: _Path, meta: dict, claimed: set[str]) -> bool:
    """True if another IVE session's native_session_id points at this rollout."""
    if not claimed:
        return False
    keys = {str(path), path.name, path.stem}
    if meta.get("id"):
        keys.add(str(meta["id"]))
    if keys & claimed:
        return True
    return any(len(c) >= 8 and c in path.name for c in claimed)


async def _claimed_native_ids(exclude_session_id: str) -> set[str]:
    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT native_session_id FROM sessions "
            "WHERE id != ? AND native_session_id IS NOT NULL AND native_session_id != ''",
            (exclude_session_id,),
        )
        rows = await cur.fetchall()
    finally:
        await db.close()
    return {str(r["native_session_id"]) for r in rows}


async def _claim_native_id(session_id: str, native_sid: str) -> bool:
    """Persist native_sid unless set already or owned by another session."""
    db = await get_db()
    try:
        cur = await db.execute(
            """UPDATE sessions SET native_session_id = ?
               WHERE id = ?
                 AND (native_session_id IS NULL OR native_session_id = '')
                 AND NOT EXISTS (
                     SELECT 1 FROM sessions WHERE native_session_id = ? AND id != ?
                 )""",
            (native_sid, session_id, native_sid, session_id),
        )
        await db.commit()
        return (cur.rowcount or 0) > 0
    finally:
        await db.close()


def _codex_owner_for_ts(ts: float | None, abs_workspace: str) -> str | None:
    """Live detector in this workspace that most plausibly owns a rollout.

    The rollout's session_meta timestamp is at or after its PTY start, so the
    owner is the detector with the latest start that is not after it.
    """
    if ts is None:
        return None
    best_sid, best_start = None, None
    for sid, (ws, start) in _codex_detect_active.items():
        if ws != abs_workspace or start > ts + _CODEX_TS_SKEW:
            continue
        if best_start is None or start > best_start:
            best_sid, best_start = sid, start
    return best_sid


def _codex_detection_candidates(pre_existing_files: set[str] | None) -> list[_Path]:
    current = _snapshot_codex_sessions()
    if pre_existing_files is not None:
        return [_Path(p) for p in current - pre_existing_files]
    paths = [_Path(p) for p in current]
    return sorted(paths, key=lambda p: p.stat().st_mtime, reverse=True)[:5]


async def detect_codex_session(session_id: str, workspace_path: str,
                               pre_existing_files: set[str] | None = None):
    """Detect the Codex rollout JSONL created for this PTY.

    Codex writes the rollout lazily (on the first prompt), so this keeps
    polling with backoff instead of giving up after a fixed short window.
    """
    generation = _begin_native_detection(session_id)
    abs_workspace = os.path.abspath(workspace_path)
    _codex_detect_active[session_id] = (abs_workspace, time.time())
    try:
        for elapsed, delay in _native_detection_delays():
            await _asyncio.sleep(delay)
            if await _native_detection_should_stop(session_id, generation, elapsed, "Codex"):
                return

            candidates = [p for p in _codex_detection_candidates(pre_existing_files) if p.is_file()]
            if not candidates:
                continue
            claimed = await _claimed_native_ids(session_id)
            matching = []
            for path in candidates:
                meta = _read_codex_session_meta(path)
                if not _codex_meta_matches_workspace(meta, workspace_path):
                    continue
                if not _codex_meta_is_root_thread(meta):
                    continue
                if _codex_rollout_claimed(path, meta, claimed):
                    continue
                owner = _codex_owner_for_ts(_codex_meta_ts(meta, path), abs_workspace)
                if owner is not None and owner != session_id:
                    continue
                matching.append((path, meta))
            if not matching:
                continue

            target_file, meta = max(matching, key=lambda item: item[0].stat().st_mtime)
            native_sid = str(meta.get("id") or target_file.stem)
            if await _claim_native_id(session_id, native_sid):
                logger.info("Detected Codex session: %s → %s", session_id[:8], native_sid)
                return
            # Lost a race (claimed elsewhere or already set): re-check next tick.

        logger.info("Codex session %s: file detection gave up after %ds",
                    session_id[:8], int(_NATIVE_DETECT_MAX_SECONDS))
    finally:
        if _native_detect_generation.get(session_id) == generation:
            _codex_detect_active.pop(session_id, None)


async def _self_heal_codex_native_session(session: dict, workspace_path: str) -> str | None:
    """Resolve a lost Codex native_session_id from unclaimed rollouts.

    Used when a transcript is requested for a Codex session whose detection
    never succeeded. Picks the earliest unclaimed rollout whose cwd matches
    and whose session_meta timestamp lies after the session's created_at and
    before the next still-unresolved Codex session in the same workspace.
    Throttled per session so polling views stay cheap.
    """
    session_id = session.get("id")
    if not session_id or not workspace_path:
        return None
    if session_id in _codex_detect_active:
        return None  # a live detector is still on it
    now = time.time()
    last = _codex_self_heal_last.get(session_id)
    if last is not None and now - last < _CODEX_SELF_HEAL_THROTTLE:
        return None
    _codex_self_heal_last[session_id] = now

    created = _parse_utc_ts(session.get("created_at"))
    if created is None:
        return None
    lower = created - _CODEX_TS_SKEW
    abs_workspace = os.path.abspath(workspace_path)

    db = await get_db()
    try:
        cur = await db.execute(
            """SELECT s.id, s.created_at, s.native_session_id, w.path AS workspace_path
               FROM sessions s LEFT JOIN workspaces w ON s.workspace_id = w.id
               WHERE s.id != ? AND s.cli_type = 'codex'""",
            (session_id,),
        )
        others = [dict(r) for r in await cur.fetchall()]
    finally:
        await db.close()

    claimed = await _claimed_native_ids(session_id)
    upper = None
    for other in others:
        if other.get("native_session_id"):
            continue
        if not other.get("workspace_path") or os.path.abspath(other["workspace_path"]) != abs_workspace:
            continue
        other_created = _parse_utc_ts(other.get("created_at"))
        if other_created is not None and other_created > created:
            upper = other_created if upper is None else min(upper, other_created)

    best = None
    for sessions_dir in _get_codex_sessions_dirs():
        if not sessions_dir.exists():
            continue
        for path in sessions_dir.rglob("*.jsonl"):
            try:
                if path.stat().st_mtime < lower:
                    continue  # last written before the session existed
            except OSError:
                continue
            meta = _read_codex_session_meta_head(path)
            if not _codex_meta_matches_workspace(meta, workspace_path):
                continue
            if not _codex_meta_is_root_thread(meta):
                continue
            ts = _codex_meta_ts(meta, path)
            if ts is None or ts < lower or (upper is not None and ts >= upper - _CODEX_TS_SKEW):
                continue
            if _codex_rollout_claimed(path, meta, claimed):
                continue
            if best is None or ts < best[0]:
                best = (ts, path, meta)
    if not best:
        return None

    _, path, meta = best
    native_sid = str(meta.get("id") or path.stem)
    if await _claim_native_id(session_id, native_sid):
        logger.info("Self-healed Codex session: %s → %s", session_id[:8], native_sid)
        return native_sid
    return None


async def detect_antigravity_session(
    session_id: str,
    workspace_path: str,
    pre_existing_files: set[str] | None = None,
    cli_home: str | _Path | None = None,
):
    """Detect the Antigravity conversation id created or reused for this workspace."""
    target_sid = None
    abs_workspace = os.path.abspath(workspace_path)

    generation = _begin_native_detection(session_id)
    for elapsed, delay in _native_detection_delays():
        await _asyncio.sleep(delay)
        if await _native_detection_should_stop(session_id, generation, elapsed, "Antigravity"):
            return

        if pre_existing_files is not None:
            current = _snapshot_antigravity_sessions(cli_home)
            new_paths = current - pre_existing_files
            if len(new_paths) == 1:
                target_sid = _Path(next(iter(new_paths))).name
                break
            if len(new_paths) > 1:
                candidates = [_Path(p) for p in new_paths]
                target_sid = max(candidates, key=lambda p: p.stat().st_mtime).name
                break
            continue

        target_sid = _get_antigravity_conversation_for_workspace(abs_workspace, cli_home)
        if target_sid:
            break

    if not target_sid:
        logger.info("Antigravity session %s: conversation detection failed after retries", session_id[:8])
        return

    db = await get_db()
    try:
        await db.execute(
            "UPDATE sessions SET native_session_id = ? WHERE id = ?",
            (target_sid, session_id),
        )
        await db.commit()
    finally:
        await db.close()

    logger.info("Detected Antigravity session: %s → %s", session_id[:8], target_sid)


async def _resolve_antigravity_native_session(
    session_id: str,
    config: dict,
    wait_timeout: float = 0.0,
) -> str | None:
    """Best-effort resolve and persist the Antigravity conversation id.

    Antigravity model changes require a process restart because model choice is
    applied through its settings file. Restarting before IVE knows the native
    conversation id risks opening a blank conversation, so callers that restart
    should resolve this first.
    """
    native_sid = config.get("native_session_id")
    if native_sid:
        return native_sid

    workspace_path = config.get("workspace_path") or ""
    cli_home = config.get("cli_runtime_home")
    account_id = config.get("account_id")
    if not cli_home and account_id:
        cli_home = managed_home("antigravity", account_id)
    deadline = _asyncio.get_event_loop().time() + max(0.0, wait_timeout)
    while True:
        try:
            db_check = await get_db()
            try:
                cur = await db_check.execute(
                    "SELECT native_session_id FROM sessions WHERE id = ?",
                    (session_id,),
                )
                row = await cur.fetchone()
                if row and row["native_session_id"]:
                    native_sid = row["native_session_id"]
                    break
            finally:
                await db_check.close()
        except Exception:
            pass

        native_sid = _get_antigravity_conversation_for_workspace(workspace_path, cli_home)
        if native_sid:
            break
        if _asyncio.get_event_loop().time() >= deadline:
            return None
        await _asyncio.sleep(0.25)

    db = await get_db()
    try:
        await db.execute(
            "UPDATE sessions SET native_session_id = ? WHERE id = ?",
            (native_sid, session_id),
        )
        await db.commit()
    finally:
        await db.close()
    config["native_session_id"] = native_sid
    return native_sid


_CLAUDE_DETECT_TS_SKEW = 5.0


def _claude_transcript_started_at(path: _Path) -> float | None:
    """Epoch of a Claude transcript's first timestamped entry (or birth time)."""
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            for idx, line in enumerate(fh):
                if idx >= 20:
                    break
                try:
                    entry = json.loads(line)
                except (json.JSONDecodeError, ValueError):
                    continue
                ts = entry.get("timestamp") if isinstance(entry, dict) else None
                if isinstance(ts, str) and ts:
                    try:
                        parsed = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    except ValueError:
                        continue
                    if parsed.tzinfo is None:
                        parsed = parsed.replace(tzinfo=datetime.timezone.utc)
                    return parsed.timestamp()
    except OSError:
        return None
    try:
        st = path.stat()
    except OSError:
        return None
    return getattr(st, "st_birthtime", None) or st.st_mtime


async def _native_ids_owned_by_other_sessions(session_id: str) -> set[str]:
    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT native_session_id FROM sessions "
            "WHERE id != ? AND native_session_id IS NOT NULL AND native_session_id != ''",
            (session_id,),
        )
        return {str(r["native_session_id"]) for r in await cur.fetchall()}
    finally:
        await db.close()


async def _filter_claude_detection_candidates(
    candidates: list[_Path], session_id: str, started_at: float | None,
) -> list[_Path]:
    """Drop transcripts that cannot belong to this PTY.

    Files whose conversation id another IVE session already owns, and files
    whose conversation started before this PTY did (the user's own terminal
    Claude, an older run) are ignored.
    """
    if not candidates:
        return []
    claimed = await _native_ids_owned_by_other_sessions(session_id)
    kept: list[_Path] = []
    for path in candidates:
        if path.stem in claimed or not path.is_file():
            continue
        if started_at is not None:
            began = _claude_transcript_started_at(path)
            if began is None or began < started_at - _CLAUDE_DETECT_TS_SKEW:
                continue
        kept.append(path)
    return kept


async def detect_claude_session(session_id: str, workspace_path: str,
                                 force_rename: bool = False,
                                 pre_existing_files: set[str] | None = None,
                                 cli_home: str | _Path | None = None,
                                 started_at: float | None = None):
    """Detect which Claude Code conversation file belongs to this session.

    Hooks are the primary source of the native id (hooks.py). This is the
    fallback for when no hook arrives, so it:
      * never replaces an id that is already stored (hook or prior run);
        it only reads that id's file for the slug,
      * diffs against pre_existing_files to find files created after start,
      * ignores files owned by another IVE session or begun before this PTY
        (``started_at``, defaults to now = scheduling right after spawn),
      * only claims a file seen on two consecutive polls, giving the hook
        that fires with the same prompt time to land first,
      * marks a file-based guess as tentative, so a later hook with another
        id replaces it instead of looking like /branch.
    """
    generation = _begin_native_detection(session_id)
    if started_at is None and not force_rename:
        started_at = time.time()
    target_file = None
    existing_sid = None
    existing_name = None
    from_files = False
    seen_candidates: set[str] = set()

    # Retry: check every 2s for up to 20s
    for attempt in range(10):
        await _asyncio.sleep(2)
        # A replacement PTY owns detection now. An old delayed poll must not
        # bind the replacement to the exited process's conversation.
        if _native_detect_generation.get(session_id) != generation:
            return

        project_dirs = [d for d in _get_project_dirs(workspace_path, cli_home) if d.exists()]
        if not project_dirs:
            continue

        # Check current DB state (hooks may have resolved the native ID already)
        db_check = await get_db()
        try:
            cur = await db_check.execute(
                "SELECT native_session_id, name FROM sessions WHERE id = ?", (session_id,))
            row = await cur.fetchone()
            existing_sid = row["native_session_id"] if row else None
            existing_name = row["name"] if row else None
        finally:
            await db_check.close()
        if not row:
            return

        # 1. If we already have a session ID (from hooks or prior run), use that file
        if existing_sid:
            for project_dir in project_dirs:
                candidate = project_dir / f"{existing_sid}.jsonl"
                if candidate.exists():
                    target_file = candidate
                    break  # Got it — proceed to slug extraction
            if target_file:
                break
            # The stored id wins even before its file exists; never swap it
            # for some other new file in the folder.
            continue

        # 2. Diff against snapshot to find the NEW file
        if pre_existing_files is not None:
            current_files = {
                str(f)
                for project_dir in project_dirs
                for f in project_dir.glob("*.jsonl")
            }
            candidates = [_Path(f) for f in current_files - pre_existing_files]
        else:
            # 3. Last resort: newest files (only if no snapshot available)
            candidates = sorted(
                [f for project_dir in project_dirs for f in project_dir.glob("*.jsonl")],
                key=lambda f: f.stat().st_mtime, reverse=True)[:5]
        candidates = await _filter_claude_detection_candidates(
            candidates, session_id, started_at)
        ripe = [f for f in candidates if str(f) in seen_candidates]
        seen_candidates.update(str(f) for f in candidates)
        if ripe:
            target_file = max(ripe, key=lambda f: f.stat().st_mtime)
            from_files = True
            break

    if not target_file:
        logger.info(f"Claude session {session_id[:8]}: file detection failed after retries")
        return

    native_sid = target_file.stem

    # Read the slug from the session file
    slug = None
    try:
        with open(target_file, "r") as f:
            lines = f.readlines()
        for line in reversed(lines):
            try:
                entry = json.loads(line)
                if entry.get("slug"):
                    slug = entry["slug"]
                    break
            except json.JSONDecodeError:
                continue
    except Exception:
        pass

    if not slug and not native_sid:
        return

    # Store in DB only while this detector still owns the current launch.
    db = await get_db()
    try:
        if _native_detect_generation.get(session_id) != generation:
            return
        updates = ["native_session_id = ?"]
        values = [native_sid]
        new_name = None
        if slug:
            updates.append("native_slug = ?")
            values.append(slug)
            # Update session name if: force_rename, or still has default name
            if force_rename or not existing_name or existing_name.startswith("Session "):
                updates.append("name = ?")
                values.append(slug)
                new_name = slug
        values.extend([session_id, native_sid])
        # Never overwrite an id a hook stored in the meantime.
        cur = await db.execute(
            f"UPDATE sessions SET {', '.join(updates)} WHERE id = ? "
            "AND (native_session_id IS NULL OR native_session_id = '' "
            "OR native_session_id = ?)",
            values,
        )
        await db.commit()
        if not (cur.rowcount or 0):
            logger.info("Claude session %s: native id already set by a hook; "
                        "file detection result %s dropped", session_id[:8], native_sid)
            return
        if from_files:
            from hooks import mark_tentative_native_id
            mark_tentative_native_id(session_id, native_sid)
        if new_name:
            await broadcast({
                "type": "session_renamed",
                "session_id": session_id,
                "name": new_name,
                "native_session_id": native_sid,
                "native_slug": slug,
            })
    finally:
        await db.close()

    logger.info(f"Detected Claude session: {session_id} → {native_sid} ({slug})")


def _snapshot_files_for_detection(
    cli_type: str,
    workspace_path: str,
    cli_home: str | _Path | None = None,
) -> set[str] | None:
    """Snapshot session files before PTY start (for new-file detection)."""
    if cli_type == "claude":
        return _snapshot_jsonl_files(workspace_path, cli_home)
    elif cli_type == "gemini":
        return _snapshot_gemini_sessions(workspace_path)
    elif cli_type == "codex":
        return _snapshot_codex_sessions()
    elif cli_type == "antigravity":
        return _snapshot_antigravity_sessions(cli_home)
    return None


def _schedule_session_detection(cli_type: str, session_id: str, workspace_path: str,
                                pre_files: set[str] | None,
                                cli_home: str | _Path | None = None):
    """Schedule async session detection after PTY starts."""
    if cli_type == "claude":
        _asyncio.ensure_future(detect_claude_session(
            session_id, workspace_path, pre_existing_files=pre_files, cli_home=cli_home))
    elif cli_type == "gemini":
        _asyncio.ensure_future(detect_gemini_session(
            session_id, workspace_path, pre_existing_files=pre_files))
    elif cli_type == "codex":
        _asyncio.ensure_future(detect_codex_session(
            session_id, workspace_path, pre_existing_files=pre_files))
    elif cli_type == "antigravity":
        _asyncio.ensure_future(detect_antigravity_session(
            session_id, workspace_path, pre_existing_files=pre_files, cli_home=cli_home))


async def get_session_config(session_id: str) -> dict | None:
    db = await get_db()
    try:
        cur = await db.execute(
            """SELECT s.*, w.path AS workspace_path, w.sandbox_type, w.sandbox_network,
                      w.alloy_enabled
               FROM sessions s
               JOIN workspaces w ON s.workspace_id = w.id
               WHERE s.id = ?""",
            (session_id,),
        )
        row = await cur.fetchone()
        if row:
            d = dict(row)
            if d.get("worktree") and d.get("native_session_id") and (d.get("cli_type") or "claude") == "claude":
                worktree_path = await asyncio.to_thread(_claude_resume_worktree, d)
                if worktree_path:
                    d["workspace_path"] = worktree_path
                    d["worktree_path"] = worktree_path
                    d["_resume_worktree_path"] = worktree_path
            if d.get("sandbox_type") is None:
                d["sandbox_type"] = "none"
            if d.get("sandbox_network") is None:
                d["sandbox_network"] = 1
            return d
        return None
    finally:
        await db.close()


