def _normalize_api_key_provider(provider: str | None, key: str | None = None) -> str:
    p = (provider or "").strip().lower()
    aliases = {
        "anthropic": "anthropic",
        "claude": "anthropic",
        "zai": "z_ai",
        "z.ai": "z_ai",
        "z_ai": "z_ai",
        "z-ai": "z_ai",
        "z": "z_ai",
        "zai_glm51": "z_ai_glm51",
        "z.ai_glm51": "z_ai_glm51",
        "z_ai_glm51": "z_ai_glm51",
        "z-ai-glm51": "z_ai_glm51",
        "zai-premium": "z_ai_glm51",
        "z_ai_premium": "z_ai_glm51",
        "gateway": "anthropic_gateway",
        "anthropic_gateway": "anthropic_gateway",
        "claude_gateway": "anthropic_gateway",
        "custom_anthropic": "anthropic_gateway",
        "google": "google",
        "gemini": "google",
        "openai": "openai",
        "codex": "openai",
    }
    if p in aliases:
        return aliases[p]
    k = (key or "").strip()
    if k.startswith("sk-ant-"):
        return "anthropic"
    if k.startswith("AIza"):
        return "google"
    if k.startswith("sk-"):
        return "openai"
    return "anthropic"


_CLAUDE_MODEL_ALIASES = {"haiku", "sonnet", "opus"}
_ZAI_API_KEY_PROVIDERS = {"z_ai", "z_ai_glm51"}
ZAI_MCP_SERVER_IDS = (
    "builtin-zai-vision",
    "builtin-zai-web-search",
    "builtin-zai-web-reader",
    "builtin-zai-zread",
)


def _model_aliases_for_account(account: dict, provider: str | None = None) -> list[str]:
    raw = account.get("model_aliases")
    if isinstance(raw, str):
        aliases = [p.strip() for p in re.split(r"[\n,]+", raw) if p.strip()]
    elif isinstance(raw, (list, tuple)):
        aliases = [str(p).strip() for p in raw if str(p).strip()]
    else:
        aliases = []

    if aliases:
        return aliases

    spec = API_KEY_PROVIDERS.get(provider or "")
    default_models = spec.get("default_models") if spec else None
    if default_models:
        return [p.strip() for p in default_models.split(",") if p.strip()]
    return []


def _normalize_model_aliases(value, provider: str | None = None) -> str | None:
    aliases = _model_aliases_for_account({"model_aliases": value}, provider)
    if not aliases:
        return None
    return ", ".join(dict.fromkeys(aliases))


def _base_url_for_account(account: dict, provider: str | None = None) -> str:
    url = (account.get("base_url") or "").strip()
    if not url:
        spec = API_KEY_PROVIDERS.get(provider or "")
        url = (spec.get("default_base_url") if spec else "") or ""
    return url.rstrip("/")


def _is_claude_gateway_provider(provider: str) -> bool:
    return bool(API_KEY_PROVIDERS.get(provider, {}).get("gateway"))


async def _session_uses_zai_claude_account(db, cli_type: str | None, account_id: str | None) -> bool:
    if (cli_type or "claude").lower() != "claude" or not account_id:
        return False
    cur = await db.execute(
        "SELECT api_key, api_key_provider FROM accounts WHERE id = ?",
        (account_id,),
    )
    row = await cur.fetchone()
    if not row or not row["api_key"]:
        return False
    from crypto import decrypt_secret
    provider = _normalize_api_key_provider(row["api_key_provider"], decrypt_secret(row["api_key"]))
    return provider in _ZAI_API_KEY_PROVIDERS


async def _sync_zai_mcp_servers_for_session(
    db,
    session_id: str,
    cli_type: str | None,
    account_id: str | None,
) -> None:
    """Keep Z.AI MCP attachments scoped to Claude sessions using a Z.AI account."""
    placeholders = ",".join("?" for _ in ZAI_MCP_SERVER_IDS)
    if await _session_uses_zai_claude_account(db, cli_type, account_id):
        cur = await db.execute(
            f"SELECT id FROM mcp_servers WHERE id IN ({placeholders})",
            ZAI_MCP_SERVER_IDS,
        )
        existing = {row["id"] for row in await cur.fetchall()}
        for mcp_id in ZAI_MCP_SERVER_IDS:
            if mcp_id in existing:
                await db.execute(
                    "INSERT OR IGNORE INTO session_mcp_servers "
                    "(session_id, mcp_server_id) VALUES (?, ?)",
                    (session_id, mcp_id),
                )
    else:
        await db.execute(
            f"DELETE FROM session_mcp_servers "
            f"WHERE session_id = ? AND mcp_server_id IN ({placeholders})",
            (session_id, *ZAI_MCP_SERVER_IDS),
        )


class UnsupportedMCPProfileError(RuntimeError):
    """The selected profile does not declare the protocol its strategy needs."""


def _render_mcp_argv(
    session_obj: UnifiedSession,
    template: list[str],
    *,
    server_name: str,
    command: str = "",
    args: list[str] | None = None,
    transport: str = "stdio",
    resolved_env: dict[str, str] | None = None,
    effective_approve: bool = False,
) -> list[str]:
    profile = session_obj.profile
    binary = session_obj._resolved_binary()
    scalar = {
        "{binary}": binary,
        "{server_name}": server_name,
        "{command}": command,
        "{transport}": transport,
    }
    rendered: list[str] = []
    for token in template:
        if token == "{args}":
            rendered.extend(str(item) for item in (args or []))
        elif token == "{env}":
            if resolved_env and not profile.mcp_env_argv:
                raise UnsupportedMCPProfileError(
                    f"CLI profile '{profile.id}' has no MCP env argv template"
                )
            for key, value in sorted((resolved_env or {}).items()):
                rendered.extend(
                    part.replace("{key}", key).replace("{value}", value)
                    for part in profile.mcp_env_argv
                )
        elif token == "{auto_approve}":
            if effective_approve:
                rendered.extend(profile.mcp_auto_approve_argv)
        else:
            value = token
            for placeholder, replacement in scalar.items():
                value = value.replace(placeholder, replacement)
            rendered.append(value)
    return rendered


async def _ive_owned_mcp_server_names() -> set[str]:
    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT server_name FROM mcp_servers WHERE is_builtin = 1"
        )
        return {
            str(row["server_name"]).strip()
            for row in await cur.fetchall()
            if row["server_name"]
        }
    finally:
        await db.close()


# ─── Codex: per-session MCP via `-c` overrides ──────────────────────────
# codex-cli 0.16x merges `-c mcp_servers.<name>.<key>=<toml>` into its config
# for that one process (verified with `codex -c ... mcp list --json`): a new
# name becomes a server, an existing one has the given keys replaced (env
# tables merge key by key). So each Codex PTY gets its own WORKER_SESSION_ID
# etc. without `codex mcp add/remove` rewriting the shared config.toml.
_CODEX_MCP_NAME_RE = re.compile(r"^[A-Za-z0-9_-]+$")
# Env values whose names look secret stay out of argv (visible in `ps`):
# they go into the PTY env and are forwarded by name via `env_vars`.
_SECRET_ENV_KEY_RE = re.compile(r"(KEY|TOKEN|SECRET|PASSWORD|PASSWD|AUTH|CREDENTIAL)", re.I)


def _toml_inline(value) -> str:
    """Render a JSON-ish value as an inline TOML value for `codex -c`."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    if isinstance(value, (list, tuple)):
        return "[" + ", ".join(_toml_inline(v) for v in value) + "]"
    if isinstance(value, dict):
        return "{" + ", ".join(
            f"{json.dumps(str(k), ensure_ascii=False)} = {_toml_inline(v)}"
            for k, v in sorted(value.items())
        ) + "}"
    # JSON string escapes are valid TOML basic-string escapes.
    return json.dumps("" if value is None else str(value), ensure_ascii=False)


def _codex_mcp_secret_env_name(server_name: str, key: str) -> str:
    safe = re.sub(r"[^A-Za-z0-9]", "_", f"{server_name}_{key}").upper()
    return f"IVE_MCP_{safe}"


def _codex_mcp_override_args(server_name: str, entry: dict,
                             extra_env: dict[str, str]) -> list[str]:
    """`-c` overrides that define one MCP server for a single codex process.

    ``entry`` is _mcp_config_entry_for_server()'s shape. Secret-looking env
    values and headers are put in ``extra_env`` (the PTY env) and referenced
    by name, so they never appear on the command line.
    """
    if not _CODEX_MCP_NAME_RE.match(server_name or ""):
        logger.warning("Codex MCP: skipping server %r (name not usable in a -c path)", server_name)
        return []
    prefix = f"mcp_servers.{server_name}"
    pairs: list[tuple[str, object]] = [("enabled", True)]
    if entry.get("url"):
        pairs.append(("url", entry["url"]))
        headers, env_headers = {}, {}
        for key, value in (entry.get("headers") or {}).items():
            if _SECRET_ENV_KEY_RE.search(str(key)):
                env_name = _codex_mcp_secret_env_name(server_name, str(key))
                extra_env[env_name] = str(value)
                env_headers[str(key)] = env_name
            else:
                headers[str(key)] = str(value)
        if headers:
            pairs.append(("http_headers", headers))
        if env_headers:
            pairs.append(("env_http_headers", env_headers))
    else:
        pairs.append(("command", entry.get("command") or ""))
        pairs.append(("args", [str(a) for a in (entry.get("args") or [])]))
        env, forwarded = {}, []
        for key, value in (entry.get("env") or {}).items():
            key, value = str(key), str(value)
            if _SECRET_ENV_KEY_RE.search(key) and extra_env.get(key, value) == value:
                extra_env[key] = value
                forwarded.append(key)
            else:
                env[key] = value
        if env:
            pairs.append(("env", env))
        if forwarded:
            pairs.append(("env_vars", sorted(forwarded)))
    args: list[str] = []
    for key, value in pairs:
        args.extend(["-c", f"{prefix}.{key}={_toml_inline(value)}"])
    return args


def _codex_global_mcp_names(extra_env: dict[str, str]) -> set[str]:
    """MCP server names in the config.toml this Codex process will read."""
    home = extra_env.get("CODEX_HOME") or os.environ.get("CODEX_HOME") or "~/.codex"
    path = _Path(home).expanduser() / "config.toml"
    try:
        import tomllib
        with path.open("rb") as fh:
            data = tomllib.load(fh)
    except Exception:
        return set()
    servers = data.get("mcp_servers")
    return {str(k) for k in servers} if isinstance(servers, dict) else set()


async def _codex_disable_stale_mcp_args(selected: set[str],
                                        extra_env: dict[str, str]) -> list[str]:
    """Turn off IVE-owned servers left in config.toml by older IVE versions
    (`codex mcp add`) that this session did not select, for this process only."""
    present = _codex_global_mcp_names(extra_env)
    if not present:
        return []
    owned = await _ive_owned_mcp_server_names()
    args: list[str] = []
    for name in sorted((owned & present) - selected):
        if _CODEX_MCP_NAME_RE.match(name):
            args.extend(["-c", f"mcp_servers.{name}.enabled=false"])
    return args


# ``mcp_add`` CLIs (Codex) keep MCP registrations in one global config file
# (~/.codex/config.toml) that every ``mcp add/remove`` call rewrites. Starts
# run those calls one at a time under this lock, so two Codex sessions starting
# together never interleave writes, and a fresh Codex reads its own session's
# registration before the next start rewrites it (_MCP_ADD_SETTLE_SECS).
_MCP_ADD_LOCK = asyncio.Lock()
_MCP_ADD_SETTLE_SECS = 3.0
# What this backend last wrote per (binary, config home, server name): the
# rendered add argv, or None after a remove. Unchanged registrations are not
# rewritten, servers already removed are not removed again. Process-local, so
# a backend restart re-checks everything once.
_MCP_ADD_STATE: dict[tuple[str, str, str], Optional[tuple[str, ...]]] = {}


def _mcp_add_state_key(session_obj: UnifiedSession, env: dict[str, str],
                       server_name: str) -> tuple[str, str, str]:
    home = env.get("CODEX_HOME") or env.get("HOME") or ""
    return (session_obj._resolved_binary(), home, server_name)


async def _release_mcp_add_lock_later(delay: float) -> None:
    try:
        await asyncio.sleep(delay)
    finally:
        _MCP_ADD_LOCK.release()


async def _prune_mcp_add_servers(
    session_obj: UnifiedSession,
    selected_server_names: set[str],
    workspace_path: str,
    env: dict[str, str],
) -> None:
    """Remove stale registrations using the registry's built-in ownership bit."""
    profile = session_obj.profile
    if profile.mcp_strategy != "mcp_add":
        return
    if not workspace_path:
        raise UnsupportedMCPProfileError("mcp_add requires a workspace path")
    if not profile.mcp_remove_argv:
        raise UnsupportedMCPProfileError(
            f"CLI profile '{profile.id}' has no MCP remove argv template"
        )
    owned_names = await _ive_owned_mcp_server_names()
    stale_names = sorted(owned_names - set(selected_server_names or set()))
    removed_any = False
    for server_name in stale_names:
        state_key = _mcp_add_state_key(session_obj, env, server_name)
        if state_key in _MCP_ADD_STATE and _MCP_ADD_STATE[state_key] is None:
            continue  # already removed by this backend
        removed_any = True
        remove_cmd = _render_mcp_argv(
            session_obj,
            profile.mcp_remove_argv,
            server_name=server_name,
        )
        proc = await _asyncio.create_subprocess_exec(
            *remove_cmd,
            cwd=workspace_path,
            env=env,
            stdout=_asyncio.subprocess.DEVNULL,
            stderr=_asyncio.subprocess.DEVNULL,
        )
        await proc.communicate()
        _MCP_ADD_STATE[state_key] = None
    return removed_any


def _resolve_mcp_env_values(
    raw_env: dict,
    config: dict,
    session_id: str,
    extra_env: dict[str, str] | None = None,
    *,
    w2w_comms: str = "0",
    w2w_context: str = "0",
    w2w_coordination: str = "0",
    alloy_enabled: str = "0",
) -> dict[str, str]:
    extra_env = extra_env or {}
    z_ai_api_key = (
        extra_env.get("Z_AI_API_KEY")
        or extra_env.get("ANTHROPIC_AUTH_TOKEN")
        or ""
    )
    replacements = {
        "{host}": HOST,
        "{port}": str(PORT),
        "{workspace_id}": config.get("workspace_id", ""),
        "{workspace_path}": config.get("workspace_path", ""),
        "{session_id}": session_id,
        "{session_type}": config.get("session_type") or "worker",
        # Per-person Brainstormer owner identity. NULL columns (e.g. on a
        # Commander session) resolve to "" => owner, the single-operator
        # default. Brainstormer-owned sessions carry their real owner key.
        "{owner_actor_kind}": config.get("owner_actor_kind") or "",
        "{owner_actor_id}": config.get("owner_actor_id") or "",
        "{w2w_comms}": w2w_comms,
        "{w2w_context}": w2w_context,
        "{w2w_coordination}": w2w_coordination,
        "{alloy_enabled}": alloy_enabled,
        "{z_ai_api_key}": z_ai_api_key,
        "{zai_api_key}": z_ai_api_key,
        "{account_api_key}": z_ai_api_key,
    }
    resolved = {}
    for key, value in (raw_env or {}).items():
        text = str(value)
        for token, replacement in replacements.items():
            text = text.replace(token, str(replacement))
        resolved[key] = text
    return resolved


def _mcp_config_entry_for_server(
    srv: dict,
    resolved_env: dict[str, str],
    *,
    preserve_raw_env: bool = False,
) -> dict:
    server_type = str(srv.get("server_type") or "stdio").lower().replace("_", "-")
    entry_env = srv.get("env") if preserve_raw_env else resolved_env

    if server_type in {"http", "streamable-http", "streamablehttp"}:
        entry = {"type": "http", "url": srv["command"]}
        if entry_env:
            entry["headers"] = entry_env
        return entry

    if server_type == "sse":
        entry = {"type": "sse", "url": srv["command"]}
        if entry_env:
            entry["headers"] = entry_env
        return entry

    command = srv["command"]
    args = srv.get("args") or []
    # IVE's own stdio servers are seeded with command "python3", but the SYSTEM
    # python3 can be too old to even import them (observed live: macOS CLT ships
    # 3.9, mcp_server.py's PEP-604 annotations die at def-time, and the CLI
    # boots SILENTLY toolless — the Commander had hands on paper and none in
    # practice). The backend that writes this config is, by construction, a
    # working interpreter for its own scripts — so for our own backend scripts,
    # pin the entry to it instead of whatever "python3" resolves to.
    if command in ("python3", "python"):
        import sys
        from resource_path import backend_dir
        if any(isinstance(a, str) and a.startswith(str(backend_dir())) for a in args):
            command = sys.executable
    entry = {"command": command, "args": args}
    if entry_env:
        entry["env"] = entry_env
    return entry


# ─── MCP assembly: ONE implementation, every spawn path ──────────────────
# A Commander once booted with zero MCP tools despite a correct
# session_mcp_servers binding, because each spawn path carried its own copy
# of this logic (and the supervisor restart path had none at all). Anything
# that materializes a session's MCP bindings goes through
# _apply_session_mcp below — terminal start_pty, auto-start, and restart.


async def _load_session_w2w_flags(workspace_id: str) -> tuple[str, str, str]:
    """Snapshot a workspace's W2W flags as "0"/"1" strings for env injection.

    Read once per spawn so the worker MCP can pick them up from env instead
    of API-round-tripping back into a server that is still starting up.
    """
    comms = context = coordination = "0"
    try:
        db = await get_db()
        try:
            cur = await db.execute(
                "SELECT comms_enabled, context_sharing_enabled, "
                "coordination_enabled FROM workspaces WHERE id = ?",
                (workspace_id or "",),
            )
            row = await cur.fetchone()
            if row:
                comms = "1" if row["comms_enabled"] else "0"
                context = "1" if row["context_sharing_enabled"] else "0"
                coordination = "1" if row["coordination_enabled"] else "0"
        finally:
            await db.close()
    except Exception as exc:
        logger.debug("W2W env-flag fetch skipped: %s", exc)
    return comms, context, coordination


async def _load_session_mcp_servers(session_id: str, config: dict) -> list[dict]:
    """Return the MCP server rows bound to a session, args/env decoded.

    Also reconciles Z.AI attachments and writes back
    ``sessions.active_mcp_server_ids`` so the UI's "active" list always
    reflects what the spawn is about to materialize.
    """
    servers: list[dict] = []
    db = await get_db()
    try:
        await _sync_zai_mcp_servers_for_session(
            db,
            session_id,
            config.get("cli_type", "claude"),
            config.get("account_id"),
        )
        cur = await db.execute(
            """SELECT ms.*, sms.auto_approve_override
               FROM mcp_servers ms
               JOIN session_mcp_servers sms ON ms.id = sms.mcp_server_id
               WHERE sms.session_id = ?""",
            (session_id,),
        )
        for row in await cur.fetchall():
            srv = dict(row)
            srv["args"] = json.loads(srv["args"] or "[]")
            srv["env"] = json.loads(srv["env"] or "{}")
            servers.append(srv)

        await db.execute(
            "UPDATE sessions SET active_mcp_server_ids = ? WHERE id = ?",
            (json.dumps([s["id"] for s in servers]), session_id),
        )
        await db.commit()
    finally:
        await db.close()
    return servers


def _apply_frozen_mcp_binaries(servers: list[dict]) -> None:
    """In frozen builds, point builtin MCP servers at their compiled binaries."""
    from resource_path import is_frozen as _is_frozen
    if not _is_frozen():
        return
    from helper_command import BUILTIN_HELPERS, helper_command
    for srv in servers:
        helper = BUILTIN_HELPERS.get(srv.get("id"))
        if helper:
            command = helper_command(helper)
            srv["command"], srv["args"] = command[0], command[1:]


async def _register_mcp_add_server(session_obj: UnifiedSession, srv: dict,
                                   resolved_env: dict[str, str],
                                   effective_approve, workspace_path: str,
                                   subprocess_env: dict[str, str]) -> bool:
    """Register one server through profile-declared add/remove argv templates.

    Returns False when the identical registration is already in place (no
    config rewrite), True when it was (re)written.
    """
    if not workspace_path:
        raise UnsupportedMCPProfileError("mcp_add requires a workspace path")
    profile = session_obj.profile
    if not profile.mcp_add_argv or not profile.mcp_remove_argv:
        raise UnsupportedMCPProfileError(
            f"CLI profile '{profile.id}' has no verified mcp_add protocol"
        )
    add_cmd = _render_mcp_argv(
        session_obj,
        profile.mcp_add_argv,
        server_name=srv["server_name"],
        command=srv["command"],
        args=srv.get("args") or [],
        transport=srv.get("server_type", "stdio"),
        resolved_env=resolved_env,
        effective_approve=bool(effective_approve),
    )
    state_key = _mcp_add_state_key(session_obj, subprocess_env, srv["server_name"])
    if _MCP_ADD_STATE.get(state_key) == tuple(add_cmd):
        return False
    # Unknown until the add below succeeds.
    _MCP_ADD_STATE.pop(state_key, None)
    remove_cmd = _render_mcp_argv(
        session_obj,
        profile.mcp_remove_argv,
        server_name=srv["server_name"],
    )
    try:
        remove_proc = await _asyncio.create_subprocess_exec(
            *remove_cmd, cwd=workspace_path, env=subprocess_env,
            stdout=_asyncio.subprocess.DEVNULL,
            stderr=_asyncio.subprocess.DEVNULL,
        )
        await remove_proc.communicate()
    except Exception:
        pass

    proc = await _asyncio.create_subprocess_exec(
        *add_cmd, cwd=workspace_path, env=subprocess_env,
        stdout=_asyncio.subprocess.PIPE,
        stderr=_asyncio.subprocess.PIPE,
    )
    _stdout, stderr = await proc.communicate()
    if proc.returncode:
        detail = stderr.decode(errors="replace")[:400] if stderr else ""
        raise RuntimeError(
            f"MCP registration failed for {srv['server_name']} ({proc.returncode}): {detail}"
        )
    _MCP_ADD_STATE[state_key] = tuple(add_cmd)
    return True


async def _apply_session_mcp(session_obj: UnifiedSession, config: dict,
                             session_id: str,
                             extra_env: dict[str, str]) -> dict:
    """Materialize a session's MCP bindings onto ``session_obj``.

    THE MCP assembly. Covers all three strategies (config_file,
    global_config_file, mcp_add), the frozen-binary rewrite, the
    tester_headed Playwright override, auto-approve → allowed tools, the
    legacy ``sessions.mcp_config`` fallback, and Antigravity's
    always-needs-a-config rule.

    Returns ``{"servers": [...], "w2w": (comms, context, coordination),
    "config_path": str | None}``. The W2W flags are snapshotted here and
    handed back so callers can put them in the PTY env without re-querying.
    """
    w2w = await _load_session_w2w_flags(config.get("workspace_id", ""))
    servers = await _load_session_mcp_servers(session_id, config)

    subprocess_env = os.environ.copy()
    subprocess_env.update(extra_env)
    workspace_path = config.get("workspace_path", "") or ""
    strategy = session_obj.profile.mcp_strategy

    if strategy == "mcp_add":
        if not session_obj.profile.mcp_add_argv or not session_obj.profile.mcp_remove_argv:
            raise UnsupportedMCPProfileError(
                f"CLI profile '{session_obj.profile.id}' has no verified mcp_add protocol"
            )
    elif strategy == "config_file":
        if not session_obj.supports(Feature.MCP_CONFIG_PATH):
            raise UnsupportedMCPProfileError(
                f"CLI profile '{session_obj.profile.id}' cannot receive an MCP config path"
            )
    elif strategy == "config_override":
        pass  # Codex: `-c mcp_servers.*` on this process's argv only
    elif strategy == "global_config_file":
        if session_obj.profile.mcp_config_adapter != "antigravity":
            raise UnsupportedMCPProfileError(
                f"CLI profile '{session_obj.profile.id}' has no verified global MCP adapter"
            )
    else:
        raise UnsupportedMCPProfileError(
            f"CLI profile '{session_obj.profile.id}' does not declare an MCP strategy"
        )

    mcp_add_lock_held = False
    mcp_add_wrote = False
    if strategy == "mcp_add":
        await _MCP_ADD_LOCK.acquire()
        mcp_add_lock_held = True
    try:
        mcp_add_wrote = await _prune_mcp_add_servers(
            session_obj,
            {str(s.get("server_name") or "") for s in servers},
            workspace_path,
            subprocess_env,
        ) or False
        result = await _apply_session_mcp_servers(
            session_obj, config, session_id, extra_env, servers, w2w,
            strategy, workspace_path, subprocess_env,
        )
        mcp_add_wrote = mcp_add_wrote or result
        if strategy == "config_override":
            session_obj.launch_args.extend(await _codex_disable_stale_mcp_args(
                {str(s.get("server_name") or "") for s in servers}, extra_env))
    finally:
        if mcp_add_lock_held:
            if mcp_add_wrote:
                # Keep the next Codex start from rewriting the global config
                # before this session's CLI has read it.
                asyncio.ensure_future(_release_mcp_add_lock_later(_MCP_ADD_SETTLE_SECS))
            else:
                _MCP_ADD_LOCK.release()
    return await _finish_session_mcp(session_obj, config, session_id, extra_env, servers, w2w)


async def _apply_session_mcp_servers(session_obj: UnifiedSession, config: dict,
                                     session_id: str, extra_env: dict[str, str],
                                     servers: list, w2w: tuple, strategy: str,
                                     workspace_path: str,
                                     subprocess_env: dict[str, str]) -> bool:
    """Register/write the selected servers; True if an mcp_add config changed."""
    mcp_add_wrote = False
    if servers:
        # Per-session Playwright arg overrides. The tester_headed tag (the
        # "Show browser" checkbox in the Tester picker) strips --headless so
        # the browser is visible. Default is headless.
        try:
            session_tags = json.loads(config.get("tags") or "[]")
        except (TypeError, ValueError):
            session_tags = []
        if "tester_headed" in session_tags:
            for srv in servers:
                if srv["id"] == "builtin-playwright":
                    srv["args"] = [a for a in srv.get("args", []) if a != "--headless"]

        _apply_frozen_mcp_binaries(servers)

        mcp_json = {"mcpServers": {}}
        auto_approved_names: list[str] = []

        for srv in servers:
            resolved_env = _resolve_mcp_env_values(
                srv["env"],
                config,
                session_id,
                extra_env,
                w2w_comms=w2w[0],
                w2w_context=w2w[1],
                w2w_coordination=w2w[2],
                alloy_enabled="1" if config.get("alloy_enabled") else "0",
            )
            effective_approve = (
                srv["auto_approve_override"]
                if srv["auto_approve_override"] is not None
                else srv["auto_approve"]
            )
            if strategy == "mcp_add":
                if await _register_mcp_add_server(
                    session_obj, srv, resolved_env, effective_approve,
                    workspace_path, subprocess_env,
                ):
                    mcp_add_wrote = True
            elif strategy == "config_override":
                # Codex hands stdio MCP servers only an env allowlist plus the
                # configured env, so the session proof (see session_proofs)
                # must be configured explicitly for session-bound servers.
                if session_id and any(
                    "{session_id}" in str(v) for v in (srv.get("env") or {}).values()
                ):
                    import session_proofs
                    resolved_env = {
                        **resolved_env,
                        session_proofs.ENV_VAR: session_proofs.issue(session_id),
                    }
                session_obj.launch_args.extend(_codex_mcp_override_args(
                    srv["server_name"],
                    _mcp_config_entry_for_server(srv, resolved_env),
                    extra_env,
                ))
            else:
                mcp_json["mcpServers"][srv["server_name"]] = _mcp_config_entry_for_server(
                    srv,
                    resolved_env,
                    preserve_raw_env=strategy == "global_config_file",
                )
            if effective_approve:
                auto_approved_names.append(srv["server_name"])

        if strategy in ("mcp_add", "config_override"):
            if auto_approved_names and session_obj.supports(Feature.ALLOWED_MCP_SERVERS):
                session_obj.set(Feature.ALLOWED_MCP_SERVERS, auto_approved_names)
        elif strategy == "global_config_file":
            from antigravity_runtime import write_mcp_config as _write_agy_mcp_config
            agy_mcp_path = _write_agy_mcp_config(mcp_json, home=extra_env.get("HOME"))
            session_obj.set(Feature.MCP_CONFIG_PATH, str(agy_mcp_path))
        else:
            MCP_CONFIG_DIR.mkdir(parents=True, exist_ok=True)
            mcp_cfg_path = MCP_CONFIG_DIR / f"session-{session_id}.json"
            mcp_cfg_path.write_text(json.dumps(mcp_json, indent=2))
            session_obj.set(Feature.MCP_CONFIG_PATH, str(mcp_cfg_path))
            _raw_tools = session_obj.get(Feature.ALLOWED_TOOLS) or []
            existing_tools = (
                json.loads(_raw_tools) if isinstance(_raw_tools, str) else list(_raw_tools)
            )
            for sname in auto_approved_names:
                existing_tools.append(f"mcp__{sname}__*")
            if existing_tools:
                session_obj.set(Feature.ALLOWED_TOOLS, existing_tools)
    elif config.get("session_type") == "commander" and strategy == "mcp_add":
        if session_obj.supports(Feature.ALLOWED_MCP_SERVERS):
            session_obj.set(Feature.ALLOWED_MCP_SERVERS, ["commander"])
    elif config.get("mcp_config"):
        # Legacy fallback: session row still carries an old config file path.
        session_obj.set(Feature.MCP_CONFIG_PATH, config["mcp_config"])
        is_commander = config.get("session_type") == "commander"
        if is_commander or config.get("auto_approve_mcp"):
            try:
                mcp_path = _Path(config["mcp_config"])
                if mcp_path.exists():
                    mcp_data = json.loads(mcp_path.read_text())
                    _raw_tools = session_obj.get(Feature.ALLOWED_TOOLS) or []
                    existing_tools = (
                        json.loads(_raw_tools) if isinstance(_raw_tools, str)
                        else list(_raw_tools)
                    )
                    for server_name in mcp_data.get("mcpServers", {}):
                        from mcp_server import TOOLS as _MCP_TOOLS
                        for tool_name in _MCP_TOOLS:
                            existing_tools.append(f"mcp__{server_name}__{tool_name}")
                    if existing_tools:
                        session_obj.set(Feature.ALLOWED_TOOLS, existing_tools)
            except Exception as e:
                logger.warning(f"Failed to resolve legacy MCP tools: {e}")
    return mcp_add_wrote


async def _finish_session_mcp(session_obj: UnifiedSession, config: dict,
                              session_id: str, extra_env: dict[str, str],
                              servers: list, w2w: tuple) -> dict:
    strategy = session_obj.profile.mcp_strategy
    # Profiles using the verified Antigravity adapter require a valid config,
    # even when no servers were selected.
    if (
        session_obj.profile.mcp_config_adapter == "antigravity"
        and not session_obj.get(Feature.MCP_CONFIG_PATH)
    ):
        from antigravity_runtime import ensure_mcp_config_valid as _ensure_agy_mcp_config
        agy_mcp_path = _ensure_agy_mcp_config(home=extra_env.get("HOME"))
        session_obj.set(Feature.MCP_CONFIG_PATH, str(agy_mcp_path))

    config_path = session_obj.get(Feature.MCP_CONFIG_PATH)
    logger.info(
        "Session %s MCP assembly (%s/%s): %d server(s) [%s]",
        session_id[:8],
        session_obj.profile.id,
        strategy,
        len(servers),
        ", ".join(sorted(str(s.get("server_name") or "?") for s in servers)) or "none",
    )
    return {
        "servers": servers,
        "w2w": w2w,
        "config_path": str(config_path) if config_path else None,
    }


def _api_key_env_for_session(cli_type: str, account: dict, model: str | None = None) -> dict[str, str]:
    """Return per-session API-key env vars only when provider matches the CLI."""
    from crypto import decrypt_secret
    key = (decrypt_secret(account.get("api_key")) or "").strip()
    if not key:
        return {}
    provider = _normalize_api_key_provider(account.get("api_key_provider"), key)
    spec = API_KEY_PROVIDERS.get(provider)
    if not spec or cli_type not in spec["session_clis"]:
        return {}

    if _is_claude_gateway_provider(provider):
        base_url = _base_url_for_account(account, provider)
        if not base_url:
            return {}
        env = {env_name: key for env_name in spec["env"]}
        env[spec.get("base_url_env", "ANTHROPIC_BASE_URL")] = base_url
        env["CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY"] = "1"
        env.update(spec.get("model_env") or {})
        if provider in {"z_ai", "z_ai_glm51"}:
            env.setdefault("API_TIMEOUT_MS", "3000000")

        selected_model = (model or "").strip()
        if selected_model and selected_model.lower() not in _CLAUDE_MODEL_ALIASES:
            env["ANTHROPIC_MODEL"] = selected_model
            env["ANTHROPIC_DEFAULT_OPUS_MODEL"] = selected_model
            env["ANTHROPIC_DEFAULT_SONNET_MODEL"] = selected_model
            env["ANTHROPIC_DEFAULT_HAIKU_MODEL"] = selected_model
        return env

    env = {env_name: key for env_name in spec["env"]}
    return env


_CLAUDE_GATEWAY_SETTINGS_ENV_KEYS = {
    "ANTHROPIC_AUTH_TOKEN",
    "ANTHROPIC_BASE_URL",
    "ANTHROPIC_MODEL",
    "ANTHROPIC_DEFAULT_OPUS_MODEL",
    "ANTHROPIC_DEFAULT_SONNET_MODEL",
    "ANTHROPIC_DEFAULT_HAIKU_MODEL",
    "API_TIMEOUT_MS",
    "CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY",
}


def _read_json_object(path: _Path) -> dict:
    try:
        if path.exists():
            data = json.loads(path.read_text())
            if isinstance(data, dict):
                return data
    except (OSError, json.JSONDecodeError):
        pass
    return {}


def _ensure_claude_first_run_state(
    extra_env: dict[str, str],
    workspace_path: str | None = None,
) -> None:
    """Mark IVE-managed Claude profiles as already past interactive setup."""
    config_env = get_profile("claude").config_dir_env
    cfg_dir = extra_env.get(config_env) if config_env else None
    if not cfg_dir:
        return

    state_path = _Path(cfg_dir) / ".claude.json"
    try:
        state_path.parent.mkdir(parents=True, exist_ok=True)
        data = _read_json_object(state_path)
        source = _read_json_object(_Path.home() / ".claude.json")

        if not data.get("firstStartTime"):
            data["firstStartTime"] = datetime.datetime.now(datetime.UTC).isoformat()
        if source.get("userID") and not data.get("userID"):
            data["userID"] = source["userID"]
        if source.get("claudeCodeFirstTokenDate") and not data.get("claudeCodeFirstTokenDate"):
            data["claudeCodeFirstTokenDate"] = source["claudeCodeFirstTokenDate"]
        data["hasCompletedOnboarding"] = True
        data["lastOnboardingVersion"] = source.get("lastOnboardingVersion") or data.get("lastOnboardingVersion") or "2.1.133"
        data.setdefault("shiftEnterKeyBindingInstalled", True)
        data.setdefault("opusProMigrationComplete", True)
        data.setdefault("sonnet1m45MigrationComplete", True)

        if workspace_path:
            abs_workspace = str(_Path(workspace_path).expanduser().resolve())
            projects = data.get("projects")
            if not isinstance(projects, dict):
                projects = {}
                data["projects"] = projects
            project_state = projects.get(abs_workspace)
            if not isinstance(project_state, dict):
                project_state = {}
                projects[abs_workspace] = project_state
            project_state["hasTrustDialogAccepted"] = True
            project_state["hasCompletedProjectOnboarding"] = True
            project_state.setdefault("projectOnboardingSeenCount", 1)

        state_path.write_text(json.dumps(data, indent=2) + "\n")
    except OSError as e:
        logger.warning("Failed to seed Claude first-run state %s: %s", state_path, e)


def _write_claude_account_settings_env(extra_env: dict[str, str], account_env: dict[str, str]) -> None:
    """Persist managed Claude gateway env vars into the isolated account profile."""
    config_env = get_profile("claude").config_dir_env
    cfg_dir = extra_env.get(config_env) if config_env else None
    if not cfg_dir or not account_env:
        return

    settings_path = _Path(cfg_dir) / "settings.json"
    try:
        settings_path.parent.mkdir(parents=True, exist_ok=True)
        if settings_path.exists():
            try:
                data = json.loads(settings_path.read_text())
            except json.JSONDecodeError:
                logger.warning("Claude settings JSON was invalid, replacing env block: %s", settings_path)
                data = {}
        else:
            data = {}

        if not isinstance(data, dict):
            data = {}
        env = data.get("env")
        if not isinstance(env, dict):
            env = {}
            data["env"] = env

        changed = False
        for key in sorted(_CLAUDE_GATEWAY_SETTINGS_ENV_KEYS):
            value = account_env.get(key)
            if value is None:
                if key in env:
                    del env[key]
                    changed = True
                continue
            if env.get(key) != value:
                env[key] = value
                changed = True

        if changed or not settings_path.exists():
            settings_path.write_text(json.dumps(data, indent=2) + "\n")
    except OSError as e:
        logger.warning("Failed to write Claude account settings env %s: %s", settings_path, e)


async def _account_for_session(config: dict) -> dict | None:
    account_id = config.get("account_id")
    if not account_id:
        return None
    db_acc = await get_db()
    try:
        cur_acc = await db_acc.execute(
            "SELECT * FROM accounts WHERE id = ?",
            (account_id,),
        )
        acc_row = await cur_acc.fetchone()
        return dict(acc_row) if acc_row else None
    finally:
        await db_acc.close()


async def _launch_model_for_session(config: dict) -> str | None:
    """Return the CLI-visible model for launch.

    Claude Code may reject non-Claude model ids on the command line. For
    Anthropic-compatible gateway accounts, keep the session's selected model in
    env mappings and launch Claude Code through the stable sonnet alias.
    """
    model = config.get("model")
    if (config.get("cli_type") or "claude").lower() != "claude":
        return model
    if not model or str(model).lower() in _CLAUDE_MODEL_ALIASES:
        return model
    acc = await _account_for_session(config)
    if not acc or not acc.get("api_key"):
        return model
    from crypto import decrypt_secret
    provider = _normalize_api_key_provider(acc.get("api_key_provider"), decrypt_secret(acc.get("api_key")))
    if _is_claude_gateway_provider(provider):
        return "sonnet"
    return model


async def _launch_config_for_session(config: dict) -> dict:
    launch_config = dict(config)
    launch_config["model"] = await _launch_model_for_session(config)
    return launch_config


async def _prepare_session_cli_env(config: dict, session_id: str) -> dict[str, str]:
    """Return env vars for an IVE-managed CLI profile plus optional account auth."""
    cli_type = (config.get("cli_type") or "claude").lower()
    account_id = config.get("account_id")
    extra_env: dict[str, str] = {}
    account_key_env: dict[str, str] = {}
    account_key_is_gateway = False
    profile_account_id: str | None = None

    if account_id:
        db_acc = await get_db()
        try:
            cur_acc = await db_acc.execute(
                "SELECT * FROM accounts WHERE id = ?",
                (account_id,),
            )
            acc_row = await cur_acc.fetchone()
            if not acc_row:
                raise RuntimeError(f"account {account_id} does not exist")
            acc = dict(acc_row)
            if acc.get("api_key"):
                account_key_env = _api_key_env_for_session(cli_type, acc, config.get("model"))
                if not account_key_env:
                    raise RuntimeError(
                        f"API-key account '{acc.get('name')}' is not compatible with {cli_type}"
                    )
                extra_env.update(account_key_env)
                from crypto import decrypt_secret
                provider = _normalize_api_key_provider(acc.get("api_key_provider"), decrypt_secret(acc.get("api_key")))
                account_key_is_gateway = _is_claude_gateway_provider(provider)
                if cli_type == "claude" and account_key_is_gateway:
                    profile_account_id = acc["id"]
            elif acc.get("type") == "oauth":
                if acc.get("cli_type") != cli_type:
                    raise RuntimeError(
                        f"OAuth account '{acc.get('name')}' belongs to {acc.get('cli_type') or 'no CLI'}, not {cli_type}"
                    )
                from account_sandbox import verify_account_credentials
                verification = await asyncio.to_thread(
                    verify_account_credentials,
                    acc["id"],
                    cli_type,
                )
                if not acc.get("credentials_verified_at") or not verification.get("verified"):
                    raise RuntimeError(
                        f"OAuth account '{acc.get('name')}' has no verified credentials in its own sandbox"
                    )
                if acc.get("status") not in {"active", "quota_exceeded"}:
                    raise RuntimeError(
                        f"OAuth account '{acc.get('name')}' is not usable ({acc.get('status')})"
                    )
                profile_account_id = acc["id"]
        finally:
            await db_acc.close()

    extra_env.update(prepare_ive_cli_env(cli_type, account_id=profile_account_id))
    extra_env["IVE_PROVIDER_LIMITS_SCOPE"] = account_id or "host"
    extra_env["IVE_ALLOY_ENABLED"] = "1" if config.get("alloy_enabled") else "0"
    if cli_type == "claude":
        from session_budget import claude_compaction_env
        extra_env.update(claude_compaction_env())
        _ensure_claude_first_run_state(extra_env, config.get("workspace_path"))
    if cli_type == "claude" and account_key_is_gateway and account_key_env:
        _write_claude_account_settings_env(extra_env, account_key_env)

    try:
        from hook_installer import (
            HookInstallError,
            codex_hooks_notice,
            install_hooks_for_managed_profile,
        )
        hook_trust = install_hooks_for_managed_profile(cli_type, extra_env.get("HOME"))
        trust_notice = codex_hooks_notice(hook_trust) if cli_type == "codex" else None
        if trust_notice:
            logger.warning("Session %s: %s", session_id[:8], trust_notice)
            try:
                await broadcast({
                    "session_id": session_id,
                    "type": "hooks_notice",
                    "cli": cli_type,
                    "message": trust_notice,
                    "reason": "codex_hooks_untrusted",
                    "untrusted": (hook_trust or {}).get("ive_untrusted") or [],
                })
            except Exception as exc:
                logger.warning("Could not surface Codex hook trust notice: %s", exc)
        elif cli_type == "codex" and isinstance(hook_trust, dict) and hook_trust.get("auto_trusted"):
            logger.info(
                "Session %s: trusted %d IVE Codex hook(s) in %s",
                session_id[:8], hook_trust["auto_trusted"], hook_trust.get("path"),
            )
    except HookInstallError as exc:
        raise RuntimeError(
            f"CLI profile '{cli_type}' hooks are unsupported: {exc}"
        ) from exc
    except (OSError, ValueError) as exc:
        raise RuntimeError(
            f"Managed hook installation failed for '{cli_type}': {exc}"
        ) from exc

    if profile_account_id:
        logger.info(
            "Session %s using sandboxed %s HOME: %s",
            session_id,
            cli_type,
            extra_env.get("HOME"),
        )
    else:
        logger.debug(
            "Session %s using IVE-managed %s HOME: %s",
            session_id,
            cli_type,
            extra_env.get("HOME"),
        )

    return extra_env


async def _experimental_safety_gate_enabled() -> bool:
    db_sg = await get_db()
    try:
        cur_sg = await db_sg.execute(
            "SELECT value FROM app_settings WHERE key = 'experimental_safety_gate'"
        )
        row = await cur_sg.fetchone()
        return bool(row and row["value"] == "on")
    finally:
        await db_sg.close()


async def _apply_worker_safety_gate_permission(
    config: dict,
    session_id: str,
    runtime_env: dict[str, str],
    *,
    auto_start: bool = False,
) -> str:
    """Keep the user's native agent mode; IVE checks are additional gates.

    A configured safety hook must not silently turn Auto/Default into Bypass.
    Overview and Terminal share this mode, including every resumed launch.
    Hook installation and the safety gate's own enforcement remain unchanged.
    """
    return config.get("permission_mode") or "auto"


def _as_string_list(value) -> list[str]:
    if value is None or value == "":
        return []
    if isinstance(value, list):
        return [str(v) for v in value]
    if isinstance(value, str):
        try:
            decoded = json.loads(value)
            if isinstance(decoded, list):
                return [str(v) for v in decoded]
        except json.JSONDecodeError:
            pass
        return [value]
    return [str(value)]


def _activate_antigravity_session_rules_dir(
    session_obj,
    session_id: str,
    prompt_text: str | None,
) -> str | None:
    """Attach an IVE-owned temp Rules workspace to this agy process."""
    if not (prompt_text or "").strip():
        return None
    from antigravity_runtime import prepare_session_rules_dir
    rules_dir = prepare_session_rules_dir(session_id, prompt_text or "")
    if not rules_dir:
        raise RuntimeError("Antigravity session Rules directory was not created")
    add_dirs = _as_string_list(session_obj.get(Feature.ADD_DIRS))
    rules_dir_s = str(rules_dir)
    if rules_dir_s not in add_dirs:
        add_dirs.append(rules_dir_s)
    session_obj.set(Feature.ADD_DIRS, add_dirs)
    return rules_dir_s


async def _record_session_runtime_home(
    session_id: str,
    cli_type: str | None,
    cli_home: str | None,
) -> None:
    """Persist the HOME needed to find native transcripts later."""
    if (cli_type or "claude").lower() != "antigravity":
        return
    db_rt = await get_db()
    try:
        await db_rt.execute(
            "UPDATE sessions SET cli_runtime_home = ? WHERE id = ?",
            (cli_home, session_id),
        )
        await db_rt.commit()
    finally:
        await db_rt.close()


async def _fail_session_start(
    session_id: str,
    message: str,
    reason: str = "startup_failed",
) -> None:
    """Mark a session start as failed before a PTY is launched."""
    db_fail = await get_db()
    try:
        await db_fail.execute(
            "UPDATE sessions SET status = 'error' WHERE id = ?",
            (session_id,),
        )
        await db_fail.commit()
    finally:
        await db_fail.close()
    await broadcast({
        "session_id": session_id,
        "type": "error",
        "message": message,
    })
    await broadcast({
        "session_id": session_id,
        "type": "status",
        "status": "error",
        "pty_alive": False,
        "reason": reason,
    })
    # Brain session-feedback loop (producer): this is the canonical pre-PTY
    # blocker. Emit the failed-to-start event so the Brain can learn it. The
    # workspace_id lookup + emit are best-effort — never break session-start.
    try:
        ws_id = None
        db_ws = await get_db()
        try:
            cur_ws = await db_ws.execute(
                "SELECT workspace_id FROM sessions WHERE id = ?", (session_id,)
            )
            ws_row = await cur_ws.fetchone()
            if ws_row:
                ws_id = ws_row["workspace_id"]
        finally:
            await db_ws.close()
        await bus.emit(CommanderEvent.SESSION_FAILED_TO_START, {
            "session_id": session_id,
            "workspace_id": ws_id,
            "reason": reason,
        }, source="api")
    except Exception:
        logger.debug("SESSION_FAILED_TO_START emit skipped (_fail_session_start)", exc_info=True)


async def broadcast(event: dict):
    data = json.dumps(event)
    dead = []
    embedded_session = event.get("session")
    if not isinstance(embedded_session, dict):
        embedded_session = None
    embedded_task = event.get("task")
    if not isinstance(embedded_task, dict):
        embedded_task = None
    session_id = event.get("session_id") or (
        embedded_session.get("id") if embedded_session else None
    )
    session = embedded_session or (
        await get_session_config(session_id) if session_id else None
    )
    workspace_id = event.get("workspace_id") or (
        session.get("workspace_id") if session else None
    ) or (
        embedded_task.get("workspace_id") if embedded_task else None
    )
    for ws in list(ws_clients):
        ctx = getattr(ws, "_ive_auth_ctx", None)
        if session_id:
            if session is not None:
                if not _session_readable_to_auth(session, ctx):
                    continue
            elif not bool(getattr(ctx, "is_owner", False)):
                # A missing/deleted row cannot be safely scoped for a joiner.
                continue
        elif workspace_id and not _workspace_visible_to_auth(workspace_id, ctx):
            continue
        try:
            await ws.send_str(data)
        except (ConnectionResetError, ConnectionError, RuntimeError):
            dead.append(ws)
    for ws in dead:
        ws_clients.discard(ws)
    # A queued test may have waited for this tester's current turn. Resume on
    # confirmed idle without interrupting that turn or requiring a new enqueue.
    if event.get("type") == "session_state" and event.get("state") == "idle" and session and workspace_id:
        try:
            testing_tags = json.loads(session.get("tags") or "[]")
        except (ValueError, TypeError):
            testing_tags = []
        if "capability_testing" in testing_tags:
            asyncio.create_task(_process_test_queue(workspace_id))


async def _broadcast_commander_event(envelope: dict) -> None:
    """Client sink for event_bus: same scoping rules as broadcast().

    Events tied to a session or workspace go through broadcast(). Events
    with neither cannot be scoped for a joiner, so only owners get them.
    """
    if envelope.get("session_id") or envelope.get("workspace_id"):
        await broadcast(envelope)
        return
    data = json.dumps(envelope)
    for ws in list(ws_clients):
        if not bool(getattr(getattr(ws, "_ive_auth_ctx", None), "is_owner", False)):
            continue
        try:
            await ws.send_str(data)
        except (ConnectionResetError, ConnectionError, RuntimeError):
            ws_clients.discard(ws)


# ─── PTY output batching ──────────────────────────────────────────────────
# Batch PTY output per session into ~16ms windows (one frame) before sending
# over WebSocket. This prevents Ink's full-screen TUI renders from being
# split across multiple messages, which causes garbled terminal output.

import asyncio as _asyncio
import time as _time

_output_buffers: dict[str, list[bytes]] = {}
_output_timers: dict[str, _asyncio.TimerHandle] = {}
# Per-session incremental UTF-8 decoder — holds incomplete codepoints across
# flushes so a multi-byte char split between chunks doesn't render as U+FFFD.
_output_decoders: dict[str, codecs.IncrementalDecoder] = {}
# Per-session bytes held back at flush time because they look like the start
# of an incomplete ANSI escape sequence. Prepended to the next flush.
_output_held_bytes: dict[str, bytes] = {}
_output_inferred_status: dict[str, str] = {}
_session_cli_type_cache: dict[str, str] = {}
_terminal_streams: dict[str, TerminalStream] = {}
_terminal_stream_locks: dict[str, asyncio.Lock] = {}
# Effective permission ceiling of each live PTY. A Code caller may attach to a
# process only when this says the process was actually launched with Code flags.
_pty_effective_modes: dict[str, str] = {}
# Per-session PTY start timestamp. During the first _INITIAL_COLLAPSE_MS
# after spawn, _flush_output looks for a full-screen-clear (\x1b[2J) in
# the accumulated buffer and drops bytes before it. This collapses the
# Claude Code "render banner once at default size, then SIGWINCH from
# fit-addon, then redraw at real size" sequence into a single render —
# the user no longer sees both banners in scrollback.
_pty_start_time: dict[str, float] = {}
_INITIAL_COLLAPSE_MS = 1500


def mark_pty_started(session_id: str, mode: str = "full") -> None:
    """Begin the initial-render collapse window for `session_id`."""
    _pty_start_time[session_id] = _time.time()
    _pty_effective_modes[session_id] = mode
    _terminal_streams[session_id] = TerminalStream()
    _terminal_stream_locks[session_id] = asyncio.Lock()


def _terminal_stream(session_id: str) -> TerminalStream:
    stream = _terminal_streams.get(session_id)
    if stream is None:
        stream = TerminalStream()
        _terminal_streams[session_id] = stream
    return stream


def _terminal_stream_lock(session_id: str) -> asyncio.Lock:
    lock = _terminal_stream_locks.get(session_id)
    if lock is None:
        lock = asyncio.Lock()
        _terminal_stream_locks[session_id] = lock
    return lock


async def _send_terminal_resume(
    ws: web.WebSocketResponse,
    session_id: str,
    *,
    after_sequence=None,
    generation=None,
) -> None:
    """Atomically enqueue a replay followed by the live-stream watermark."""
    config = await get_session_config(session_id)
    if not config or not _session_readable_to_auth(
        config, getattr(ws, "_ive_auth_ctx", None)
    ):
        return
    await _flush_output(session_id)
    async with _terminal_stream_lock(session_id):
        replay = _terminal_stream(session_id).replay(
            after_sequence=after_sequence,
            generation=generation,
        )
        if replay.reset_required:
            await ws.send_json({
                "session_id": session_id,
                "type": "terminal_reset",
                "stream_generation": replay.generation,
                "reason": replay.reason,
            })
        for frame in replay.frames:
            await ws.send_json({
                "session_id": session_id,
                "type": "output",
                "data": frame.data,
                "sequence": frame.sequence,
                "stream_generation": replay.generation,
                "replay": True,
            })
        geometry = pty_mgr.get_geometry(session_id) or {}
        await ws.send_json({
            "session_id": session_id,
            "type": "terminal_resumed",
            "pty_alive": pty_mgr.is_alive(session_id),
            "stream_generation": replay.generation,
            "latest_sequence": replay.latest_sequence,
            "gap_reset": replay.reset_required,
            **geometry,
        })
        subscriptions = getattr(ws, "_ive_terminal_sessions", None)
        if subscriptions is not None:
            subscriptions.add(session_id)


def _split_ansi_tail(data: bytes) -> tuple[bytes, bytes]:
    """Split data into (safe_to_emit, hold_for_next_flush).

    Detects an incomplete ANSI escape sequence at the tail of `data` and
    returns the trailing partial bytes separately so they can be combined
    with the next chunk. xterm.js's parser resets per write(), so emitting
    half of a CSI ends up rendering the leading bytes as garbled state and
    the trailing bytes as literal text — visible as the position drift in
    streamed Claude output.
    """
    if not data:
        return b"", b""
    last_esc = data.rfind(b"\x1b")
    if last_esc == -1:
        return data, b""
    rest = data[last_esc + 1:]
    if not rest:
        return data[:last_esc], data[last_esc:]
    first = rest[0]
    if first == 0x5B:  # CSI: ESC [ <params 0x30-0x3F>* <inter 0x20-0x2F>* <final 0x40-0x7E>
        for b in rest[1:]:
            if 0x40 <= b <= 0x7E:
                return data, b""  # complete CSI
            if not (0x20 <= b <= 0x3F):
                return data, b""  # malformed; let xterm handle
        return data[:last_esc], data[last_esc:]  # incomplete CSI
    if first == 0x5D:  # OSC: ESC ] ... <BEL or ST>
        if 0x07 in rest or b"\x1b\\" in rest:
            return data, b""
        return data[:last_esc], data[last_esc:]
    if first == 0x4F:  # SS3: ESC O <one byte>
        return (data, b"") if len(rest) >= 2 else (data[:last_esc], data[last_esc:])
    # Other ESC + 1 byte sequences are already complete (rest[0] is the byte)
    return data, b""


def _schedule_flush(session_id: str):
    if session_id in _output_timers:
        return  # Already scheduled
    loop = _asyncio.get_event_loop()
    _output_timers[session_id] = loop.call_later(0.016, lambda: _asyncio.ensure_future(_flush_output(session_id)))

# ─── PTY output flush ─────────────────────────────────────────────────
# Session state detection is primarily handled by CLI lifecycle hooks
# (see hooks.py). Some CLIs, notably Antigravity, can render activity before
# hook state arrives, so output flush also has a narrow provider-specific
# fallback for active/inactive status.


async def _cached_session_cli_type(session_id: str) -> str:
    cached = _session_cli_type_cache.get(session_id)
    if cached:
        return cached
    db = await get_db()
    try:
        cur = await db.execute("SELECT cli_type FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
        cli_type = (row["cli_type"] if row else None) or "claude"
        cli_type = str(cli_type).lower()
        _session_cli_type_cache[session_id] = cli_type
        return cli_type
    finally:
        await db.close()


async def _maybe_mark_claude_interrupted(session_id: str, screen: str | None = None, source: str = "interrupt") -> bool:
    """Clear active work or a cancelled approval after the confirmed empty
    prompt appears (Claude sends no Stop hook on Esc)."""
    import hooks as _hooks
    if _hooks._hook_sessions.get(session_id, {}).get("state") not in {"working", "prompting"}:
        return False
    if screen is None:
        screen = capture_proc.get_screen(session_id) or capture_proc.get_buffer(session_id, 80)
    if not _hooks.claude_screen_shows_interrupt(screen):
        return False
    return await _hooks.mark_interrupted(session_id, source)


_CLAUDE_INTERRUPT_INPUTS = {"\x1b", "\x03"}
_CLAUDE_INTERRUPT_CHECK_DELAYS = (0.4, 1.0, 2.5)


async def _confirm_claude_interrupt_after_input(session_id: str) -> None:
    """After a bare Esc / Ctrl+C, re-check the screen a few times: the
    interrupt notice may land after the last output-triggered check."""
    elapsed = 0.0
    for delay in _CLAUDE_INTERRUPT_CHECK_DELAYS:
        await _asyncio.sleep(delay - elapsed)
        elapsed = delay
        if not pty_mgr.is_alive(session_id):
            return
        try:
            if await _maybe_mark_claude_interrupted(session_id, source="interrupt_input"):
                return
        except Exception as exc:
            logger.debug("Interrupt check failed for %s: %s", session_id[:8], exc)
            return


async def _maybe_broadcast_output_inferred_status(session_id: str) -> None:
    if not pty_mgr.is_alive(session_id):
        return
    cli_type = await _cached_session_cli_type(session_id)
    if cli_type in {"claude", "codex"}:
        from session_attention import get_attention, observe_terminal
        screen = capture_proc.get_screen(session_id) or capture_proc.get_buffer(session_id, 80)
        if observe_terminal(session_id, screen):
            await broadcast({"type": "session_attention", "session_id": session_id,
                             "attention": get_attention(session_id)})
        if cli_type == "claude":
            await _maybe_mark_claude_interrupted(session_id, screen, "interrupt_output")
    if cli_type != "antigravity":
        return

    text = capture_proc.get_buffer(session_id, 160)
    desired = None
    try:
        from hooks import get_session_logical_status
        if get_session_logical_status(session_id, True, "idle") == "running":
            desired = "running"
    except Exception:
        desired = None

    if desired is None:
        if _looks_antigravity_busy(cli_type, text):
            desired = "running"
        elif _output_inferred_status.get(session_id) == "running" and _looks_ready_for_input(cli_type, text):
            desired = "idle"

    if desired and _output_inferred_status.get(session_id) != desired:
        _output_inferred_status[session_id] = desired
        await broadcast({
            "session_id": session_id,
            "type": "status",
            "status": desired,
            "pty_alive": True,
        })


async def _flush_output(session_id: str):
    _output_timers.pop(session_id, None)
    chunks = _output_buffers.pop(session_id, [])
    held = _output_held_bytes.pop(session_id, b"")
    if not chunks and not held:
        return

    # If new chunks arrived, combine with held bytes and re-split the tail.
    # If only held bytes remain (timer fired with no new output), force-emit
    # them — they're either a genuinely partial sequence Claude never finished
    # or held bytes from a prior flush whose follow-up never came.
    if chunks:
        raw = held + b"".join(chunks)
    else:
        raw = held

    # During the initial-render window, drop everything before the LAST
    # "fresh-frame boundary" so Claude's pre-resize banner doesn't pile
    # up in xterm's scrollback alongside the post-resize one.
    #
    # Claude Code does NOT emit \x1b[2J (verified empirically — count=0
    # across a full startup capture). Its rendering strategy is cursor-
    # home (\x1b[H) followed by paint-over. So \x1b[H is the only
    # available frame boundary; collapsing to the last one drops the
    # earlier render's bytes before they reach xterm.
    #
    # We still also accept \x1b[2J as a boundary for tools that DO emit
    # it (Gemini and any non-Claude future CLI). After the window
    # expires, both sequences pass through untouched — clears outside
    # the startup window are legitimate.
    start_t = _pty_start_time.get(session_id)
    if start_t is not None:
        if (_time.time() - start_t) * 1000 < _INITIAL_COLLAPSE_MS:
            # Take whichever comes later (the actual most-recent frame
            # boundary). Position 0 doesn't count — that's the start of
            # a single-render stream and there's nothing to drop.
            last_2j = raw.rfind(b"\x1b[2J")
            last_h  = raw.rfind(b"\x1b[H")
            last_boundary = max(last_2j, last_h)
            if last_boundary > 0:
                raw = raw[last_boundary:]
                # Reset the UTF-8 decoder — we may have just thrown
                # away continuation bytes it was waiting on.
                _output_decoders.pop(session_id, None)
        else:
            _pty_start_time.pop(session_id, None)

    if chunks:
        safe, hold = _split_ansi_tail(raw)
    else:
        safe, hold = raw, b""

    if hold:
        _output_held_bytes[session_id] = hold
        # Schedule a stale flush so genuinely-partial sequences eventually
        # reach the terminal even if no further output arrives.
        if session_id not in _output_timers:
            loop = _asyncio.get_event_loop()
            _output_timers[session_id] = loop.call_later(
                0.1, lambda: _asyncio.ensure_future(_flush_output(session_id)))

    if not safe:
        return

    decoder = _output_decoders.get(session_id)
    if decoder is None:
        decoder = codecs.getincrementaldecoder("utf-8")(errors="replace")
        _output_decoders[session_id] = decoder
    text = decoder.decode(safe)
    if not text:
        return
    config = await get_session_config(session_id)
    if not config:
        return
    async with _terminal_stream_lock(session_id):
        stream = _terminal_stream(session_id)
        frame = stream.append(text)
        msg = json.dumps({
            "session_id": session_id,
            "type": "output",
            "data": text,
            "sequence": frame.sequence,
            "stream_generation": stream.generation,
        })
        dead = []
        for ws in list(ws_clients):
            if session_id not in getattr(ws, "_ive_terminal_sessions", set()):
                continue
            if not _session_readable_to_auth(
                config, getattr(ws, "_ive_auth_ctx", None)
            ):
                continue
            try:
                await ws.send_str(msg)
            except (ConnectionResetError, ConnectionError, RuntimeError):
                dead.append(ws)
        for ws in dead:
            ws_clients.discard(ws)

    try:
        await _maybe_broadcast_output_inferred_status(session_id)
    except Exception as exc:
        logger.debug("Output-inferred status skipped for %s: %s", session_id[:8], exc)

# ─── Trust prompt auto-acceptance ─────────────────────────────────────
# Both CLIs show interactive trust prompts for untrusted workspace folders.
# These fire BEFORE hooks are initialized, so hooks can't detect them.
# Output only schedules a check; acceptance uses the current visible menu.
_TRUST_PATTERNS = [
    b"trust",                      # Also catches Codex's "Trust and continue"
    b"trust this folder",           # Claude: "Yes, I trust this folder"
    b"I trust this folder",         # Claude alternative
    b"safety check",                # Claude: "Quick safety check" header
    b"Itrustthisfolder",            # Claude TUI (spaces stripped in raw bytes)
    b"safetycheck",                 # Claude TUI (spaces stripped)
    b"Yes, I trust",                # Claude with spaces
    b"Trust folder",                # Gemini: "1. Trust folder"
    b"Trust parent folder",         # Gemini: "2. Trust parent folder"
    # Codex 0.16x onboarding (tui/src/onboarding/directory_trust.rs):
    # "Trust this folder? Codex can read, edit, and run files here ..." with
    # "› 1. Trust and continue / 2. Open restricted". The highlighted default
    # is "Trust and continue", so Enter accepts (and codex persists
    # [projects."<repo root>"] trust_level = "trusted" itself).
    b"Trust and continue",
    b"Trustandcontinue",            # Codex TUI (spaces become cursor moves)
    b"Trustthisfolder",
]
_trust_handled: dict[str, float] = {}  # Track last auto-accept time per session (allow multiple)
_startup_prompt_handled: dict[str, float] = {}
_startup_prompt_recent: dict[str, str] = {}
_bad_thinking_signature_recovery: set[str] = set()
_bad_thinking_signature_exits: set[str] = set()


def _strip_pty_control_bytes(data: bytes) -> bytes:
    """Remove common PTY control sequences before prompt pattern matching."""
    import re as _re
    ansi_re = _re.compile(rb'\x1b\[[0-9;]*[a-zA-Z~]|\x1b\][^\x07]*\x07|\x1b[()][A-Z0-9]')
    return ansi_re.sub(b'', data)


def _has_codex_update_prompt_text(text: str, require_skip_choice: bool = False) -> bool:
    lower = (text or "").lower()
    has_update_notice = (
        "update available" in lower
        or "brew upgrade --cask codex" in lower
        or "update codex by running" in lower
    )
    if not has_update_notice:
        return False
    has_update_choice = any(
        marker in lower
        for marker in (
            "update now",
            "update codex",
            "upgrade now",
            "upgrade codex",
            "run brew upgrade",
            "brew upgrade --cask codex",
        )
    )
    has_skip_choice = any(
        marker in lower
        for marker in (
            "skip until next version",
            "skip this version",
            "skip for now",
            "not now",
            "later",
            "continue without updating",
            "\n2.",
            " 2.",
        )
    )
    has_numbered_menu = (
        ("\n1." in lower or " 1." in lower)
        and (
            "\n2." in lower or " 2." in lower
            or "\n3." in lower or " 3." in lower
        )
    )
    if require_skip_choice:
        return has_update_choice and (has_skip_choice or has_numbered_menu)
    return has_update_choice


def _check_startup_selection_prompts(session_id: str, data: bytes) -> bool:
    """Handle startup menus where pressing Enter can select a bad default.

    Codex's update prompt defaults to "Update now"; automated sessions should
    continue with the installed CLI instead of changing binaries mid-session.
    """
    import time as _time
    last = _startup_prompt_handled.get(session_id, 0)
    if _time.monotonic() - last < 30.0:
        return False

    stripped = _strip_pty_control_bytes(data)
    try:
        chunk_text = stripped.decode("utf-8", errors="replace")
    except Exception:
        return False
    text = (_startup_prompt_recent.get(session_id, "") + chunk_text)[-6000:]
    _startup_prompt_recent[session_id] = text

    if not _has_codex_update_prompt_text(text, require_skip_choice=True):
        return False

    _startup_prompt_handled[session_id] = _time.monotonic()

    async def _dismiss_codex_update():
        await _asyncio.sleep(0.5)
        for _ in range(3):
            if not pty_mgr.is_alive(session_id):
                return
            pty_mgr.write(session_id, b"\x1b")
            await _asyncio.sleep(0.15)
        logger.info("Dismissed Codex startup update prompt for session %s", session_id[:8])

    _asyncio.ensure_future(_dismiss_codex_update())
    return True


def _trust_prompt_selection(text: str) -> dict | None:
    """Recognize a complete folder-trust menu and its explicit selection.

    A quoted old menu above a returned input prompt is not an active menu.
    Missing/ambiguous selection is safe to display as blocked, never to accept.
    """
    text = _strip_pty_control_bytes((text or "").encode("utf-8")).decode("utf-8", errors="replace")
    # CLI menus use NBSP too; preserve line boundaries and normalize only
    # horizontal spacing before recognizing the selected trust option.
    text = re.sub(r"[^\S\r\n\v\f\x85\u2028\u2029]", " ", text)
    compact = _compact_cli_text(text)
    if "yes,itrustthisfolder" in compact and "no,exit" in compact:
        cli, wanted, labels = "claude", "yes,itrustthisfolder", {"yes,itrustthisfolder", "no,exit"}
    elif ("trustandcontinue" in compact and ("quit" in compact or "openrestricted" in compact)
          and ("folderaccess" in compact or "trustthisfolder" in compact)):
        # Codex 0.16x: "› 1. Trust and continue" plus either "2. Quit" or
        # "2. Open restricted" (tui/src/onboarding/directory_trust.rs).
        cli, wanted, labels = "codex", "trustandcontinue", {"trustandcontinue", "quit", "openrestricted"}
    elif "trustfolder" in compact and "trustparentfolder" in compact:
        cli, wanted, labels = "gemini", "trustfolder", {"trustfolder", "trustparentfolder", "donottrust", "don'ttrust"}
    else:
        return None
    pattern = re.compile(
        r"(?m)^[ \t]*(?P<cursor>[❯›>●])?[ \t]*(?:\d+[.)]\s*)?"
        r"(?P<label>Yes,\s*I\s*trust\s*this\s*folder|No,\s*exit|"
        r"Trust\s+and\s+continue|Quit|Open\s+restricted|Trust\s+parent\s+folder|Trust\s+folder|Do\s+not\s+trust|Don't\s+trust)[ \t]*(?=\n|$)",
        re.IGNORECASE,
    )
    options = [match for match in pattern.finditer(text) if _compact_cli_text(match["label"]) in labels]
    values = [_compact_cli_text(match["label"]) for match in options]
    if len(options) < 2 or values.count(wanted) != 1 or len(set(values)) != len(values):
        return None
    if re.search(r"(?m)^[ \t]*[❯›>][ \t]*(?:$|try\b|type\b)", text[options[-1].end():], re.IGNORECASE):
        return None
    selected = [index for index, match in enumerate(options) if match["cursor"]]
    return {"cli_type": cli, "options": tuple(values), "target": values.index(wanted),
            "selected": selected[0] if len(selected) == 1 else None}


def _check_auto_trust(session_id: str, data: bytes):
    """Select the affirmative folder-trust option, then verify before Enter."""
    import time as _time
    last = _trust_handled.get(session_id, 0)
    if _time.monotonic() - last < 2.0:
        return  # rate limit — don't spam Enter
    # Strip ANSI sequences for pattern matching (raw PTY output is full of them)
    stripped = _strip_pty_control_bytes(data)
    text_lower = stripped.lower()
    raw_lower = data.lower()
    for pattern in _TRUST_PATTERNS:
        pat_lower = pattern.lower()
        if pat_lower in text_lower or pat_lower in raw_lower:
            _trust_handled[session_id] = _time.monotonic()
            attempt = _trust_handled[session_id]
            # _pty_start_time expires after the initial-render window; it is
            # not a lifetime token. The stream changes only for a new PTY.
            lifetime = _terminal_streams.get(session_id)

            def same_lifetime():
                return (pty_mgr.is_alive(session_id)
                        and _trust_handled.get(session_id) == attempt
                        and _terminal_streams.get(session_id) is lifetime)

            def current_selection():
                if not same_lifetime():
                    return None
                # Never accept from historical output if the screen is blank.
                try:
                    return _trust_prompt_selection(capture_proc.get_screen(session_id))
                except Exception:
                    return None

            async def _auto_accept():
                await _asyncio.sleep(0.5)
                menu = current_selection()
                if not menu or menu["selected"] is None:
                    return
                signature = (menu["cli_type"], menu["options"])
                for _ in range(len(menu["options"])):
                    menu = current_selection()
                    if not menu or (menu["cli_type"], menu["options"]) != signature or menu["selected"] is None:
                        return
                    if menu["selected"] == menu["target"]:
                        # A delayed redraw or manual action must not turn an
                        # earlier affirmative selection into an accidental exit.
                        await _asyncio.sleep(0.15)
                        confirm = current_selection()
                        if (confirm and (confirm["cli_type"], confirm["options"]) == signature
                                and confirm["selected"] == confirm["target"]
                                and pty_mgr.write(session_id, b"\r")):
                            logger.info("Confirmed affirmative folder trust for session %s", session_id[:8])
                        return
                    direction = 1 if menu["selected"] < menu["target"] else -1
                    if not pty_mgr.write(session_id, b"\x1b[B" if direction > 0 else b"\x1b[A"):
                        return
                    previous = menu["selected"]
                    for _ in range(15):
                        await _asyncio.sleep(0.1)
                        if not same_lifetime():
                            return
                        updated = current_selection()
                        if not updated or updated["selected"] is None:
                            continue  # Ink can clear the cursor while repainting.
                        if (updated["cli_type"], updated["options"]) != signature:
                            return
                        if updated["selected"] != previous:
                            break
                    else:
                        return  # No verified navigation: never guess with Enter.
            _asyncio.ensure_future(_auto_accept())
            return


def _has_bad_thinking_signature_error(data: bytes) -> bool:
    try:
        text = data.decode("utf-8", errors="replace").lower()
    except Exception:
        return False
    has_thinking_block_reference = (
        "thinking block" in text
        or "`thinking`" in text
        or "`redacted_thinking`" in text
        or "redacted_thinking" in text
    )
    return (
        "invalid signature in thinking block" in text
        or (
            "api error: 400" in text
            and has_thinking_block_reference
            and "signature" in text
        )
        or (
            "api error: 400" in text
            and has_thinking_block_reference
            and (
                "cannot be modified" in text
                or "must remain as they were" in text
            )
        )
    )


async def _recover_bad_thinking_signature(session_id: str):
    """Recover from unrecoverable Claude native-resume transcript corruption.

    Claude's extended-thinking blocks are verified by the API. If a saved
    native JSONL transcript contains an invalid/stale/mutated thinking block,
    every resume attempt loops on errors like:
      API Error: 400 ... Invalid signature in thinking block
      API Error: 400 ... `thinking` or `redacted_thinking` blocks in the
      latest assistant message cannot be modified

    Commander cannot repair Claude's signed block. The only reliable recovery
    is to stop this PTY, clear the native resume id, and let the next start
    create a fresh Claude conversation instead of replaying the corrupt one.
    """
    if session_id in _bad_thinking_signature_recovery:
        return
    _bad_thinking_signature_recovery.add(session_id)
    _bad_thinking_signature_exits.add(session_id)

    config = await get_session_config(session_id)
    cli_type = (config or {}).get("cli_type", "claude")
    if cli_type != "claude":
        _bad_thinking_signature_recovery.discard(session_id)
        _bad_thinking_signature_exits.discard(session_id)
        return

    logger.warning("Recovering session %s from Claude thinking-block resume error", session_id[:8])

    db = await get_db()
    try:
        await db.execute(
            """UPDATE sessions
               SET native_session_id = NULL,
                   status = 'error'
               WHERE id = ?""",
            (session_id,),
        )
        await db.commit()
    finally:
        await db.close()

    await broadcast({
        "session_id": session_id,
        "type": "output",
        "data": (
            "\r\n\x1b[31m[Commander detected a corrupt Claude resume transcript: "
            "Claude rejected a signed thinking block from the saved transcript. Resume has been disabled for "
            "this session; restart it to continue in a fresh Claude conversation.]\x1b[0m\r\n"
        ),
    })
    await broadcast({
        "session_id": session_id,
        "type": "status",
        "status": "error",
        "pty_alive": False,
        "reason": "claude_thinking_block_resume_error",
    })
    await _stop_session_expected(session_id)


async def handle_pty_output(session_id: str, data: bytes):
    import shell_session as _shell_session  # plain terminals (cli_type "shell")
    # A plain terminal gets no agent prompt automation: IVE never types into
    # the user's shell (trust menus, update prompts, resume recovery).
    if _session_cli_type_cache.get(session_id) != _shell_session.SHELL_CLI_TYPE:
        startup_selection_handled = _check_startup_selection_prompts(session_id, data)
        if not startup_selection_handled:
            _check_auto_trust(session_id, data)
        if _has_bad_thinking_signature_error(data):
            _asyncio.ensure_future(_recover_bad_thinking_signature(session_id))
    if session_id not in _output_buffers:
        _output_buffers[session_id] = []
    _output_buffers[session_id].append(data)
    _schedule_flush(session_id)




async def _mark_session_pty_started(session_id: str) -> None:
    """Persist the PTY lifetime before output or a fast exit can race us."""
    import session_supervisor
    session_supervisor.mark_started(session_id)
    db = await get_db()
    try:
        await db.execute(
            """UPDATE sessions
               SET status = 'running', last_active_at = datetime('now')
               WHERE id = ?""",
            (session_id,),
        )
        await db.commit()
    finally:
        await db.close()


async def _stop_session_expected(session_id: str) -> None:
    """Stop a PTY without allowing its signal exit to masquerade as a crash."""
    import session_supervisor
    session_supervisor.expect_exit(session_id)
    await pty_mgr.stop_session(session_id)


async def handle_pty_input_error(session_id: str, info: dict):
    """Queued input was dropped after a stalled write: tell the user."""
    await broadcast({
        "session_id": session_id,
        "type": "error",
        "reason": info.get("reason") or "input_stalled",
        "message": (
            f"Input to session {session_id[:8]} stalled and was not submitted "
            f"({info.get('dropped', 0)} queued input(s) discarded). Check the terminal and resend."
        ),
    })


async def handle_pty_exit(session_id: str, code: int):
    import shell_session as _shell_session  # plain terminals (cli_type "shell")
    pending_timer = _output_timers.pop(session_id, None)
    if pending_timer is not None:
        pending_timer.cancel()
    await _flush_output(session_id)
    import session_supervisor
    expected_exit = session_supervisor.exit_is_expected(session_id)
    classification = await session_supervisor.record_exit(session_id, code)
    db = await get_db()
    try:
        if classification == "crashed":
            await db.execute(
                "UPDATE sessions SET status = 'error' WHERE id = ?",
                (session_id,),
            )
        else:
            # A clean end (user stop, exit 0, shell closed) is 'stopped', so a
            # reload still tells it apart from a session that never started
            # ('idle'). Preserve a more specific terminal state set before an
            # expected stop (for example auth_failed or transcript corruption).
            await db.execute(
                """UPDATE sessions SET status = 'stopped'
                   WHERE id = ? AND status NOT IN ('auth_failed', 'error')""",
                (session_id,),
            )
        await db.commit()
    finally:
        await db.close()
    from hooks import cleanup_session
    cleanup_session(session_id)
    await broadcast({
        "session_id": session_id,
        "type": "exit",
        "code": code,
        "classification": classification,
    })
    _terminal_streams.pop(session_id, None)
    _terminal_stream_locks.pop(session_id, None)
    if (_session_cli_type_cache.get(session_id) == _shell_session.SHELL_CLI_TYPE
            or pty_mgr.is_session_start_blocked(session_id)):
        # Plain terminals and sessions being deleted must not start background
        # reflection/summary jobs that outlive their registration.
        for _state in (_input_bufs, _session_turns, _input_esc, _output_decoders,
                       _output_held_bytes, _output_inferred_status,
                       _session_cli_type_cache, _pty_start_time, _session_workspace):
            _state.pop(session_id, None)
        return
    if session_id in _bad_thinking_signature_exits:
        _bad_thinking_signature_exits.discard(session_id)
        _bad_thinking_signature_recovery.discard(session_id)
        await broadcast({
            "session_id": session_id,
            "type": "status",
            "status": "error",
            "pty_alive": False,
            "reason": "claude_thinking_block_resume_error",
        })
    # Selected memory engine's optional session-finalization work.
    if extension_host.available("myelin"):
        try:
            _fire_and_forget(_maybe_run_myelin_sleep(session_id))
        except Exception:
            logger.debug("Memory finalization trigger failed for %s", session_id[:8])
    # Session Advisor: analyze session quality in background
    try:
        from session_advisor import analyze_session, clear_intent
        _fire_and_forget(analyze_session(session_id))
        clear_intent(session_id)
    except Exception:
        logger.debug("Session advisor cleanup skipped for %s", session_id[:8])
    # Skill Suggester: cleanup session state
    try:
        from skill_suggester import clear_session as clear_skill_session
        clear_skill_session(session_id)
    except Exception:
        logger.debug("Skill suggester cleanup skipped for %s", session_id[:8])
    # Auto-distill: extract reusable artifact on clean exit
    try:
        if not expected_exit:
            _fire_and_forget(_maybe_auto_distill(session_id, code))
    except Exception:
        logger.debug("Auto-distill skipped for %s", session_id[:8])
    # Optional product-owned learned-context extraction.
    if extension_host.available("myelin"):
        try:
            _fire_and_forget(_maybe_auto_extract_knowledge(session_id, code))
        except Exception:
            logger.debug("Learned-context extraction skipped for %s", session_id[:8])
    # Auto-summary: generate short session summary on exit
    try:
        if not expected_exit:
            _fire_and_forget(_maybe_auto_summarize(session_id))
    except Exception:
        logger.debug("Auto-summary skipped for %s", session_id[:8])
    # Cleanup module-level per-session state to prevent memory leaks
    _trust_handled.pop(session_id, None)
    _startup_prompt_handled.pop(session_id, None)
    _startup_prompt_recent.pop(session_id, None)
    _input_bufs.pop(session_id, None)
    _session_turns.pop(session_id, None)
    _input_esc.pop(session_id, None)
    _output_decoders.pop(session_id, None)
    _output_held_bytes.pop(session_id, None)
    _output_inferred_status.pop(session_id, None)
    _session_cli_type_cache.pop(session_id, None)
    _pty_start_time.pop(session_id, None)
    _session_workspace.pop(session_id, None)


async def _maybe_auto_distill(session_id: str, exit_code: int):
    """Auto-distill a session on clean exit if experimental flag is enabled.

    Gate conditions:
      - exit_code == 0 (clean exit)
      - experimental_auto_distill == "on"
      - 5+ conversation turns
      - session_type is worker or default (not commander/tester/documentor)
      - not a worktree/branch session
    """
    if exit_code != 0:
        return

    db = await get_db()
    try:
        # Check experimental flag
        cur = await db.execute(
            "SELECT value FROM app_settings WHERE key = 'experimental_auto_distill'"
        )
        row = await cur.fetchone()
        if not row or row["value"] != "on":
            return

        # Get session info
        cur = await db.execute(
            """SELECT s.*, w.path AS workspace_path, w.orchestration_policy, w.inherit_orchestration_policy_from
               FROM sessions s
               LEFT JOIN workspaces w ON s.workspace_id = w.id
               WHERE s.id = ?""",
            (session_id,),
        )
        sess = await cur.fetchone()
        if not sess:
            return
        sess = dict(sess)
        if sess.get("inherit_orchestration_policy_from"):
            from db import resolve_workspace_orchestration_policy
            sess["orchestration_policy"] = await resolve_workspace_orchestration_policy(db, sess["workspace_id"])

        # Gate: skip special session types
        if sess.get("session_type") in ("commander", "tester", "documentor"):
            return

        # Gate: skip worktree/branch sessions
        if sess.get("worktree"):
            return

        # Gate: check conversation length (need 5+ turns)
        messages = []
        native_sid = sess.get("native_session_id")
        workspace_path = sess.get("workspace_path")
        if native_sid and workspace_path:
            transcript_file = _get_native_transcript_path(
                sess.get("cli_type"),
                workspace_path,
                native_sid,
                cli_home=_session_transcript_home(sess),
            )
            if transcript_file and transcript_file.exists():
                messages = read_session_messages(str(transcript_file))

        if not messages:
            cur = await db.execute(
                "SELECT * FROM messages WHERE session_id = ? ORDER BY created_at",
                (session_id,),
            )
            rows = await cur.fetchall()
            messages = [dict(r) for r in rows]

        if len(messages) < 5:
            return

        # Auto-detect best artifact type based on conversation content
        conversation = _format_conversation_for_distill(messages, max_chars=6000)
        if not conversation or len(conversation.strip()) < 100:
            return

        artifact_type = _detect_distill_type(conversation)
        cli = sess.get("cli_type") or "claude"
        session_model = sess.get("model")
        session_name = sess.get("name") or session_id[:8]
    finally:
        await db.close()

    import background_ai
    # Build and launch distill job
    prompt_template = _DISTILL_PROMPTS[artifact_type]
    prompt = prompt_template.format(
        conversation=conversation,
        instructions="This is an automatic distill — extract the single most reusable artifact from the session.",
    )
    receipt = await background_ai.claim("distill", session_id, conversation, prompt_chars=len(prompt))
    if receipt is None:
        return

    job_id = str(uuid.uuid4())
    _background_jobs[job_id] = {
        "type": "distill",
        "status": "queued",
        "session_id": session_id,
        "artifact_type": artifact_type,
    }

    from llm_router import model_id_for_provider
    try:
        model_id = await model_id_for_provider(cli, session_model)
    except Exception as exc:
        _background_jobs.pop(job_id, None)
        await background_ai.finish(receipt, success=False)
        logger.warning("auto-distill provider resolution failed: %s", exc)
        return

    import asyncio as _asyncio
    _asyncio.ensure_future(_run_background_llm_job(
        job_id=job_id,
        job_type="distill",
        model_id=model_id,
        prompt=prompt,
        extra={
            "session_id": session_id,
            "session_name": session_name,
            "artifact_type": artifact_type,
            "auto": True,
        },
        automatic_receipt=receipt,
    ))
    logger.info("Auto-distill started for session %s (type=%s)", session_id[:8], artifact_type)


def _detect_distill_type(conversation: str) -> str:
    """Heuristic to pick the best artifact type for auto-distill.

    Analyzes conversation text with keyword counting — no LLM call needed.
    """
    text_lower = conversation.lower()

    # Count correction indicators
    corrections = sum(1 for phrase in [
        "no, ", "not that", "actually,", "instead,", "wrong", "don't do",
        "stop ", "that's not", "let me rephrase", "i meant",
    ] if phrase in text_lower)

    # Count multi-step workflow indicators
    steps = sum(1 for phrase in [
        "step 1", "step 2", "first,", "then,", "next,", "finally,",
        "after that", "now let's", "phase 1", "phase 2",
    ] if phrase in text_lower)

    # Count convention/pattern indicators
    patterns = sum(1 for phrase in [
        "always ", "never ", "convention", "pattern", "style ",
        "architecture", "structure", "naming", "format",
    ] if phrase in text_lower)

    if corrections >= 3:
        return "guideline"  # corrections → extract rules to prevent recurrence
    elif steps >= 4:
        return "cascade"    # multi-step → extract as reusable cascade
    elif patterns >= 3:
        return "guideline"  # conventions → extract as guideline
    else:
        return "prompt"     # default → extract as reusable prompt template
















async def _maybe_auto_summarize(session_id: str):
    """Generate a 1-2 sentence summary for a session on exit.

    Gate: explicit summary opt-in, 3+ messages and no existing summary.
    """
    import background_ai
    if not await background_ai.enabled("summary"):
        return
    db = await get_db()
    try:
        cur = await db.execute(
            """SELECT s.*, w.path AS workspace_path, w.orchestration_policy, w.inherit_orchestration_policy_from
               FROM sessions s
               LEFT JOIN workspaces w ON s.workspace_id = w.id
               WHERE s.id = ?""",
            (session_id,),
        )
        sess = await cur.fetchone()
        if not sess:
            return
        sess = dict(sess)
        if sess.get("inherit_orchestration_policy_from"):
            from db import resolve_workspace_orchestration_policy
            sess["orchestration_policy"] = await resolve_workspace_orchestration_policy(db, sess["workspace_id"])

        # Skip if summary already exists
        if sess.get("summary"):
            return

        # Reuse paid-for context instead of asking another model on exit.
        cur_digest = await db.execute(
            "SELECT task_summary FROM session_digests WHERE session_id = ?", (session_id,)
        )
        existing_digest = await cur_digest.fetchone()
        if existing_digest and (existing_digest["task_summary"] or "").strip():
            summary = existing_digest["task_summary"].strip()[:1000]
            await db.execute("UPDATE sessions SET summary = ? WHERE id = ?", (summary, session_id))
            await db.commit()
            await broadcast({"type": "session_summary", "session_id": session_id, "summary": summary})
            return

        # Fetch conversation messages (JSONL first, then DB)
        messages = []
        native_sid = sess.get("native_session_id")
        workspace_path = sess.get("workspace_path")
        if native_sid and workspace_path:
            transcript_file = _get_native_transcript_path(
                sess.get("cli_type"),
                workspace_path,
                native_sid,
                cli_home=_session_transcript_home(sess),
            )
            if transcript_file and transcript_file.exists():
                messages = read_session_messages(str(transcript_file))

        if not messages:
            cur2 = await db.execute(
                "SELECT * FROM messages WHERE session_id = ? ORDER BY created_at",
                (session_id,),
            )
            rows = await cur2.fetchall()
            messages = [dict(r) for r in rows]

        if len(messages) < 3:
            return

        conversation = _format_conversation_for_distill(messages, max_chars=6000)
        if not conversation or len(conversation.strip()) < 50:
            return

        # Fetch session digest for extra context if available
        digest_context = ""
        try:
            cur3 = await db.execute(
                "SELECT task_summary, discoveries, decisions FROM session_digests WHERE session_id = ?",
                (session_id,),
            )
            digest = await cur3.fetchone()
            if digest:
                parts = []
                if digest["task_summary"]:
                    parts.append(f"Task: {digest['task_summary']}")
                if digest["discoveries"] and digest["discoveries"] != "[]":
                    parts.append(f"Discoveries: {digest['discoveries']}")
                if digest["decisions"] and digest["decisions"] != "[]":
                    parts.append(f"Decisions: {digest['decisions']}")
                if parts:
                    digest_context = "\n\nWorker digest:\n" + "\n".join(parts)
        except Exception:
            pass

        try:
            from orchestration_policy import role_model
            policy_cli, policy_model = role_model(sess.get("orchestration_policy"), "summary")
        except Exception:
            policy_cli, policy_model = None, None
        cli = policy_cli or sess.get("cli_type") or "claude"
    finally:
        await db.close()

    # Generate summary via LLM
    from llm_router import call_json, model_id_for_provider
    try:
        model_id = await model_id_for_provider(cli, policy_model)
        summary_result = await background_ai.call_json(
            "summary", session_id, model_id=model_id,
            prompt=(
                "Summarize this coding session in 1-2 concise sentences. "
                "Focus on what was accomplished or attempted. Be specific about the task, not generic.\n\n"
                f"Session transcript:\n{conversation}{digest_context}"
            ),
            system=(
                "You are a concise summarizer. Return exactly one JSON object "
                'with a string field named summary: {"summary":"..."}.'
            ),
            timeout_s=30,
            allow_fallback=False,
        )
        if summary_result is None:
            return
        summary = str(summary_result.get("summary") or "").strip()
        if not summary or len(summary) < 10:
            return

        db2 = await get_db()
        try:
            await db2.execute(
                "UPDATE sessions SET summary = ? WHERE id = ?",
                (summary, session_id),
            )
            await db2.commit()
        finally:
            await db2.close()

        await broadcast({
            "type": "session_summary",
            "session_id": session_id,
            "summary": summary,
        })
        logger.info("Auto-summary generated for session %s", session_id[:8])
    except Exception as e:
        logger.warning("Auto-summary failed for %s: %s", session_id[:8], e)


async def _maybe_unarchive_on_input(session_id: str):
    """Auto-unarchive a session when the user sends new input to it."""
    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT archived FROM sessions WHERE id = ?", (session_id,)
        )
        row = await cur.fetchone()
        if row and row["archived"]:
            await db.execute(
                "UPDATE sessions SET archived = 0 WHERE id = ?", (session_id,)
            )
            await db.commit()
            await broadcast({
                "type": "session_archived",
                "session_id": session_id,
                "archived": 0,
            })
            logger.info("Auto-unarchived session %s on new input", session_id[:8])
    finally:
        await db.close()


# ─── Background task registry (prevents GC of fire-and-forget tasks) ──────
_bg_tasks: set[_asyncio.Task] = set()
_server_stopping = False

def _fire_and_forget(coro):
    """Schedule a coroutine as a background task without risk of GC."""
    if _server_stopping:
        coro.close()
        return
    task = _asyncio.create_task(coro)
    _bg_tasks.add(task)
    task.add_done_callback(_bg_tasks.discard)


async def _settle_background_tasks(grace: float = 0.5, cancel_timeout: float = 5.0) -> None:
    """Finish short writes, then cancel optional work before closing the loop."""
    tasks = {task for task in _bg_tasks if not task.done() and task is not asyncio.current_task()}
    if not tasks:
        return
    done, pending = await asyncio.wait(tasks, timeout=grace)
    for task in pending:
        task.cancel()
    if pending:
        cancelled, pending = await asyncio.wait(pending, timeout=cancel_timeout)
        done |= cancelled
    for task in done:
        if not task.cancelled():
            error = task.exception()
            if error:
                logger.debug("Background task ended during server stop: %s", error)
    if pending:
        logger.warning("%d background task(s) exceeded the cancellation deadline", len(pending))


# ─── Branch session creation ─────────────────────────────────────────────

async def _open_original_as_tab(branch_session_id: str, original_native_id: str):
    """After /branch, open the ORIGINAL conversation as a new Commander tab.

    The current PTY (branch_session_id) is now running the branch.  We create
    a sibling session for the original conversation so the user can see both
    side-by-side.  The new session gets --resume <original_native_id> when its
    PTY starts.
    """
    db = await get_db()
    try:
        # Look up the branch session (was the parent before /branch)
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (branch_session_id,))
        parent = await cur.fetchone()
        if not parent:
            return
        parent = dict(parent)

        # Guard: don't create a duplicate if we already have a session for this native ID
        cur = await db.execute(
            "SELECT id FROM sessions WHERE native_session_id = ? AND id != ?",
            (original_native_id, branch_session_id),
        )
        if await cur.fetchone():
            return

        # Create session for the original conversation
        import uuid as _uuid
        new_id = str(_uuid.uuid4())
        original_name = parent["name"] or "Session"
        # Rename the branch session to indicate it's a branch
        branch_name = f"{original_name} (branch)"
        await db.execute(
            "UPDATE sessions SET name = ? WHERE id = ?",
            (branch_name, branch_session_id),
        )

        # ── Resolve branch group (peer linkage) ─────────────────────────
        from hooks import _generate_branch_label
        if parent.get("branch_group"):
            branch_group = parent["branch_group"]
            branch_label = parent.get("branch_label", "")
        else:
            branch_group = str(_uuid.uuid4())
            cur = await db.execute(
                "SELECT DISTINCT branch_label FROM sessions WHERE workspace_id = ? AND branch_label IS NOT NULL",
                (parent["workspace_id"],),
            )
            existing = {row["branch_label"] for row in await cur.fetchall()}
            branch_label = _generate_branch_label(branch_group, existing)
            # Tag the branch session (which was the original before /branch)
            await db.execute(
                "UPDATE sessions SET branch_group = ?, branch_label = ? WHERE id = ?",
                (branch_group, branch_label, branch_session_id),
            )

        await db.execute(
            """INSERT INTO sessions
               (id, workspace_id, name, model, permission_mode, effort,
                budget_usd, system_prompt, allowed_tools, disallowed_tools,
                add_dirs, cli_type, parent_session_id, native_session_id,
                branch_group, branch_label)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (new_id, parent["workspace_id"], original_name,
             _model_for_storage(
                 get_profile(parent.get("cli_type", "claude")),
                 parent.get("model"),
                 parent.get("session_type"),
             ),
             parent["permission_mode"], parent["effort"],
             parent.get("budget_usd"), parent.get("system_prompt"),
             parent.get("allowed_tools"), parent.get("disallowed_tools"),
             parent.get("add_dirs"), parent.get("cli_type", "claude"),
             branch_session_id, original_native_id,
             branch_group, branch_label),
        )

        # Copy guidelines from the branch session (skip deleted guidelines)
        cur = await db.execute(
            """SELECT sg.guideline_id FROM session_guidelines sg
               JOIN guidelines g ON g.id = sg.guideline_id
               WHERE sg.session_id = ?""",
            (branch_session_id,),
        )
        for row in await cur.fetchall():
            await db.execute(
                "INSERT OR IGNORE INTO session_guidelines (session_id, guideline_id) VALUES (?, ?)",
                (new_id, row["guideline_id"]),
            )

        # Copy MCP servers from the branch session (skip deleted servers)
        cur = await db.execute(
            """SELECT sm.mcp_server_id, sm.auto_approve_override FROM session_mcp_servers sm
               JOIN mcp_servers m ON m.id = sm.mcp_server_id
               WHERE sm.session_id = ?""",
            (branch_session_id,),
        )
        for row in await cur.fetchall():
            await db.execute(
                "INSERT OR IGNORE INTO session_mcp_servers (session_id, mcp_server_id, auto_approve_override) VALUES (?, ?, ?)",
                (new_id, row["mcp_server_id"], row["auto_approve_override"]),
            )

        await db.commit()

        # Clear stale native_session_id on the branch session — it still holds
        # the ORIGINAL's UUID but the PTY is now running a different conversation.
        # The next hook event from the branch will re-capture the correct ID.
        await db.execute(
            "UPDATE sessions SET native_session_id = NULL WHERE id = ?",
            (branch_session_id,),
        )
        await db.commit()
        from hooks import clear_native_id_cache
        clear_native_id_cache(branch_session_id)

        # Fetch the new session and broadcast
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (new_id,))
        new_session = dict(await cur.fetchone())

        # Re-fetch branch session so frontend gets updated branch_group/label + name
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (branch_session_id,))
        updated_branch = dict(await cur.fetchone())

        await broadcast({
            "type": "session_created",
            "session": new_session,
            "auto_open": True,
            "parent_session_id": branch_session_id,
            "updated_parent": updated_branch,
        })
        # Also broadcast the rename of the branch session
        await broadcast({
            "type": "session_renamed",
            "session_id": branch_session_id,
            "name": branch_name,
        })

        logger.info(
            "Branch detected: opened original %s as tab (branch=%s)",
            new_id[:8], branch_session_id[:8],
        )
    except Exception as e:
        logger.exception("Failed to open original as tab after /branch: %s", e)
    finally:
        await db.close()


# ─── Gemini /branch — Commander-layer implementation ─────────────────────
#
# Gemini CLI has no native /branch.  We intercept the slash command in the
# WebSocket input handler and implement branching ourselves: create a session
# for the original conversation (resumable via --resume), then stop + restart
# the current PTY fresh so it becomes the "branch."

async def _maybe_handle_gemini_branch(session_id: str) -> bool:
    """Intercept /branch for Gemini sessions (no native support).

    Returns True if handled (caller should swallow the input).
    """
    buf = _input_bufs.get(session_id, "").strip()
    if buf != "/branch":
        return False

    config = await get_session_config(session_id)
    if not config or config.get("cli_type") != "gemini":
        return False

    native_sid = config.get("native_session_id")
    if not native_sid:
        pty_mgr.write(session_id,
                      b"\r\n\x1b[33m[No conversation to branch \xe2\x80\x94 start chatting first]\x1b[0m\r\n")
        return True

    import uuid as _uuid
    from hooks import _generate_branch_label

    db = await get_db()
    try:
        # Guard: don't create duplicate
        cur = await db.execute(
            "SELECT id FROM sessions WHERE native_session_id = ? AND id != ?",
            (native_sid, session_id),
        )
        if await cur.fetchone():
            pty_mgr.write(session_id,
                          b"\r\n\x1b[33m[Branch already exists for this conversation]\x1b[0m\r\n")
            return True

        new_id = str(_uuid.uuid4())
        original_name = config["name"] or "Session"
        branch_name = f"{original_name} (branch)"

        # ── Branch group ──────────────────────────────────────────────
        if config.get("branch_group"):
            branch_group = config["branch_group"]
            branch_label = config.get("branch_label", "")
        else:
            branch_group = str(_uuid.uuid4())
            cur = await db.execute(
                "SELECT DISTINCT branch_label FROM sessions "
                "WHERE workspace_id = ? AND branch_label IS NOT NULL",
                (config["workspace_id"],),
            )
            existing = {row["branch_label"] for row in await cur.fetchall()}
            branch_label = _generate_branch_label(branch_group, existing)
            # Tag the branch session (current)
            await db.execute(
                "UPDATE sessions SET branch_group = ?, branch_label = ?, name = ? WHERE id = ?",
                (branch_group, branch_label, branch_name, session_id),
            )

        # ── Insert original session ───────────────────────────────────
        await db.execute(
            """INSERT INTO sessions
               (id, workspace_id, name, model, permission_mode, effort,
                budget_usd, system_prompt, allowed_tools, disallowed_tools,
                add_dirs, cli_type, parent_session_id, native_session_id,
                branch_group, branch_label)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (new_id, config["workspace_id"], original_name,
             _model_for_storage(get_profile("gemini"), config.get("model"), config.get("session_type")),
             config["permission_mode"], config["effort"],
             config.get("budget_usd"), config.get("system_prompt"),
             config.get("allowed_tools"), config.get("disallowed_tools"),
             config.get("add_dirs"), "gemini",
             session_id, native_sid,
             branch_group, branch_label),
        )

        # ── Copy guidelines ───────────────────────────────────────────
        cur = await db.execute(
            """SELECT sg.guideline_id FROM session_guidelines sg
               JOIN guidelines g ON g.id = sg.guideline_id
               WHERE sg.session_id = ?""",
            (session_id,),
        )
        for row in await cur.fetchall():
            await db.execute(
                "INSERT OR IGNORE INTO session_guidelines (session_id, guideline_id) VALUES (?, ?)",
                (new_id, row["guideline_id"]),
            )

        # ── Copy MCP servers ─────────────────────────────────────────
        cur = await db.execute(
            """SELECT sm.mcp_server_id, sm.auto_approve_override FROM session_mcp_servers sm
               JOIN mcp_servers m ON m.id = sm.mcp_server_id
               WHERE sm.session_id = ?""",
            (session_id,),
        )
        for row in await cur.fetchall():
            await db.execute(
                "INSERT OR IGNORE INTO session_mcp_servers "
                "(session_id, mcp_server_id, auto_approve_override) VALUES (?, ?, ?)",
                (new_id, row["mcp_server_id"], row["auto_approve_override"]),
            )

        # Keep native_session_id on the branch so it resumes with full context
        # (matches Claude's behavior: branch keeps conversation, original also preserved)
        await db.commit()

        # Fetch rows for broadcast
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (new_id,))
        new_session = dict(await cur.fetchone())
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        updated_branch = dict(await cur.fetchone())
    except Exception as e:
        logger.exception("Gemini /branch failed: %s", e)
        pty_mgr.write(session_id,
                      b"\r\n\x1b[31m[Branch failed \xe2\x80\x94 see server log]\x1b[0m\r\n")
        return True
    finally:
        await db.close()

    # Write feedback to terminal
    pty_mgr.write(session_id,
                  f"\r\n\x1b[35m\u2442 Branched! Original conversation saved as "
                  f"\"{original_name}\" tab.\x1b[0m\r\n".encode("utf-8"))

    # Broadcast original session (opens as background tab + toast)
    await broadcast({
        "type": "session_created",
        "session": new_session,
        "auto_open": True,
        "parent_session_id": session_id,
        "updated_parent": updated_branch,
    })
    await broadcast({
        "type": "session_renamed",
        "session_id": session_id,
        "name": branch_name,
    })

    # Stop PTY + auto-restart fresh (reuses switch_session_cli pattern)
    await _stop_session_expected(session_id)
    from hooks import clear_native_id_cache
    clear_native_id_cache(session_id)
    await broadcast({
        "type": "session_switched",
        "session_id": session_id,
        "cli_type": "gemini",
        "model": config["model"],
    })

    logger.info("Gemini /branch: original %s, branch %s restarting fresh",
                new_id[:8], session_id[:8])
    return True


# ─── Conversation turn tracking ───────────────────────────────────────────

_input_bufs: dict[str, str] = {}
_session_turns: dict[str, list[str]] = {}
_input_esc: dict[str, int] = {}  # 0=normal, 1=got ESC, 2=CSI body
_session_workspace: dict[str, str] = {}  # session_id → workspace_id (for advisor)

def _track_input(session_id: str, raw: str):
    """Track user keystrokes, split into turns on Enter.

    Includes a small state machine to skip ANSI escape sequences
    (focus events, device-attribute responses, arrow keys, etc.) so
    they don't pollute the buffer with ``[I``, ``[?1;2c``, etc.
    """
    if session_id not in _input_bufs:
        _input_bufs[session_id] = ""
    state = _input_esc.get(session_id, 0)

    for ch in raw:
        code = ord(ch)

        # ── Inside escape sequence → skip until done ──────────
        if state == 1:                         # got ESC, next byte decides type
            if ch == '[':
                state = 2                      # CSI sequence (\x1b[...)
            elif ch == 'O':
                state = 3                      # SS3 (\x1bO + one byte)
            else:
                state = 0                      # unknown / bare ESC, done
            continue
        if state == 2:                         # CSI body — skip until final byte
            if 0x40 <= code <= 0x7E:           # final byte → sequence done
                state = 0
            continue
        if state == 3:                         # SS3 — skip one byte then done
            state = 0
            continue

        # ── Normal state ──────────────────────────────────────
        if ch == '\x1b':
            state = 1
        elif ch in ('\r', '\n'):
            line = _input_bufs[session_id].strip()
            if line:
                if session_id not in _session_turns:
                    _session_turns[session_id] = []
                _session_turns[session_id].append(line)
                # Session Advisor: feed intent accumulator
                try:
                    from session_advisor import update_intent
                    # Look up workspace_id for this session
                    ws_id = _session_workspace.get(session_id)
                    _fire_and_forget(update_intent(
                        session_id, line, source="user",
                        workspace_id=ws_id, broadcast_fn=broadcast,
                    ))
                except Exception:
                    pass
                # Skill Suggester: push real-time suggestions
                try:
                    from skill_suggester import maybe_suggest_skills
                    ws_id = _session_workspace.get(session_id)
                    _fire_and_forget(maybe_suggest_skills(
                        session_id, line,
                        workspace_id=ws_id, broadcast_fn=broadcast,
                    ))
                except Exception:
                    pass
            _input_bufs[session_id] = ""
        elif ch == '\x7f' or ch == '\x08':
            _input_bufs[session_id] = _input_bufs[session_id][:-1]
        elif code >= 32:
            _input_bufs[session_id] += ch

    _input_esc[session_id] = state


def get_session_turns(session_id: str) -> list[str]:
    return _session_turns.get(session_id, [])


# ─── @prompt:<name> token expansion on Enter ─────────────────────────────
#
# When the user presses Enter in the terminal and their accumulated input
# contains @prompt:<name> tokens, we expand them server-side before the
# message reaches Claude. The expansion is done by backspacing over the
# raw input in the PTY and retyping the expanded version — all in a single
# write so it's atomic from the terminal's perspective.
#
# This lives server-side (not client-side) because:
#   1. _input_bufs already tracks what the user typed (no duplication)
#   2. The DB with prompts is right here
#   3. It works for ALL input paths (terminal, paste, replay, etc.)

import re as _re

_PROMPT_TOKEN_RE = _re.compile(r'@prompt:(?:"([^"]+)"|(\S+))', _re.IGNORECASE)


def _find_prompt_by_name(prompts: list[dict], name: str):
    """Case-insensitive name lookup: exact → normalized → prefix."""
    lc = name.lower()
    for p in prompts:
        if p["name"].lower() == lc:
            return p
    norm = lc.replace(" ", "").replace("-", "").replace("_", "")
    for p in prompts:
        if p["name"].lower().replace(" ", "").replace("-", "").replace("_", "") == norm:
            return p
    for p in prompts:
        if p["name"].lower().startswith(lc):
            return p
    return None


def _expand_prompt_tokens(text: str, prompts: list[dict]) -> str:
    """Replace @prompt:<name> tokens with their content."""
    def _replacer(m):
        name = m.group(1) or m.group(2)
        hit = _find_prompt_by_name(prompts, name)
        return hit["content"] if hit else m.group(0)
    return _PROMPT_TOKEN_RE.sub(_replacer, text)




async def _maybe_expand_input(session_id: str, raw_input: str):
    """If raw_input contains Enter and the accumulated buffer has @prompt:
    tokens, return bytes to write to PTY instead (backspaces + expanded +
    Enter). Returns None when no expansion is needed.

    On expansion, also updates _input_bufs / _session_turns so the
    tracking state stays consistent, and emits a token_expanded event.
    """
    # Only trigger when the chunk contains Enter
    if "\r" not in raw_input and "\n" not in raw_input:
        return None

    # _input_bufs already has the accumulated (escape-cleaned) text from
    # prior _track_input calls. For the common case (Enter arrives as its
    # own chunk), this is the complete user input.
    buf = _input_bufs.get(session_id, "").strip()
    if not buf:
        return None

    # Quick regex check — skip the DB hit if there are no @prompt: tokens
    if not _PROMPT_TOKEN_RE.search(buf):
        return None

    logger.info("Token expansion: matched @prompt: in buffer (%d chars): %s", len(buf), buf[:80])

    # Fetch prompts from DB
    db = await get_db()
    try:
        rows = await db.execute_fetchall(
            "SELECT id, name, content FROM prompts"
        )
        prompts = [dict(r) for r in rows]
    finally:
        await db.close()

    expanded = _expand_prompt_tokens(buf, prompts)
    if expanded == buf:
        return None  # Token was present but name didn't match anything

    # Collapse newlines → spaces. Ink's TextInput is single-line; any
    # \n in the prompt content would be interpreted as Enter (submitting
    # a partial message). For full multiline prompts use Composer (⌘E).
    expanded = expanded.replace("\r\n", " ").replace("\r", " ").replace("\n", " ")

    logger.info("Token expansion: expanded to %d chars", len(expanded))

    # Two-phase write mirroring the frontend's sendTerminalCommand.
    # Phase 1 (immediate): clear existing input
    # Phase 2 (after delay): expanded text + Enter
    # Use CLI-appropriate clear: Escape+DEL for Claude Ink, Ctrl-U for Gemini.
    cli_type = "claude"
    try:
        _cfg = await get_session_config(session_id)
        if _cfg:
            cli_type = _cfg.get("cli_type", "claude")
    except Exception:
        pass
    if cli_type == "gemini":
        pty_mgr.write(session_id, b"\x15")  # Ctrl-U
    else:
        pty_mgr.write(session_id, b"\x1b" + b"\x7f" * 50)

    async def _send_expanded():
        await _asyncio.sleep(0.3)
        # Write text and submit \r in *separate* writes. A combined
        # text+\r blob lets Claude's Ink paste-detection swallow the
        # trailing CR for any expansion past ~80 chars.
        if pty_mgr.write(session_id, expanded.encode("utf-8")) is False:
            logger.warning("Token expansion for %s not typed (input rejected)", session_id[:8])
            return
        await _asyncio.sleep(0.4)
        pty_mgr.write(session_id, b"\r")

    _asyncio.ensure_future(_send_expanded())

    # Update tracking state (what _track_input would have done)
    if session_id not in _session_turns:
        _session_turns[session_id] = []
    _session_turns[session_id].append(expanded.strip())
    _input_bufs[session_id] = ""

    # Audit event only (fire-and-forget). No WebSocket message: the terminal
    # already shows the expanded text, and no client acts on the signal.
    session = await get_session_config(session_id)
    _asyncio.ensure_future(bus.emit(
        "token_expanded",
        {
            "session_id": session_id,
            "workspace_id": session["workspace_id"] if session else None,
            "original": buf,
            "expanded_preview": expanded[:200],
            "tokens": [m.group(0) for m in _PROMPT_TOKEN_RE.finditer(buf)],
        },
        source="terminal",
    ))

    # Return empty bytes — signals caller to NOT forward the original
    # Enter keystroke (we already scheduled the expanded text + Enter).
    return b""


async def _replay_turns(session_id: str, turns: list[str]):
    """Replay saved conversation turns into a session, waiting for each response."""
    import re

    # Broadcast replaying status
    await broadcast({"session_id": session_id, "type": "status", "status": "replaying"})

    for i, turn in enumerate(turns):
        # Wait for Claude Code to show input prompt (❯ or >)
        for _ in range(60):  # Max 30 seconds per turn
            buf = capture_proc.get_buffer(session_id, 5)
            if '❯' in buf or '> ' in buf or (i == 0 and 'shortcuts' in buf.lower()):
                break
            await asyncio.sleep(0.5)

        await asyncio.sleep(0.3)  # Small extra pause for Ink to settle

        # Type the message, then submit Enter as a separate write — a
        # combined blob can be paste-detected by Ink and the \r dropped.
        pty_mgr.write(session_id, turn.encode('utf-8'))
        await asyncio.sleep(0.4)
        pty_mgr.write(session_id, b'\r')

        # Wait for response to complete (prompt reappears)
        await asyncio.sleep(2)  # Minimum wait for response to start
        for _ in range(120):  # Max 60 seconds for response
            buf = capture_proc.get_buffer(session_id, 3)
            # Check if prompt appeared again (Claude is done)
            last_lines = buf.strip().split('\n')
            if any('❯' in l for l in last_lines[-3:]):
                break
            await asyncio.sleep(0.5)

    # Done replaying
    await broadcast({"session_id": session_id, "type": "status", "status": "idle"})
    await broadcast({"session_id": session_id, "type": "replay_done"})


async def _adopt_sessions(commander_id: str, target_ids: list[str]):
    """Set parent_session_id on targets if the source is a commander session."""
    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT session_type FROM sessions WHERE id = ?", (commander_id,)
        )
        row = await cur.fetchone()
        if not row or row["session_type"] != "commander":
            return
        for sid in target_ids:
            await db.execute(
                "UPDATE sessions SET parent_session_id = ? WHERE id = ? AND (parent_session_id IS NULL OR parent_session_id != ?)",
                (commander_id, sid, commander_id),
            )
        await db.commit()
    finally:
        await db.close()


# ─── WebSocket ────────────────────────────────────────────────────────────

async def ws_handler(request: web.Request) -> web.WebSocketResponse:
    import shell_session as _shell_session  # plain terminals (cli_type "shell")
    ws = web.WebSocketResponse(heartbeat=30.0)
    await ws.prepare(request)
    QueuedWebSocket(ws)
    ws_clients.add(ws)
    geometry_viewer_id = f"ws:{id(ws)}"
    ws._ive_terminal_sessions = set()

    # Tag the socket with its joiner_session id (when present) so a
    # subsequent /api/sessions/auth/{id}/revoke can close live connections
    # the revoked joiner is holding open. Without this, revocation only
    # affects the next HTTP request — the existing WS keeps driving PTYs.
    auth_ctx = request.get("auth")
    ws._ive_actor_id = getattr(auth_ctx, "actor_id", None) if auth_ctx else None
    ws._ive_auth_ctx = auth_ctx
    ws._ive_actor_kind = getattr(auth_ctx, "actor_kind", None) if auth_ctx else None
    ws._ive_actor_label = getattr(auth_ctx, "label", None) if auth_ctx else None
    ws._ive_mode = getattr(auth_ctx, "mode", None) if auth_ctx else None
    ws._ive_expires_at = getattr(auth_ctx, "expires_at", None) if auth_ctx else None
    ws._ive_is_owner = bool(getattr(auth_ctx, "is_owner", False)) if auth_ctx else False
    ws._ive_remote_ip = _request_remote_ip(request)
    ws._ive_user_agent = request.headers.get("User-Agent")
    ws._ive_connected_at = _utc_now_iso()
    logger.info(f"WebSocket connected ({len(ws_clients)} total)")

    try:
        async for msg in ws:
            if msg.type == aiohttp.WSMsgType.TEXT:
                try:
                    data = json.loads(msg.data)
                except json.JSONDecodeError:
                    continue

                action = data.get("action")

                # A PIN-locked phone may keep its socket for presence, but
                # cannot start, type into or steer anything until unlocked.
                if ws._ive_actor_kind == "owner_device" and action not in (
                    "hello", "presence_update",
                ):
                    if _phone_access.lock.is_locked(ws._ive_actor_id):
                        await ws.send_json({"type": "phone_locked"})
                        continue
                    _phone_access.lock.touch(ws._ive_actor_id)

                if action == "start_pty":
                    session_id = data.get("session_id")
                    cols = data.get("cols", 120)
                    rows = data.get("rows", 40)

                    if not session_id:
                        continue

                    config = await get_session_config(session_id)
                    if not config or not _session_visible_to_request(config, request):
                        await ws.send_json({
                            "session_id": session_id,
                            "type": "error",
                            "message": "Session not found",
                        })
                        continue

                    if not await _terminal_control_allowed(
                        ws, request, config, "start_pty"
                    ):
                        continue

                    if pty_mgr.is_alive(session_id):
                        # keep_size: a hidden or Overview terminal attaches
                        # to a running PTY without resizing it (every resize
                        # makes the CLI redraw its whole screen).
                        keep_size = bool(data.get("keep_size"))
                        geometry = pty_mgr.request_geometry(
                            session_id, geometry_viewer_id,
                            None if keep_size else cols,
                            None if keep_size else rows,
                        )
                        if geometry:
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "terminal_geometry",
                                **geometry,
                            })
                        await _send_terminal_resume(ws, session_id)
                        continue

                    if _shell_session.is_shell_session(config):
                        # Plain terminal: the login shell, nothing else.
                        outcome = await _start_shell_pty(
                            session_id, config, cols, rows,
                            geometry_owner=geometry_viewer_id,
                        )
                        if not outcome.get("ok"):
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "error",
                                "message": outcome.get("reason") or "Terminal could not start",
                            })
                            continue
                        geometry = pty_mgr.get_geometry(session_id)
                        if geometry:
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "terminal_geometry",
                                "authoritative": True,
                                "changed": False,
                                **geometry,
                            })
                        stream = _terminal_stream(session_id)
                        await _send_terminal_resume(
                            ws, session_id, after_sequence=0, generation=stream.generation,
                        )
                        continue

                    # Fetch attached guidelines and build combined system prompt.
                    # Three sources stack into the final --append-system-prompt:
                    #   1. session.system_prompt (legacy free-text field)
                    #   2. Legacy guidelines (session_guidelines)
                    #   3. Plugin guideline components (session_plugin_components
                    #      where type='guideline') — from the plugin marketplace,
                    #      CLI-agnostic (works for both Claude and Gemini).
                    system_prompt_parts = []
                    if config.get("system_prompt"):
                        system_prompt_parts.append(config["system_prompt"])

                    _stype = (config.get("session_type") or "").strip()
                    if _stype == "planner":
                        if not any("You are the Planner" in p for p in system_prompt_parts):
                            system_prompt_parts.append(PLANNER_SYSTEM_PROMPT)
                    elif _stype == "architect":
                        system_prompt_parts.append(ARCHITECT_SYSTEM_PROMPT)
                    elif _stype == "brainstormer":
                        if not any("You are the Brainstormer" in p for p in system_prompt_parts):
                            system_prompt_parts.append(BRAINSTORMER_SYSTEM_PROMPT)
                    elif _stype == "secure":
                        system_prompt_parts.append(SECURE_SYSTEM_PROMPT)
                    elif _stype in ("", "worker", "test_worker"):
                        system_prompt_parts.append(WORKER_SYSTEM_PROMPT_FRAGMENT)

                    # Track which guideline IDs are ACTUALLY loaded into the
                    # system prompt. Written back to sessions.active_guideline_ids
                    # so the GuidelinePanel can show accurate "active" vs "pending"
                    # labels and detect unchecked-but-still-cached guidelines.
                    loaded_guideline_ids = []

                    db_gl = await get_db()
                    try:
                        cur_gl = await db_gl.execute(
                            """SELECT g.id, g.content FROM guidelines g
                               JOIN session_guidelines sg ON g.id = sg.guideline_id
                               WHERE sg.session_id = ?""",
                            (session_id,),
                        )
                        for row_gl in await project_guidelines(db_gl, await cur_gl.fetchall()):
                            system_prompt_parts.append(row_gl["content"])
                            loaded_guideline_ids.append(row_gl["id"])

                        # Plugin guideline components:
                        #   • activation='always' → injected into system prompt
                        #   • activation='on_demand' → on disk as SKILL.md,
                        #     discovered natively by the CLI (not injected here)
                        cur_plugin = await db_gl.execute(
                            """SELECT pc.content
                               FROM plugin_components pc
                               JOIN session_plugin_components spc
                                    ON pc.id = spc.component_id
                               WHERE spc.session_id = ?
                                 AND pc.type = 'guideline'
                                 AND COALESCE(pc.activation, 'always') = 'always'
                               ORDER BY pc.order_index, pc.name""",
                            (session_id,),
                        )
                        for row_p in await cur_plugin.fetchall():
                            if row_p["content"]:
                                system_prompt_parts.append(row_p["content"])

                        # Experimental: checkpoint protocol injection.
                        cur_exp = await db_gl.execute(
                            "SELECT value FROM app_settings WHERE key = ?",
                            ("experimental_checkpoint_protocol",),
                        )
                        exp_row = await cur_exp.fetchone()
                        if exp_row and exp_row["value"] == "on":
                            system_prompt_parts.append(
                                experimental.CHECKPOINT_PROTOCOL_PROMPT
                            )

                        # Experimental: model switching prompt injection.
                        cur_ms = await db_gl.execute(
                            "SELECT value FROM app_settings WHERE key = ?",
                            ("experimental_model_switching",),
                        )
                        ms_row = await cur_ms.fetchone()
                        if ms_row and ms_row["value"] == "on" and config.get("plan_model") and config.get("execute_model"):
                            pm = config.get("plan_model") or config.get("model", "opus")
                            em = config.get("execute_model") or config.get("model", "sonnet")
                            system_prompt_parts.append(
                                experimental.MODEL_SWITCHING_PROMPT.format(
                                    plan_model=pm, execute_model=em,
                                )
                            )

                        # Commander memory injection: append remembered context
                        # from Commander's memory_entries DB.  This is the key
                        # abstraction — every CLI (Claude, Gemini, future CLIs)
                        # gets the same memory entries regardless of whether
                        # the CLI has native auto-memory support.
                        _mem_info = None
                        _ws_id_mem = config.get("workspace_id", "")
                        _mem_max = 4000
                        _mem_settings: dict = {}
                        try:
                            from memory_sync import sync_manager as _sync_mgr
                            _mem_settings = await _sync_mgr.get_settings(_ws_id_mem)
                            _mem_max = _mem_settings.get("memory_max_chars", 4000)
                            # The quick start root is not a project: never
                            # write provider memory files into it.
                            if (
                                _mem_settings.get("enabled", True)
                                and _mem_settings.get("auto_sync", True)
                                and not _quick_start.is_quick_workspace_cached(_ws_id_mem)
                            ):
                                _ws_path_mem = config.get("workspace_path")
                                if _ws_id_mem and _ws_path_mem:
                                    _sync_result = await _sync_mgr.sync(
                                        _ws_id_mem,
                                        _ws_path_mem,
                                        source_cli=config.get("cli_type"),
                                    )
                                    if _sync_result.status != "conflicts":
                                        await _sync_mgr.sync_entries_to_project_memory(
                                            _ws_id_mem,
                                            _ws_path_mem,
                                        )
                        except Exception:
                            pass

                        # Aggressive output styles also compress the memory
                        # block (matches export_for_prompt's compact contract).
                        # Resolve effective style here so it can drive both the
                        # memory render and the later style-prompt injection.
                        try:
                            from output_styles import resolve_output_style as _resolve_style
                            _peek_ws_style = config.get("ws_output_style")
                            if not _peek_ws_style:
                                try:
                                    _peek_db = await get_db()
                                    _peek_cur = await _peek_db.execute(
                                        "SELECT output_style FROM workspaces WHERE id = ?",
                                        (_ws_id_mem,))
                                    _peek_row = await _peek_cur.fetchone()
                                    _peek_ws_style = _peek_row["output_style"] if _peek_row else None
                                    await _peek_db.close()
                                except Exception:
                                    _peek_ws_style = None
                            _peek_global = None
                            try:
                                _peek_gs = await get_db()
                                _peek_gc = await _peek_gs.execute(
                                    "SELECT value FROM app_settings WHERE key = 'output_style'")
                                _peek_gr = await _peek_gc.fetchone()
                                _peek_global = _peek_gr["value"] if _peek_gr else None
                                await _peek_gs.close()
                            except Exception:
                                pass
                            effective_style = _resolve_style(
                                config.get("output_style"), _peek_ws_style, _peek_global)
                        except Exception:
                            effective_style = "default"
                        from output_styles import style_compacts_memory
                        _compact_memory = style_compacts_memory(effective_style)

                        try:
                            mem_prompt, _mem_info = await _session_memory_prompt(
                                config, session_id, _mem_settings, _mem_max, _compact_memory,
                            )
                            if mem_prompt:
                                system_prompt_parts.append(mem_prompt)
                        except Exception as mem_exc:
                            logger.debug("Memory injection skipped: %s", mem_exc)

                        # Runtime/toolchain guidance: give workers and testers
                        # the workspace's preferred interpreters and package
                        # manager commands before they run verification.
                        try:
                            _runtime_stype = (config.get("session_type") or "worker").strip()
                            if _runtime_stype in ("", "worker", "test_worker", "tester"):
                                _ws_path_runtime = config.get("workspace_path")
                                if _ws_path_runtime:
                                    from workspace_runtime import detect_workspace_runtime_env
                                    _runtime_env = detect_workspace_runtime_env(_ws_path_runtime)
                                    _runtime_prompt = (_runtime_env or {}).get("prompt") or ""
                                    if _runtime_prompt:
                                        system_prompt_parts.append(_runtime_prompt[:6000])
                        except Exception as runtime_exc:
                            logger.debug("Runtime environment injection skipped: %s", runtime_exc)

                        # ── W2W: Inject workspace knowledge into system prompt ─
                        try:
                            _ws_id = config.get("workspace_id", "")
                            ws_db = await get_db()
                            try:
                                ws_cur = await ws_db.execute(
                                    "SELECT context_sharing_enabled, comms_enabled FROM workspaces WHERE id = ?",
                                    (_ws_id,),
                                )
                                ws_flags = await ws_cur.fetchone()
                            finally:
                                await ws_db.close()

                            _session_type_w2w = (config.get("session_type") or "").strip()
                            _is_tester_w2w = _session_type_w2w in ("tester", "test_worker")
                            _is_commander_w2w = _session_type_w2w == "commander"
                            _is_documentor_w2w = _session_type_w2w == "documentor"
                            _is_brainstormer_w2w = _session_type_w2w == "brainstormer"

                            if ws_flags and ws_flags["context_sharing_enabled"]:
                                if extension_host.available("myelin"):
                                    knowledge_prompt = await _myelin_workspace_knowledge(config, _ws_id)
                                    if knowledge_prompt:
                                        system_prompt_parts.append(knowledge_prompt)

                                # Inject recent file activity from peer sessions
                                try:
                                    fa_db = await get_db()
                                    try:
                                        fa_cur = await fa_db.execute(
                                            """SELECT file_path, session_name, task_summary, task_title,
                                                      MAX(created_at) AS last_edited
                                               FROM file_activity
                                               WHERE workspace_id = ? AND session_id != ?
                                                 AND created_at > datetime('now', '-2 hours')
                                               GROUP BY file_path, session_id
                                               ORDER BY last_edited DESC LIMIT 20""",
                                            (_ws_id, session_id),
                                        )
                                        fa_rows = await fa_cur.fetchall()
                                    finally:
                                        await fa_db.close()

                                    if fa_rows:
                                        fa_lines = ["## Recent File Activity (Peers)\n",
                                                     "Files recently edited by peer sessions:"]
                                        for fa in fa_rows:
                                            goal = fa["task_title"] or fa["task_summary"] or "unknown task"
                                            fa_lines.append(
                                                f"- `{fa['file_path']}` — {fa['session_name']} ({goal})"
                                            )
                                        fa_lines.append("")
                                        system_prompt_parts.append("\n".join(fa_lines))
                                except Exception:
                                    pass

                                if extension_host.available("swarmlock"):
                                    overlap_prompt = await _swarmlock_session_overlap(config, session_id, _ws_id)
                                    if overlap_prompt:
                                        system_prompt_parts.append(overlap_prompt)

                                # Context sharing prompt fragment.
                                # Testers don't edit shared code, so they get a trimmed
                                # surface: no conflict-avoidance tools, no "before editing
                                # any file" rituals — just the memory/digest/knowledge loop
                                # they actually use. contribute_knowledge stays in the tester
                                # block because gotchas the tester finds (flaky selectors,
                                # UI quirks, "still broken" notes) should land in the shared
                                # KB so the next implementer sees them.
                                if _is_brainstormer_w2w:
                                    system_prompt_parts.append(
                                        _extension_prompts.render("## Shared Context — Brainstormer\n\nYou are not bound to an implementation ticket and do not use active-ticket worker bookkeeping. Use list_backlog{related_candidates} before filing candidate ideas. Use create_candidate_task only for reviewable backlog candidates, and use research/observatory tools when evidence would improve the idea. Commander will later decide execution routing.", "shared_context", role="brainstormer")
                                    )
                                elif _is_documentor_w2w:
                                    # Documentor MCP only exposes save_memory from the W2W
                                    # surface — no peer comms, no digests, no contribute_knowledge.
                                    # Skip the block entirely; documentor's role prompt covers
                                    # what it actually does.
                                    pass
                                elif _is_commander_w2w:
                                    system_prompt_parts.append(
                                        _extension_prompts.render("## Shared Context (W2W) — Commander\n\nYou orchestrate workers; you rarely edit code yourself, so you skip per-file conflict checks. Your loop is:\n\n### Before assigning or routing a task\n{prior_context}2. **list_worker_digests()** — what every worker is currently doing. Use this to spot idle capacity and avoid double-booking.\n{semantic_overlap}### While orchestrating\n- **get_session_digest(session_id)** — pull a single worker's current task, focus, decisions, and discoveries.\n- **save_memory** — your private playbook. Save routing decisions, worker reliability notes, and user-correction feedback. If the memory describes or extends a durable file-backed artifact (doc, spec, prompt, workflow, manifest, test, UI component), include the canonical source path(s) in the memory content and update the existing memory idempotently when new files extend it.\n{shared_learning}### You do NOT have\nupdate_digest, post_message, get_file_context, check_messages, list_peers, blocking_bulletin, find_similar_tasks — those are worker-only. Use the commander-side equivalents above.", "shared_context", role="commander")
                                    )
                                elif _is_tester_w2w:
                                    system_prompt_parts.append(
                                        _extension_prompts.render("## Shared Context (W2W) — Tester\n\nYou are a verifier, not an implementer. You don't edit shared code, so you skip the conflict-avoidance machinery. Your W2W loop is:\n\n### Before each test run\n{prior_context}{similar_tasks}### While testing\n- **update_digest(task_summary?, current_focus?, discoveries?)** — keep your digest current so commander and the UI can see what you're testing right now.\n- **save_memory** — save flaky tests, undocumented behavior, reusable selectors, and user-correction feedback. If the memory describes a test file, fixture, screenshot, doc, workflow, or other durable artifact, include its canonical source path(s) in the memory content and update the existing memory idempotently when new files extend it. See your role prompt for what to save.\n{shared_learning}### When you find a bug\nReport findings up — do NOT try to coordinate a fix yourself. Use update_my_task() with detailed reproduction steps and notes. Commander will file follow-up tasks for implementer workers.", "shared_context", role="tester")
                                    )
                                else:
                                    system_prompt_parts.append(
                                        "Note: Workspace peer coordination and file locks are programmatically enforced at the middleware layer by hooks before tool execution."
                                    )

                            if ws_flags and ws_flags["comms_enabled"]:
                                if _is_brainstormer_w2w:
                                    pass
                                elif _is_documentor_w2w:
                                    # Documentor has no peer-comms tools — skip this block.
                                    pass
                                elif _is_commander_w2w:
                                    system_prompt_parts.append(
                                        "## Peer Communication (W2W) — Commander\n\n"
                                        "You talk to workers, not the other way around. Channels:\n\n"
                                        "- **send_message(session_id, message)** — direct a specific worker. "
                                        "Use this to redirect, ask a clarifying question, or hand off context.\n"
                                        "- **broadcast_message(message)** — fan out to all active workers in "
                                        "the workspace (e.g. user changed direction; merge freeze; new constraint).\n"
                                        "- **headsup(to='all'|session_id, message=...)** — non-blocking notice. "
                                        "Fire-and-continue when you want workers to SEE something but you're not "
                                        "waiting on them (e.g. \"reassigning the auth area to session X\").\n\n"
                                        "You do NOT have post_message, check_messages, or list_peers — "
                                        "those are worker bulletin-board tools. For peer state, use "
                                        "list_worker_digests / get_session_digest instead."
                                    )
                                elif _is_tester_w2w:
                                    system_prompt_parts.append(
                                        "## Peer Communication (W2W) — Tester\n\n"
                                        "You can talk to peers but rarely need to. Two channels:\n\n"
                                        "- **headsup(to='commander', message=...)** — surface a finding or "
                                        "escalation to commander when you've hit something they should see "
                                        "immediately (a critical regression, a blocker for the test plan).\n"
                                        "- **post_message(topic, content, priority='info')** — coordinate with "
                                        "sibling test-workers if you're running in parallel (e.g. \"I'm taking "
                                        "the login flow, you take signup\").\n\n"
                                        "You do NOT need to: lock files, send blocking bulletins, or warn peers "
                                        "about your edits — testers don't edit code."
                                    )
                                else:
                                    pass

                            # ── Active ticket binding ─────────────────────
                            # Only worker/planner sessions get a per-turn active-ticket
                            # block. Commander orchestrates (no single ticket); tester
                            # surfaces bugs via update_my_task; documentor doesn't bind.
                            if not _is_brainstormer_w2w and not _is_documentor_w2w and not _is_commander_w2w and not _is_tester_w2w:
                                try:
                                    bd_db = await get_db()
                                    try:
                                        bd_cur = await bd_db.execute(
                                            "SELECT board_doc_mode FROM workspaces WHERE id = ?",
                                            (_ws_id,),
                                        )
                                        bd_row = await bd_cur.fetchone()
                                        bd_mode = (bd_row["board_doc_mode"] if bd_row else "agent_with_backstop") or "agent_with_backstop"

                                        if bd_mode != "off":
                                            sess_cur = await bd_db.execute(
                                                "SELECT active_ticket_id, task_id FROM sessions WHERE id = ?",
                                                (session_id,),
                                            )
                                            sess_row = await sess_cur.fetchone()
                                            active_tid = (sess_row["active_ticket_id"] if sess_row else None) or (sess_row["task_id"] if sess_row else None)
                                            if active_tid:
                                                tk_cur = await bd_db.execute(
                                                    "SELECT id, title, status FROM tasks WHERE id = ?",
                                                    (active_tid,),
                                                )
                                                tk_row = await tk_cur.fetchone()
                                                if tk_row:
                                                    short = (tk_row["id"] or "")[:8]
                                                    title = (tk_row["title"] or "").strip().replace("\n", " ")[:80]
                                                    status = tk_row["status"] or "?"
                                                    system_prompt_parts.append(
                                                        f"## Active Ticket\n\n"
                                                        f"[Active ticket: #{short} — {status}: \"{title}\"]\n\n"
                                                        "This is the ticket you're currently bound to. If your work "
                                                        "drifts from this ticket, call switch_active_ticket(ticket_id) "
                                                        "to rebind, or switch_active_ticket(null) to unbind. At completion, "
                                                        "document_to_board(action='update') uses this binding."
                                                    )
                                                else:
                                                    # Stale binding: ticket was deleted
                                                    system_prompt_parts.append(
                                                        "## Active Ticket\n\n"
                                                        "[No active ticket bound — prior binding pointed to a deleted ticket]\n\n"
                                                        "If feature-shaped work begins, call switch_active_ticket(ticket_id) "
                                                        "to bind to an existing ticket, or call document_to_board(action='create') "
                                                        "at completion to create a new one."
                                                    )
                                            else:
                                                system_prompt_parts.append(
                                                    "## Active Ticket\n\n"
                                                    "[No active ticket bound]\n\n"
                                                    "You're working unbound. If feature-shaped work begins, call "
                                                    "switch_active_ticket(ticket_id) to bind to an existing ticket, "
                                                    "or just call document_to_board(action='create') at completion "
                                                    "to create a new one."
                                                )
                                    finally:
                                        await bd_db.close()
                                except Exception as bd_exc:
                                    logger.debug("Active ticket block skipped: %s", bd_exc)
                        except Exception as w2w_exc:
                            logger.warning("W2W injection skipped: %s", w2w_exc)

                        # Write back the snapshot of which guidelines are NOW
                        # in the system prompt. This column is the single source
                        # of truth for "active in system prompt" vs "pending".
                        await db_gl.execute(
                            "UPDATE sessions SET active_guideline_ids = ? WHERE id = ?",
                            (json.dumps(loaded_guideline_ids), session_id),
                        )
                        # Write back memory injection metadata (mirrors active_guideline_ids)
                        await db_gl.execute(
                            "UPDATE sessions SET memory_injected_info = ? WHERE id = ?",
                            (_mem_info, session_id),
                        )
                        await db_gl.commit()
                    finally:
                        await db_gl.close()

                    # MCP servers are assembled further down, once the
                    # UnifiedSession exists, via the shared _apply_session_mcp.

                    from prompt_context import project_instructions
                    instructions = project_instructions(config.get("cli_type", "claude"), config.get("workspace_path"))
                    if instructions:
                        system_prompt_parts.append(instructions)

                    # ── Resolve output style (session → workspace → global) ──
                    from output_styles import resolve_output_style, get_style_prompt
                    _ws_style = config.get("ws_output_style")  # from workspace join
                    if not _ws_style:
                        # Fetch workspace output_style if not in config
                        try:
                            _ws_db = await get_db()
                            _ws_cur = await _ws_db.execute(
                                "SELECT output_style FROM workspaces WHERE id = ?",
                                (config.get("workspace_id", ""),))
                            _ws_row = await _ws_cur.fetchone()
                            _ws_style = _ws_row["output_style"] if _ws_row else None
                            await _ws_db.close()
                        except Exception:
                            _ws_style = None
                    _global_style = None
                    try:
                        _gs_db = await get_db()
                        _gs_cur = await _gs_db.execute(
                            "SELECT value FROM app_settings WHERE key = 'output_style'")
                        _gs_row = await _gs_cur.fetchone()
                        _global_style = _gs_row["value"] if _gs_row else None
                        await _gs_db.close()
                    except Exception:
                        pass
                    try:
                        effective_style = resolve_output_style(
                            config.get("output_style"), _ws_style, _global_style)
                        style_prompt = get_style_prompt(effective_style)
                    except ValueError as exc:
                        await ws.send_json({
                            "session_id": session_id,
                            "type": "error",
                            "message": str(exc),
                        })
                        continue
                    if style_prompt:
                        system_prompt_parts.append(style_prompt)

                    # ── Auto Skill Suggestions: inject top-3 into system prompt ──
                    try:
                        _ask_db = await get_db()
                        try:
                            _ask_cur = await _ask_db.execute(
                                "SELECT value FROM app_settings WHERE key = 'experimental_auto_skill_suggestions'"
                            )
                            _ask_row = await _ask_cur.fetchone()
                        finally:
                            await _ask_db.close()
                        if _ask_row and _ask_row["value"] == "on":
                            from skill_suggester import suggest_for_session
                            # Build context from session name + purpose + existing system prompt,
                            # plus recent workspace digests so the match reflects what the user
                            # has actually been doing — not just static session config.
                            _skill_ctx_parts = []
                            if config.get("name"):
                                _skill_ctx_parts.append(config["name"])
                            if config.get("purpose"):
                                _skill_ctx_parts.append(config["purpose"])
                            if config.get("system_prompt"):
                                _skill_ctx_parts.append(config["system_prompt"][:300])
                            _ws_id = config.get("workspace_id")
                            if _ws_id:
                                try:
                                    _dg_db = await get_db()
                                    try:
                                        _dg_cur = await _dg_db.execute(
                                            "SELECT task_summary, current_focus FROM session_digests "
                                            "WHERE workspace_id = ? AND (task_summary != '' OR current_focus != '') "
                                            "ORDER BY updated_at DESC LIMIT 3",
                                            (_ws_id,),
                                        )
                                        for _dg_row in await _dg_cur.fetchall():
                                            for _f in ("task_summary", "current_focus"):
                                                _v = (_dg_row[_f] or "").strip()
                                                if _v:
                                                    _skill_ctx_parts.append(_v[:200])
                                    finally:
                                        await _dg_db.close()
                                except Exception as _dg_err:
                                    logger.debug("Skill ctx digest enrichment skipped: %s", _dg_err)
                            _skill_ctx = " ".join(_skill_ctx_parts)
                            if _skill_ctx.strip():
                                _skill_block = await suggest_for_session(_skill_ctx)
                                if _skill_block:
                                    system_prompt_parts.append(_skill_block)
                    except Exception as _skill_err:
                        logger.debug("Skill suggestion injection skipped: %s", _skill_err)

                    # ── Build CLI command via UnifiedSession ─────────────────
                    cli_type = config.get("cli_type", "claude")
                    extra_env = await _prepare_session_cli_env(config, session_id)
                    await _apply_worker_safety_gate_permission(
                        config, session_id, extra_env
                    )
                    launch_config = await _launch_config_for_session(config)
                    session_obj = UnifiedSession(cli_type, launch_config)
                    _cli_home = extra_env.get("HOME")

                    # Inject system prompt (guidelines, plugins, AGENTS.md, output style)
                    #
                    # Claude extended-thinking blocks carry signatures that
                    # are verified when a native conversation is resumed. If
                    # we restart with --resume and also append a fresh system
                    # prompt, Claude can reject its own saved thinking blocks
                    # with "Invalid signature in thinking block". Resumed
                    # Claude sessions already have their original prompt
                    # context in the native transcript, so keep that context
                    # stable on resume.
                    #
                    # Claude (>= 2.1.29x) also snapshots the system prompt on a
                    # conversation's first request and replays it on every
                    # resume, so context appended here on a --resume only takes
                    # effect after the next compaction, or immediately when
                    # IVE_CLAUDE_FRESH_SYSTEM_PROMPT=1 makes UnifiedSession pass
                    # --system-prompt-snapshot off (opt-in because of the
                    # thinking-signature risk above).
                    _deferred_initial_prompt = None
                    if system_prompt_parts:
                        combined_prompt = "\n\n".join(system_prompt_parts)
                        if session_obj.profile.managed_context_adapter == "antigravity_rules":
                            _deferred_initial_prompt = combined_prompt
                        else:
                            session_obj.append_system_prompt(combined_prompt)

                    if (
                        session_obj.profile.managed_context_adapter == "antigravity_rules"
                        and _deferred_initial_prompt
                    ):
                        try:
                            _agy_rules_dir = _activate_antigravity_session_rules_dir(
                                session_obj,
                                session_id,
                                _deferred_initial_prompt,
                            )
                            if _agy_rules_dir:
                                _deferred_initial_prompt = None
                                logger.info(
                                    "Antigravity session %s using private Rules add-dir: %s",
                                    session_id[:8],
                                    _agy_rules_dir,
                                )
                        except Exception as exc:
                            msg = (
                                "Antigravity startup blocked: IVE could not prepare "
                                f"the session Rules add-dir ({exc})."
                            )
                            logger.error("%s", msg)
                            await _fail_session_start(
                                session_id,
                                msg,
                                "antigravity_rules_setup_failed",
                            )
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "error",
                                "message": msg,
                            })
                            continue

                    if _deferred_initial_prompt:
                        msg = (
                            f"{cli_type} startup blocked: IVE has no native managed-context "
                            "injection path for this CLI. Refusing to paste internal context "
                            "into the terminal prompt."
                        )
                        logger.error("%s", msg)
                        await _fail_session_start(
                            session_id,
                            msg,
                            "managed_context_native_injection_missing",
                        )
                        await ws.send_json({
                            "session_id": session_id,
                            "type": "error",
                            "message": msg,
                        })
                        continue

                    await _record_session_runtime_home(session_id, cli_type, _cli_home)

                    # ── MCP servers: the one shared assembly ──
                    # Same helper the auto-start and restart paths call, so a
                    # session's session_mcp_servers rows materialize the same
                    # way no matter which entry point spawned the PTY.
                    _mcp_result = await _apply_session_mcp(
                        session_obj, config, session_id, extra_env
                    )
                    _w2w_comms_env, _w2w_context_env, _w2w_coord_env = _mcp_result["w2w"]

                    # ── Resume: resolve native session ID ──
                    # Pre-checks the transcript; a pointer whose transcript is
                    # gone is cleared here and this same start spawns fresh
                    # instead of booting a --resume that exits on arrival.
                    await _apply_session_resume(
                        session_obj, config, session_id, extra_env
                    )

                    # Mode policy: clamp Code mode + reject Brief PTY starts
                    # before build_command() reads the (now-mutated) config.
                    _ws_ctx = get_auth(request)
                    if not _ws_ctx.is_owner:
                        try:
                            import mode_policy as _mode_policy
                            _bash_allow = await _get_code_bash_allowlist()
                            _mode_policy.enforce_mode_for_pty(
                                session_obj, _ws_ctx.mode,
                                code_bash_allowlist=_bash_allow,
                            )
                        except Exception as _mode_err:
                            await _emit_terminal_mode_violation(
                                ws, _ws_ctx, config, "start_pty", str(_mode_err)
                            )
                            continue

                    if session_obj.profile.id == "antigravity":
                        from antigravity_runtime import apply_model as _apply_agy_model
                        await _refresh_antigravity_native_context(config)
                        _apply_agy_model(config.get("model"), home=_cli_home)

                    # Build final command
                    cmd = session_obj.build_command()
                    cmd_binary = cmd[0]
                    cmd_args = cmd[1:]

                    # Inject hook relay env vars so the CLI hook script
                    # can POST lifecycle events back to Commander.
                    extra_env["COMMANDER_SESSION_ID"] = session_id
                    import session_proofs
                    extra_env[session_proofs.ENV_VAR] = session_proofs.issue(session_id)
                    extra_env["COMMANDER_API_URL"] = f"http://{HOST}:{PORT}"
                    extra_env["COMMANDER_WORKSPACE_ID"] = config.get("workspace_id", "")
                    extra_env["COMMANDER_WORKSPACE_PATH"] = config.get("workspace_path", "")
                    extra_env["COMMANDER_SESSION_TYPE"] = config.get("session_type") or "worker"
                    extra_env["COMMANDER_CLI_TYPE"] = cli_type
                    extra_env["WORKER_SESSION_ID"] = session_id
                    extra_env["WORKER_WORKSPACE_ID"] = config.get("workspace_id", "")
                    extra_env["WORKER_SESSION_TYPE"] = config.get("session_type") or "worker"
                    extra_env["WORKER_W2W_COMMS"] = _w2w_comms_env
                    extra_env["WORKER_W2W_CONTEXT"] = _w2w_context_env
                    extra_env["WORKER_W2W_COORDINATION"] = _w2w_coord_env

                    # Git attribution is captured out-of-band. Keep Git's
                    # author/committer identity on normal repo/user config.
                    try:
                        from git_attribution import inject_git_attribution_env
                        await inject_git_attribution_env(config, session_id, extra_env)
                    except Exception as git_attr_exc:
                        logger.debug("Git attribution env skipped: %s", git_attr_exc)

                    if extension_host.available("swarmlock"):
                        extra_env.update(await _swarmlock_launch_environment(config, session_id))

                    try:
                        # Snapshot existing session files BEFORE starting PTY (for resume detection)
                        pre_files = None
                        if not config.get("native_session_id"):
                            pre_files = _snapshot_files_for_detection(
                                cli_type,
                                config["workspace_path"],
                                extra_env.get("HOME"),
                            )
                        # A new PTY lifetime re-arms one-shot output failure
                        # detection and discards stale auth banners from the
                        # previous process.
                        capture_proc.clear_buffer(session_id)
                        mark_pty_started(session_id, _ws_ctx.mode)
                        await pty_mgr.start_session(
                            session_id, config["workspace_path"], cols, rows, cmd_args, extra_env, cmd_binary,
                            sandbox_type=config.get("sandbox_type", "none"),
                            sandbox_network=bool(config.get("sandbox_network", 1)),
                            geometry_owner=geometry_viewer_id,
                        )
                        await _mark_session_pty_started(session_id)
                        await _clear_auth_failed_session_state(session_id)
                        from hooks import get_session_logical_status
                        pty_alive = pty_mgr.is_alive(session_id)
                        logical_status = get_session_logical_status(session_id, pty_alive, "idle")
                        await broadcast({"session_id": session_id, "type": "status", "status": logical_status, "pty_alive": pty_alive})
                        geometry = pty_mgr.get_geometry(session_id)
                        if geometry:
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "terminal_geometry",
                                "authoritative": True,
                                "changed": False,
                                **geometry,
                            })
                        stream = _terminal_stream(session_id)
                        await _send_terminal_resume(
                            ws,
                            session_id,
                            after_sequence=0,
                            generation=stream.generation,
                        )

                        # Session Advisor: track workspace mapping + seed intent with purpose
                        if config.get("workspace_id"):
                            _session_workspace[session_id] = config["workspace_id"]
                        _session_cli_type_cache[session_id] = cli_type
                        try:
                            from session_advisor import update_intent
                            purpose = config.get("purpose")
                            if purpose:
                                _fire_and_forget(update_intent(
                                    session_id, purpose, source="purpose",
                                    workspace_id=config.get("workspace_id"),
                                    broadcast_fn=broadcast,
                                ))
                        except Exception:
                            pass
                        # Detect this session's specific conversation file for resume
                        if not config.get("native_session_id"):
                            _schedule_session_detection(
                                cli_type,
                                session_id,
                                config["workspace_path"],
                                pre_files,
                                extra_env.get("HOME"),
                            )
                    except Exception as e:
                        logger.exception(f"Failed to start PTY for {session_id}")
                        await ws.send_json({
                            "session_id": session_id,
                            "type": "error",
                            "message": str(e),
                        })

                elif action == "input":
                    session_id = data.get("session_id")
                    input_data = data.get("data", "")
                    cfg = await get_session_config(session_id) if session_id else None
                    if not cfg or not _session_visible_to_request(cfg, request):
                        await ws.send_json({
                            "session_id": session_id,
                            "type": "error",
                            "message": "Session not found",
                        })
                        continue
                    if not await _terminal_control_allowed(
                        ws, request, cfg, "input"
                    ):
                        continue
                    if _shell_session.is_shell_session(cfg):
                        # Plain terminal: keystrokes go straight to the shell.
                        # No prompt expansion, /login interception, branch or
                        # rename handling, prompt tracking.
                        if input_data and not pty_mgr.is_alive(session_id):
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "error",
                                "message": "Session not running",
                            })
                        elif input_data:
                            pty_mgr.write(session_id, input_data.encode("utf-8"))
                        continue
                    if session_id and _is_auth_recovery_input(input_data):
                        _input_bufs[session_id] = ""
                        await _broadcast_auth_recovery(
                            session_id,
                            (cfg.get("cli_type") or "claude").lower(),
                            intercepted_login=True,
                        )
                        continue
                    # BUG L7: surface dead session_ids instead of silently
                    # dropping the keystrokes — clients had no way to learn
                    # the PTY is gone short of polling.
                    if session_id and input_data and not pty_mgr.is_alive(session_id):
                        await ws.send_json({
                            "session_id": session_id,
                            "type": "error",
                            "message": "Session not running",
                        })
                        continue
                    if session_id and input_data:
                        cli_type = (cfg or {}).get("cli_type", "claude")
                        # Only what is on screen right now counts. Scrollback
                        # holds arbitrary agent output ("Added a Login button").
                        startup_blocker = _detect_cli_startup_blocker(
                            cli_type,
                            _startup_blocker_text(session_id),
                        )
                        if startup_blocker and startup_blocker.get("type") in _AUTH_BLOCKER_TYPES:
                            # Login prompts are detected heuristically: tell the
                            # client (recovery notice), but let the keystroke
                            # through. The user may be signing in right here.
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "error",
                                "message": startup_blocker["label"],
                                "startup_blocker": startup_blocker,
                            })
                            startup_blocker = None
                        if startup_blocker and not _is_startup_control_input(input_data):
                            if cli_type == "codex" and startup_blocker.get("type") == "update_required":
                                for _ in range(3):
                                    if not pty_mgr.is_alive(session_id):
                                        break
                                    pty_mgr.write(session_id, b"\x1b")
                                    await _asyncio.sleep(0.15)
                                await ws.send_json({
                                    "session_id": session_id,
                                    "type": "error",
                                    "message": "Codex update prompt dismissed; retry once the prompt returns.",
                                    "startup_blocker": startup_blocker,
                                })
                                continue
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "error",
                                "message": startup_blocker["label"],
                                "startup_blocker": startup_blocker,
                            })
                            continue

                        # ── Gemini /branch interception ──
                        # Gemini has no native /branch — intercept on Enter
                        # and handle it at the Commander layer.
                        if "\r" in input_data or "\n" in input_data:
                            try:
                                if await _maybe_handle_gemini_branch(session_id):
                                    _input_bufs[session_id] = ""
                                    continue
                            except Exception as _br_err:
                                logger.warning("Gemini /branch interception failed: %s", _br_err)

                        # Check for @prompt: token expansion on Enter.
                        # Wrapped in try/except so any bug degrades to the
                        # normal passthrough — never blocks terminal input.
                        expansion = None
                        try:
                            expansion = await _maybe_expand_input(session_id, input_data)
                        except Exception as _exp_err:
                            logger.warning("Token expansion failed: %s", _exp_err)
                        if expansion is not None:
                            pty_mgr.write(session_id, expansion)
                        else:
                            pty_mgr.write(session_id, input_data.encode("utf-8"))
                            _track_input(session_id, input_data)
                            if input_data in _CLAUDE_INTERRUPT_INPUTS and str(cli_type or "claude").lower() == "claude":
                                _fire_and_forget(_confirm_claude_interrupt_after_input(session_id))
                        # Auto-unarchive: if user sends input to an archived session
                        try:
                            _fire_and_forget(_maybe_unarchive_on_input(session_id))
                        except Exception:
                            pass
                        # Detect /rename command → re-scan session for updated slug
                        if "/rename" in input_data:
                            if cfg:
                                _rename_cli_home = managed_home("claude", cfg["account_id"]) if cfg.get("account_id") else None
                                _asyncio.ensure_future(detect_claude_session(
                                    session_id,
                                    cfg["workspace_path"],
                                    force_rename=True,
                                    cli_home=_rename_cli_home,
                                ))

                elif action == "replay_turns":
                    session_id = data.get("session_id")
                    turns = data.get("turns", [])
                    if session_id and turns:
                        cfg = await get_session_config(session_id)
                        if not cfg or not _session_visible_to_request(cfg, request):
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "error",
                                "message": "Session not found",
                            })
                            continue
                        if not await _terminal_control_allowed(
                            ws, request, cfg, "replay_turns"
                        ):
                            continue
                        # Validate the session is alive before scheduling the
                        # 90s replay coroutine. Without this check, bogus IDs
                        # broadcast a 'replaying' status to every connected
                        # client and run silently for 90s (BUG H5).
                        if not pty_mgr.is_alive(session_id):
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "error",
                                "message": "Session not running",
                            })
                            continue
                        asyncio.create_task(_replay_turns(session_id, turns))

                elif action in ("claim_geometry", "release_geometry"):
                    # Phone remote: while a phone shows a session full screen
                    # it owns the PTY size (its width, fewer than 80 columns
                    # allowed); leaving the view releases it and the other
                    # screens re-claim their own size (terminal_geometry_available).
                    session_id = data.get("session_id")
                    if not session_id:
                        continue
                    cfg = await get_session_config(session_id)
                    if not cfg or not _session_visible_to_request(cfg, request):
                        continue
                    if not await _terminal_control_allowed(ws, request, cfg, "resize"):
                        continue
                    if action == "release_geometry":
                        if pty_mgr.release_geometry(session_id, geometry_viewer_id):
                            await broadcast({"session_id": session_id, "type": "terminal_geometry_available"})
                        continue
                    try:
                        cols = max(10, min(int(data.get("cols")), 500))
                        rows = max(4, min(int(data.get("rows")), 300))
                    except (TypeError, ValueError):
                        continue
                    previous, geometry = pty_mgr.claim_geometry(session_id, geometry_viewer_id, cols, rows)
                    if not geometry:
                        continue
                    await ws.send_json({"session_id": session_id, "type": "terminal_geometry", **geometry})
                    if previous and previous != geometry_viewer_id:
                        # Everyone else now follows the phone's size.
                        notice = json.dumps({
                            "session_id": session_id, "type": "terminal_geometry",
                            "authoritative": False, "changed": geometry["changed"],
                            "cols": geometry["cols"], "rows": geometry["rows"],
                        })
                        for other_ws in list(ws_clients):
                            if other_ws is ws:
                                continue
                            try:
                                await other_ws.send_str(notice)
                            except (ConnectionResetError, ConnectionError, RuntimeError):
                                pass

                elif action == "resize":
                    session_id = data.get("session_id")
                    cols = data.get("cols", 120)
                    rows = data.get("rows", 40)
                    if session_id:
                        cfg = await get_session_config(session_id)
                        if not cfg or not _session_visible_to_request(cfg, request):
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "error",
                                "message": "Session not found",
                            })
                            continue
                        if not await _terminal_control_allowed(
                            ws, request, cfg, "resize"
                        ):
                            continue
                        if not pty_mgr.is_alive(session_id):
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "error",
                                "message": "Session not running",
                            })
                            continue
                        geometry = pty_mgr.request_geometry(
                            session_id, geometry_viewer_id, cols, rows,
                        )
                        if geometry:
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "terminal_geometry",
                                **geometry,
                            })

                elif action == "resume_pty":
                    session_id = data.get("session_id")
                    cfg = await get_session_config(session_id) if session_id else None
                    if (
                        session_id
                        and cfg
                        and _session_readable_to_request(cfg, request)
                        and pty_mgr.is_alive(session_id)
                    ):
                        if not await _terminal_control_allowed(
                            ws, request, cfg, "resume_pty"
                        ):
                            continue
                        # No cols/rows: keep the PTY size (hidden/Overview
                        # terminals); the reply tells the client that size.
                        geometry = pty_mgr.request_geometry(
                            session_id,
                            geometry_viewer_id,
                            data.get("cols"),
                            data.get("rows"),
                        )
                        if geometry:
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "terminal_geometry",
                                **geometry,
                            })
                        await _send_terminal_resume(
                            ws,
                            session_id,
                            after_sequence=data.get("after_sequence"),
                            generation=data.get("stream_generation"),
                        )
                    elif session_id:
                        await ws.send_json({
                            "session_id": session_id,
                            "type": "terminal_resumed",
                            "pty_alive": False,
                        })

                elif action == "broadcast":
                    session_ids = data.get("session_ids", [])
                    input_data = data.get("data", "")
                    source_session_id = data.get("source_session_id")
                    if session_ids and input_data:
                        encoded = input_data.encode("utf-8")
                        visible_sids = []
                        for sid in session_ids:
                            cfg = await get_session_config(sid)
                            if (
                                cfg
                                and _session_visible_to_request(cfg, request)
                                and await _terminal_control_allowed(
                                    ws, request, cfg, "broadcast"
                                )
                            ):
                                visible_sids.append(sid)
                        for sid in visible_sids:
                            pty_mgr.write(sid, encoded)
                        # If a commander session broadcasts to workers, adopt them
                        if source_session_id and visible_sids:
                            asyncio.create_task(_adopt_sessions(source_session_id, visible_sids))

                elif action == "stop":
                    session_id = data.get("session_id")
                    if session_id:
                        cfg = await get_session_config(session_id)
                        if not cfg or not _session_visible_to_request(cfg, request):
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "error",
                                "message": "Session not found",
                            })
                            continue
                        if not await _terminal_control_allowed(
                            ws, request, cfg, "stop"
                        ):
                            continue
                        if not pty_mgr.is_alive(session_id):
                            await ws.send_json({
                                "session_id": session_id,
                                "type": "error",
                                "message": "Session not running",
                            })
                            continue
                        await _stop_session_expected(session_id)

                # ── Live Preview (Playwright browser) ──────────────
                # Multi-peer: previews are coalesced by share_key
                # (workspace_id + port). All subscribers receive frames;
                # one subscriber at a time holds the driver role.
                elif action == "preview_start":
                    url = data.get("url", "").strip()
                    if not url:
                        continue
                    if not url.startswith(("http://", "https://")):
                        url = "https://" + url
                    pw = data.get("width", 1280)
                    ph = data.get("height", 720)
                    workspace_id = data.get("workspace_id")
                    try:
                        import preview_browser
                        sub_id = _ws_subscriber_id(ws)
                        share_key = preview_browser.share_key_for(url, workspace_id)

                        async def _send_frame(b64, _ws=ws):
                            await _ws.send_json({"type": "preview_frame", "data": b64})

                        async def _send_nav(new_url, _ws=ws):
                            await _ws.send_json({"type": "preview_navigated", "url": new_url})

                        async def _send_driver(driver, _ws=ws):
                            await _ws.send_json({
                                "type": "preview_driver_changed",
                                "driver_id": driver,
                            })

                        pid, started_new, driver_id = await preview_browser.start_or_attach(
                            url=url,
                            width=pw,
                            height=ph,
                            share_key=share_key,
                            subscriber_id=sub_id,
                            on_frame=_send_frame,
                            on_navigate=_send_nav,
                            on_driver_changed=_send_driver,
                        )
                        ws_preview_subs.setdefault(id(ws), set()).add(pid)
                        await ws.send_json({
                            "type": "preview_started",
                            "preview_id": pid,
                            "url": url,
                            "share_key": share_key,
                            "shared": share_key is not None,
                            "started_new": started_new,
                            "driver_id": driver_id,
                            "is_driver": driver_id == sub_id,
                            "subscriber_id": sub_id,
                            "subscriber_count": preview_browser.subscriber_count(pid),
                        })
                    except Exception as e:
                        logger.warning("Preview start failed: %s", e)
                        await ws.send_json({"type": "preview_error", "error": str(e)})

                elif action == "preview_input":
                    pid = data.get("preview_id")
                    evt = data.get("event")
                    if pid and evt:
                        import preview_browser
                        sub_id = _ws_subscriber_id(ws)
                        ok = await preview_browser.send_input(pid, sub_id, evt)
                        if not ok:
                            await ws.send_json({
                                "type": "preview_driver_denied",
                                "preview_id": pid,
                                "driver_id": preview_browser.get_driver(pid),
                            })

                elif action == "preview_navigate":
                    pid = data.get("preview_id")
                    url = data.get("url", "").strip()
                    if pid and url:
                        if not url.startswith(("http://", "https://")):
                            url = "https://" + url
                        import preview_browser
                        sub_id = _ws_subscriber_id(ws)
                        ok = await preview_browser.navigate(pid, sub_id, url)
                        if not ok:
                            await ws.send_json({
                                "type": "preview_driver_denied",
                                "preview_id": pid,
                                "driver_id": preview_browser.get_driver(pid),
                            })

                elif action == "preview_resize":
                    pid = data.get("preview_id")
                    pw = data.get("width", 1280)
                    ph = data.get("height", 720)
                    if pid:
                        import preview_browser
                        sub_id = _ws_subscriber_id(ws)
                        await preview_browser.resize(pid, sub_id, pw, ph)

                elif action == "preview_claim_driver":
                    pid = data.get("preview_id")
                    if pid:
                        import preview_browser
                        sub_id = _ws_subscriber_id(ws)
                        await preview_browser.claim_driver(pid, sub_id)

                elif action == "preview_screenshot":
                    pid = data.get("preview_id")
                    if pid:
                        import preview_browser
                        png = await preview_browser.screenshot_png(pid)
                        if png:
                            import base64
                            await ws.send_json({
                                "type": "preview_screenshot",
                                "preview_id": pid,
                                "data": base64.b64encode(png).decode(),
                            })

                elif action == "preview_stop":
                    # In the multi-peer model this is "I'm leaving" — the
                    # page only actually shuts down once subscribers hit 0
                    # and the grace period elapses.
                    pid = data.get("preview_id")
                    if pid:
                        import preview_browser
                        sub_id = _ws_subscriber_id(ws)
                        await preview_browser.unsubscribe(pid, sub_id)
                        subs = ws_preview_subs.get(id(ws))
                        if subs:
                            subs.discard(pid)

                # ── Multiplayer presence ──────────────────────
                elif action == "hello":
                    client_id = data.get("client_id")
                    name = data.get("name", "Anonymous")
                    color = data.get("color", "#6366f1")
                    if client_id:
                        ws_peers.pop(client_id, None)
                        ws_peers[client_id] = {
                            "ws": ws,
                            "name": name,
                            "color": color,
                            "viewing_session": None,
                        }
                        # Send snapshot of existing peers to the joiner
                        snapshot = []
                        for cid, info in ws_peers.items():
                            if cid != client_id:
                                snapshot.append({
                                    "client_id": cid,
                                    "name": info["name"],
                                    "color": info["color"],
                                    "viewing_session": info["viewing_session"],
                                })
                        await ws.send_json({
                            "type": "presence_snapshot",
                            "peers": snapshot,
                        })
                        # Broadcast join to everyone else
                        join_msg = json.dumps({
                            "type": "presence_join",
                            "client_id": client_id,
                            "name": name,
                            "color": color,
                        })
                        for other_ws in ws_clients:
                            if other_ws is not ws:
                                try:
                                    await other_ws.send_str(join_msg)
                                except (ConnectionResetError, ConnectionError, RuntimeError):
                                    pass

                elif action == "presence_update":
                    client_id = data.get("client_id")
                    if client_id and client_id in ws_peers:
                        if "viewing_session" in data:
                            ws_peers[client_id]["viewing_session"] = data["viewing_session"]
                        if "name" in data:
                            ws_peers[client_id]["name"] = data["name"]
                        if "color" in data:
                            ws_peers[client_id]["color"] = data["color"]
                        info = ws_peers[client_id]
                        update_msg = json.dumps({
                            "type": "presence_update",
                            "client_id": client_id,
                            "name": info["name"],
                            "color": info["color"],
                            "viewing_session": info["viewing_session"],
                        })
                        for other_ws in ws_clients:
                            if other_ws is not ws:
                                try:
                                    await other_ws.send_str(update_msg)
                                except (ConnectionResetError, ConnectionError, RuntimeError):
                                    pass

            elif msg.type in (aiohttp.WSMsgType.ERROR, aiohttp.WSMsgType.CLOSE):
                break
    finally:
        qws = getattr(ws, "_queued_ws", None)
        if qws:
            qws.close_task()
        ws_clients.discard(ws)
        released_geometry = pty_mgr.release_geometry_owner(geometry_viewer_id)
        for released_session_id in released_geometry:
            await broadcast({
                "session_id": released_session_id,
                "type": "terminal_geometry_available",
            })

        # Unsubscribe from any active Playwright previews so the headless
        # pages are torn down (after grace period) instead of leaking.
        owned_pids = ws_preview_subs.pop(id(ws), set())
        if owned_pids:
            try:
                import preview_browser
                sub_id = _ws_subscriber_id(ws)
                for pid in owned_pids:
                    await preview_browser.unsubscribe(pid, sub_id)
            except Exception as e:
                logger.debug("Preview unsubscribe on disconnect failed: %s", e)
        # Clean up peer presence and notify others
        leaving_id = None
        for cid, info in ws_peers.items():
            if info["ws"] is ws:
                leaving_id = cid
                break
        if leaving_id:
            ws_peers.pop(leaving_id, None)
            leave_msg = json.dumps({
                "type": "presence_leave",
                "client_id": leaving_id,
            })
            for other_ws in ws_clients:
                try:
                    await other_ws.send_str(leave_msg)
                except (ConnectionResetError, ConnectionError, RuntimeError):
                    pass
        logger.info(f"WebSocket disconnected ({len(ws_clients)} total)")

    return ws


# ─── REST: Workspaces ────────────────────────────────────────────────────

import workspace_fields


async def list_workspaces(request: web.Request) -> web.Response:
    ctx = get_auth(request)
    db = await get_db()
    try:
        # Sort by user-defined order first (order_index, ascending), then by last_used_at as a tiebreaker.
        # Workspaces that have never been reordered have order_index = 0 and fall back to recency.
        if ctx.is_owner:
            cur = await db.execute(
                "SELECT * FROM workspaces ORDER BY order_index ASC, last_used_at DESC NULLS LAST"
            )
        else:
            cur = await db.execute(
                "SELECT * FROM workspaces WHERE id = ?",
                (ctx.workspace_id,),
            )
        rows = await cur.fetchall()
        return web.json_response([
            _with_quick_flag(workspace_fields.project_row(r)) for r in rows
        ])
    finally:
        await db.close()


_OVERVIEW_DETAIL_LIMIT = 5
_OVERVIEW_SESSION_STATUSES = (
    "running", "idle", "stopped", "auth_failed", "quota_exceeded", "error",
)
_OVERVIEW_BLOCKED_STATUSES = ("auth_failed", "quota_exceeded", "error")
_OVERVIEW_RESEARCH_TERMINAL_STATUSES = (
    "complete", "completed", "failed", "error", "cancelled", "stopped",
)
TEST_QUEUE_RUNNING_TIMEOUT_SECONDS = 30 * 60
TEST_QUEUE_MAX_ATTEMPTS = 2
TEST_QUEUE_ATTENTION_STATUSES = ("failed", "parked")


async def get_overview(request: web.Request) -> web.Response:
    """Return IVE-owned live state for every workspace visible to the caller."""
    ctx = get_auth(request)
    db = await get_db()
    try:
        if ctx.is_owner:
            cur = await db.execute(
                "SELECT id, name FROM workspaces "
                "ORDER BY order_index ASC, last_used_at DESC NULLS LAST"
            )
        else:
            cur = await db.execute(
                "SELECT id, name FROM workspaces WHERE id = ?",
                (ctx.workspace_id,),
            )
        workspace_rows = await cur.fetchall()
        workspace_ids = [row["id"] for row in workspace_rows]
        projects = {}
        for row in workspace_rows:
            projects[row["id"]] = {
                "id": row["id"],
                "name": row["name"],
                "sessions": {
                    "total": 0,
                    "by_status": {
                        status: 0 for status in _OVERVIEW_SESSION_STATUSES
                    },
                },
                "blocked_sessions": {"total": 0, "items": []},
                "open_tasks": {"total": 0, "items": []},
                "test_queue": {
                    "depth": 0,
                    "running_total": 0,
                    "running": None,
                },
                "test_attention": {"total": 0, "items": []},
                "active_research": {"total": 0, "items": []},
            }

        if not workspace_ids:
            return web.json_response({
                "workspace_total": 0,
                "detail_limit": _OVERVIEW_DETAIL_LIMIT,
                "workspaces": [],
            })

        workspace_marks = ",".join("?" for _ in workspace_ids)

        cur = await db.execute(
            f"""SELECT workspace_id, status, COUNT(*) AS total
                  FROM sessions
                 WHERE workspace_id IN ({workspace_marks})
                 GROUP BY workspace_id, status""",
            workspace_ids,
        )
        for row in await cur.fetchall():
            project = projects[row["workspace_id"]]
            status = row["status"] or "idle"
            count = row["total"]
            project["sessions"]["total"] += count
            project["sessions"]["by_status"].setdefault(status, 0)
            project["sessions"]["by_status"][status] += count
            if status in _OVERVIEW_BLOCKED_STATUSES:
                project["blocked_sessions"]["total"] += count

        blocked_marks = ",".join("?" for _ in _OVERVIEW_BLOCKED_STATUSES)
        cur = await db.execute(
            f"""WITH ranked AS (
                    SELECT id, workspace_id, name, session_type, status,
                           parent_session_id, last_active_at,
                           ROW_NUMBER() OVER (
                               PARTITION BY workspace_id
                               ORDER BY COALESCE(last_active_at, created_at) DESC, id
                           ) AS detail_rank
                      FROM sessions
                     WHERE workspace_id IN ({workspace_marks})
                       AND status IN ({blocked_marks})
                )
                SELECT * FROM ranked WHERE detail_rank <= ?
                ORDER BY workspace_id, detail_rank""",
            (*workspace_ids, *_OVERVIEW_BLOCKED_STATUSES, _OVERVIEW_DETAIL_LIMIT),
        )
        for row in await cur.fetchall():
            projects[row["workspace_id"]]["blocked_sessions"]["items"].append({
                "id": row["id"],
                "name": row["name"],
                "role": row["session_type"],
                "status": row["status"],
                "reason": row["status"],
                "parent_session_id": row["parent_session_id"],
                "last_active_at": row["last_active_at"],
            })

        cur = await db.execute(
            f"""WITH ranked AS (
                    SELECT id, workspace_id, title, status, priority, updated_at,
                           COUNT(*) OVER (PARTITION BY workspace_id) AS total,
                           ROW_NUMBER() OVER (
                               PARTITION BY workspace_id
                               ORDER BY priority DESC, updated_at DESC, id
                           ) AS detail_rank
                      FROM tasks
                     WHERE workspace_id IN ({workspace_marks})
                       AND status NOT IN ('done', 'verified')
                )
                SELECT * FROM ranked WHERE detail_rank <= ?
                ORDER BY workspace_id, detail_rank""",
            (*workspace_ids, _OVERVIEW_DETAIL_LIMIT),
        )
        for row in await cur.fetchall():
            project = projects[row["workspace_id"]]["open_tasks"]
            project["total"] = row["total"]
            project["items"].append({
                "id": row["id"],
                "title": row["title"],
                "status": row["status"],
                "priority": row["priority"],
                "updated_at": row["updated_at"],
            })

        cur = await db.execute(
            f"""SELECT workspace_id, status, COUNT(*) AS total
                  FROM test_queue
                 WHERE workspace_id IN ({workspace_marks})
                   AND status IN ('queued', 'running')
                 GROUP BY workspace_id, status""",
            workspace_ids,
        )
        for row in await cur.fetchall():
            queue = projects[row["workspace_id"]]["test_queue"]
            if row["status"] == "queued":
                queue["depth"] = row["total"]
            else:
                queue["running_total"] = row["total"]

        cur = await db.execute(
            f"""WITH ranked AS (
                    SELECT id, workspace_id, task_id, task_revision, title,
                           assigned_session_id, started_at,
                           ROW_NUMBER() OVER (
                               PARTITION BY workspace_id
                               ORDER BY started_at ASC, created_at ASC, id
                           ) AS detail_rank
                      FROM test_queue
                     WHERE workspace_id IN ({workspace_marks})
                       AND status = 'running'
                )
                SELECT * FROM ranked WHERE detail_rank = 1""",
            workspace_ids,
        )
        for row in await cur.fetchall():
            projects[row["workspace_id"]]["test_queue"]["running"] = {
                "id": row["id"],
                "task_id": row["task_id"],
                "task_revision": row["task_revision"],
                "title": row["title"],
                "assigned_session_id": row["assigned_session_id"],
                "started_at": row["started_at"],
            }

        attention_marks = ",".join("?" for _ in TEST_QUEUE_ATTENTION_STATUSES)
        cur = await db.execute(
            f"""WITH ranked AS (
                    SELECT id, workspace_id, task_id, task_revision, title,
                           status, assigned_session_id, result_summary,
                           attempt_count, completed_at,
                           COUNT(*) OVER (PARTITION BY workspace_id) AS total,
                           ROW_NUMBER() OVER (
                               PARTITION BY workspace_id
                               ORDER BY completed_at DESC, created_at DESC, id
                           ) AS detail_rank
                      FROM test_queue
                     WHERE workspace_id IN ({workspace_marks})
                       AND status IN ({attention_marks})
                )
                SELECT * FROM ranked WHERE detail_rank <= ?
                ORDER BY workspace_id, detail_rank""",
            (
                *workspace_ids,
                *TEST_QUEUE_ATTENTION_STATUSES,
                _OVERVIEW_DETAIL_LIMIT,
            ),
        )
        for row in await cur.fetchall():
            attention = projects[row["workspace_id"]]["test_attention"]
            attention["total"] = row["total"]
            attention["items"].append({
                "id": row["id"],
                "task_id": row["task_id"],
                "task_revision": row["task_revision"],
                "title": row["title"],
                "status": row["status"],
                "assigned_session_id": row["assigned_session_id"],
                "result_summary": row["result_summary"],
                "attempt_count": row["attempt_count"],
                "completed_at": row["completed_at"],
            })

        terminal_marks = ",".join(
            "?" for _ in _OVERVIEW_RESEARCH_TERMINAL_STATUSES
        )
        cur = await db.execute(
            f"""WITH ranked AS (
                    SELECT id, workspace_id, topic, status, session_id, updated_at,
                           COUNT(*) OVER (PARTITION BY workspace_id) AS total,
                           ROW_NUMBER() OVER (
                               PARTITION BY workspace_id
                               ORDER BY updated_at DESC, id
                           ) AS detail_rank
                      FROM research_entries
                     WHERE workspace_id IN ({workspace_marks})
                       AND status NOT IN ({terminal_marks})
                )
                SELECT * FROM ranked WHERE detail_rank <= ?
                ORDER BY workspace_id, detail_rank""",
            (
                *workspace_ids,
                *_OVERVIEW_RESEARCH_TERMINAL_STATUSES,
                _OVERVIEW_DETAIL_LIMIT,
            ),
        )
        for row in await cur.fetchall():
            research = projects[row["workspace_id"]]["active_research"]
            research["total"] = row["total"]
            research["items"].append({
                "id": row["id"],
                "topic": row["topic"],
                "status": row["status"],
                "session_id": row["session_id"],
                "updated_at": row["updated_at"],
            })

        return web.json_response({
            "workspace_total": len(workspace_rows),
            "detail_limit": _OVERVIEW_DETAIL_LIMIT,
            "workspaces": [projects[row["id"]] for row in workspace_rows],
        })
    finally:
        await db.close()


async def list_workspace_files(request: web.Request) -> web.Response:
    workspace_id = request.match_info["id"]
    if not _workspace_visible_to_auth(workspace_id, get_auth(request)):
        return web.json_response({"error": "workspace not found"}, status=404)
    rel_path = request.query.get("path") or ""

    # Reject traversal rather than silently turning it into another path.
    from pathlib import Path
    rel_path = rel_path.replace("\\", "/")
    if Path(rel_path).is_absolute() or ".." in Path(rel_path).parts:
        return web.json_response({"error": "access denied"}, status=403)

    db = await get_db()
    try:
        cur = await db.execute("SELECT path FROM workspaces WHERE id = ?", (workspace_id,))
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "workspace not found"}, status=404)
        ws_path = row["path"]
    finally:
        await db.close()

    import os
    try:
        root = Path(ws_path).resolve()
        target_dir = (root / rel_path).resolve()
        target_dir.relative_to(root)
    except (ValueError, OSError, RuntimeError):
        return web.json_response({"error": "access denied"}, status=403)

    if not os.path.exists(target_dir):
        return web.json_response({"error": "directory not found"}, status=404)

    if not os.path.isdir(target_dir):
        return web.json_response({"error": "not a directory"}, status=400)

    ignored_names = {".git", "node_modules", ".next", "__pycache__", ".svelte-kit", "dist", "build"}

    items = []
    try:
        for entry in os.scandir(target_dir):
            if entry.name in ignored_names:
                continue
            try:
                Path(entry.path).resolve().relative_to(root)
            except (ValueError, OSError, RuntimeError):
                continue
            is_dir = entry.is_dir()
            item_rel_path = os.path.join(rel_path, entry.name)
            size = 0
            if not is_dir:
                try:
                    size = entry.stat().st_size
                except OSError:
                    pass
            items.append({
                "name": entry.name,
                "path": item_rel_path,
                "is_dir": is_dir,
                "size": size
            })
    except OSError as e:
        return web.json_response({"error": str(e)}, status=500)

    items.sort(key=lambda x: (not x["is_dir"], x["name"].lower()))
    return web.json_response({"ok": True, "path": rel_path, "items": items})




async def reorder_workspaces(request: web.Request) -> web.Response:
    body = await request.json()
    ids = body.get("ids") or []
    if not isinstance(ids, list):
        return web.json_response({"error": "ids must be a list"}, status=400)
    db = await get_db()
    try:
        # Order indices are 1-based and densely packed by the order in `ids`.
        for idx, wid in enumerate(ids, start=1):
            await db.execute("UPDATE workspaces SET order_index = ? WHERE id = ?", (idx, wid))
        await db.commit()
        return web.json_response({"ok": True, "count": len(ids)})
    finally:
        await db.close()


async def browse_folder(request: web.Request) -> web.Response:
    """POST /api/browse-folder — open native OS folder picker and return selected path."""
    import asyncio
    import sys

    if sys.platform == "darwin":
        cmd = [
            "osascript", "-e",
            'set f to POSIX path of (choose folder with prompt "Select project folder")',
        ]
    elif sys.platform == "linux":
        cmd = ["zenity", "--file-selection", "--directory", "--title=Select project folder"]
    else:
        return web.json_response({"error": "unsupported platform"}, status=400)

    try:
        proc = await asyncio.create_subprocess_exec(
            *cmd,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, _ = await proc.communicate()
        if proc.returncode != 0:
            return web.json_response({"error": "cancelled"}, status=400)
        path = stdout.decode().strip().rstrip("/")
        return web.json_response({"path": path})
    except FileNotFoundError:
        return web.json_response({"error": "folder picker not available"}, status=500)


async def search_local_projects(request: web.Request) -> web.Response:
    from project_finder import search_projects
    query = request.query.get("q", "").strip()
    if not 2 <= len(query) <= 240:
        return web.json_response({"error": "Describe the project using 2 to 240 characters."}, status=400)
    db = await get_db()
    try:
        rows = await (await db.execute("SELECT id, name, path FROM workspaces")).fetchall()
        workspaces = [dict(row) for row in rows]
    finally:
        await db.close()
    result = await asyncio.to_thread(search_projects, query, workspaces)
    return web.json_response(result, headers={"Cache-Control": "no-store"})


async def create_workspace(request: web.Request) -> web.Response:
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid JSON body"}, status=400)
    if not isinstance(body, dict):
        return web.json_response({"error": "expected JSON object"}, status=400)
    path = str(body.get("path") or "").strip()
    name = str(body.get("name") or "").strip() or path.rstrip("/").split("/")[-1]
    if not path:
        return web.json_response({"error": "path required"}, status=400)

    import os
    expanded = os.path.expanduser(path)
    if not os.path.isabs(expanded):
        # A bare "my-project" / "Desktop/x" must never resolve against the
        # server's cwd — anchor relative paths at the user's home.
        expanded = os.path.join(os.path.expanduser("~"), expanded)
    if not os.path.isdir(expanded):
        if body.get("create_dir"):
            try:
                os.makedirs(expanded, exist_ok=True)
            except OSError as e:
                return web.json_response(
                    {"error": f"could not create directory: {e}"}, status=400)
        else:
            return web.json_response({"error": f"directory not found: {path}"}, status=400)
    path = os.path.abspath(expanded)
    name = name or path.rstrip("/").split("/")[-1]

    ws_id = str(uuid.uuid4())
    db = await get_db()
    try:
        existing = await db.execute(
            "SELECT id, name, path FROM workspaces WHERE path = ?", (path,)
        )
        existing_row = await existing.fetchone()
        if existing_row:
            # Only return identifying fields — the workspaces row may carry
            # browser profile paths and other internal state we don't want
            # to leak across the 409 boundary.
            return web.json_response({
                "error": "workspace already exists for this path",
                "existing": {
                    "id": existing_row["id"],
                    "name": existing_row["name"],
                    "path": existing_row["path"],
                },
            }, status=409)
        initial = {
            "id": ws_id, "name": name, "path": path,
            "comms_enabled": 1, "coordination_enabled": 1, "context_sharing_enabled": 1,
            **workspace_fields.create_values(),
        }
        await db.execute(
            f"INSERT INTO workspaces ({', '.join(initial)}) VALUES ({', '.join('?' for _ in initial)})",
            tuple(initial.values()),
        )
        await db.commit()
        cur = await db.execute("SELECT * FROM workspaces WHERE id = ?", (ws_id,))
        row = await cur.fetchone()
        asyncio.create_task(_ensure_workspace_commander_safely(ws_id))
        # True-up the managed memory block on (re)registration: renders current
        # entries into the repo's provider memory files — and with zero entries
        # STRIPS any orphaned block left by a previous DB generation (the sync
        # writes unconditionally; an empty entry set renders to nothing). Makes
        # re-adding a repo self-healing after a DB reset.
        asyncio.create_task(_sync_memory_to_cli(ws_id))
        return web.json_response(_with_quick_flag(workspace_fields.project_row(row)), status=201)
    finally:
        await db.close()


async def update_workspace(request: web.Request) -> web.Response:
    ws_id = request.match_info["id"]
    body = await request.json()
    if "research_llm_url" in body:
        return web.json_response(
            {
                "error": "research endpoints are configured on the selected model provider",
                "code": "research_provider_registry_required",
                "field": "research_llm_url",
            },
            status=400,
        )
    for model_field in workspace_fields.model_fields():
        if model_field not in body or body[model_field] is None:
            continue
        from model_providers import ModelProviderError
        from llm_router import resolve_model
        try:
            await resolve_model(body[model_field], required_capability="json")
        except ModelProviderError as exc:
            return web.json_response(
                {"error": str(exc), "code": exc.code, "field": model_field},
                status=400,
            )
    db = await get_db()
    try:
        fields, values = [], []
        for key, value in workspace_fields.update_values(body).items():
            fields.append(f"{key} = ?")
            values.append(value)
        if not fields:
            return web.json_response({"error": "no fields"}, status=400)
        values.append(ws_id)
        await db.execute(f"UPDATE workspaces SET {', '.join(fields)} WHERE id = ?", values)
        await db.commit()

        # Bust W2W flag cache when workspace toggles change
        if any(k in body for k in ("comms_enabled", "coordination_enabled", "context_sharing_enabled")):
            try:
                from hooks import invalidate_w2w_cache
                invalidate_w2w_cache()  # clear all — workspace change affects all sessions
            except Exception:
                pass

        cur = await db.execute("SELECT * FROM workspaces WHERE id = ?", (ws_id,))
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "workspace not found"}, status=404)
        if any(k in body for k in (
            "alloy_enabled", "commander_max_workers", "tester_max_workers",
            "orchestration_policy", "inherit_orchestration_policy_from",
        )):
            try:
                ws_prompt_dict = dict(row)
                if ws_prompt_dict.get("inherit_orchestration_policy_from"):
                    from db import resolve_workspace_orchestration_policy
                    ws_prompt_dict["orchestration_policy"] = await resolve_workspace_orchestration_policy(db, ws_id)
                await db.execute(
                    """UPDATE sessions
                       SET system_prompt = ?
                       WHERE workspace_id = ? AND session_type = 'commander'""",
                    (_build_commander_dynamic_prompt(ws_prompt_dict), ws_id),
                )
                await db.commit()
            except Exception as prompt_exc:
                logger.debug("Commander prompt refresh skipped after workspace update: %s", prompt_exc)
        return web.json_response(_with_quick_flag(workspace_fields.project_row(row)))
    finally:
        await db.close()


async def delete_workspace(request: web.Request) -> web.Response:
    from workspace_deletion import delete_registration, WorkspaceDeleteBusy
    from idle_reflection import clear_session
    import pipeline_engine
    import cascade_runner

    ws_id = request.match_info["id"]
    try:
        deleted = await delete_registration(
            ws_id, get_db=get_db, pty_manager=pty_mgr,
            stop_session=_stop_session_expected,
            cancel_pipeline=pipeline_engine.cancel_run,
            stop_cascade=cascade_runner.stop_run,
            clear_session=clear_session,
        )
    except WorkspaceDeleteBusy as exc:
        return web.json_response({"error": str(exc)}, status=409)
    if deleted is None:
        return web.json_response({"error": "workspace not found"}, status=404)

    # Remove only IVE's generated mirror after deregistration. Capture the old
    # opt-in before deleting it; looking settings up now would create an orphan
    # workspace_memory row. Unmanaged provider/user content remains untouched.
    if deleted["path"]:
        try:
            from memory_sync import sync_manager
            await sync_manager.strip_managed_blocks(
                deleted["path"], consent=deleted["native_memory_enabled"],
            )
        except Exception as exc:
            logger.debug("delete_workspace: strip_managed_blocks failed: %s", exc)
    # No directories/source files are deleted. Separate inherited workspaces
    # remain registered, with their inherited policy detached by the FK.
    payload = {"workspace_id": ws_id, "session_ids": deleted["session_ids"]}
    await broadcast({"type": "workspace_deleted", **payload})
    await bus.emit(CommanderEvent.WORKSPACE_DELETED, {
        **payload, "name": deleted["name"],
    }, source="api", actor="user")
    return web.json_response({"ok": True, **payload})


# ─── REST: Sessions ──────────────────────────────────────────────────────

BRAINSTORMER_PUBLIC_TAG = "brainstorm_public"
BRAINSTORMER_ENSURE_LOCKS: dict[str, asyncio.Lock] = {}


def _brainstormer_ensure_lock(workspace_id: str, owner_kind: str, owner_id: str) -> asyncio.Lock:
    key = f"{workspace_id}:{owner_kind}:{owner_id}"
    lock = BRAINSTORMER_ENSURE_LOCKS.get(key)
    if lock is None:
        lock = asyncio.Lock()
        BRAINSTORMER_ENSURE_LOCKS[key] = lock
    return lock


def _brainstormer_owner_key(ctx) -> tuple[str, str]:
    """Collapse auth context into the per-person Brainstormer owner key."""
    if ctx.is_owner:
        return "owner", ""
    return ctx.actor_kind or "joiner_session", ctx.actor_id or ""


def _brainstormer_owner_label(ctx) -> str:
    label = (ctx.label or "").strip()
    if label:
        return label
    if ctx.is_owner:
        return "Owner"
    if ctx.actor_id:
        return f"Joiner {ctx.actor_id[:8]}"
    return "Joiner"


def _brainstormer_session_owner_label(session: dict) -> str:
    owner_kind = (session.get("owner_actor_kind") or "").strip()
    owner_id = (session.get("owner_actor_id") or "").strip()
    if owner_kind == "owner":
        return "Owner"
    if owner_id:
        return f"Joiner {owner_id[:8]}"
    return "Unknown"


def _is_brainstormer_session(session: dict) -> bool:
    return (session.get("session_type") or "worker") == "brainstormer"


def _brainstormer_is_public(session: dict) -> bool:
    if not _is_brainstormer_session(session):
        return False
    return BRAINSTORMER_PUBLIC_TAG in _session_tags_from_value(session.get("tags"))


def _workspace_visible_to_auth(workspace_id: str | None, ctx) -> bool:
    """Owners are instance-wide; every joiner is bound to one workspace."""
    if ctx is None:
        return False
    if ctx.is_owner:
        return True
    scoped_workspace_id = (getattr(ctx, "workspace_id", None) or "").strip()
    return bool(workspace_id and scoped_workspace_id == workspace_id)


def _session_owned_by_auth(session: dict, ctx) -> bool:
    if (session.get("session_type") or "worker") != "brainstormer":
        return True
    owner_kind = (session.get("owner_actor_kind") or "").strip()
    owner_id = (session.get("owner_actor_id") or "").strip()
    if not owner_kind:
        # Legacy/unowned Brainstormers should not leak to joiners.
        return bool(ctx.is_owner)
    return (owner_kind, owner_id) == _brainstormer_owner_key(ctx)


def _session_visible_to_auth(session: dict, ctx) -> bool:
    return (
        _workspace_visible_to_auth(session.get("workspace_id"), ctx)
        and _session_owned_by_auth(session, ctx)
    )


def _session_readable_to_auth(session: dict, ctx) -> bool:
    """Output/read access includes public Brainstormers in the same workspace."""
    if not _workspace_visible_to_auth(session.get("workspace_id"), ctx):
        return False
    return _session_owned_by_auth(session, ctx) or (
        _is_brainstormer_session(session) and _brainstormer_is_public(session)
    )


def _session_visible_to_request(session: dict, request: web.Request) -> bool:
    ctx = get_auth(request)
    if not _workspace_visible_to_auth(session.get("workspace_id"), ctx):
        return False
    caller_session_id = (request.headers.get("X-IVE-Session-Id") or "").strip()
    if caller_session_id and caller_session_id == session.get("id"):
        return True
    if caller_session_id and (session.get("session_type") or "worker") == "brainstormer":
        return False
    return _session_visible_to_auth(session, ctx)


def _session_readable_to_request(session: dict, request: web.Request) -> bool:
    """Read access may include public Brainstormers; control access does not."""
    ctx = get_auth(request)
    if not _workspace_visible_to_auth(session.get("workspace_id"), ctx):
        return False
    caller_session_id = (request.headers.get("X-IVE-Session-Id") or "").strip()
    if caller_session_id:
        # Agent-origin calls should not inspect other people's Brainstormer
        # transcripts. Self-read remains available for the running session.
        return caller_session_id == session.get("id")
    return _session_readable_to_auth(session, ctx)


def _terminal_control_violation(ctx, config: dict, action: str) -> str | None:
    import shell_session as _shell_session  # plain terminals (cli_type "shell")
    if ctx.is_owner:
        return None
    if _shell_session.is_shell_session(config) and (ctx.mode or "").strip().lower() != "full":
        # A plain terminal is unrestricted host shell access.
        return "Terminal sessions need Full access"
    session_id = config.get("id")
    pty_alive = bool(session_id and pty_mgr.is_alive(session_id))
    target_mode = _pty_effective_modes.get(session_id) if pty_alive else None
    if pty_alive and not target_mode:
        target_mode = (config.get("owner_mode") or "full").strip().lower()
    import mode_policy as _mode_policy
    return _mode_policy.terminal_control_violation(
        ctx.mode,
        action=action,
        pty_alive=pty_alive,
        target_mode=target_mode,
    )


async def _record_terminal_mode_violation(
    ctx,
    config: dict,
    action: str,
    reason: str,
    path: str,
) -> None:
    session_id = config.get("id")
    payload = {
        "path": path,
        "session_id": session_id,
        "workspace_id": config.get("workspace_id"),
        "actor_kind": ctx.actor_kind,
        "actor_id": ctx.actor_id,
        "mode": ctx.mode,
        "reason": reason,
    }
    try:
        await bus.emit(
            CommanderEvent.MODE_VIOLATION_BLOCKED,
            payload,
            source="api",
        )
    except Exception:
        logger.exception("Failed to persist terminal mode violation")


async def _emit_terminal_mode_violation(
    ws: web.WebSocketResponse,
    ctx,
    config: dict,
    action: str,
    reason: str,
) -> None:
    session_id = config.get("id")
    await _record_terminal_mode_violation(
        ctx, config, action, reason, f"/ws:{action}"
    )
    await ws.send_json({
        "session_id": session_id,
        "type": "error",
        "message": f"Mode-blocked: {reason}",
    })


async def _terminal_control_allowed(
    ws: web.WebSocketResponse,
    request: web.Request,
    config: dict,
    action: str,
) -> bool:
    """Apply the caller's mode at every PTY control boundary."""
    ctx = get_auth(request)
    reason = _terminal_control_violation(ctx, config, action)
    if reason is None:
        return True
    await _emit_terminal_mode_violation(ws, ctx, config, action, reason)
    return False


def _decorate_session_dict(session: dict) -> dict:
    from hooks import get_session_logical_status
    from session_attention import get_attention
    d = dict(session)
    pty_alive = pty_mgr.is_alive(d["id"])
    d["pty_alive"] = pty_alive
    logical_status = get_session_logical_status(d["id"], pty_alive, d.get("status") or "idle")
    if logical_status == "idle" and pty_alive and (d.get("cli_type") or "").lower() == "antigravity":
        try:
            if _looks_antigravity_busy(d.get("cli_type"), capture_proc.get_buffer(d["id"], 160)):
                logical_status = "running"
        except Exception as exc:
            logger.debug("Antigravity status fallback skipped for %s: %s", d["id"][:8], exc)
    d["status"] = logical_status
    d["attention"] = get_attention(d["id"]) if pty_alive else None
    d["agentState"] = "prompting" if logical_status == "waiting" else "working" if logical_status == "running" else logical_status
    # What the agent did last and how many turns it finished (in-memory hook
    # state, lives as long as the PTY): the board's activity line after a reload.
    from hooks import get_session_activity
    d.update(get_session_activity(d["id"]))
    try:
        d["tags"] = json.loads(d.get("tags") or "[]")
    except (json.JSONDecodeError, TypeError):
        d["tags"] = []
    if _is_brainstormer_session(d):
        d["brainstorm_public"] = BRAINSTORMER_PUBLIC_TAG in d["tags"]
    d["quick"] = _quick_start.is_quick_workspace_cached(d.get("workspace_id"))
    return d


def _decorate_readable_session_dict(session: dict, request: web.Request) -> dict:
    d = _decorate_session_dict(session)
    if not _is_brainstormer_session(d):
        return d
    owned = _session_visible_to_auth(session, get_auth(request))
    d["read_only"] = not owned
    d["is_mine"] = owned
    d["brainstorm_owner_label"] = _brainstormer_session_owner_label(session)
    if not owned:
        for key in (
            "system_prompt",
            "allowed_tools",
            "disallowed_tools",
            "mcp_config",
            "account_id",
            "native_session_id",
            "native_slug",
            "cli_runtime_home",
            "memory_injected_info",
            "owner_actor_kind",
            "owner_actor_id",
            "owner_mode",
        ):
            d.pop(key, None)
    return d


async def _get_visible_session_for_request(session_id: str, request: web.Request) -> dict | None:
    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
    finally:
        await db.close()
    if not row:
        return None
    session = dict(row)
    if not _session_visible_to_request(session, request):
        return None
    return session


async def _get_readable_session_for_request(session_id: str, request: web.Request) -> dict | None:
    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
    finally:
        await db.close()
    if not row:
        return None
    session = dict(row)
    if not _session_readable_to_request(session, request):
        return None
    return session


async def list_sessions(request: web.Request) -> web.Response:
    # Accept both ?workspace= (legacy) and ?workspace_id= (CLAUDE.md docs +
    # most clients). Previously only ?workspace= worked, so workers calling
    # with ?workspace_id= got every session in every workspace (BUG C5).
    workspace_id = request.query.get("workspace_id") or request.query.get("workspace")
    db = await get_db()
    try:
        # Sort by user-defined order first; recency is the tiebreaker for sessions that have
        # never been reordered (order_index = 0).
        if workspace_id:
            cur = await db.execute(
                "SELECT * FROM sessions WHERE workspace_id = ? "
                "ORDER BY order_index ASC, last_active_at DESC NULLS LAST",
                (workspace_id,),
            )
        else:
            cur = await db.execute(
                "SELECT * FROM sessions ORDER BY order_index ASC, last_active_at DESC NULLS LAST"
            )
        rows = await cur.fetchall()
        result = []
        for r in rows:
            d = dict(r)
            if _session_visible_to_request(d, request):
                result.append(_decorate_session_dict(d))
        return web.json_response(result)
    finally:
        await db.close()


async def get_session_by_id(request: web.Request) -> web.Response:
    """Return a single session row as dict. Used by worker MCP for self-lookup
    (active_ticket_id, task_id, workspace_id) — all of which need a single
    point of truth that the agent can read mid-turn.
    """
    sid = request.match_info["id"]
    row = await _get_readable_session_for_request(sid, request)
    if not row:
        return web.json_response({"error": "session not found"}, status=404)
    return web.json_response(_decorate_readable_session_dict(row, request))


async def get_session_capabilities(request: web.Request) -> web.Response:
    """Return the read-only, secret-safe composition state for one session."""
    session_id = request.match_info["id"]
    session = await _get_visible_session_for_request(session_id, request)
    if not session:
        return web.json_response({"error": "session not found"}, status=404)

    from session_capabilities import collect_session_capabilities

    db = await get_db()
    try:
        capabilities = await collect_session_capabilities(db, session)
    finally:
        await db.close()
    return web.json_response({"capabilities": capabilities})


async def get_session_runtime_model(request: web.Request) -> web.Response:
    """Model/effort the CLI really used on its latest turn (read from the
    native transcript), so /model switches inside the terminal show up.
    Falls back to the launch config when no turn is recorded yet."""
    session_id = request.match_info["id"]
    session = await _get_visible_session_for_request(session_id, request)
    if not session:
        return web.json_response({"error": "session not found"}, status=404)
    from runtime_model import read_runtime_model
    from session_budget import read_context_usage, COMPACT_WINDOW

    cli = (session.get("cli_type") or "claude").lower()
    observed = None
    context_usage = None
    native_sid = session.get("native_session_id")
    if native_sid and cli in ("claude", "codex"):
        workspace_path = session.get("workspace_path")
        if not workspace_path and session.get("workspace_id"):
            workspace_path = await _get_workspace_path(session["workspace_id"])

        def _read():
            path = _get_native_transcript_path(
                cli, workspace_path, native_sid,
                cli_home=_session_transcript_home(session),
            )
            found = read_runtime_model(path) if path else None
            if found is not None and "at" not in found:
                try:
                    found["at"] = os.path.getmtime(path)
                except OSError:
                    pass
            return found, read_context_usage(path)

        try:
            observed, context_usage = await asyncio.to_thread(_read)
        except Exception as exc:
            logger.debug("runtime model read failed for %s: %s", session_id, exc)
        # A live model/effort switch relaunched the CLI after this turn: the
        # transcript still shows the old values until the next turn.
        relaunched_at = _launch_applied_at.get(session_id)
        if observed and relaunched_at and (observed.get("at") or 0) < relaunched_at:
            observed = None
    return web.json_response({
        "session_id": session_id,
        "configured": {"model": session.get("model"), "effort": session.get("effort")},
        "observed": observed,
        "launched": pty_mgr.get_launch_model(session_id),
        "context": context_usage,
        "auto_compact_window": COMPACT_WINDOW if cli == "claude" else None,
    })


CAPABILITY_HANDOFFS = {
    "testing": {
        "label": "Testing Worker",
        "tag": "capability_testing",
        "role": "tester",
        "mcp_servers": ("builtin-worker-board", "builtin-playwright"),
        "guidelines": ("builtin-testing-agent",),
        "purpose": "Verify behavior with browser automation, tests, screenshots, and clear pass/fail reports.",
    },
    "documentation": {
        "label": "Documentation Worker",
        "tag": "capability_documentation",
        "role": "documentor",
        "mcp_servers": ("builtin-worker-board", "builtin-documentor", "builtin-playwright"),
        "guidelines": ("builtin-documentation-agent",),
        "purpose": "Maintain project documentation, screenshots, GIF demos, and docs builds.",
    },
}


def _normalize_capability(value: str | None) -> str | None:
    capability = (value or "").strip().lower().replace("-", "_")
    aliases = {
        "test": "testing",
        "tests": "testing",
        "browser_testing": "testing",
        "verification": "testing",
        "verify": "testing",
        "docs": "documentation",
        "doc": "documentation",
        "document": "documentation",
    }
    return aliases.get(capability, capability if capability in CAPABILITY_HANDOFFS else None)


def _session_tags_from_value(value) -> list[str]:
    if isinstance(value, list):
        return [str(v) for v in value]
    if isinstance(value, str) and value:
        try:
            parsed = json.loads(value)
            if isinstance(parsed, list):
                return [str(v) for v in parsed]
        except Exception:
            return []
    return []


async def _attach_capability_to_session(
    db,
    session_id: str,
    capability_cfg: dict,
    *,
    task_id: str | None = None,
    extra_tags: list[str] | None = None,
) -> None:
    for mcp_id in capability_cfg["mcp_servers"]:
        await db.execute(
            "INSERT OR IGNORE INTO session_mcp_servers "
            "(session_id, mcp_server_id, auto_approve_override) VALUES (?, ?, 1)",
            (session_id, mcp_id),
        )
    for guideline_id in capability_cfg["guidelines"]:
        await db.execute(
            "INSERT OR IGNORE INTO session_guidelines (session_id, guideline_id) VALUES (?, ?)",
            (session_id, guideline_id),
        )
    cur = await db.execute("SELECT tags FROM sessions WHERE id = ?", (session_id,))
    row = await cur.fetchone()
    tags = _session_tags_from_value(row["tags"] if row else None)
    for tag in [capability_cfg["tag"], *(extra_tags or [])]:
        if tag and tag not in tags:
            tags.append(tag)
    fields = ["tags = ?"]
    values = [json.dumps(tags)]
    if task_id:
        fields.append("active_ticket_id = ?")
        values.append(task_id)
    values.append(session_id)
    await db.execute(f"UPDATE sessions SET {', '.join(fields)} WHERE id = ?", values)


# Session-reuse routing policy: a worker's digest grades its own context_health.
# Refuse to reuse stale/failed context (a fresh session beats poisoned context);
# rank the rest good > mixed > unknown. Categorical, not similarity-scored.
_REUSE_UNHEALTHY_HEALTH = {"stale", "failed"}
_REUSE_HEALTH_RANK = {"good": 0, "mixed": 1, "unknown": 2}


async def _find_reusable_capability_session(
    db,
    workspace_id: str,
    capability_cfg: dict,
    *,
    cli_type: str | None = None,
    allow_busy: bool = False,
    task_id: str | None = None,
) -> dict | None:
    cur = await db.execute(
        """SELECT s.*, d.context_health AS digest_health
           FROM sessions s
           LEFT JOIN session_digests d ON d.session_id = s.id
           WHERE s.workspace_id = ? AND s.session_type = 'worker'
                 AND COALESCE(s.archived, 0) = 0
           ORDER BY s.last_active_at DESC NULLS LAST, s.created_at DESC""",
        (workspace_id,),
    )
    rows = await cur.fetchall()
    from hooks import get_session_logical_status
    candidates: list[tuple[int, int, dict]] = []
    for row in rows:
        sess = dict(row)
        if cli_type and (sess.get("cli_type") or "claude") != cli_type:
            continue
        if capability_cfg["tag"] not in _session_tags_from_value(sess.get("tags")):
            continue
        alive = pty_mgr.is_alive(sess["id"])
        logical = get_session_logical_status(sess["id"], alive, sess.get("status") or "idle")
        if not (allow_busy or not alive or logical in {"idle", "exited"}):
            continue
        health = (sess.get("digest_health") or "unknown").strip().lower()
        if health in _REUSE_UNHEALTHY_HEALTH:
            continue
        sess["status"] = logical
        sess["pty_alive"] = alive
        sess["context_health"] = health
        # Tier 0: already bound to this goal → best actor, already holds the
        # task's context. Stale same-ticket sessions were dropped above, so this
        # only ever prefers a healthy one ("prefer bound session unless stale").
        same_ticket = bool(task_id) and sess.get("active_ticket_id") == task_id
        candidates.append((0 if same_ticket else 1, _REUSE_HEALTH_RANK.get(health, 2), sess))
    if not candidates:
        return None
    # Stable sort keeps the query's recency order as the final tiebreak within
    # equal (tier, health).
    candidates.sort(key=lambda c: (c[0], c[1]))
    return candidates[0][2]


def _capability_permission_mode(profile, cli_type: str, capability: str, explicit: str | None) -> str:
    if explicit:
        return explicit
    if capability == "testing" and profile.supports(Feature.PLAN_MODE):
        return "plan"
    if capability == "documentation" and cli_type == "claude":
        return "acceptEdits"
    return profile.default_permission_mode


async def _resolve_capability_policy(db, workspace_id: str, role: str) -> tuple[str | None, str | None]:
    try:
        cur = await db.execute(
            "SELECT orchestration_policy, inherit_orchestration_policy_from FROM workspaces WHERE id = ?",
            (workspace_id,),
        )
        row = await cur.fetchone()
        if not row:
            return None, None
        policy_str = row["orchestration_policy"]
        if row["inherit_orchestration_policy_from"]:
            from db import resolve_workspace_orchestration_policy
            policy_str = await resolve_workspace_orchestration_policy(db, workspace_id)
        from orchestration_policy import role_model
        return role_model(policy_str, role)
    except Exception:
        return None, None


async def _create_capability_worker(
    db,
    workspace_id: str,
    capability: str,
    capability_cfg: dict,
    body: dict,
    source_session: dict | None,
    task_id: str | None,
    extra_tags: list[str],
) -> dict | web.Response:
    cur = await db.execute("SELECT name FROM workspaces WHERE id = ?", (workspace_id,))
    ws = await cur.fetchone()
    if not ws:
        return web.json_response({"error": "workspace not found"}, status=404)
    policy_cli, policy_model = await _resolve_capability_policy(db, workspace_id, capability_cfg["role"])
    if body.get("_agent_model_policy"):
        chosen_cli = policy_cli or (source_session or {}).get("cli_type") or "claude"
        chosen_model = policy_model or ((source_session or {}).get("model") if (source_session or {}).get("cli_type", "claude") == chosen_cli else None)
        chosen_model = chosen_model or _profile_default_model_for_role(get_profile(chosen_cli), capability_cfg["role"])
        if ((body.get("cli_type") and body["cli_type"] != chosen_cli)
                or (body.get("model") and body["model"] != chosen_model)):
            return web.json_response({"error": "Worker model must match the user's policy or configured parent model.", "code": "model_choice_locked", "cli_type": chosen_cli, "model": chosen_model}, status=403)
        body = {**body, "cli_type": chosen_cli, "model": chosen_model}
    cli_type = body.get("cli_type") or policy_cli or (source_session or {}).get("cli_type") or "claude"
    if not is_active_cli(cli_type):
        return _inactive_cli_response(cli_type)
    profile = get_profile(cli_type)
    model = body.get("model")
    if model in (None, ""):
        if policy_model and not _profile_option_valid(profile.available_models, policy_model):
            policy_model = None
        model = policy_model or _profile_default_model_for_role(profile, capability_cfg["role"])
    model = _model_for_storage(profile, model, capability_cfg["role"])
    permission_mode = _capability_permission_mode(profile, cli_type, capability, body.get("permission_mode"))
    if not _profile_option_valid(profile.available_permission_modes, permission_mode, allow_empty=False):
        permission_mode = profile.default_permission_mode
    effort = _effort_for_storage(profile, body.get("effort"))
    session_id = str(uuid.uuid4())
    name = (body.get("name") or "").strip() or f"{capability_cfg['label']} ({profile.label})"
    purpose = (body.get("purpose") or capability_cfg["purpose"]).strip()
    account_id = body.get("account_id") or (source_session or {}).get("account_id")
    tags = [capability_cfg["tag"], *extra_tags]
    await db.execute(
        """INSERT INTO sessions
           (id, workspace_id, name, model, permission_mode, effort, account_id,
            cli_type, session_type, auto_approve_mcp, auto_approve_plan, purpose,
            tags, active_ticket_id)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'worker', 1, ?, ?, ?, ?)""",
        (
            session_id, workspace_id, name, model, permission_mode, effort, account_id,
            cli_type, 1 if capability == "documentation" else 0, purpose,
            json.dumps(tags), task_id,
        ),
    )
    await _sync_zai_mcp_servers_for_session(db, session_id, cli_type, account_id)
    await _attach_capability_to_session(db, session_id, capability_cfg, task_id=task_id, extra_tags=extra_tags)
    cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
    return dict(await cur.fetchone())


def _build_capability_handoff_prompt(
    *,
    capability: str,
    capability_cfg: dict,
    prompt: str,
    reason: str,
    source_session: dict | None,
    task: dict | None,
    original_prompt: str = "",
) -> str:
    lines = [f"Capability handoff: {capability_cfg['label']}"]
    if source_session:
        lines.append(f"Source session: {source_session.get('name') or source_session.get('id')} ({source_session.get('id')})")
    if task:
        lines.append(f"Feature board task: {task.get('title') or task.get('id')} ({task.get('id')})")
    if reason:
        lines.append(f"Reason: {reason}")
    if capability == "testing":
        lines.append(
            "Use testing/browser verification tools as needed. Do not edit product source files; report precise pass/fail results, screenshots, commands run, and any reproduction steps."
        )
        if task and _is_alloy_task(task.get("labels")):
            lines.append(ALLOY_TESTER_SYSTEM_PROMPT_FRAGMENT)
    else:
        lines.append(
            "Use documentation and browser tools as needed. Update docs/screenshots when appropriate, run the docs build if files changed, and report changed files plus build status."
        )
        if task and _is_alloy_task(task.get("labels")):
            lines.append(ALLOY_DOCUMENTOR_SYSTEM_PROMPT_FRAGMENT)
    if source_session:
        lines.append(
            "When finished, post a concise result to the workspace peer messages with topic='capability-handoff' and mention the source session id above."
        )
    lines.append("\nRequest:\n" + prompt.strip())
    brief = "\n\n".join(lines)
    if capability == "testing":
        from review_brief import build_review_brief
        brief = build_review_brief(
            brief,
            original_prompt=original_prompt,
            board_card=task,
            handoff_notes=(task or {}).get("result_summary") or prompt,
        )
    return brief


async def compose_review_brief(request: web.Request) -> web.Response:
    """POST /api/review/brief — enrich frontend-prefilled reviewer prompts.

    Optional intent is informational and resolved best-effort. Explicit task
    references are different: they must be linked to the visible reviewed
    session/workspace and fail closed on a scope mismatch.
    """
    body = await request.json()
    instructions = body.get("instructions")
    if not isinstance(instructions, str):
        instructions = str(instructions or "")

    reviewed_session_id = body.get("reviewed_session_id")
    visible_session = None
    if reviewed_session_id:
        visible = await _get_readable_session_for_request(reviewed_session_id, request)
        if not visible:
            reviewed_session_id = None
        else:
            visible_session = visible
    if body.get("task_id") and not visible_session:
        return web.json_response(
            {"error": "an explicit task requires a visible reviewed session"},
            status=403,
        )

    original_prompt = ""
    card = None
    try:
        from review_brief import ReviewScopeError, resolve_review_intent_sources
        db = await get_db()
        try:
            original_prompt, card = await resolve_review_intent_sources(
                db,
                reviewed_session_id=reviewed_session_id,
                task_id=body.get("task_id"),
                fallback_original_prompt=body.get("original_prompt"),
                allowed_workspace_id=(visible_session or {}).get("workspace_id"),
                require_explicit_task_link=bool(body.get("task_id")),
            )
        finally:
            await db.close()
    except ReviewScopeError as error:
        return web.json_response({"error": str(error)}, status=403)
    except Exception:
        pass

    handoff_notes = body.get("handoff_notes")
    if not handoff_notes and card:
        handoff_notes = card.get("result_summary")
    from review_brief import build_review_brief
    return web.json_response({
        "brief": build_review_brief(
            instructions,
            original_prompt=original_prompt,
            board_card=card,
            handoff_notes=handoff_notes,
            original_prompt_ref=(
                f"ive:session/{reviewed_session_id}/first-user-prompt"
                if reviewed_session_id else None
            ),
        )
    })


async def _send_text_to_session(session_id: str, message: str) -> bool:
    if not pty_mgr.is_alive(session_id):
        return False
    cli_type = await _session_cli_type(session_id)
    ready_timeout = 8 if cli_type in {"antigravity", "codex"} else 0
    await _wait_for_cli_input_ready(session_id, cli_type, ready_timeout)
    if cli_type == "gemini":
        pty_mgr.write(session_id, b"\x15")
        payload = message.replace("\n", " ").replace("\r", " ").encode("utf-8")
    else:
        pty_mgr.write(session_id, b"\x1b" + b"\x7f" * 50)
        payload = message.encode("utf-8")
    await _asyncio.sleep(0.3)
    if pty_mgr.write(session_id, payload) is False:
        return False  # never submit a stale or partial input line
    await _asyncio.sleep(max(0.4, min(1.5, len(payload) / 600)))
    return pty_mgr.write(session_id, b"\r") is not False


async def request_capability_handoff(request: web.Request) -> web.Response:
    body = await request.json()
    from permission_mode_policy import is_agent_origin
    body["_agent_model_policy"] = is_agent_origin(request)
    capability = _normalize_capability(body.get("capability"))
    if not capability:
        return web.json_response({"error": "capability must be testing or documentation"}, status=400)
    prompt = (body.get("prompt") or body.get("message") or "").strip()
    if not prompt:
        return web.json_response({"error": "prompt required"}, status=400)
    capability_cfg = CAPABILITY_HANDOFFS[capability]
    source_session_id = body.get("source_session_id") or request.headers.get("X-IVE-Session-Id")
    workspace_id = body.get("workspace_id") or request.headers.get("X-IVE-Workspace-Id")
    task_id = body.get("task_id")
    reuse = body.get("reuse", True) is not False
    allow_busy = bool(body.get("allow_busy", False))
    extra_tags = []
    if capability == "testing" and body.get("show_browser"):
        extra_tags.append("tester_headed")
    if capability == "documentation" and body.get("allow_all_edits"):
        extra_tags.append("unrestricted_edit")

    db = await get_db()
    created = False
    source_session = None
    task = None
    original_prompt = ""
    try:
        if source_session_id:
            cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (source_session_id,))
            source_row = await cur.fetchone()
            if not source_row:
                return web.json_response({"error": "source_session_id not found"}, status=404)
            source_session = dict(source_row)
            if workspace_id and source_session.get("workspace_id") != workspace_id:
                return web.json_response({"error": "source session belongs to a different workspace"}, status=409)
            workspace_id = workspace_id or source_session.get("workspace_id")
            task_id = task_id or source_session.get("active_ticket_id") or source_session.get("task_id")
        if not workspace_id:
            return web.json_response({"error": "workspace_id required"}, status=400)
        cur = await db.execute("SELECT id FROM workspaces WHERE id = ?", (workspace_id,))
        if not await cur.fetchone():
            return web.json_response({"error": "workspace not found"}, status=404)
        if task_id:
            cur = await db.execute("SELECT * FROM tasks WHERE id = ?", (task_id,))
            task_row = await cur.fetchone()
            if not task_row:
                return web.json_response({"error": "task not found"}, status=404)
            task = dict(task_row)
            if task.get("workspace_id") != workspace_id:
                return web.json_response({"error": "task belongs to a different workspace"}, status=409)

        if capability == "testing":
            try:
                from review_brief import resolve_review_intent_sources
                original_prompt, resolved_task = await resolve_review_intent_sources(
                    db,
                    reviewed_session_id=source_session_id,
                    task_id=task_id,
                )
                task = task or resolved_task
            except Exception:
                pass

        target = None
        cli_filter = body.get("cli_type")
        if reuse:
            target = await _find_reusable_capability_session(
                db, workspace_id, capability_cfg, cli_type=cli_filter, allow_busy=allow_busy,
                task_id=task_id,
            )
        if target:
            await _attach_capability_to_session(db, target["id"], capability_cfg, task_id=task_id, extra_tags=extra_tags)
            target_session_id = target["id"]
        else:
            target = await _create_capability_worker(
                db, workspace_id, capability, capability_cfg, body, source_session, task_id, extra_tags,
            )
            if isinstance(target, web.Response):
                return target
            target_session_id = target["id"]
            created = True

        if task_id:
            await db.execute(
                """INSERT INTO task_events (task_id, event_type, actor, old_value, new_value, message)
                   VALUES (?, 'capability_handoff_requested', 'agent', ?, ?, ?)""",
                (
                    task_id,
                    source_session_id,
                    target_session_id,
                    f"{capability_cfg['label']} handoff requested",
                ),
            )
        await db.commit()

        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (target_session_id,))
        target_session = dict(await cur.fetchone())
        try:
            target_session["tags"] = json.loads(target_session.get("tags") or "[]")
        except Exception:
            target_session["tags"] = []
    finally:
        await db.close()

    if created:
        await broadcast({"type": "session_created", "session": target_session})
        await bus.emit(CommanderEvent.SESSION_SPAWNED, {
            "session_id": target_session_id,
            "workspace_id": workspace_id,
            "name": target_session.get("name"),
            "model": target_session.get("model"),
            "session_type": target_session.get("session_type"),
        }, source="api", actor="agent")
    else:
        await broadcast({
            "type": "session_update",
            "session_id": target_session_id,
            "workspace_id": target_session.get("workspace_id"),
            "session": target_session,
        })

    if not pty_mgr.is_alive(target_session_id):
        try:
            await _autostart_session_pty(target_session_id)
            await _asyncio.sleep(1.0)
        except Exception as exc:
            return web.json_response({
                "ok": False,
                "error": f"handoff worker created/reused but could not start: {exc}",
                "target_session_id": target_session_id,
                "created": created,
            }, status=500)
    handoff_prompt = _build_capability_handoff_prompt(
        capability=capability,
        capability_cfg=capability_cfg,
        prompt=prompt,
        reason=(body.get("reason") or "").strip(),
        source_session=source_session,
        task=task,
        original_prompt=original_prompt,
    )
    sent = await _send_text_to_session(target_session_id, handoff_prompt)
    return web.json_response({
        "ok": sent,
        "capability": capability,
        "target_session_id": target_session_id,
        "target_session": target_session,
        "source_session_id": source_session_id,
        "task_id": task_id,
        "created": created,
        "reused": not created,
        "message_sent": sent,
    })


async def reorder_sessions(request: web.Request) -> web.Response:
    """Reorder sessions within a workspace.

    Body: { "workspace_id": "...", "ids": ["sess1", "sess2", ...] }
    """
    body = await request.json()
    workspace_id = body.get("workspace_id")
    ids = body.get("ids") or []
    if not workspace_id or not isinstance(ids, list):
        return web.json_response({"error": "workspace_id and ids list required"}, status=400)
    db = await get_db()
    try:
        for idx, sid in enumerate(ids, start=1):
            await db.execute(
                "UPDATE sessions SET order_index = ? WHERE id = ? AND workspace_id = ?",
                (idx, sid, workspace_id),
            )
        await db.commit()
        return web.json_response({"ok": True, "count": len(ids)})
    finally:
        await db.close()


async def create_session(request: web.Request) -> web.Response:
    import shell_session as _shell_session  # plain terminals (cli_type "shell")
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid JSON body"}, status=400)
    if not isinstance(body, dict):
        return web.json_response({"error": "expected JSON object"}, status=400)

    def requested_ids(field: str) -> list[str]:
        value = body.get(field, [])
        if value is None:
            return []
        if not isinstance(value, list) or any(
            not isinstance(item, str) or not item.strip() for item in value
        ):
            raise ValueError(f"{field} must be a list of non-empty ids")
        return list(dict.fromkeys(item.strip() for item in value))

    try:
        guideline_ids = requested_ids("guideline_ids")
        mcp_server_ids = requested_ids("mcp_server_ids")
        tags = requested_ids("tags")
    except ValueError as exc:
        return web.json_response({"error": str(exc)}, status=400)
    mcp_overrides = body.get("mcp_overrides", {})
    if not isinstance(mcp_overrides, dict):
        return web.json_response({"error": "mcp_overrides must be an object"}, status=400)

    workspace_id = body.get("workspace_id")
    if not workspace_id:
        return web.json_response({"error": "workspace_id required"}, status=400)
    if not _workspace_visible_to_auth(workspace_id, get_auth(request)):
        return web.json_response({"error": "workspace not found"}, status=404)
    session_type = body.get("session_type", "worker")
    requested_cli_type = body.get("cli_type")
    requested_model = body.get("model")
    task_id = body.get("task_id")
    policy_cli, policy_model = None, None
    workspace_alloy_enabled = False
    task_for_session = None

    # Validate workspace exists before INSERT — without this, a bogus
    # workspace_id leaked the SQLite FK error as a 500 (BUG H2).
    _check_db = await get_db()
    try:
        cur = await _check_db.execute(
            "SELECT id, orchestration_policy, inherit_orchestration_policy_from, alloy_enabled FROM workspaces WHERE id = ?", (workspace_id,)
        )
        ws_row = await cur.fetchone()
        if not ws_row:
            return web.json_response({"error": "workspace not found"}, status=404)
        workspace_alloy_enabled = bool(ws_row["alloy_enabled"])
        policy_str = ws_row["orchestration_policy"]
        if ws_row["inherit_orchestration_policy_from"]:
            from db import resolve_workspace_orchestration_policy
            policy_str = await resolve_workspace_orchestration_policy(_check_db, workspace_id)
        try:
            from orchestration_policy import policy_role_for_session_type, role_model
            policy_cli, policy_model = role_model(
                policy_str,
                policy_role_for_session_type(
                    session_type,
                    body.get("policy_role") or body.get("role"),
                ),
            )
        except Exception:
            policy_cli, policy_model = None, None
    finally:
        await _check_db.close()

    # A plain terminal (the user's login shell) is not an agent: no policy,
    # model, permissions, guidelines, MCP servers, worker board or task.
    if _shell_session.is_shell_cli(requested_cli_type):
        return await _create_shell_session(request, body, workspace_id)

    if task_id and session_type != "commander":
        db_ready = await get_db()
        try:
            cur = await db_ready.execute("SELECT * FROM tasks WHERE id = ?", (task_id,))
            task_row = await cur.fetchone()
            if not task_row:
                return web.json_response({"error": "task not found"}, status=404)
            task_for_session = dict(task_row)
            if task_for_session.get("workspace_id") != workspace_id:
                return web.json_response({"error": "task belongs to a different workspace"}, status=409)
            readiness = await get_task_ready(db_ready, task_id, task_for_session)
            if readiness and not readiness["ready"]:
                return web.json_response(unmet_dependency_response(readiness), status=409)
        finally:
            await db_ready.close()

    from permission_mode_policy import is_agent_origin
    if is_agent_origin(request):
        parent_id = request.headers.get("X-IVE-Session-Id")
        parent = await get_session_config(parent_id) if parent_id else None
        chosen_cli = policy_cli or (parent or {}).get("cli_type") or "claude"
        chosen_model = policy_model or ((parent or {}).get("model") if (parent or {}).get("cli_type", "claude") == chosen_cli else None)
        chosen_model = chosen_model or _profile_default_model_for_role(get_profile(chosen_cli), session_type)
        if ((requested_cli_type and requested_cli_type != chosen_cli)
                or (requested_model and requested_model != chosen_model)
                or body.get("plan_model") or body.get("execute_model")):
            return web.json_response({"error": "Worker model must match the user's workspace policy or configured parent model.",
                                      "code": "model_choice_locked", "cli_type": chosen_cli, "model": chosen_model}, status=403)
        requested_cli_type, requested_model = chosen_cli, chosen_model

    session_id = str(uuid.uuid4())
    # Explicit caller CLI wins; otherwise the workspace role policy may choose
    # the provider. Fall back to Claude for legacy callers/workspaces.
    cli_type = requested_cli_type or policy_cli or "claude"
    if not is_active_cli(cli_type):
        return _inactive_cli_response(cli_type)
    try:
        cli_availability = await _registered_cli_availability()
    except Exception as exc:
        logger.error("CLI availability registry unavailable: %s", exc)
        return web.json_response({
            "error": "CLI availability could not be verified",
            "code": "cli_availability_unavailable",
        }, status=503)
    if not cli_availability.get(cli_type, False):
        return web.json_response({
            "error": f"{get_profile(cli_type).label} is not installed or enabled",
            "code": "cli_binary_missing",
            "cli_type": cli_type,
        }, status=409)
    name = body.get("name", "").strip() or f"Session {session_id[:8]}"
    profile = get_profile(cli_type)
    model = requested_model
    if model in (None, ""):
        if policy_model:
            valid_model_ids = {
                str(m.get("id")) for m in getattr(profile, "available_models", [])
                if isinstance(m, dict) and m.get("id") is not None
            }
            if valid_model_ids and str(policy_model) not in valid_model_ids:
                policy_model = None
        model = policy_model or _profile_default_model_for_role(profile, session_type)
    model = _model_for_storage(profile, model, session_type)
    permission_mode = body.get("permission_mode", profile.default_permission_mode)
    _mode_err = _permission_mode_error(profile, permission_mode)
    if _mode_err is not None:
        return _mode_err
    effort = _effort_for_storage(profile, body.get("effort"))
    system_prompt = body.get("system_prompt", "")
    if workspace_alloy_enabled and task_for_session and _is_alloy_task(task_for_session.get("labels")):
        if session_type == "test_worker":
            alloy_prompt = ALLOY_TESTER_SYSTEM_PROMPT_FRAGMENT
        else:
            alloy_prompt = ALLOY_WORKER_SYSTEM_PROMPT_FRAGMENT
        if alloy_prompt and alloy_prompt not in system_prompt:
            system_prompt = alloy_prompt + ("\n\n" + system_prompt if system_prompt else "")
    disallowed_tools = body.get("disallowed_tools")
    if session_type == "brainstormer" and not disallowed_tools:
        disallowed_tools = json.dumps(COMMANDER_DISALLOWED_TOOLS)
    elif session_type == "secure" and not disallowed_tools:
        # Secure agent has NO host shell — Bash/Edit/Write blocked so the only execution
        # path is the run_in_secure_container MCP tool (into the network-clamped Kali box).
        disallowed_tools = json.dumps(SECURE_DISALLOWED_TOOLS)
    elif isinstance(disallowed_tools, list):
        disallowed_tools = json.dumps(disallowed_tools)
    plan_model = body.get("plan_model")
    execute_model = body.get("execute_model")
    auto_approve_plan = 1 if body.get("auto_approve_plan") else 0
    purpose = body.get("purpose", "").strip() or None
    account_id = body.get("account_id") or None
    # Every created agent session is the durable workspace-membership edge used
    # by actor-scoped APIs.  Never leave ordinary sessions unowned: doing so
    # forces downstream authorization to trust caller-supplied workspace IDs.
    auth_ctx = get_auth(request)
    owner_actor_kind = auth_ctx.actor_kind
    owner_actor_id = auth_ctx.actor_id or auth_ctx.device_id or "owner"
    owner_mode = auth_ctx.mode
    if session_type == "brainstormer":
        owner_actor_kind, owner_actor_id = _brainstormer_owner_key(auth_ctx)

    # Inherit worktree default from workspace if not explicitly set
    requested_worktree = body.get("worktree")
    default_worktree = False
    if requested_worktree is None:
        # Look up workspace default
        tmp_db = await get_db()
        try:
            cur = await tmp_db.execute("SELECT default_worktree FROM workspaces WHERE id = ?", (workspace_id,))
            ws_row = await cur.fetchone()
            default_worktree = bool(ws_row and ws_row["default_worktree"])
        finally:
            await tmp_db.close()
    from session_worktree import resolve_worktree
    try:
        worktree = resolve_worktree(cli_type, requested_worktree, default=default_worktree)
    except ValueError as exc:
        return web.json_response({"error": str(exc), "code": "unsupported_worktree"}, status=400)

    db = await get_db()
    try:
        async def require_existing_ids(table: str, ids: list[str], label: str) -> None:
            if not ids:
                return
            placeholders = ",".join("?" for _ in ids)
            cur = await db.execute(
                f"SELECT id FROM {table} WHERE id IN ({placeholders})",
                ids,
            )
            found = {row["id"] for row in await cur.fetchall()}
            missing = [item for item in ids if item not in found]
            if missing:
                raise ValueError(f"unknown {label}: {', '.join(missing)}")

        await require_existing_ids("guidelines", guideline_ids, "guideline id")
        await require_existing_ids("mcp_servers", mcp_server_ids, "MCP server id")
        await db.execute(
            """INSERT INTO sessions (id, workspace_id, name, model, permission_mode, effort,
               system_prompt, disallowed_tools, account_id, cli_type, plan_model, execute_model,
               auto_approve_plan, worktree, purpose, session_type,
               owner_actor_kind, owner_actor_id, owner_mode)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (session_id, workspace_id, name, model, permission_mode, effort,
             system_prompt or None, disallowed_tools, account_id, cli_type, plan_model, execute_model,
             auto_approve_plan, worktree, purpose, session_type,
             owner_actor_kind, owner_actor_id, owner_mode),
        )
        # Auto-attach MCP servers based on session type
        if session_type == "commander":
            await db.execute(
                "INSERT OR IGNORE INTO session_mcp_servers (session_id, mcp_server_id, auto_approve_override) VALUES (?, ?, 1)",
                (session_id, "builtin-commander"),
            )
        elif session_type == "test_worker":
            # Test workers get Playwright MCP for browser automation
            await db.execute(
                "INSERT OR IGNORE INTO session_mcp_servers (session_id, mcp_server_id, auto_approve_override) VALUES (?, ?, 1)",
                (session_id, "builtin-playwright"),
            )
            # Also attach testing-agent guideline
            await db.execute(
                "INSERT OR IGNORE INTO session_guidelines (session_id, guideline_id) VALUES (?, ?)",
                (session_id, "builtin-testing-agent"),
            )
            # Store session_type so it's visible in listings
            await db.execute(
                "UPDATE sessions SET session_type = 'test_worker' WHERE id = ?",
                (session_id,),
            )

        # Normal workers get worker-board tools for active-ticket binding,
        # peer context, port leasing, and capability handoff. Task assignment
        # remains optional and is handled below when task_id is provided.
        if session_type != "commander":
            await db.execute(
                "INSERT OR IGNORE INTO session_mcp_servers (session_id, mcp_server_id, auto_approve_override) VALUES (?, ?, 1)",
                (session_id, "builtin-worker-board"),
            )

        for guideline_id in guideline_ids:
            await db.execute(
                "INSERT OR IGNORE INTO session_guidelines (session_id, guideline_id) VALUES (?, ?)",
                (session_id, guideline_id),
            )
        for mcp_server_id in mcp_server_ids:
            override = mcp_overrides.get(mcp_server_id, {})
            if not isinstance(override, dict):
                raise ValueError(f"invalid MCP override for {mcp_server_id}")
            auto_override = override.get("auto_approve_override")
            if auto_override is not None:
                auto_override = 1 if bool(auto_override) else 0
            await db.execute(
                """INSERT OR REPLACE INTO session_mcp_servers
                   (session_id, mcp_server_id, auto_approve_override)
                   VALUES (?, ?, ?)""",
                (session_id, mcp_server_id, auto_override),
            )
        if tags:
            await db.execute(
                "UPDATE sessions SET tags = ? WHERE id = ?",
                (json.dumps(tags), session_id),
            )
        await _sync_zai_mcp_servers_for_session(db, session_id, cli_type, account_id)

        # Assign task when task_id is provided.
        if task_id and session_type != "commander":
            # Assign the task to this session
            await db.execute(
                "UPDATE tasks SET assigned_session_id = ?, updated_at = datetime('now') WHERE id = ?",
                (session_id, task_id),
            )
            # Set pipeline_stage to 'implementing' for pipeline tasks
            await db.execute(
                "UPDATE tasks SET pipeline_stage = 'implementing' WHERE id = ? AND pipeline = 1 AND (pipeline_stage IS NULL OR pipeline_stage = '')",
                (task_id,),
            )
            await db.execute(
                """INSERT INTO task_events (task_id, event_type, actor, old_value, new_value, message)
                   VALUES (?, 'assigned_session_id_changed', 'commander', NULL, ?, ?)""",
                (task_id, session_id, f"Task assigned to worker session {name}"),
            )

        await db.commit()
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
        result = dict(row)
        result["quick"] = _quick_start.is_quick_workspace_cached(workspace_id)
    except ValueError as exc:
        await db.rollback()
        return web.json_response({
            "error": f"session was not created: {exc}",
            "code": "invalid_session_configuration",
        }, status=400)
    except Exception as exc:
        await db.rollback()
        logger.exception("Atomic session creation failed")
        return web.json_response({
            "error": f"session was not created: {exc}",
            "code": "session_creation_failed",
        }, status=500)
    finally:
        await db.close()

    # Brainstormers are actor-private; the creating browser receives the row
    # from this HTTP response, so do not announce it globally.
    if result.get("session_type") != "brainstormer":
        try:
            await broadcast({"type": "session_created", "session": result})
        except Exception:
            logger.exception("Session created but WebSocket announcement failed")

    # Autostart is a separate, explicitly reported lifecycle operation. The
    # durable creation transaction is complete regardless of its outcome.
    autostart_outcome = {"ok": True}
    if body.get("auto_start", False):
        autostart_outcome = await _autostart_session_pty(session_id) or {"ok": True}

    try:
        await bus.emit(CommanderEvent.SESSION_SPAWNED, {
            "session_id": session_id,
            "workspace_id": result.get("workspace_id"),
            "name": result.get("name"),
            "cli_type": result.get("cli_type"),
            "model": result.get("model"),
            "session_type": result.get("session_type"),
        }, source="api", actor="user")
    except Exception:
        logger.exception("Session created but SESSION_SPAWNED event failed")
    # Additive field: existing callers ignore unknown keys; status stays 201.
    result["autostart"] = autostart_outcome
    return web.json_response(result, status=201)


async def _create_shell_session(request, body: dict, workspace_id: str) -> web.Response:
    """POST /api/sessions with cli_type "shell": a plain terminal row.

    The workspace was validated by create_session. The row carries no model,
    permission mode or effort, and nothing agent-only is attached to it.
    """
    import shell_session as _shell_session  # plain terminals (cli_type "shell")
    session_id = str(uuid.uuid4())
    name = (body.get("name") or "").strip() if isinstance(body.get("name"), str) else ""
    name = name or "Terminal"
    auth_ctx = get_auth(request)
    if not auth_ctx.is_owner and (auth_ctx.mode or "").strip().lower() != "full":
        return web.json_response({
            "error": "Terminal sessions need Full access",
            "code": "mode_violation",
        }, status=403)
    owner_actor_kind = auth_ctx.actor_kind
    owner_actor_id = auth_ctx.actor_id or auth_ctx.device_id or "owner"
    db = await get_db()
    try:
        await db.execute(
            """INSERT INTO sessions (id, workspace_id, name, model, permission_mode, effort,
               cli_type, session_type, worktree, owner_actor_kind, owner_actor_id, owner_mode)
               VALUES (?, ?, ?, '', 'default', NULL, ?, ?, 0, ?, ?, ?)""",
            (session_id, workspace_id, name, _shell_session.SHELL_CLI_TYPE,
             _shell_session.SHELL_SESSION_TYPE, owner_actor_kind, owner_actor_id, auth_ctx.mode),
        )
        await db.commit()
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        result = dict(await cur.fetchone())
        result["quick"] = _quick_start.is_quick_workspace_cached(workspace_id)
    except Exception as exc:
        await db.rollback()
        logger.exception("Terminal session creation failed")
        return web.json_response({
            "error": f"session was not created: {exc}",
            "code": "session_creation_failed",
        }, status=500)
    finally:
        await db.close()
    try:
        await broadcast({"type": "session_created", "session": result})
    except Exception:
        logger.exception("Terminal session created but WebSocket announcement failed")
    autostart_outcome = {"ok": True}
    if body.get("auto_start", False):
        autostart_outcome = await _autostart_session_pty(session_id) or {"ok": True}
    result["autostart"] = autostart_outcome
    return web.json_response(result, status=201)


async def _start_shell_pty(session_id: str, config: dict, cols: int = 120, rows: int = 40,
                           geometry_owner: str | None = None) -> dict:
    """Start the user's login shell for a "shell" session (no agent assembly).

    No hooks, MCP, resume, native-id detection or transcript: just the shell
    in the session's folder with a clean environment. Every (re)start is a
    new shell.
    """
    import shell_session as _shell_session  # plain terminals (cli_type "shell")
    cwd = config.get("workspace_path") or os.path.expanduser("~")
    if not os.path.isdir(cwd):
        cwd = os.path.expanduser("~")
    cmd = _shell_session.shell_command()
    try:
        capture_proc.clear_buffer(session_id)
        _session_cli_type_cache[session_id] = _shell_session.SHELL_CLI_TYPE
        # New output stream generation for the new shell; no initial-render
        # collapse (that exists for agent TUIs repainting after a resize).
        mark_pty_started(session_id, "full")
        _pty_start_time.pop(session_id, None)
        await pty_mgr.start_session(
            session_id, cwd, cols, rows, cmd[1:], {}, cmd[0],
            sandbox_type="none", sandbox_network=True,
            geometry_owner=geometry_owner, plain_shell=True,
        )
        await _mark_session_pty_started(session_id)
        pty_alive = pty_mgr.is_alive(session_id)
        await broadcast({"session_id": session_id, "type": "status",
                         "status": "running" if pty_alive else "exited", "pty_alive": pty_alive})
        return {"ok": True}
    except Exception as exc:
        logger.warning("Terminal start failed for %s: %s", session_id, exc)
        return {"ok": False, "reason": f"pty_start_failed:{exc}"}


# ─── REST: Quick start ───────────────────────────────────────────────────
# Sessions that start without choosing a project. See quick_start.py.

import quick_start as _quick_start


class _QuickJsonRequest:
    """Feeds a fixed JSON body to a handler that reads request.json(), while
    keeping the caller's auth context, headers and app (so create_session
    applies exactly the same checks as POST /api/sessions)."""

    def __init__(self, request, body: dict):
        self._request = request
        self._body = body

    async def json(self, *args, **kwargs):
        return dict(self._body)

    def get(self, key, default=None):
        return self._request.get(key, default)

    def __getitem__(self, key):
        return self._request[key]

    def __contains__(self, key):
        return key in self._request

    def __getattr__(self, name):
        return getattr(self._request, name)


def _with_quick_flag(workspace: dict) -> dict:
    workspace["is_quick"] = _quick_start.is_quick_workspace_cached(workspace.get("id"))
    return workspace


async def get_quick_start(request: web.Request) -> web.Response:
    db = await get_db()
    try:
        return web.json_response(await _quick_start.get_state(db))
    finally:
        await db.close()


async def put_quick_start(request: web.Request) -> web.Response:
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid JSON body"}, status=400)
    if not isinstance(body, dict):
        return web.json_response({"error": "expected JSON object"}, status=400)
    db = await get_db()
    try:
        state = await _quick_start.set_root(db, body.get("root"))
    except ValueError as exc:
        return web.json_response({"error": str(exc)}, status=400)
    finally:
        await db.close()
    return web.json_response(state)


async def ensure_quick_workspace(request: web.Request) -> web.Response:
    """POST /api/quick-start/workspace: create the quick workspace if needed.

    Lets "Set up session…" without a project open the full dialog in the
    start folder before any quick session exists. Returns the workspace JSON.
    """
    db = await get_db()
    try:
        workspace = await _quick_start.ensure_workspace(db)
    finally:
        await db.close()
    return web.json_response(_with_quick_flag(workspace_fields.project_row(workspace)))


async def create_quick_session(request: web.Request) -> web.Response:
    """POST /api/sessions/quick {cli_type?, model?, name?, auto_start?, workspace_id?}.

    Without workspace_id (or with the quick workspace) the session starts in
    the quick start root; with a project workspace_id it starts in that project.
    """
    try:
        body = await request.json()
    except Exception:
        body = {}
    if body is None:
        body = {}
    if not isinstance(body, dict):
        return web.json_response({"error": "expected JSON object"}, status=400)
    # Optional workspace_id: the same one-line start, but inside that project
    # (sidebar "New Session", ⌘N with a project selected, Home composer).
    target_id = body.get("workspace_id")
    if target_id is not None and (not isinstance(target_id, str) or not target_id.strip()):
        return web.json_response({"error": "workspace_id must be a non-empty string"}, status=400)
    target_id = target_id.strip() if isinstance(target_id, str) else None
    name = body.get("name")
    name = name.strip() if isinstance(name, str) else ""
    db = await get_db()
    try:
        project = None
        if target_id and not _quick_start.is_quick_workspace_cached(target_id):
            if not _workspace_visible_to_auth(target_id, get_auth(request)):
                return web.json_response({"error": "workspace not found"}, status=404)
            row = await (await db.execute(
                "SELECT id FROM workspaces WHERE id = ?", (target_id,))).fetchone()
            if not row:
                return web.json_response({"error": "workspace not found"}, status=404)
            # A project session gets what the full dialog preselects: the
            # default guidelines and the MCP servers enabled by default.
            # Worktree follows the workspace default (create_session).
            guideline_ids = [r["id"] for r in await (await db.execute(
                "SELECT id FROM guidelines WHERE is_default = 1")).fetchall()]
            mcp_ids = [r["id"] for r in await (await db.execute(
                "SELECT id FROM mcp_servers WHERE default_enabled = 1")).fetchall()]
            project = {"id": target_id, "guideline_ids": guideline_ids, "mcp_server_ids": mcp_ids}
        else:
            workspace = await _quick_start.ensure_workspace(db)
    finally:
        await db.close()
    if project:
        session_body = {
            "workspace_id": project["id"],
            "name": name or _quick_start.DEFAULT_PROJECT_SESSION_NAME,
            "session_type": "worker",
            "guideline_ids": project["guideline_ids"],
            "mcp_server_ids": project["mcp_server_ids"],
        }
    else:
        session_body = {
            "workspace_id": workspace["id"],
            "name": name or _quick_start.DEFAULT_SESSION_NAME,
            "session_type": "worker",
            # No default guidelines and no optional MCP servers: only what IVE
            # always attaches (the worker board) — see create_session.
            "guideline_ids": [],
            "mcp_server_ids": [],
            "worktree": False,
        }
    # Home composer chips: the permission mode and effort are chosen before
    # the session exists; create_session validates them per CLI profile.
    for key in ("cli_type", "model", "permission_mode", "effort"):
        if isinstance(body.get(key), str) and body[key].strip():
            session_body[key] = body[key].strip()
    if "auto_start" in body:
        session_body["auto_start"] = bool(body["auto_start"])
    return await create_session(_QuickJsonRequest(request, session_body))


async def attach_session_to_workspace(request: web.Request) -> web.Response:
    """POST /api/sessions/{id}/attach {workspace_id? | path?}."""
    session_id = request.match_info["id"]
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid JSON body"}, status=400)
    if not isinstance(body, dict):
        return web.json_response({"error": "expected JSON object"}, status=400)
    visible = await _get_visible_session_for_request(session_id, request)
    if not visible:
        return web.json_response({"error": "session not found"}, status=404)
    db = await get_db()
    try:
        result = await _quick_start.attach_session(
            db, session_id,
            workspace_id=body.get("workspace_id") or None,
            path=body.get("path") or None,
            undo_token=body.get("undo_token"),
        )
    except _quick_start.AttachError as exc:
        return web.json_response({"error": str(exc)}, status=exc.status)
    finally:
        await db.close()
    workspace = result["workspace"]
    if result["workspace_created"]:
        # Same follow-ups as POST /api/workspaces for a newly registered folder.
        asyncio.create_task(_ensure_workspace_commander_safely(workspace["id"]))
        asyncio.create_task(_sync_memory_to_cli(workspace["id"]))
    session = _decorate_session_dict(result["session"])
    try:
        await broadcast({
            "type": "session_update",
            "session_id": session["id"],
            "workspace_id": session.get("workspace_id"),
            "session": session,
        })
    except Exception:
        logger.exception("Session attached but WebSocket announcement failed")
    return web.json_response({
        "session": session,
        "workspace": _with_quick_flag(workspace_fields.project_row(workspace)),
        "undo_token": result.get("undo_token"),
    })


async def get_session_project_hint(request: web.Request) -> web.Response:
    session_id = request.match_info["id"]
    if not await _get_visible_session_for_request(session_id, request):
        return web.json_response({"error": "session not found"}, status=404)
    db = await get_db()
    try:
        return web.json_response(await _quick_start.current_hint(db, session_id))
    finally:
        await db.close()


async def _autostart_session_pty(session_id: str, *, cols: int = 120, rows: int = 40):
    """Start a PTY for an already-created session row.

    Used by:
      • create_session(auto_start=True)
      • pipeline_engine._auto_create_session — auto-created stage sessions
        previously left a session row with no PTY, so the very next stage
        crashed on the is_alive check (BUG H6).
    """
    import shell_session as _shell_session  # plain terminals (cli_type "shell")
    config = await get_session_config(session_id)
    if not config:
        logger.warning(f"_autostart_session_pty: no config for {session_id}")
        # Brain session-feedback loop (producer): a failed-to-start that is
        # otherwise swallowed must still be learnable. Best-effort only — never
        # let the emit break the (already best-effort) autostart path.
        try:
            await bus.emit(CommanderEvent.SESSION_FAILED_TO_START, {
                "session_id": session_id,
                "workspace_id": None,
                "reason": "no_config",
            }, source="api")
        except Exception:
            logger.debug("SESSION_FAILED_TO_START emit skipped (no_config)", exc_info=True)
        # Brain dispatch correlation (synchronous resolution): return the
        # outcome so create_session can surface it and the Brain can resolve
        # the dispatch job at dispatch time (no TTL-sweep strand).
        return {"ok": False, "reason": "no_config"}
    if _shell_session.is_shell_session(config):
        return await _start_shell_pty(session_id, config, cols, rows)
    cli_type = config.get("cli_type") or "claude"
    model = config.get("model")
    permission_mode = config.get("permission_mode", "auto")
    effort = config.get("effort") or None
    system_prompt = config.get("system_prompt") or ""
    session_type = config.get("session_type") or ""

    extra_env = await _prepare_session_cli_env(config, session_id)
    permission_mode = await _apply_worker_safety_gate_permission(
        config, session_id, extra_env, auto_start=True
    )
    launch_model = await _launch_model_for_session(config)
    auto_sess = UnifiedSession(cli_type, {
        "model": launch_model,
        "permission_mode": permission_mode,
        "effort": effort,
        "worktree": config.get("worktree", 0),
    })
    _auto_cli_home = extra_env.get("HOME")
    _auto_deferred_prompt = None
    if session_type == "planner" and "You are the Planner" not in system_prompt:
        system_prompt = (
            PLANNER_SYSTEM_PROMPT + ("\n\n" + system_prompt if system_prompt else "")
        )
    elif session_type == "architect" and "You are the Architect" not in system_prompt:
        system_prompt = (
            ARCHITECT_SYSTEM_PROMPT + ("\n\n" + system_prompt if system_prompt else "")
        )
    elif session_type == "brainstormer" and "You are the Brainstormer" not in system_prompt:
        system_prompt = (
            BRAINSTORMER_SYSTEM_PROMPT + ("\n\n" + system_prompt if system_prompt else "")
        )
    elif session_type == "secure" and "You are the Secure agent" not in system_prompt:
        system_prompt = (
            SECURE_SYSTEM_PROMPT + ("\n\n" + system_prompt if system_prompt else "")
        )
    elif session_type in ("", "worker", "test_worker") and WORKER_SYSTEM_PROMPT_FRAGMENT:
        if "## Git Commits and IVE Attribution" not in system_prompt:
            system_prompt = (
                WORKER_SYSTEM_PROMPT_FRAGMENT + ("\n\n" + system_prompt if system_prompt else "")
            )
    if system_prompt and auto_sess.profile.managed_context_adapter == "antigravity_rules":
        _auto_deferred_prompt = system_prompt
    elif system_prompt:
        auto_sess.append_system_prompt(system_prompt)

    if (
        auto_sess.profile.managed_context_adapter == "antigravity_rules"
        and _auto_deferred_prompt
    ):
        try:
            _private_auto_agy_rules_dir = _activate_antigravity_session_rules_dir(
                auto_sess,
                session_id,
                _auto_deferred_prompt,
            )
            if _private_auto_agy_rules_dir:
                _auto_deferred_prompt = None
                logger.info(
                    "Antigravity auto-start session %s using private Rules add-dir: %s",
                    session_id[:8],
                    _private_auto_agy_rules_dir,
                )
        except Exception as exc:
            msg = (
                "Antigravity auto-start blocked: IVE could not prepare "
                f"the session Rules add-dir ({exc})."
            )
            logger.error("%s", msg)
            await _fail_session_start(
                session_id,
                msg,
                "antigravity_rules_setup_failed",
            )
            return {"ok": False, "reason": "antigravity_rules_setup_failed"}

    if _auto_deferred_prompt:
        msg = (
            f"{cli_type} auto-start blocked: IVE has no native managed-context "
            "injection path for this CLI. Refusing to paste internal context "
            "into the terminal prompt."
        )
        logger.error("%s", msg)
        await _fail_session_start(
            session_id,
            msg,
            "managed_context_native_injection_missing",
        )
        return {"ok": False, "reason": "managed_context_native_injection_missing"}

    await _record_session_runtime_home(session_id, cli_type, _auto_cli_home)

    # ── Resume: pre-checked so a dead pointer becomes a fresh spawn ──
    await _apply_session_resume(auto_sess, config, session_id, extra_env)

    # ── MCP servers: the one shared assembly (same helper as start_pty) ──
    _auto_mcp_result = await _apply_session_mcp(
        auto_sess, config, session_id, extra_env
    )
    _a_w2w_comms, _a_w2w_context, _a_w2w_coord = _auto_mcp_result["w2w"]

    auto_mode = (config.get("owner_mode") or "full").strip().lower()
    if auto_mode != "full":
        try:
            import mode_policy as _mode_policy
            _mode_policy.enforce_mode_for_pty(
                auto_sess,
                auto_mode,
                code_bash_allowlist=await _get_code_bash_allowlist(),
            )
        except Exception as exc:
            await _fail_session_start(
                session_id,
                f"Mode-blocked: {exc}",
                "mode_violation",
            )
            return {"ok": False, "reason": "mode_violation"}

    if auto_sess.profile.id == "antigravity":
        from antigravity_runtime import apply_model as _auto_apply_agy_model
        await _refresh_antigravity_native_context(config)
        _auto_apply_agy_model(model, home=_auto_cli_home)

    cmd = auto_sess.build_command()

    # Mirror the manual-start path's extra_env construction so auto-started
    # PTYs also get account auth + hook relay env vars. Without these, hooks
    # can't POST lifecycle events back, breaking session_state, plan
    # detection, oversight, etc.
    extra_env["COMMANDER_SESSION_ID"] = session_id
    import session_proofs
    extra_env[session_proofs.ENV_VAR] = session_proofs.issue(session_id)
    extra_env["COMMANDER_API_URL"] = f"http://{HOST}:{PORT}"
    extra_env["COMMANDER_WORKSPACE_ID"] = config.get("workspace_id", "")
    extra_env["COMMANDER_WORKSPACE_PATH"] = config.get("workspace_path", "")
    extra_env["COMMANDER_SESSION_TYPE"] = config.get("session_type") or "worker"
    extra_env["COMMANDER_CLI_TYPE"] = cli_type
    extra_env["WORKER_SESSION_ID"] = session_id
    extra_env["WORKER_WORKSPACE_ID"] = config.get("workspace_id", "")
    extra_env["WORKER_SESSION_TYPE"] = config.get("session_type") or "worker"
    extra_env["WORKER_W2W_COMMS"] = _a_w2w_comms
    extra_env["WORKER_W2W_CONTEXT"] = _a_w2w_context
    extra_env["WORKER_W2W_COORDINATION"] = _a_w2w_coord

    # Git attribution is captured out-of-band. Keep Git's author/committer
    # identity on normal repo/user config.
    try:
        from git_attribution import inject_git_attribution_env
        await inject_git_attribution_env(config, session_id, extra_env)
    except Exception as git_attr_exc:
        logger.debug("Git attribution env skipped (autostart): %s", git_attr_exc)

    try:
        pre_files = _snapshot_files_for_detection(
            cli_type,
            config["workspace_path"],
            extra_env.get("HOME"),
        )
        # Re-arm one-shot output failure detection for this replacement PTY.
        capture_proc.clear_buffer(session_id)
        mark_pty_started(session_id, auto_mode)
        await pty_mgr.start_session(
            session_id,
            config["workspace_path"],
            cols,
            rows,
            cmd[1:], extra_env, cmd[0],
            sandbox_type=config.get("sandbox_type", "none"),
            sandbox_network=bool(config.get("sandbox_network", 1))
        )
        await _mark_session_pty_started(session_id)
        await _clear_auth_failed_session_state(session_id)
        from hooks import get_session_logical_status
        pty_alive = pty_mgr.is_alive(session_id)
        logical_status = get_session_logical_status(session_id, pty_alive, "idle")
        await broadcast({"session_id": session_id, "type": "status", "status": logical_status, "pty_alive": pty_alive})
        _session_cli_type_cache[session_id] = cli_type
        _schedule_session_detection(
            cli_type,
            session_id,
            config["workspace_path"],
            pre_files,
            extra_env.get("HOME"),
        )
    except Exception as e:
        logger.warning(f"Auto-start PTY failed for {session_id}: {e}")
        # Brain session-feedback loop (producer): surface the swallowed PTY-start
        # failure so the Brain can learn it. Best-effort only — never let the
        # emit break the (already best-effort) autostart path.
        try:
            await bus.emit(CommanderEvent.SESSION_FAILED_TO_START, {
                "session_id": session_id,
                "workspace_id": config.get("workspace_id"),
                "reason": f"pty_start_failed:{e}",
            }, source="api")
        except Exception:
            logger.debug("SESSION_FAILED_TO_START emit skipped (pty_start_failed)", exc_info=True)
        # Brain dispatch correlation (synchronous resolution): return the
        # failure outcome so the dispatch job resolves at dispatch time.
        return {"ok": False, "reason": f"pty_start_failed:{e}"}

    # Normal success path — PTY started. Brain dispatch correlation: return a
    # success outcome so create_session can surface autostart={"ok": True} and
    # the dispatch job resolves synchronously (no strand at "dispatched").
    return {"ok": True}


async def _supervisor_spawn_pty_from_row(row: dict) -> None:
    """Full-assembly spawn used by session_supervisor.restart().

    Installed over session_supervisor._spawn_pty_from_row at startup so a
    restart (manual POST or crash auto-restart) rebuilds MCP config, resume
    state, hook-relay env and sandbox flags exactly like a normal start.
    The supervisor has already stopped any old PTY and expects an exception
    on failure, so translate _autostart_session_pty's outcome dict.
    """
    session_id = row.get("id")
    if not session_id:
        raise RuntimeError("supervisor restart: row has no session id")
    outcome = await _autostart_session_pty(
        session_id, cols=row.get("_pty_cols", 120), rows=row.get("_pty_rows", 40),
    ) or {}
    if not outcome.get("ok"):
        raise RuntimeError(
            f"supervisor restart spawn failed: {outcome.get('reason') or 'unknown'}"
        )


def _install_supervisor_spawn_hook() -> None:
    """Route session_supervisor restarts through the full spawn path.

    session_supervisor._spawn_pty_from_row rebuilds only the bare CLI
    command — no MCP config, no guidelines (its docstring says so and asks
    for this refactor). Both of its entry points (crash auto-restart and
    POST /api/sessions/{id}/restart) could therefore bring a Commander back
    with ZERO MCP tools despite a correct session_mcp_servers binding.
    """
    import session_supervisor
    session_supervisor._spawn_pty_from_row = _supervisor_spawn_pty_from_row


def _commander_provision_suppression_key(workspace_id: str) -> str:
    return f"workspace:{workspace_id}:commander_auto_provision_suppressed"


async def delete_session(request: web.Request) -> web.Response:
    session_id = request.match_info["id"]
    # MCP-S4: a worker MCP caller cannot kill sibling sessions. Allow only
    # commander or self-deletion.
    caller = await _resolve_caller(request)
    if caller and caller["session_type"] not in ("commander",):
        if caller["session_id"] != session_id:
            return web.json_response(
                {"error": "forbidden: only commander or the session itself can delete a session"},
                status=403,
            )
    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT * FROM sessions WHERE id = ?", (session_id,)
        )
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "session not found"}, status=404)
        session_meta = dict(row) if row else {}
        if not _session_visible_to_request(session_meta, request):
            return web.json_response({"error": "session not found"}, status=404)
        await _stop_session_expected(session_id)
        if session_meta.get("session_type") == "commander" and session_meta.get("workspace_id"):
            # Explicit deletion also opts this workspace out of the dormant
            # default. Commit the preference and deletion together: a failed
            # delete must not silently change future startup behavior.
            await db.execute(
                """INSERT INTO app_settings (key, value, updated_at)
                   VALUES (?, '1', datetime('now'))
                   ON CONFLICT(key) DO UPDATE SET value = '1', updated_at = excluded.updated_at""",
                (_commander_provision_suppression_key(session_meta["workspace_id"]),),
            )
        await db.execute("DELETE FROM sessions WHERE id = ?", (session_id,))
        await db.commit()
    finally:
        await db.close()

    await bus.emit(CommanderEvent.SESSION_DELETED, {
        "session_id": session_id,
        "workspace_id": session_meta.get("workspace_id"),
        "name": session_meta.get("name"),
    }, source="api", actor="user")
    # The bus event is not fanned out to browser sockets; tell every open
    # tab/client directly so none keeps a ghost entry for the deleted session.
    await broadcast({
        "type": "session_deleted",
        "session_id": session_id,
        "workspace_id": session_meta.get("workspace_id"),
    })
    return web.json_response({"ok": True})


# ─── REST: Messages ──────────────────────────────────────────────────────

def _num_or_none(value):
    try:
        if value is None or value == "":
            return None
        return float(value)
    except (TypeError, ValueError):
        return None


def _first_num(*values):
    for value in values:
        n = _num_or_none(value)
        if n is not None:
            return n
    return None


def _nested_num(value: dict, *path: str):
    current = value
    for key in path:
        if not isinstance(current, dict):
            return None
        current = current.get(key)
    return _num_or_none(current)


def _extract_cli_message_metrics(msg: dict) -> dict:
    """Extract token/cost metadata from native CLI history entries.

    Claude Code stores Anthropic usage under message.usage. Gemini variants
    commonly use usageMetadata with prompt/candidate/total token counts. Codex
    can expose OpenAI Responses usage with cached input under nested
    input_tokens_details. Keep this permissive so future CLIs can still
    populate the telemetry UI.
    """
    if not isinstance(msg, dict):
        return {}

    inner = msg.get("message") if isinstance(msg.get("message"), dict) else {}
    usage = {}
    for candidate in (
        msg.get("usage"),
        inner.get("usage"),
        msg.get("usageMetadata"),
        inner.get("usageMetadata"),
        msg.get("usage_metadata"),
        inner.get("usage_metadata"),
    ):
        if isinstance(candidate, dict):
            usage.update(candidate)

    input_tokens = _first_num(
        usage.get("input_tokens"),
        usage.get("prompt_tokens"),
        usage.get("promptTokenCount"),
        usage.get("inputTokenCount"),
    )
    output_tokens = _first_num(
        usage.get("output_tokens"),
        usage.get("completion_tokens"),
        usage.get("candidatesTokenCount"),
        usage.get("outputTokenCount"),
    )
    cache_creation_tokens = _first_num(
        usage.get("cache_creation_input_tokens"),
        usage.get("cacheCreationInputTokens"),
    )
    direct_cache_read_tokens = _first_num(
        usage.get("cache_read_input_tokens"),
        usage.get("cacheReadInputTokens"),
    )
    included_cache_read_tokens = _first_num(
        usage.get("cachedContentTokenCount"),
        _nested_num(usage, "input_tokens_details", "cached_tokens"),
        _nested_num(usage, "prompt_tokens_details", "cached_tokens"),
        _nested_num(usage, "inputTokensDetails", "cachedTokens"),
        _nested_num(usage, "promptTokensDetails", "cachedTokens"),
        usage.get("cached_tokens"),
        usage.get("cachedTokens"),
    )
    cache_read_tokens = direct_cache_read_tokens
    if cache_read_tokens is None:
        cache_read_tokens = included_cache_read_tokens

    if (
        input_tokens is not None
        and direct_cache_read_tokens is None
        and included_cache_read_tokens is not None
    ):
        input_tokens = max(0, input_tokens - included_cache_read_tokens)

    total_tokens = _first_num(
        usage.get("total_tokens"),
        usage.get("totalTokenCount"),
        usage.get("token_count"),
        msg.get("token_count"),
    )

    if total_tokens is None:
        parts = [input_tokens, output_tokens, cache_creation_tokens, cache_read_tokens]
        present = [p for p in parts if p is not None]
        if present:
            total_tokens = sum(present)

    cost_usd = _first_num(msg.get("costUSD"), msg.get("cost_usd"), inner.get("cost_usd"))
    duration_ms = _first_num(msg.get("durationMs"), msg.get("duration_ms"), inner.get("duration_ms"))

    return {
        "usage": usage or None,
        "input_tokens": int(input_tokens) if input_tokens is not None else None,
        "output_tokens": int(output_tokens) if output_tokens is not None else None,
        "cache_creation_tokens": int(cache_creation_tokens) if cache_creation_tokens is not None else None,
        "cache_read_tokens": int(cache_read_tokens) if cache_read_tokens is not None else None,
        "token_count": int(total_tokens) if total_tokens is not None else None,
        "cost_usd": cost_usd,
        "duration_ms": int(duration_ms) if duration_ms is not None else None,
    }


def _read_task_output_file(path_value: str, max_bytes: int = 65536) -> dict:
    """Read Claude background-task output files from temp task directories only."""
    if not path_value:
        return {}
    try:
        path = _Path(path_value).expanduser()
        resolved = path.resolve()
        allowed_bases = {
            _Path("/tmp").resolve(),
            _Path("/private/tmp").resolve(),
            _Path(tempfile.gettempdir()).resolve(),
        }
        if not any(resolved == base or base in resolved.parents for base in allowed_bases):
            return {}
        if resolved.suffix != ".output" or "tasks" not in resolved.parts:
            return {}
        if not resolved.is_file():
            return {}

        size = resolved.stat().st_size
        with resolved.open("rb") as f:
            truncated = size > max_bytes
            if truncated:
                f.seek(-max_bytes, 2)
            data = f.read(max_bytes)
        text = data.decode("utf-8", errors="replace").strip()
        if not text:
            return {"output_text": "", "output_truncated": False, "output_size": size}
        return {
            "output_text": text,
            "output_truncated": truncated,
            "output_size": size,
        }
    except Exception as e:
        logger.debug("Failed to read task output file %s: %s", path_value, e)
        return {}


def _tool_result_text(content) -> str:
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, str):
                parts.append(item)
            elif isinstance(item, dict) and item.get("text"):
                parts.append(str(item.get("text")))
        return "\n".join(parts)
    return str(content)


_IVE_MANAGED_CONTEXT_START = "<ive-managed-context>"
_IVE_MANAGED_CONTEXT_END = "</ive-managed-context>"


async def _refresh_antigravity_native_context(config: dict) -> None:
    """Refresh IVE-owned Antigravity Rules for durable workspace context.

    Stable workspace memory belongs in .agents/rules. Per-session prompts,
    active tickets, attached guidelines, and other transient details stay in
    the filtered managed turn to avoid leaking one agy session into another.
    """
    workspace_path = config.get("workspace_path")
    if not workspace_path:
        return

    try:
        from antigravity_runtime import ensure_ive_workspace_rule
        ensure_ive_workspace_rule(workspace_path)

        from memory_sync import get_provider, sync_manager
        provider = get_provider("antigravity")
        if not provider:
            return

        workspace_id = config.get("workspace_id")
        memory_path = provider.memory_file_path(workspace_path)
        central = await sync_manager.read_central(workspace_id) if workspace_id else ""
        if central or (memory_path and not memory_path.exists()):
            provider.write_memory(workspace_path, central)

        if workspace_id:
            from memory_manager import memory_manager
            entries = await memory_manager.list_entries(workspace_id=workspace_id)
            if entries:
                provider.write_auto_memory(workspace_path, entries)
    except Exception as exc:
        logger.debug("Antigravity native context refresh skipped: %s", exc)


def _content_text_for_filter(content) -> str:
    if isinstance(content, str):
        stripped = content.strip()
        if stripped and stripped[0] in "[{":
            try:
                return _content_text_for_filter(json.loads(stripped))
            except (json.JSONDecodeError, TypeError):
                return content
        return content
    if isinstance(content, list):
        return "\n".join(_content_text_for_filter(item) for item in content)
    if isinstance(content, dict):
        if content.get("type") == "text" and content.get("text") is not None:
            return str(content.get("text") or "")
        for key in ("text", "content", "message", "summary"):
            if content.get(key) not in (None, ""):
                return _content_text_for_filter(content.get(key))
        return ""
    return "" if content is None else str(content)


def _is_ive_managed_context_message(role: str, content, idx: int | None = None) -> bool:
    role_name = (role or "").lower()
    if role_name not in ("user", "human"):
        return False

    text = _content_text_for_filter(content).strip()
    if not text:
        return False
    return text.startswith(_IVE_MANAGED_CONTEXT_START)


def _native_transcript_has_ive_managed_context(
    cli_type: str,
    workspace_path: str,
    native_sid: str,
    cli_home: str | _Path | None = None,
) -> bool:
    """Return true if a resumed native transcript already has IVE startup context."""
    if not cli_type or not workspace_path or not native_sid:
        return False

    try:
        transcript_file = _get_native_transcript_path(
            cli_type,
            workspace_path,
            native_sid,
            cli_home=cli_home,
        )
        if not transcript_file or not transcript_file.exists():
            return False

        for idx, msg in enumerate(read_session_messages(str(transcript_file))):
            normalized = normalize_jsonl_entry(msg)
            if not normalized:
                continue
            role, content = normalized
            if _is_ive_managed_context_message(role, content, idx):
                return True
    except Exception as exc:
        logger.debug("Managed context transcript check skipped: %s", exc)
    return False


def _parse_background_task_start_text(text: str) -> dict | None:
    text = text or ""
    # Cheap literal prefilters: every pattern below needs one of these
    # substrings, and the regexes cost ~10-25 ms per 400 KB tool output.
    lowered = text.lower()
    has_done = "(id:" in lowered
    has_started = "command running in background with id:" in lowered
    has_output_file = ".output" in lowered
    if not (has_done or has_started or has_output_file):
        return None
    done_match = has_done and re.search(
        r"(?:^|\n)\s*(?:Done|Completed)\s*\(ID:\s*`?([A-Za-z0-9_-]+)`?\)\.\s*Output(?:\s+was)?:\s*([\s\S]*)$",
        text,
        re.IGNORECASE,
    )
    if done_match:
        return {
            "type": "task_notification",
            "task_id": done_match.group(1),
            "status": "completed",
            "summary": "Background command completed",
            "output_text": done_match.group(2).strip(),
        }

    match = has_started and re.search(
        r"Command running in background with ID:\s*([A-Za-z0-9_-]+)\.\s*Output is being written to:\s*(\S+)",
        text,
        re.IGNORECASE,
    )
    if match:
        return {
            "type": "task_notification",
            "task_id": match.group(1),
            "status": "running",
            "summary": "Background command started",
            "output_file": match.group(2),
        }

    if not has_output_file:
        return None
    id_match = re.search(r"(?:Task ID|ID|id)\s*:?\s*([A-Za-z0-9_-]+)", text, re.IGNORECASE)
    output_match = re.search(r"Output(?:\s+file)?\s*:?\s*(\S+\.output)\b", text, re.IGNORECASE)
    if not id_match or not output_match:
        return None

    status_match = re.search(r"\b(completed|complete|done|failed|error|running|started)\b", text, re.IGNORECASE)
    status = status_match.group(1).lower() if status_match else "running"
    summary = "Background command completed" if status in ("completed", "complete", "done") else "Background command started"
    return {
        "type": "task_notification",
        "task_id": id_match.group(1),
        "status": status,
        "summary": summary,
        "output_file": output_match.group(1),
    }


def _enrich_task_notification_content(content):
    parsed_string = False
    if isinstance(content, str):
        stripped = content.strip()
        if not stripped.startswith("["):
            return content
        try:
            parsed = json.loads(stripped)
        except json.JSONDecodeError:
            return content
        if not isinstance(parsed, list):
            return content
        content = parsed
        parsed_string = True

    if not isinstance(content, list):
        return content
    enriched = []
    for block in content:
        if isinstance(block, dict) and block.get("type") == "task_notification" and block.get("output_file"):
            output = _read_task_output_file(block.get("output_file") or "")
            enriched.append({**block, **output} if output else block)
        elif isinstance(block, dict) and str(block.get("type") or "").lower() in (
            "tool_result",
            "toolresult",
            "function_response",
            "functionresponse",
        ):
            task_block = _parse_background_task_start_text(_tool_result_text(block.get("content")))
            if task_block:
                output = _read_task_output_file(task_block.get("output_file") or "")
                enriched.append({**task_block, **output} if output else task_block)
            else:
                enriched.append(block)
        else:
            enriched.append(block)
    return json.dumps(enriched) if parsed_string else enriched


# ─── Chat transcript rows (cached layer around read + normalize) ──────────
# list_messages used to re-read and re-normalize the full transcript on the
# event loop on every chat poll. transcript_cache keeps the formatted rows per
# file, parses only appended JSONL lines and serves rows after a cursor.
# _format_transcript_message is the per-entry formatting step. Normalization
# runs through a per-generation HistoryNormalizer (history_adapters), the
# incremental form of normalize_history_entries: Codex user prompts recorded
# in several shapes stay one row, also across appended chunks.

def _new_transcript_normalizer(prev=None):
    """transcript_cache state_factory: fresh normalizer per cache generation.

    On a rebuild request (a Codex user event showed up after response_item
    fallback rows were listed) the new generation starts knowing that.
    """
    from history_adapters import HistoryNormalizer
    return HistoryNormalizer.next_generation(prev)


def _format_transcript_message(msg, idx: int, session_id: str, trim: bool = True, normalizer=None):
    """Format one native transcript entry as an API row.

    Returns ``(row | None, live)``; ``live`` marks rows whose content depends
    on background-task output files and must be re-formatted per response.
    ``normalizer``: the cache generation's HistoryNormalizer while rows are
    added in order; None re-formats one already listed row on its own.
    """
    from history_adapters import normalize_history_entry_standalone
    normalized = normalizer.feed(msg) if normalizer is not None else normalize_history_entry_standalone(msg)
    if normalized is None:
        return None, False
    role, content = normalized
    if _is_ive_managed_context_message(role, content, idx):
        return None, False
    content = _enrich_task_notification_content(content)
    if isinstance(content, list):
        live = any(
            isinstance(block, dict) and block.get("type") == "task_notification" and block.get("output_file")
            for block in content
        )
    else:
        live = isinstance(content, str) and '"output_file"' in content
    truncated = False
    if trim:
        content, truncated = _transcript_cache.trim_content(content)
    if isinstance(content, list):
        content = json.dumps(content)
    elif not isinstance(content, str):
        content = str(content)

    # Use a stable key based on the index if no explicit id is found
    msg_id = msg.get("id") if isinstance(msg, dict) else None
    if not msg_id:
        msg_id = f"msg-{idx}"
    metrics = _extract_cli_message_metrics(msg)
    created_at = None
    if isinstance(msg, dict):
        created_at = msg.get("created_at") or msg.get("timestamp") or msg.get("time")

    row = {
        "id": msg_id,
        "session_id": session_id,
        "role": role,
        "content": content,
        "created_at": created_at,
        "usage": metrics.get("usage"),
        # Claude writes one API response as several rows (thinking, text,
        # tool_use) that repeat the same usage; the UI counts usage once per
        # API message id.
        "api_message_id": (
            msg["message"].get("id")
            if isinstance(msg, dict) and isinstance(msg.get("message"), dict)
            else None
        ),
        "token_count": metrics.get("token_count"),
        "input_tokens": metrics.get("input_tokens"),
        "output_tokens": metrics.get("output_tokens"),
        "cache_creation_tokens": metrics.get("cache_creation_tokens"),
        "cache_read_tokens": metrics.get("cache_read_tokens"),
        "cost_usd": metrics.get("cost_usd"),
        "duration_ms": metrics.get("duration_ms"),
    }
    if truncated:
        row["content_truncated"] = True
    return row, live


_TRANSCRIPT_PAGE_MAX = 5000


def _query_int(value, lo: int, hi: int):
    try:
        n = int(value)
    except (TypeError, ValueError):
        return None
    return max(lo, min(hi, n))


def _transcript_rows_payload(transcript_file, session_id: str, cursor, tail=None, before=None, limit=None):
    """Blocking: build the JSON body for list_messages (runs in a thread)."""
    fmt = lambda msg, idx, state: _format_transcript_message(msg, idx, session_id, normalizer=state)
    if before is not None:
        result = _transcript_cache.get_older(
            session_id, str(transcript_file), read_session_messages, fmt,
            before=before, limit=limit or 200, state_factory=_new_transcript_normalizer,
        )
        return json.dumps(result).encode()
    result = _transcript_cache.get_rows(
        session_id,
        str(transcript_file),
        read_session_messages,
        fmt,
        cursor=cursor,
        state_factory=_new_transcript_normalizer,
        tail=tail if cursor is not None else None,
    )
    if not result["raw_count"]:
        return None  # empty transcript: fall back to the DB rows, as before
    if cursor is None:
        return json.dumps(result["rows"]).encode()
    keys = ["rows", "start", "updates", "cursor", "reset"]
    if tail is not None:
        keys += ["base", "total", "before"]
    return json.dumps({key: result[key] for key in keys}).encode()


async def _transcript_messages_response(request: web.Request, transcript_file, session_id: str):
    """Serve transcript rows; ``?cursor=`` opts into the incremental shape.

    Without a ``cursor`` query parameter the response stays the plain row
    array. With ``cursor`` (empty for the first call) the body is
    ``{rows, start, updates, cursor, reset}`` (see transcript_cache.get_rows).
    ``&tail=N`` (with ``cursor``): a reset answers only the last N rows plus
    ``base`` (position of the first row), ``total`` and ``before`` (turns and
    tokens of the rows left out). ``?before=<gen>:<pos>&limit=N`` pages older
    rows: ``{rows, start, cursor, stale, before}``.
    Returns None to use the DB fallback (still a plain array).
    """
    cursor = request.query.get("cursor")
    tail = _query_int(request.query.get("tail"), 1, _TRANSCRIPT_PAGE_MAX) if "tail" in request.query else None
    before = request.query.get("before")
    limit = _query_int(request.query.get("limit"), 1, _TRANSCRIPT_PAGE_MAX)
    try:
        body = await asyncio.to_thread(
            _transcript_rows_payload, transcript_file, session_id, cursor, tail, before, limit,
        )
    except Exception as e:
        logger.warning("Error reading active session transcript file: %s", e)
        return None
    if body is None:
        return None
    return web.Response(body=body, content_type="application/json")


async def get_message_full(request: web.Request) -> web.Response:
    """Return one transcript row without chat-view trimming."""
    session_id = request.match_info["id"]
    message_id = request.match_info["message_id"]
    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        sess = await cur.fetchone()
        if not sess:
            return web.json_response({"error": "session not found"}, status=404)
        sess_dict = dict(sess)
        if not _session_readable_to_request(sess_dict, request):
            return web.json_response({"error": "session not found"}, status=404)
        workspace_path = None
        if sess_dict["workspace_id"]:
            cur = await db.execute("SELECT path FROM workspaces WHERE id = ?", (sess_dict["workspace_id"],))
            ws = await cur.fetchone()
            workspace_path = ws["path"] if ws else None
    finally:
        await db.close()
    native_sid = sess_dict["native_session_id"]
    if not native_sid or not workspace_path:
        return web.json_response({"error": "message not found"}, status=404)
    transcript_file = _get_native_transcript_path(
        sess_dict["cli_type"] or "claude",
        workspace_path,
        native_sid,
        cli_home=_session_transcript_home(sess_dict),
    )
    if not transcript_file or not transcript_file.exists():
        return web.json_response({"error": "message not found"}, status=404)

    def _load():
        path = str(transcript_file)
        # Make sure the row index is current before resolving the id.
        _transcript_cache.get_rows(
            session_id, path, read_session_messages,
            lambda msg, idx, state: _format_transcript_message(msg, idx, session_id, normalizer=state),
            state_factory=_new_transcript_normalizer,
        )
        msg, raw_idx = _transcript_cache.get_raw_message(session_id, path, message_id, read_session_messages)
        if msg is None:
            return None
        row, _ = _format_transcript_message(msg, raw_idx, session_id, trim=False)
        return row

    row = await asyncio.to_thread(_load)
    if row is None:
        return web.json_response({"error": "message not found"}, status=404)
    return web.Response(body=json.dumps(row).encode(), content_type="application/json")


def _chat_transcript_issue(cli_type: str, screen: str) -> str | None:
    if cli_type != "claude":
        return None
    compact = re.sub(r"\s+", "", (screen or "").lower())
    if "transcriptsavingisoff" in compact and "claude_code_child_session" in compact:
        return (
            "Claude is replying in the terminal, but chat history saving is disabled. "
            "Open the terminal to read and export this conversation before restarting the session."
        )
    return None


async def _sidechat_session_context(session_id):
    """Read a bounded snapshot without writing to, resuming or steering the session."""
    from sidechat import bounded_conversation
    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
        if not row:
            raise ValueError("This session is no longer available. Open another session to ask a side question.")
        session = dict(row)
        cur = await db.execute("SELECT name, path FROM workspaces WHERE id = ?", (session["workspace_id"],))
        row = await cur.fetchone()
        workspace = dict(row) if row else {}
        task = None
        task_id = session.get("active_ticket_id") or session.get("task_id")
        if task_id:
            cur = await db.execute("SELECT title, description, status FROM tasks WHERE id = ? AND workspace_id = ?", (task_id, session["workspace_id"]))
            row = await cur.fetchone()
            if row:
                task = {key: str(value or "")[:4000] for key, value in dict(row).items()}
        cur = await db.execute("SELECT role, content FROM messages WHERE session_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 150", (session_id,))
        rows = list(reversed([dict(row) for row in await cur.fetchall()]))
        cur = await db.execute("SELECT role, content FROM messages WHERE session_id = ? ORDER BY created_at, rowid LIMIT 30", (session_id,))
        first_rows = [dict(row) for row in await cur.fetchall()]
    finally:
        await db.close()
    warning = None
    if session.get("native_session_id") and workspace.get("path"):
        path = await asyncio.to_thread(
            _get_native_transcript_path, session.get("cli_type") or "claude", workspace["path"],
            session["native_session_id"], cli_home=_session_transcript_home(session))
        if path and path.exists():
            payload = await asyncio.to_thread(_transcript_rows_payload, path, session_id, "", tail=150)
            if payload:
                transcript = json.loads(payload)
                rows = transcript["rows"]
                generation = transcript["cursor"].split(":")[0]
                beginning = await asyncio.to_thread(_transcript_rows_payload, path, session_id, "",
                    before=f"{generation}:{min(30, transcript['total'])}", limit=30)
                first_rows = json.loads(beginning)["rows"] if beginning else []
        else:
            warning = "The native transcript is unavailable; only saved conversation text is included."
    first_request = next((item["content"] for item in bounded_conversation(first_rows) if item["role"] == "user"), None)
    return {"id": session_id, "name": session.get("name"), "status": session.get("status"),
            "project_name": workspace.get("name"), "project_path": session.get("worktree_path") or workspace.get("path"),
            "initial_request": first_request, "summary": str(session.get("summary") or "")[:4000],
            "task": task, "recent_conversation": bounded_conversation(rows),
            "scope": "Recent visible text only; not the full transcript or repository.", "warning": warning}


async def list_messages(request: web.Request) -> web.Response:
    session_id = request.match_info["id"]
    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        sess = await cur.fetchone()
        if not sess:
            return web.json_response({"error": "session not found"}, status=404)
        
        sess_dict = dict(sess)
        if not _session_readable_to_request(sess_dict, request):
            return web.json_response({"error": "session not found"}, status=404)
        native_sid = sess_dict["native_session_id"]
        cli_type = sess_dict["cli_type"] or "claude"
        workspace_id = sess_dict["workspace_id"]

        issue = _chat_transcript_issue(cli_type, _startup_blocker_text(session_id))
        if issue:
            # Never report a healthy, empty conversation when the actual
            # terminal has replies that cannot reach the transcript reader.
            return web.json_response({"error": issue, "code": "transcript_unavailable"}, status=503)
        
        # Load workspace path
        workspace_path = None
        if workspace_id:
            cur = await db.execute("SELECT path FROM workspaces WHERE id = ?", (workspace_id,))
            ws = await cur.fetchone()
            if ws:
                workspace_path = ws["path"]
                
        cli_home = _session_transcript_home(sess_dict)
        if not native_sid and workspace_path and cli_type == "codex":
            # Detection may have given up before Codex wrote its lazy rollout.
            native_sid = await _self_heal_codex_native_session(sess_dict, workspace_path)
        if native_sid and workspace_path:
            transcript_file = _get_native_transcript_path(
                cli_type,
                workspace_path,
                native_sid,
                cli_home=cli_home,
            )
            if transcript_file and transcript_file.exists():
                # Cached, incremental, off the event loop (see transcript_cache).
                response = await _transcript_messages_response(request, transcript_file, session_id)
                if response is not None:
                    return response

        cur = await db.execute(
            "SELECT * FROM messages WHERE session_id = ? ORDER BY created_at",
            (session_id,),
        )
        rows = await cur.fetchall()
        formatted_rows = []
        for idx, row in enumerate(rows):
            item = dict(row)
            if _is_ive_managed_context_message(item.get("role", ""), item.get("content", ""), idx):
                continue
            item["content"] = _enrich_task_notification_content(item.get("content", ""))
            formatted_rows.append(item)
        return web.json_response(formatted_rows)
    finally:
        await db.close()



# ─── REST: Cost & Tokens (REAL metrics parsed from transcripts) ───────────

def _extract_message_model(msg: dict):
    """Best-effort model id from a transcript message (claude/codex/gemini shapes)."""
    if not isinstance(msg, dict):
        return None
    inner = msg.get("message") if isinstance(msg.get("message"), dict) else {}
    for cand in (msg.get("model"), inner.get("model"), msg.get("modelId"), inner.get("modelId")):
        if isinstance(cand, str) and cand and cand.lower() != "<synthetic>":
            return cand
    return None


_COST_KEYS = ("input_tokens", "output_tokens", "cache_write_tokens", "cache_read_tokens", "cost_usd", "messages")


def _blank_cost():
    return {k: (0.0 if k == "cost_usd" else 0) for k in _COST_KEYS}


def _read_cost_transcript(cli: str, workspace_path: str, native_sid: str, cli_home):
    """Resolve, open, and parse one transcript entirely off the event loop."""
    transcript = _get_native_transcript_path(
        cli,
        workspace_path,
        native_sid,
        cli_home=cli_home,
    )
    if not transcript or not _Path(str(transcript)).exists():
        return None
    return read_session_messages(str(transcript))


async def _aggregate_cost_metrics(db, *, workspace_id=None, since=None, until=None, persist=True) -> dict:
    """Walk every session's REAL transcript and aggregate exact tokens + cost.

    Cost = real tokens (from each CLI's own transcript) × published per-model rates
    (model_pricing.py). Returns grand totals + breakdowns per CLI, per model, per session.
    When persist is set, the real per-session cost is written back into sessions.total_cost_usd,
    replacing the old inferred value.
    """
    import model_pricing

    q = "SELECT * FROM sessions"
    conds, args = [], []
    if workspace_id:
        conds.append("workspace_id = ?"); args.append(workspace_id)
    if since:
        conds.append("created_at >= ?"); args.append(since)
    if until:
        conds.append("created_at <= ?"); args.append(until)
    if conds:
        q += " WHERE " + " AND ".join(conds)
    cur = await db.execute(q, args)
    sessions = [dict(r) for r in await cur.fetchall()]
    cur = await db.execute("SELECT id, path FROM workspaces")
    ws_path = {r["id"]: r["path"] for r in await cur.fetchall()}

    per_session, per_cli, per_model = [], {}, {}
    totals = _blank_cost()
    estimated: set[str] = set()
    dirty = False

    for sess in sessions:
        cli = sess.get("cli_type") or "claude"
        native_sid = sess.get("native_session_id")
        wpath = ws_path.get(sess.get("workspace_id"))
        if not native_sid or not wpath:
            continue
        try:
            cli_home = _session_transcript_home(sess)
            messages = await asyncio.to_thread(
                _read_cost_transcript,
                cli,
                wpath,
                native_sid,
                cli_home,
            )
            if messages is None:
                continue
        except Exception:
            continue

        by_model: dict[str, dict] = {}
        for msg in messages:
            m = _extract_cli_message_metrics(msg)
            it = m.get("input_tokens") or 0
            ot = m.get("output_tokens") or 0
            cw = m.get("cache_creation_tokens") or 0
            cr = m.get("cache_read_tokens") or 0
            if not (it or ot or cw or cr):
                continue
            model = _extract_message_model(msg) or f"{cli}:unknown"
            b = by_model.setdefault(model, _blank_cost())
            b["input_tokens"] += it
            b["output_tokens"] += ot
            b["cache_write_tokens"] += cw
            b["cache_read_tokens"] += cr
            b["messages"] += 1

        sess_total = _blank_cost()
        for model, b in by_model.items():
            b["cost_usd"] = model_pricing.cost_usd(
                model,
                input_tokens=b["input_tokens"], output_tokens=b["output_tokens"],
                cache_write_tokens=b["cache_write_tokens"], cache_read_tokens=b["cache_read_tokens"],
            )
            if model_pricing.is_estimated(model):
                estimated.add(model)
            pm = per_model.setdefault(model, _blank_cost())
            for k in _COST_KEYS:
                pm[k] += b[k]
                sess_total[k] += b[k]

        if sess_total["messages"] == 0:
            continue
        pc = per_cli.setdefault(cli, _blank_cost())
        for k in _COST_KEYS:
            pc[k] += sess_total[k]
            totals[k] += sess_total[k]
        per_session.append({
            "session_id": sess["id"], "name": sess.get("name"), "cli": cli,
            "workspace_id": sess.get("workspace_id"),
            "models": sorted(by_model.keys()),
            **sess_total,
        })
        if persist:
            try:
                await db.execute(
                    "UPDATE sessions SET total_cost_usd = ? WHERE id = ?",
                    (round(sess_total["cost_usd"], 6), sess["id"]),
                )
                dirty = True
            except Exception:
                pass

    if persist and dirty:
        try:
            await db.commit()
        except Exception:
            pass

    per_session.sort(key=lambda s: s["cost_usd"], reverse=True)
    return {
        "totals": totals,
        "per_cli": [{"cli": k, **v} for k, v in sorted(per_cli.items(), key=lambda kv: -kv[1]["cost_usd"])],
        "per_model": [{"model": k, **v} for k, v in sorted(per_model.items(), key=lambda kv: -kv[1]["cost_usd"])],
        "per_session": per_session,
        "estimated_models": sorted(estimated),
        "session_count": len(per_session),
    }


async def cost_metrics_handler(request: web.Request) -> web.Response:
    """GET /api/cost — real token usage + cost across all sessions, per CLI + per model.

    Query: workspace_id, since, until (ISO), persist=0 to skip writing back total_cost_usd.
    """
    db = await get_db()
    try:
        result = await _aggregate_cost_metrics(
            db,
            workspace_id=request.query.get("workspace_id"),
            since=request.query.get("since"),
            until=request.query.get("until"),
            persist=(request.query.get("persist", "1") != "0"),
        )
        return web.json_response(result)
    finally:
        await db.close()


