def _format_conversation_for_distill(messages: list[dict], max_chars: int = 80_000) -> str:
    """Format session messages into a compact transcript for the distill prompt."""
    lines = []
    for idx, msg in enumerate(messages):
        # Handle both DB rows and JSONL entries
        normalized = normalize_jsonl_entry(msg)
        if normalized is None:
            continue
        role, content = normalized
        if _is_ive_managed_context_message(role, content, idx):
            continue

        # Parse list-shaped content from DB rows
        if isinstance(content, str) and content.startswith("["):
            try:
                parsed = json.loads(content)
                if isinstance(parsed, list):
                    content = parsed
            except json.JSONDecodeError:
                pass

        # Extract just the text parts (skip tool calls/results for brevity)
        if isinstance(content, list):
            text_parts = []
            for block in content:
                if isinstance(block, dict) and block.get("type") == "text":
                    text_parts.append(block.get("text", ""))
                elif isinstance(block, str):
                    text_parts.append(block)
            content = "\n".join(text_parts)

        if not content or not content.strip():
            continue

        label = "User" if role in ("human", "user") else "Assistant"
        lines.append(f"**{label}:**\n{content.strip()}\n")

    transcript = "\n".join(lines)
    # Truncate from the middle if too long, keeping first and last parts
    if len(transcript) > max_chars:
        half = max_chars // 2
        transcript = (
            transcript[:half]
            + "\n\n[... conversation truncated for brevity ...]\n\n"
            + transcript[-half:]
        )
    return transcript


async def _session_conversation_text(session_id: str, max_chars: int = 40_000) -> str:
    """Return adapter-normalized conversation text for a session, if available."""
    messages: list[dict] = []
    db = await get_db()
    try:
        cur = await db.execute(
            """SELECT s.*, w.path AS workspace_path
               FROM sessions s
               LEFT JOIN workspaces w ON s.workspace_id = w.id
               WHERE s.id = ?""",
            (session_id,),
        )
        sess = await cur.fetchone()
        if not sess:
            return ""

        sess = dict(sess)
        native_sid = sess.get("native_session_id")
        workspace_path = sess.get("workspace_path")
        if native_sid and workspace_path:
            transcript_file = _get_native_transcript_path(
                sess.get("cli_type"),
                workspace_path,
                native_sid,
                cli_home=_session_transcript_home(sess),
            )
            if transcript_file and transcript_file.exists():
                try:
                    messages = read_session_messages(str(transcript_file))
                except Exception as e:
                    logger.debug("Could not read native transcript for handoff: %s", e)

        if not messages:
            cur = await db.execute(
                "SELECT * FROM messages WHERE session_id = ? ORDER BY created_at",
                (session_id,),
            )
            rows = await cur.fetchall()
            messages = [dict(r) for r in rows]
    finally:
        await db.close()

    if not messages:
        return ""
    return _format_conversation_for_distill(messages, max_chars=max_chars)


_background_jobs: dict[str, dict] = {}


async def _run_background_llm_job(
    job_id: str, job_type: str, model_id: str,
    prompt: str, extra: dict, timeout: int = 180,
    automatic_receipt=None,
):
    """Run an LLM call in the background and broadcast the result via WebSocket."""
    from llm_router import call_json

    job = _background_jobs.get(job_id)
    if not job:
        if automatic_receipt:
            import background_ai
            await background_ai.finish(automatic_receipt, success=False)
        return

    job["status"] = "running"
    provider_completed = False
    try:
        result = await call_json(
            model_id, prompt, timeout_s=min(timeout, 90) if automatic_receipt else timeout,
            allow_fallback=False,
            **({"reasoning_effort": "low"} if automatic_receipt else {}),
        )
        provider_completed = True
        job["status"] = "done"
        job["result"] = result
        await broadcast({
            "type": f"{job_type}_done",
            "job_id": job_id,
            "result": result,
            **extra,
        })
    except Exception as e:
        job["status"] = "error"
        job["error"] = str(e)
        await broadcast({
            "type": f"{job_type}_error",
            "job_id": job_id,
            "error": str(e),
            **extra,
        })
    finally:
        if automatic_receipt:
            import background_ai
            await background_ai.finish(automatic_receipt, success=provider_completed)


async def summarize_session(request: web.Request) -> web.Response:
    """Generate or regenerate a short session summary on demand."""
    session_id = request.match_info["id"]
    db = await get_db()
    try:
        cur = await db.execute(
            """SELECT s.*, w.path AS workspace_path, w.orchestration_policy, w.inherit_orchestration_policy_from
               FROM sessions s
               LEFT JOIN workspaces w ON s.workspace_id = w.id
               WHERE s.id = ?""",
            (session_id,),
        )
        sess = await cur.fetchone()
        if not sess:
            return web.json_response({"error": "session not found"}, status=404)
        sess = dict(sess)
        if sess.get("inherit_orchestration_policy_from"):
            from db import resolve_workspace_orchestration_policy
            sess["orchestration_policy"] = await resolve_workspace_orchestration_policy(db, sess["workspace_id"])

        # Fetch conversation messages (JSONL first, then DB, then terminal buffer)
        messages = []
        native_sid = sess.get("native_session_id")
        workspace_path = sess.get("workspace_path")
        if native_sid and workspace_path:
            transcript_file = _get_native_transcript_path(
                sess.get("cli_type"),
                workspace_path,
                native_sid,
                cli_home=_session_transcript_home(sess),
            )
            if transcript_file and transcript_file.exists():
                messages = read_session_messages(str(transcript_file))

        if not messages:
            cur2 = await db.execute(
                "SELECT * FROM messages WHERE session_id = ? ORDER BY created_at",
                (session_id,),
            )
            rows = await cur2.fetchall()
            messages = [dict(r) for r in rows]

        if messages:
            conversation = _format_conversation_for_distill(messages, max_chars=20_000)
        else:
            conversation = capture_proc.get_buffer(session_id, 200)

        if not conversation or len(conversation.strip()) < 50:
            return web.json_response({"error": "not enough content to summarize"}, status=400)

        # Fetch session digest for extra context
        digest_context = ""
        try:
            cur3 = await db.execute(
                "SELECT task_summary, discoveries, decisions FROM session_digests WHERE session_id = ?",
                (session_id,),
            )
            digest = await cur3.fetchone()
            if digest:
                parts = []
                if digest["task_summary"]:
                    parts.append(f"Task: {digest['task_summary']}")
                if digest["discoveries"] and digest["discoveries"] != "[]":
                    parts.append(f"Discoveries: {digest['discoveries']}")
                if parts:
                    digest_context = "\n\nWorker digest:\n" + "\n".join(parts)
        except Exception:
            pass

        from orchestration_policy import role_model
        policy_cli, policy_model = role_model(sess.get("orchestration_policy"), "summary")
        cli = policy_cli or sess.get("cli_type") or "claude"
        model = policy_model or None
    finally:
        await db.close()

    from llm_router import call_json, model_id_for_provider
    model_id = await model_id_for_provider(cli, model)
    summary_result = await call_json(
        model_id=model_id,
        prompt=(
            "Summarize this coding session in 1-2 concise sentences. "
            "Focus on what was accomplished or attempted. Be specific about the task, not generic.\n\n"
            f"Session transcript:\n{conversation}{digest_context}"
        ),
        system=(
            "You are a concise summarizer. Return exactly one JSON object "
            'with a string field named summary: {"summary":"..."}.'
        ),
        timeout_s=30,
        allow_fallback=False,
    )
    summary = str(summary_result.get("summary") or "").strip()

    db2 = await get_db()
    try:
        await db2.execute(
            "UPDATE sessions SET summary = ? WHERE id = ?",
            (summary, session_id),
        )
        await db2.commit()
    finally:
        await db2.close()

    await broadcast({
        "type": "session_summary",
        "session_id": session_id,
        "summary": summary,
    })

    return web.json_response({"summary": summary})


async def distill_session(request: web.Request) -> web.Response:
    """Launch a background job to extract a reusable artifact from a session."""
    session_id = request.match_info["id"]
    body = await request.json()

    artifact_type = (body.get("type") or "").strip().lower()
    if artifact_type not in _DISTILL_PROMPTS:
        return web.json_response(
            {"error": f"type must be one of: {', '.join(_DISTILL_PROMPTS.keys())}"},
            status=400,
        )

    if "cli" in body:
        return web.json_response(
            {
                "error": "use one provider-qualified model id; the separate cli field was removed",
                "code": "legacy_model_shape",
            },
            status=400,
        )
    model_id = body.get("model") or "claude:sonnet"
    from llm_router import resolve_model
    from model_providers import ModelProviderError
    try:
        await resolve_model(model_id, required_capability="json")
    except ModelProviderError as exc:
        return web.json_response(
            {"error": str(exc), "code": exc.code, "field": "model"},
            status=400,
        )
    instructions = (body.get("instructions") or "").strip()

    # ── Fetch full conversation content ─────────────────────────────
    # Priority: 1) JSONL file (full structured history)
    #           2) DB messages (imported sessions)
    #           3) Terminal buffer (fallback — partial, last ~64KB)
    conversation = None
    messages = []

    db = await get_db()
    try:
        cur2 = await db.execute(
            """SELECT s.native_session_id, s.cli_type, s.account_id,
                      s.cli_runtime_home, s.workspace_id,
                      w.path AS workspace_path
               FROM sessions s
               LEFT JOIN workspaces w ON s.workspace_id = w.id
               WHERE s.id = ?""",
            (session_id,),
        )
        sess_row = await cur2.fetchone()

        # 1) Try JSONL — full conversation history for live/exited sessions
        ws_id = None
        if sess_row:
            native_sid = sess_row["native_session_id"]
            workspace_path = sess_row["workspace_path"]
            ws_id = sess_row["workspace_id"]
            cli_home = _session_transcript_home(dict(sess_row))
            if native_sid and workspace_path:
                transcript_file = _get_native_transcript_path(
                    sess_row["cli_type"],
                    workspace_path,
                    native_sid,
                    cli_home=cli_home,
                )
                if transcript_file and transcript_file.exists():
                    messages = read_session_messages(str(transcript_file))

            # If native_session_id wasn't detected yet, scan for most recent.
            # Only do this for live/recently-exited sessions where the hook
            # hasn't populated native_session_id yet — NOT for sessions that
            # never had a PTY (e.g. test/seeded sessions), because the scan
            # would grab a random recent JSONL from the workspace.
            if not messages and workspace_path and native_sid:
                project_dir = _get_native_transcript_dir(sess_row["cli_type"], workspace_path, cli_home=cli_home)
                if project_dir.exists():
                    cli_type = sess_row["cli_type"] or "claude"
                    glob_pat = get_profile(cli_type).session_file_pattern
                    if cli_type == "codex":
                        glob_pat = f"**/{glob_pat}"
                    candidates = sorted(
                        project_dir.glob(glob_pat),
                        key=lambda p: p.stat().st_mtime,
                        reverse=True,
                    )
                    for candidate in candidates[:3]:
                        try:
                            msgs = read_session_messages(str(candidate))
                            if msgs:
                                messages = msgs
                                break
                        except Exception:
                            continue

        # 2) Try DB messages (populated for imported sessions)
        if not messages:
            cur = await db.execute(
                "SELECT * FROM messages WHERE session_id = ? ORDER BY created_at",
                (session_id,),
            )
            rows = await cur.fetchall()
            messages = [dict(r) for r in rows]

        if messages:
            conversation = _format_conversation_for_distill(messages)

        # 3) Terminal buffer fallback — partial but better than nothing
        if not conversation:
            terminal_text = capture_proc.get_buffer(session_id, 2000)
            if terminal_text and len(terminal_text.strip()) > 50:
                conversation = terminal_text.strip()

        # Grab session name
        cur3 = await db.execute("SELECT name FROM sessions WHERE id = ?", (session_id,))
        name_row = await cur3.fetchone()
        session_name = name_row["name"] if name_row else session_id[:8]
    finally:
        await db.close()

    if not conversation:
        return web.json_response(
            {"error": "No conversation content found for this session."},
            status=404,
        )

    # Resolve workspace output style for distill formatting
    from output_styles import resolve_output_style, OUTPUT_STYLES
    _ws_os, _gl_os = None, None
    _sdb = await get_db()
    try:
        if ws_id:
            _c = await _sdb.execute("SELECT output_style FROM workspaces WHERE id = ?", (ws_id,))
            _r = await _c.fetchone()
            _ws_os = _r["output_style"] if _r else None
        _c = await _sdb.execute("SELECT value FROM app_settings WHERE key = 'output_style'")
        _r = await _c.fetchone()
        _gl_os = _r["value"] if _r else None
    except Exception:
        pass
    finally:
        await _sdb.close()
    _eff_style = resolve_output_style(None, _ws_os, _gl_os)
    _style_hint = ""
    if _eff_style != "default":
        _desc = OUTPUT_STYLES.get(_eff_style, {}).get("description", "")
        _style_hint = (
            f"\nOutput style: {_eff_style} ({_desc}). "
            "Apply to generated content — signal over noise. JSON structure unchanged.\n"
        )
    _iparts = []
    if instructions:
        _iparts.append(f"Additional instructions from the user:\n{instructions}")
    if _style_hint:
        _iparts.append(_style_hint)
    instructions_block = "\n".join(_iparts)

    # Build the distill prompt
    prompt_template = _DISTILL_PROMPTS[artifact_type]
    prompt = prompt_template.format(
        conversation=conversation,
        instructions=instructions_block,
    )

    # Launch background job
    job_id = str(uuid.uuid4())
    _background_jobs[job_id] = {
        "type": "distill",
        "status": "queued",
        "session_id": session_id,
        "artifact_type": artifact_type,
    }

    import asyncio as _asyncio
    _asyncio.ensure_future(_run_background_llm_job(
        job_id=job_id,
        job_type="distill",
        model_id=model_id,
        prompt=prompt,
        extra={
            "session_id": session_id,
            "session_name": session_name,
            "artifact_type": artifact_type,
        },
    ))

    return web.json_response({
        "job_id": job_id,
        "status": "started",
        "artifact_type": artifact_type,
    })


# ─── REST: Search ─────────────────────────────────────────────────────────

async def search_messages(request: web.Request) -> web.Response:
    q = request.query.get("q", "").strip()
    if not q:
        return web.json_response([])

    db = await get_db()
    try:
        cur = await db.execute(
            """SELECT m.*, s.name AS session_name, s.workspace_id
               FROM messages m
               JOIN sessions s ON m.session_id = s.id
               WHERE m.content LIKE ?
               ORDER BY m.created_at DESC
               LIMIT 100""",
            (f"%{q}%",),
        )
        rows = await cur.fetchall()
        return web.json_response([dict(r) for r in rows])
    finally:
        await db.close()


# ─── REST: Clone ──────────────────────────────────────────────────────────

async def _prepare_session_handoff(session_id: str) -> dict:
    """Persist exact evidence locally; only a small file reference enters context."""
    from session_handoff import write_handoff
    from config import DATA_DIR
    session = await get_session_config(session_id)
    if not session:
        raise ValueError("session not found")
    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM messages WHERE session_id = ? ORDER BY created_at, id", (session_id,))
        stored = [dict(row) for row in await cur.fetchall()]
        cur = await db.execute("SELECT * FROM session_digests WHERE session_id = ?", (session_id,))
        row = await cur.fetchone()
        digest = dict(row) if row else {}
    finally:
        await db.close()
    messages = stored
    native_id = session.get("native_session_id")
    if native_id:
        path = _get_native_transcript_path(
            session.get("cli_type"), session.get("workspace_path"), native_id,
            cli_home=_session_transcript_home(session),
        )
        if path and path.exists():
            native = await asyncio.to_thread(read_session_messages, str(path))
            if native:
                messages = native
    return await asyncio.to_thread(write_handoff, DATA_DIR / "handoffs", session, messages, digest, stored)


async def clone_session(request: web.Request) -> web.Response:
    source_id = request.match_info["id"]
    body = {}
    try:
        body = await request.json()
    except Exception:
        pass
    if not isinstance(body, dict):
        return web.json_response({"error": "Expected an object"}, status=400)
    context_mode = body.get("context_mode", "clone")
    if not isinstance(context_mode, str) or context_mode not in {"clone", "handoff", "empty"}:
        return web.json_response({"error": "Invalid context mode"}, status=400)

    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (source_id,))
        source = await cur.fetchone()
        if not source:
            return web.json_response({"error": "session not found"}, status=404)

        source = dict(source)
        if not _session_visible_to_request(source, request):
            return web.json_response({"error": "session not found"}, status=404)
        if context_mode != "clone" and source.get("read_only"):
            return web.json_response({"error": "This session is read-only"}, status=403)
        if context_mode == "handoff":
            from hooks import get_session_logical_status
            alive = pty_mgr.is_alive(source_id)
            if alive and get_session_logical_status(source_id, alive, source.get("status", "idle")) not in {"idle", "stopped", "done"}:
                return web.json_response({"error": "Wait until the session is idle before continuing in a new session."}, status=409)
            if source.get("worktree"):
                return web.json_response({"error": "Continue in this worktree session so uncommitted files stay available. A new topic can start separately."}, status=409)
        new_id = str(uuid.uuid4())

        # Support cross-CLI cloning when the requested target CLI is active.
        target_cli = body.get("cli_type", source.get("cli_type", "claude"))
        if not is_active_cli(target_cli):
            return _inactive_cli_response(target_cli)
        source_cli = source.get("cli_type", "claude")
        is_cross_cli = target_cli != source_cli

        # Translate model/mode defaults if switching CLI
        if is_cross_cli:
            target_profile = get_profile(target_cli)
            requested_model = body.get("model")
            if requested_model in (None, ""):
                requested_model = _profile_default_model_for_role(target_profile, source.get("session_type"))
            new_model = _model_for_storage(target_profile, requested_model, source.get("session_type"))
            new_mode = body.get("permission_mode", target_profile.default_permission_mode)
            _mode_err = _permission_mode_error(target_profile, new_mode)
            if _mode_err is not None:
                return _mode_err
            new_effort = _effort_for_storage(target_profile, body.get("effort"))
        else:
            target_profile = get_profile(target_cli)
            new_model = _model_for_storage(
                target_profile,
                body.get("model", source["model"]),
                source.get("session_type"),
            )
            new_mode = body.get("permission_mode", source["permission_mode"])
            if "permission_mode" in body:
                _mode_err = _permission_mode_error(target_profile, new_mode)
                if _mode_err is not None:
                    return _mode_err
            new_effort = body.get("effort", source["effort"])

        try:
            handoff = await _prepare_session_handoff(source_id) if context_mode == "handoff" else None
        except Exception as exc:
            logger.warning("Could not save handoff for %s: %s", source_id[:8], exc)
            return web.json_response({"error": "Could not save the handoff; the original session was kept."}, status=500)
        new_prompt = handoff["prompt"] if handoff else (None if context_mode == "empty" else source["system_prompt"])
        new_name = "New topic" if context_mode == "empty" else f"{source['name']} ({'continued' if handoff else 'clone'})"
        from session_worktree import resolve_worktree
        cloned_worktree = resolve_worktree(target_cli, default=source.get("worktree", False))
        await db.execute(
            """INSERT INTO sessions (id, workspace_id, name, model, permission_mode, effort,
               budget_usd, system_prompt, allowed_tools, disallowed_tools, add_dirs,
               agent, worktree, mcp_config, cli_type, scratchpad, session_type, output_style, account_id)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (new_id, source["workspace_id"], new_name, new_model,
             new_mode, new_effort, source["budget_usd"],
             new_prompt, source["allowed_tools"], source["disallowed_tools"],
             source["add_dirs"], source["agent"], cloned_worktree, source["mcp_config"],
             target_cli, source.get("scratchpad") if context_mode == "clone" else None, source.get("session_type", "worker"),
             source.get("output_style"), source.get("account_id") if not is_cross_cli else None),
        )

        # If cross-CLI clone, sync memory so the target CLI's file is up to date
        if is_cross_cli and source.get("workspace_id"):
            try:
                from memory_sync import sync_manager
                ws_path, _ = await _get_workspace_path_or_error(source["workspace_id"])
                if ws_path:
                    await sync_manager.sync(source["workspace_id"], ws_path)
            except Exception as exc:
                logger.warning("Memory sync during cross-CLI clone failed: %s", exc)

        # Copy guidelines
        cur = await db.execute(
            "SELECT guideline_id FROM session_guidelines WHERE session_id = ?",
            (source_id,),
        )
        for row in await cur.fetchall():
            await db.execute(
                "INSERT INTO session_guidelines (session_id, guideline_id) VALUES (?, ?)",
                (new_id, row["guideline_id"]),
            )

        # Copy MCP servers
        cur = await db.execute(
            "SELECT mcp_server_id, auto_approve_override FROM session_mcp_servers WHERE session_id = ?",
            (source_id,),
        )
        for row in await cur.fetchall():
            await db.execute(
                "INSERT INTO session_mcp_servers (session_id, mcp_server_id, auto_approve_override) VALUES (?, ?, ?)",
                (new_id, row["mcp_server_id"], row["auto_approve_override"]),
            )

        await db.commit()
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (new_id,))
        row = await cur.fetchone()
        result = dict(row)
        if handoff:
            result["handoff"] = {key: value for key, value in handoff.items() if key != "prompt"}
        return web.json_response(result, status=201)
    finally:
        await db.close()


# ─── REST: Merge Sessions ───────────────────────────────────────────────

async def merge_sessions(request: web.Request) -> web.Response:
    """Merge multiple sessions into one.

    Accepts { source_ids: [...], target_id: null | uuid, workspace_id: uuid }.
    Fetches messages/transcripts from each source, builds a combined context
    string, optionally creates a new session, and returns the target session
    plus the context text (the frontend sends it as PTY input).
    """
    body = await request.json()
    source_ids = body.get("source_ids", [])
    target_id = body.get("target_id")
    workspace_id = body.get("workspace_id")

    if len(source_ids) < 2:
        return web.json_response({"error": "need at least 2 source sessions"}, status=400)
    if not workspace_id:
        return web.json_response({"error": "workspace_id required"}, status=400)

    db = await get_db()
    try:
        # Validate all source sessions exist and belong to the workspace
        placeholders = ",".join("?" for _ in source_ids)
        cur = await db.execute(
            f"SELECT * FROM sessions WHERE id IN ({placeholders})", source_ids
        )
        sources = [dict(r) for r in await cur.fetchall()]
        if len(sources) != len(source_ids):
            return web.json_response({"error": "one or more sessions not found"}, status=404)
        for s in sources:
            if s["workspace_id"] != workspace_id:
                return web.json_response(
                    {"error": f"session {s['id'][:8]} belongs to a different workspace"},
                    status=400,
                )

        # Build ordered list matching source_ids order
        source_map = {s["id"]: s for s in sources}
        ordered = [source_map[sid] for sid in source_ids]

        # Gather messages / transcripts for each source
        context_parts = []
        for src in ordered:
            # Try DB messages first
            cur = await db.execute(
                "SELECT * FROM messages WHERE session_id = ? ORDER BY created_at",
                (src["id"],),
            )
            messages = [dict(r) for r in await cur.fetchall()]

            # Fall back to JSONL transcript if no DB messages
            if not messages and src.get("native_session_id"):
                cur2 = await db.execute(
                    "SELECT path FROM workspaces WHERE id = ?",
                    (src["workspace_id"],),
                )
                ws_row = await cur2.fetchone()
                if ws_row:
                    transcript_file = _get_native_transcript_path(
                        src.get("cli_type"),
                        ws_row["path"],
                        src["native_session_id"],
                        cli_home=_session_transcript_home(src),
                    )
                    if transcript_file and transcript_file.exists():
                        messages = read_session_messages(str(transcript_file))

            md = export_session_as_markdown(messages) if messages else "(no messages)"
            context_parts.append(
                f"## Session: {src['name']}\n"
                f"Model: {src.get('model', 'unknown')} | "
                f"Turns: {src.get('turn_count', 0)} | "
                f"Cost: ${src.get('total_cost_usd', 0):.4f}\n\n"
                f"{md}"
            )

        # Include workspace memory + auto-memory for richer merge context
        memory_section = ""
        try:
            from memory_sync import sync_manager
            cur_ws = await db.execute(
                "SELECT path FROM workspaces WHERE id = ?", (workspace_id,),
            )
            ws_row = await cur_ws.fetchone()
            if ws_row:
                ws_path = ws_row["path"]
                central = await sync_manager.read_central(workspace_id)
                auto = await sync_manager.read_all_auto_memory(ws_path, workspace_id=workspace_id)

                mem_parts = []
                if central:
                    mem_parts.append(f"## Project Memory\n{central[:4000]}")
                if auto:
                    lines = []
                    for cli, entries in auto.items():
                        for e in entries[:10]:
                            body_text = e.get("content", "")
                            if body_text:
                                lines.append(
                                    f"- **[{e.get('type','')}] {e.get('name','')}**: "
                                    f"{body_text[:200]}"
                                )
                    if lines:
                        mem_parts.append(
                            "## Remembered Context\n" + "\n".join(lines)
                        )
                if mem_parts:
                    memory_section = "\n\n".join(mem_parts) + "\n\n---\n\n"
        except Exception as exc:
            logger.debug("Failed to load memory for merge: %s", exc)

        session_names = ", ".join(f'"{s["name"]}"' for s in ordered)
        context = (
            f"Multiple sessions are being merged into this one ({session_names}). "
            "Below is the project memory and conversation history from each session.\n\n"
            "Please:\n"
            "1. Read through all the merged session content carefully\n"
            "2. Summarize the key findings, decisions, and progress from each session\n"
            "3. Save any important context to your memory so it persists\n"
            "4. Identify any open tasks, unresolved issues, or next steps\n"
            "5. Let me know what you've absorbed and what you're ready to continue working on\n\n"
            + memory_section
            + "\n\n---\n\n".join(context_parts)
        )

        # Create or validate target session
        if target_id:
            cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (target_id,))
            target = await cur.fetchone()
            if not target:
                return web.json_response({"error": "target session not found"}, status=404)
            target = dict(target)
        else:
            # Create a new session with merged name
            new_id = str(uuid.uuid4())
            merged_names = " + ".join(s["name"] for s in ordered[:3])
            if len(ordered) > 3:
                merged_names += f" +{len(ordered) - 3} more"
            new_name = f"Merged: {merged_names}"

            # Use config from the first source session
            first = ordered[0]
            await db.execute(
                """INSERT INTO sessions (id, workspace_id, name, model, permission_mode,
                   effort, system_prompt, account_id, cli_type)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (new_id, workspace_id, new_name,
                 _model_for_storage(
                     get_profile(first.get("cli_type", "claude")),
                     first.get("model"),
                     first.get("session_type"),
                 ),
                 first.get("permission_mode", "auto"), first.get("effort") or None,
                 first.get("system_prompt"), first.get("account_id"),
                 first.get("cli_type", "claude")),
            )

            # Merge guidelines from all sources (union, skip deleted)
            cur = await db.execute(
                f"""SELECT DISTINCT sg.guideline_id FROM session_guidelines sg
                    JOIN guidelines g ON g.id = sg.guideline_id
                    WHERE sg.session_id IN ({placeholders})""",
                source_ids,
            )
            for row in await cur.fetchall():
                await db.execute(
                    "INSERT OR IGNORE INTO session_guidelines (session_id, guideline_id) VALUES (?, ?)",
                    (new_id, row["guideline_id"]),
                )

            # Merge MCP servers from all sources (union, skip deleted)
            cur = await db.execute(
                f"""SELECT DISTINCT sm.mcp_server_id FROM session_mcp_servers sm
                    JOIN mcp_servers m ON m.id = sm.mcp_server_id
                    WHERE sm.session_id IN ({placeholders})""",
                source_ids,
            )
            for row in await cur.fetchall():
                await db.execute(
                    "INSERT OR IGNORE INTO session_mcp_servers (session_id, mcp_server_id) VALUES (?, ?)",
                    (new_id, row["mcp_server_id"]),
                )

            await db.commit()
            cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (new_id,))
            target = dict(await cur.fetchone())

        return web.json_response({"session": target, "context": context}, status=201)
    finally:
        await db.close()


# ─── REST: Session Management ────────────────────────────────────────────

async def get_provider_limits(request: web.Request) -> web.Response:
    ctx = get_auth(request)
    if not ctx or ctx.actor_kind not in {"localhost", "owner_legacy", "owner_device"}:
        return web.json_response({"error": "Account limits are only available to the owner."}, status=403)
    from provider_limits import limits_for_session
    session_id = request.query.get("session_id")
    session = {"cli_type": "codex"}
    account = None
    db = await get_db()
    try:
        if session_id:
            cur = await db.execute("SELECT id, cli_type, account_id FROM sessions WHERE id = ?", (session_id,))
            row = await cur.fetchone()
            if not row:
                return web.json_response({"error": "Session not found"}, status=404)
            session = dict(row)
            if session.get("account_id"):
                cur = await db.execute("SELECT id, name, type, cli_type, credentials_verified_at FROM accounts WHERE id = ?", (session["account_id"],))
                row = await cur.fetchone()
                account = dict(row) if row else None
    finally:
        await db.close()
    return web.json_response(await limits_for_session(session, account))


async def rename_session(request: web.Request) -> web.Response:
    session_id = request.match_info["id"]
    body = await request.json()
    name = body.get("name", "").strip()
    if not name:
        return web.json_response({"error": "name required"}, status=400)

    db = await get_db()
    try:
        cur = await db.execute("UPDATE sessions SET name = ? WHERE id = ?", (name, session_id))
        await db.commit()
        if cur.rowcount == 0:
            return web.json_response({"error": "session not found"}, status=404)
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "session not found"}, status=404)
        # Live status, pty_alive and quick like the list endpoint: the raw row
        # keeps a stale persisted status ("running") that the sidebar would
        # otherwise show as Working until the next reload.
        return web.json_response(_decorate_session_dict(dict(row)))
    finally:
        await db.close()


async def get_session_permission_mode(request: web.Request) -> web.Response:
    """Lightweight read used by the AVCP hook.

    The AVCP claude-code.sh hook calls this to decide whether a package
    install should be force-denied (the session is in plan mode). Returning
    only the one field keeps the hook's cold-path cost negligible.
    """
    session_id = request.match_info["id"]
    db = await get_db()
    try:
        row = await (await db.execute(
            "SELECT permission_mode, cli_type FROM sessions WHERE id = ?",
            (session_id,),
        )).fetchone()
        if not row:
            return web.json_response({"error": "session not found"}, status=404)
        from permission_mode_live import effective_permission_mode
        return web.json_response({
            "permission_mode": effective_permission_mode(session_id, row["permission_mode"]),
            "cli_type": row["cli_type"] or "claude",
        })
    finally:
        await db.close()


async def avcp_event_handler(request: web.Request) -> web.Response:
    """Forward an AVCP decision into the IVE event bus.

    Lets the supply-chain gate and the IVE activity feed tell one story:
    blocked/warned package installs show up alongside session events
    instead of only in the hook's stderr.
    """
    try:
        body = await request.json()
    except Exception:
        body = {}
    payload = {
        "session_id": body.get("session_id"),
        "decision":   body.get("decision"),     # allow | warn | block
        "command":    body.get("command"),
        "reason":     body.get("reason"),
        "tool":       body.get("tool"),
        "forced_by_plan_mode": bool(body.get("forced_by_plan_mode")),
    }
    try:
        await bus.emit(
            CommanderEvent.AVCP_DECISION,
            payload=payload,
            source="avcp",
            actor="hook",
        )
    except Exception as e:
        logger.debug("AVCP_DECISION emit failed: %s", e)
    return web.json_response({"ok": True})


# ── Live launch-setting apply (permission mode, model, effort) ──────────
# The Perms menu and the model/effort pickers write the session row;
# permission_mode_live brings the running CLI in line by restarting it
# through the supervisor (same path as an account switch), which resumes the
# native conversation with the new flags. Busy sessions are applied once idle.
_permission_live_applier = None
# session_id -> time.time() of the last live model/effort relaunch; the
# runtime-model endpoint ignores transcript turns older than that.
_launch_applied_at: dict[str, float] = {}

_LIVE_LAUNCH_FEATURES = {
    "permission_mode": "PERMISSION_MODE",
    "model": "MODEL",
    "effort": "EFFORT",
}


def _cli_supports_live_launch_field(cli_type: str, field_name: str) -> bool:
    try:
        feature = getattr(Feature, _LIVE_LAUNCH_FEATURES[field_name])
        binding = get_profile(cli_type or "claude").binding(feature)
    except Exception:
        return False
    if not binding or not binding.build or binding.supported is False:
        return False
    if field_name == "effort":
        try:
            return bool(get_profile(cli_type or "claude").effort_levels)
        except Exception:
            return False
    return True


def _cli_supports_live_permission_mode(cli_type: str) -> bool:
    return _cli_supports_live_launch_field(cli_type, "permission_mode")


async def _restart_session_for_launch(session_id: str, targets: dict) -> dict:
    """Restart the PTY so the CLI runs with ``targets``; resumes the conversation.

    ``expected`` makes the supervisor refuse (without touching the PTY) when
    a stored value moved on since this apply was scheduled.
    """
    import session_supervisor
    result = await session_supervisor.restart(session_id, expected=dict(targets))
    if result.get("ok"):
        if "model" in targets or "effort" in targets:
            _launch_applied_at[session_id] = time.time()
        db = await get_db()
        try:
            row = await (await db.execute(
                "SELECT native_session_id FROM sessions WHERE id = ?", (session_id,),
            )).fetchone()
        finally:
            await db.close()
        native_sid = row["native_session_id"] if row else None
        result = {**result, "resumed": bool(native_sid), "native_session_id": native_sid}
    return result


def _session_logical_status_for_apply(session_id: str) -> str:
    from hooks import get_session_logical_status
    return get_session_logical_status(session_id, pty_mgr.is_alive(session_id), "idle")


def _get_permission_live_applier():
    global _permission_live_applier
    if _permission_live_applier is None:
        from permission_mode_live import LiveLaunchApplier, set_permission_mode_resolver
        _permission_live_applier = LiveLaunchApplier(
            restart=_restart_session_for_launch,
            is_alive=pty_mgr.is_alive,
            status=_session_logical_status_for_apply,
            broadcast=broadcast,
        )
        set_permission_mode_resolver(lambda sid: _permission_live_applier.snapshot(sid, "permission_mode"))
    return _permission_live_applier


async def get_permission_mode_apply(request: web.Request) -> web.Response:
    """GET pending live permission-mode apply for a session (or state none)."""
    session_id = request.match_info["id"]
    pending = _get_permission_live_applier().snapshot(session_id, "permission_mode")
    return web.json_response(pending or {"session_id": session_id, "state": "none"})


async def get_launch_apply(request: web.Request) -> web.Response:
    """GET pending live launch applies: ``{session_id, fields: {field: snapshot}}``."""
    session_id = request.match_info["id"]
    pending = _get_permission_live_applier().pending(session_id) or {}
    return web.json_response({"session_id": session_id, "fields": pending})


async def apply_permission_mode_now(request: web.Request) -> web.Response:
    """POST: apply pending launch changes now, interrupting the turn.

    One restart applies every pending field (perms, model, effort)."""
    session_id = request.match_info["id"]
    db = await get_db()
    try:
        row = await (await db.execute(
            "SELECT * FROM sessions WHERE id = ?", (session_id,),
        )).fetchone()
    finally:
        await db.close()
    if not row or not _session_visible_to_request(dict(row), request):
        return web.json_response({"error": "session not found"}, status=404)
    from permission_mode_policy import is_agent_origin
    if is_agent_origin(request):
        return web.json_response({"error": "only the user can apply launch settings"}, status=403)
    result = await _get_permission_live_applier().apply_now(session_id)
    status = 200 if result.get("state") in ("applied", "none", "applying") else 409
    return web.json_response(result, status=status)


async def update_session(request: web.Request) -> web.Response:
    """Update session config fields (model, permission_mode, effort, etc.)."""
    session_id = request.match_info["id"]
    body = await request.json()
    db = await get_db()
    try:
        cur_vis = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        vis_row = await cur_vis.fetchone()
        if not vis_row:
            return web.json_response({"error": "session not found"}, status=404)
        if not _session_visible_to_request(dict(vis_row), request):
            return web.json_response({"error": "session not found"}, status=404)
        if "account_id" in body or "cli_type" in body:
            return web.json_response(
                {
                    "error": (
                        "account_id and cli_type cannot be relabelled on a session; "
                        "use restart-with-account for an awaited replacement PTY"
                    )
                },
                status=409,
            )
        from permission_mode_policy import is_agent_origin
        if is_agent_origin(request):
            from model_policy import switching_enabled, switch_error
            if any(k in body and body[k] != dict(vis_row).get(k) for k in ("plan_model", "execute_model")):
                return web.json_response({"error": "Only the user can configure model switching", "code": "model_choice_locked"}, status=403)
            if "model" in body:
                reason = switch_error(dict(vis_row), body["model"], await switching_enabled(db))
                if reason:
                    return web.json_response({"error": reason, "code": "model_choice_locked"}, status=403)

        if "permission_mode" in body:
            # Reject modes this session's CLI cannot launch with (e.g. codex
            # 0.162 refuses `-a untrusted` and the PTY dies on restart).
            from cli_profiles import (
                UnknownCLIProfileError as _UnknownCLI,
                get_profile as _cli_profile,
                permission_mode_error_payload as _mode_error_payload,
            )
            try:
                _mode_payload = _mode_error_payload(
                    _cli_profile(dict(vis_row).get("cli_type") or "claude"),
                    body.get("permission_mode"),
                )
            except _UnknownCLI:
                _mode_payload = None
            if _mode_payload is not None:
                return web.json_response(_mode_payload, status=400)

        if "worktree" in body:
            from session_worktree import resolve_worktree
            try:
                body["worktree"] = resolve_worktree(dict(vis_row).get("cli_type") or "claude", body["worktree"])
            except ValueError as exc:
                return web.json_response({"error": str(exc), "code": "unsupported_worktree"}, status=400)

        allowed = ("name", "model", "permission_mode", "effort", "budget_usd",
                   "system_prompt", "allowed_tools", "disallowed_tools",
                   "add_dirs", "agent", "worktree", "mcp_config", "scratchpad",
                   "native_session_id", "native_slug", "auto_approve_mcp",
                   "plan_model", "execute_model", "auto_approve_plan", "output_style", "tags",
                   "archived", "summary",
                   "task_id", "active_ticket_id",
                   "board_action", "board_action_at", "board_action_note")

        # ── permission_mode ceiling enforcement ────────────────────────
        # The user picks the session's permission_mode in the UI; that
        # choice is the ceiling for the local AGENT. Without this guard
        # the plan-mode tool block in hooks.py is bypassable — the agent
        # would PUT permission_mode: "auto" on itself and walk out.
        #
        # Joiners (Code/Full) are authed humans and explicitly allowed to
        # change permission_mode — including widening — per owner trust
        # model. We still tag the audit event with who did it.
        live_apply_request = None
        if "permission_mode" in body:
            from permission_mode_policy import (
                is_agent_origin,
                validate_agent_mode_change,
            )
            cur_row = await (
                await db.execute(
                    "SELECT permission_mode, cli_type FROM sessions WHERE id = ?",
                    (session_id,),
                )
            ).fetchone()
            current_mode = (cur_row["permission_mode"] if cur_row else "default") or "default"
            cli_type_cur = (cur_row["cli_type"] if cur_row else "claude") or "claude"
            proposed_mode = str(body["permission_mode"])

            ctx = request.get("auth")
            agent_origin = is_agent_origin(request)
            if agent_origin:
                origin_label = "agent"
            elif ctx is not None and not ctx.is_owner:
                origin_label = "joiner"
            else:
                origin_label = "user"

            if agent_origin:
                _reason = validate_agent_mode_change(cli_type_cur, current_mode, proposed_mode)
                if _reason:
                    try:
                        await bus.emit(
                            CommanderEvent.PERMISSION_MODE_REJECTED,
                            payload={
                                "session_id": session_id,
                                "cli_type": cli_type_cur,
                                "from": current_mode,
                                "to": proposed_mode,
                                "reason": _reason,
                                "source": origin_label,
                                "actor_kind": (ctx.actor_kind if ctx else None),
                            },
                            source="api",
                            actor=origin_label,
                        )
                    except Exception as _emit_err:
                        logger.debug("PERMISSION_MODE_REJECTED emit failed: %s", _emit_err)
                    return web.json_response(
                        {"error": _reason, "from": current_mode, "to": proposed_mode},
                        status=403,
                    )

            # Opt-in (the Perms menu sends apply_live): bring the running CLI
            # in line after the DB write. Agent-origin changes never restart.
            if body.get("apply_live") and not agent_origin:
                live_apply_request = (current_mode, proposed_mode, cli_type_cur)

            if current_mode != proposed_mode:
                try:
                    await bus.emit(
                        CommanderEvent.PERMISSION_MODE_CHANGED,
                        payload={
                            "session_id": session_id,
                            "from": current_mode,
                            "to": proposed_mode,
                            "source": origin_label,
                            "actor_kind": (ctx.actor_kind if ctx else None),
                        },
                        source="api",
                        actor=origin_label,
                    )
                except Exception as _emit_err:
                    logger.debug("PERMISSION_MODE_CHANGED emit failed: %s", _emit_err)

        live_launch_fields = []
        if body.get("apply_live"):
            from permission_mode_policy import is_agent_origin as _is_agent
            if not _is_agent(request):
                live_launch_fields = [f for f in ("model", "effort") if f in body]
        if "effort" in body and body.get("effort") not in (None, ""):
            _effort_cli = dict(vis_row).get("cli_type") or "claude"
            try:
                _levels = list(get_profile(_effort_cli).effort_levels or [])
            except Exception:
                _levels = []
            if _levels and str(body["effort"]).strip().lower() not in _levels:
                return web.json_response(
                    {"error": f"effort must be one of {', '.join(_levels)} (or empty for the CLI default)"},
                    status=400,
                )
            if _levels:
                body["effort"] = str(body["effort"]).strip().lower()

        if "model" in body:
            cur_model = await db.execute(
                "SELECT cli_type, session_type FROM sessions WHERE id = ?",
                (session_id,),
            )
            model_row = await cur_model.fetchone()
            if not model_row:
                return web.json_response({"error": "session not found"}, status=404)
            model_cli = body.get("cli_type") or model_row["cli_type"] or "claude"
            body["model"] = _model_for_storage(
                get_profile(model_cli),
                body.get("model"),
                model_row["session_type"],
            )

        fields, values = [], []
        for key in allowed:
            if key in body:
                val = body[key]
                # Tags stored as JSON array
                if key == "tags" and isinstance(val, list):
                    val = json.dumps(val)
                fields.append(f"{key} = ?")
                values.append(val)
        if not fields:
            return web.json_response({"error": "no fields to update"}, status=400)

        # Read pre-update state for fields whose change we emit events for.
        old_active_ticket_id: str | None = None
        if "active_ticket_id" in body:
            pre_cur = await db.execute(
                "SELECT active_ticket_id FROM sessions WHERE id = ?", (session_id,),
            )
            pre_row = await pre_cur.fetchone()
            old_active_ticket_id = (pre_row["active_ticket_id"] if pre_row else None)

        values.append(session_id)
        await db.execute(
            f"UPDATE sessions SET {', '.join(fields)} WHERE id = ?", values
        )
        await db.commit()
        # Broadcast archive/summary state changes to all connected clients
        if "archived" in body:
            await broadcast({
                "type": "session_archived",
                "session_id": session_id,
                "archived": body["archived"],
            })
        if "summary" in body:
            await broadcast({
                "type": "session_summary",
                "session_id": session_id,
                "summary": body["summary"],
            })

        # Emit SESSION_TICKET_REBOUND only when the bound ticket actually
        # changed. switch_active_ticket and document_to_board both PUT
        # through this route, so a single emit point covers worker tools
        # and direct UI edits.
        if "active_ticket_id" in body:
            new_active_ticket_id = body.get("active_ticket_id")
            if new_active_ticket_id != old_active_ticket_id:
                try:
                    await bus.emit(CommanderEvent.SESSION_TICKET_REBOUND, {
                        "session_id": session_id,
                        "old_ticket_id": old_active_ticket_id,
                        "new_ticket_id": new_active_ticket_id,
                    }, source="api", actor="user")
                except Exception as e:
                    logger.debug("SESSION_TICKET_REBOUND emit failed: %s", e)

        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "session not found"}, status=404)
        updated = dict(row)
        updated["quick"] = _quick_start.is_quick_workspace_cached(updated.get("workspace_id"))
        # One applier call for every live field so they share one restart.
        live_cli = updated.get("cli_type") or "claude"
        live_changes: dict = {}
        live_result: dict = {}
        if live_apply_request is not None:
            _from_mode, _to_mode, _apply_cli = live_apply_request
            if _cli_supports_live_permission_mode(_apply_cli):
                live_changes["permission_mode"] = (_from_mode, _to_mode)
            else:
                live_result["permission_mode"] = {
                    "session_id": session_id, "field": "permission_mode",
                    "state": "unsupported", "mode": _to_mode, "value": _to_mode,
                }
        pre_row = dict(vis_row)
        for _field in live_launch_fields:
            if _cli_supports_live_launch_field(live_cli, _field):
                live_changes[_field] = (pre_row.get(_field), updated.get(_field))
            else:
                live_result[_field] = {
                    "session_id": session_id, "field": _field,
                    "state": "unsupported", "value": updated.get(_field),
                }
        if live_changes:
            live_result.update(
                await _get_permission_live_applier().request_fields(session_id, live_changes)
            )
        if "permission_mode" in live_result:
            updated["permission_apply"] = live_result["permission_mode"]
        if live_result:
            updated["launch_apply"] = live_result
        return web.json_response(updated)
    finally:
        await db.close()


