async def create_template(request: web.Request) -> web.Response:
    body = await request.json()
    name = body.get("name", "").strip()
    if not name:
        return web.json_response({"error": "name required"}, status=400)

    tid = str(uuid.uuid4())
    db = await get_db()
    try:
        await db.execute(
            """INSERT INTO templates (id, name, model, permission_mode, effort,
               budget_usd, system_prompt, allowed_tools, guideline_ids, mcp_server_ids, conversation_turns,
               plan_model, execute_model, auto_approve_plan, account_id, cli_type)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (tid, name, body.get("model"), body.get("permission_mode"),
             body.get("effort"), body.get("budget_usd"), body.get("system_prompt"),
             body.get("allowed_tools"), json.dumps(body.get("guideline_ids", [])),
             json.dumps(body.get("mcp_server_ids", [])),
             json.dumps(body.get("conversation_turns", [])),
             body.get("plan_model"), body.get("execute_model"),
             1 if body.get("auto_approve_plan") else 0,
             body.get("account_id") or None, body.get("cli_type") or "claude"),
        )
        await db.commit()
        cur = await db.execute("SELECT * FROM templates WHERE id = ?", (tid,))
        row = await cur.fetchone()
        return web.json_response(dict(row), status=201)
    finally:
        await db.close()


async def delete_template(request: web.Request) -> web.Response:
    tid = request.match_info["id"]
    db = await get_db()
    try:
        await db.execute("DELETE FROM templates WHERE id = ?", (tid,))
        await db.commit()
        return web.json_response({"ok": True})
    finally:
        await db.close()


async def apply_template(request: web.Request) -> web.Response:
    """Create a session from a template with potential field overrides."""
    tid = request.match_info["id"]
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid JSON body"}, status=400)
    if not isinstance(body, dict):
        return web.json_response({"error": "expected JSON object"}, status=400)
    workspace_id = body.get("workspace_id")
    if not isinstance(workspace_id, str) or not workspace_id.strip():
        return web.json_response({"error": "workspace_id required"}, status=400)
    if not _workspace_visible_to_auth(workspace_id, get_auth(request)):
        return web.json_response({"error": "workspace not found"}, status=404)

    db = await get_db()
    try:
        cur = await db.execute("SELECT id FROM workspaces WHERE id = ?", (workspace_id,))
        if not await cur.fetchone():
            return web.json_response({"error": "workspace not found"}, status=404)
        cur = await db.execute("SELECT * FROM templates WHERE id = ?", (tid,))
        tmpl = await cur.fetchone()
        if not tmpl:
            return web.json_response({"error": "template not found"}, status=404)
        tmpl = dict(tmpl)

        session_id = str(uuid.uuid4())
        name = body.get("name", "").strip() or f"{tmpl['name']} — {session_id[:8]}"
        cli_type = body.get("cli_type", tmpl.get("cli_type") or "claude")
        if not is_active_cli(cli_type):
            if body.get("cli_type"):
                return _inactive_cli_response(cli_type)
            cli_type = "claude"
        try:
            cli_availability = await _registered_cli_availability()
        except Exception as exc:
            logger.error("CLI availability registry unavailable: %s", exc)
            return web.json_response({
                "error": "CLI availability could not be verified",
                "code": "cli_availability_unavailable",
            }, status=503)
        if not cli_availability.get(cli_type, False):
            return web.json_response({
                "error": f"{get_profile(cli_type).label} is not installed or enabled",
                "code": "cli_binary_missing",
                "cli_type": cli_type,
            }, status=409)
        profile = get_profile(cli_type)
        session_type = body.get("session_type", "worker")
        model = _model_for_storage(profile, body.get("model", tmpl.get("model")), session_type)
        permission_mode = body.get("permission_mode", tmpl.get("permission_mode") or profile.default_permission_mode)
        if "permission_mode" in body:
            _mode_err = _permission_mode_error(profile, permission_mode)
            if _mode_err is not None:
                return _mode_err
        elif not permission_mode_valid_for_profile(profile, permission_mode):
            # Templates are CLI-agnostic; a mode saved for another CLI must
            # not reach this CLI's argv.
            permission_mode = profile.default_permission_mode
        effort = _effort_for_storage(profile, body.get("effort", tmpl.get("effort")))
        budget_usd = body.get("budget_usd", tmpl.get("budget_usd"))
        system_prompt = body.get("system_prompt", tmpl.get("system_prompt"))
        allowed_tools = body.get("allowed_tools", tmpl.get("allowed_tools"))
        plan_model = body.get("plan_model", tmpl.get("plan_model"))
        execute_model = body.get("execute_model", tmpl.get("execute_model"))
        auto_approve_plan = 1 if body.get("auto_approve_plan", tmpl.get("auto_approve_plan", 0)) else 0
        purpose = body.get("purpose", "").strip() or None
        account_id = body.get("account_id", tmpl.get("account_id")) or None

        requested_worktree = body.get("worktree")
        default_worktree = False
        if requested_worktree is None:
            tmp_db = await get_db()
            try:
                cur_ws = await tmp_db.execute("SELECT default_worktree FROM workspaces WHERE id = ?", (workspace_id,))
                ws_row = await cur_ws.fetchone()
                default_worktree = bool(ws_row and ws_row["default_worktree"])
            finally:
                await tmp_db.close()
        from session_worktree import resolve_worktree
        try:
            worktree = resolve_worktree(cli_type, requested_worktree, default=default_worktree)
        except ValueError as exc:
            return web.json_response({"error": str(exc), "code": "unsupported_worktree"}, status=400)

        await db.execute(
            """INSERT INTO sessions (id, workspace_id, name, model, permission_mode, effort,
               budget_usd, system_prompt, allowed_tools, plan_model, execute_model, auto_approve_plan,
               account_id, cli_type, worktree, purpose, session_type)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (session_id, workspace_id, name, model, permission_mode, effort,
             budget_usd, system_prompt, allowed_tools, plan_model, execute_model, auto_approve_plan,
             account_id, cli_type, worktree, purpose, session_type),
        )

        # Apply template guidelines (skip any that were deleted) or use custom overrides
        body_gids = body.get("guideline_ids")
        if body_gids is not None:
            gids = body_gids
        else:
            gids = json.loads(tmpl.get("guideline_ids") or "[]")
        if not isinstance(gids, list) or any(not isinstance(gid, str) for gid in gids):
            raise ValueError("guideline_ids must be a list of ids")
        gids = list(dict.fromkeys(gids))

        if gids:
            placeholders = ",".join("?" for _ in gids)
            cur2 = await db.execute(f"SELECT id FROM guidelines WHERE id IN ({placeholders})", gids)
            existing_gids = {row["id"] for row in await cur2.fetchall()}
            missing_gids = [gid for gid in gids if gid not in existing_gids]
            if missing_gids:
                raise ValueError(f"unknown guideline id: {', '.join(missing_gids)}")
            for gid in gids:
                await db.execute(
                    "INSERT OR IGNORE INTO session_guidelines (session_id, guideline_id) VALUES (?, ?)",
                    (session_id, gid),
                )

        # Apply template MCP servers (skip any that were deleted) or use custom overrides
        body_mcp_ids = body.get("mcp_server_ids")
        if body_mcp_ids is not None:
            mcp_ids = body_mcp_ids
        else:
            mcp_ids = json.loads(tmpl.get("mcp_server_ids") or "[]")
        if not isinstance(mcp_ids, list) or any(not isinstance(mid, str) for mid in mcp_ids):
            raise ValueError("mcp_server_ids must be a list of ids")
        mcp_ids = list(dict.fromkeys(mcp_ids))
        mcp_overrides = body.get("mcp_overrides", {})
        if not isinstance(mcp_overrides, dict):
            raise ValueError("mcp_overrides must be an object")

        if mcp_ids:
            placeholders = ",".join("?" for _ in mcp_ids)
            cur2 = await db.execute(f"SELECT id FROM mcp_servers WHERE id IN ({placeholders})", mcp_ids)
            existing_mids = {row["id"] for row in await cur2.fetchall()}
            missing_mids = [mid for mid in mcp_ids if mid not in existing_mids]
            if missing_mids:
                raise ValueError(f"unknown MCP server id: {', '.join(missing_mids)}")
            for mid in mcp_ids:
                override = mcp_overrides.get(mid, {})
                if not isinstance(override, dict):
                    raise ValueError(f"invalid MCP override for {mid}")
                auto_override = override.get("auto_approve_override")
                if auto_override is not None:
                    auto_override = 1 if bool(auto_override) else 0
                await db.execute(
                    """INSERT OR IGNORE INTO session_mcp_servers
                       (session_id, mcp_server_id, auto_approve_override)
                       VALUES (?, ?, ?)""",
                    (session_id, mid, auto_override),
                )

        if session_type != "commander":
            await db.execute(
                "INSERT OR IGNORE INTO session_mcp_servers (session_id, mcp_server_id, auto_approve_override) VALUES (?, ?, 1)",
                (session_id, "builtin-worker-board"),
            )

        tags = body.get("tags", [])
        if not isinstance(tags, list) or any(not isinstance(tag, str) for tag in tags):
            raise ValueError("tags must be a list of strings")
        if tags:
            await db.execute(
                "UPDATE sessions SET tags = ? WHERE id = ?",
                (json.dumps(list(dict.fromkeys(tags))), session_id),
            )
        await _sync_zai_mcp_servers_for_session(db, session_id, cli_type, account_id)

        await db.commit()
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
        result = dict(row)
    except ValueError as exc:
        await db.rollback()
        return web.json_response({
            "error": f"session was not created: {exc}",
            "code": "invalid_session_configuration",
        }, status=400)
    except Exception as exc:
        await db.rollback()
        logger.exception("Atomic template session creation failed")
        return web.json_response({
            "error": f"session was not created: {exc}",
            "code": "session_creation_failed",
        }, status=500)
    finally:
        await db.close()

    try:
        await broadcast({"type": "session_created", "session": result})
    except Exception:
        logger.exception("Template session created but WebSocket announcement failed")
    try:
        await bus.emit(CommanderEvent.SESSION_SPAWNED, {
            "session_id": session_id,
            "workspace_id": result.get("workspace_id"),
            "name": result.get("name"),
            "cli_type": result.get("cli_type"),
            "model": result.get("model"),
            "session_type": result.get("session_type"),
        }, source="api", actor="user")
    except Exception:
        logger.exception("Template session created but SESSION_SPAWNED event failed")
    return web.json_response(result, status=201)


# ─── REST: Grid templates ───────────────────────────────────────────
# A grid template defines a custom CSS-grid layout for the multi-terminal grid view.
# Each template owns its own cell-to-session assignments (which session lives in
# which cell), so swapping templates doesn't drop your in-progress placements.

def _serialize_grid_template(row) -> dict:
    d = dict(row)
    try:
        d["cells"] = json.loads(d.get("cells") or "[]")
    except Exception:
        d["cells"] = []
    try:
        d["cell_assignments"] = json.loads(d.get("cell_assignments") or "{}")
    except Exception:
        d["cell_assignments"] = {}
    return d


async def list_grid_templates(request: web.Request) -> web.Response:
    workspace_id = request.query.get("workspace")
    db = await get_db()
    try:
        if workspace_id:
            cur = await db.execute(
                "SELECT * FROM grid_templates WHERE workspace_id = ? OR workspace_id IS NULL ORDER BY created_at ASC",
                (workspace_id,),
            )
        else:
            cur = await db.execute("SELECT * FROM grid_templates ORDER BY created_at ASC")
        rows = await cur.fetchall()
        return web.json_response([_serialize_grid_template(r) for r in rows])
    finally:
        await db.close()


async def create_grid_template(request: web.Request) -> web.Response:
    body = await request.json()
    tid = body.get("id") or str(uuid.uuid4())
    workspace_id = body.get("workspace_id")
    name = (body.get("name") or "").strip() or "New layout"
    cols = max(1, min(6, int(body.get("cols") or 3)))
    cells = json.dumps(body.get("cells") or [])
    assignments = json.dumps(body.get("cell_assignments") or {})
    db = await get_db()
    try:
        await db.execute(
            "INSERT INTO grid_templates (id, workspace_id, name, cols, cells, cell_assignments) "
            "VALUES (?, ?, ?, ?, ?, ?)",
            (tid, workspace_id, name, cols, cells, assignments),
        )
        await db.commit()
        cur = await db.execute("SELECT * FROM grid_templates WHERE id = ?", (tid,))
        row = await cur.fetchone()
        return web.json_response(_serialize_grid_template(row), status=201)
    finally:
        await db.close()


async def update_grid_template(request: web.Request) -> web.Response:
    tid = request.match_info["id"]
    body = await request.json()
    fields, values = [], []
    if "name" in body:
        fields.append("name = ?")
        values.append((body.get("name") or "").strip() or "New layout")
    if "cols" in body:
        fields.append("cols = ?")
        values.append(max(1, min(6, int(body["cols"] or 3))))
    if "cells" in body:
        fields.append("cells = ?")
        values.append(json.dumps(body["cells"] or []))
    if "cell_assignments" in body:
        fields.append("cell_assignments = ?")
        values.append(json.dumps(body["cell_assignments"] or {}))
    if not fields:
        return web.json_response({"error": "no fields"}, status=400)
    fields.append("updated_at = datetime('now')")
    values.append(tid)
    db = await get_db()
    try:
        await db.execute(
            f"UPDATE grid_templates SET {', '.join(fields)} WHERE id = ?",
            values,
        )
        await db.commit()
        cur = await db.execute("SELECT * FROM grid_templates WHERE id = ?", (tid,))
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "not found"}, status=404)
        return web.json_response(_serialize_grid_template(row))
    finally:
        await db.close()


async def delete_grid_template(request: web.Request) -> web.Response:
    tid = request.match_info["id"]
    db = await get_db()
    try:
        await db.execute("DELETE FROM grid_templates WHERE id = ?", (tid,))
        await db.commit()
        return web.json_response({"ok": True})
    finally:
        await db.close()


