async def list_session_captures(request: web.Request) -> web.Response:
    session_id = request.match_info["id"]
    capture_type = request.query.get("type")
    limit = int(request.query.get("limit", "20"))
    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "session not found"}, status=404)
        if not _session_readable_to_request(dict(row), request):
            return web.json_response({"error": "session not found"}, status=404)
        if capture_type:
            cur = await db.execute(
                """SELECT * FROM output_captures
                   WHERE session_id = ? AND capture_type = ?
                   ORDER BY created_at DESC LIMIT ?""",
                (session_id, capture_type, limit),
            )
        else:
            cur = await db.execute(
                """SELECT * FROM output_captures
                   WHERE session_id = ?
                   ORDER BY created_at DESC LIMIT ?""",
                (session_id, limit),
            )
        rows = await cur.fetchall()
        return web.json_response([dict(r) for r in rows])
    finally:
        await db.close()


async def _session_exists(session_id: str) -> bool:
    db = await get_db()
    try:
        cur = await db.execute("SELECT 1 FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
        return row is not None
    finally:
        await db.close()


async def get_session_output(request: web.Request) -> web.Response:
    session_id = request.match_info["id"]
    config = await _get_readable_session_for_request(session_id, request)
    if not config:
        return web.json_response({"error": "session not found"}, status=404)
    lines = int(request.query.get("lines", "100"))
    cli_type = await _session_cli_type(session_id)
    permission_view_state = None
    if request.query.get("permission_view") == "1" and cli_type == "claude":
        screen = capture_proc.get_screen(session_id)
        if _is_incomplete_permission_screen(screen):
            if _terminal_control_violation(get_auth(request), config, "resize"):
                permission_view_state = "control_unavailable"
            else:
                permission_view_state = await _expand_overview_permission_screen(session_id)
    return web.json_response({
        "session_id": session_id,
        "lines": lines,
        "text": capture_proc.get_buffer(session_id, lines),
        "screen": capture_proc.get_screen(session_id),
        "startup_blocker": _detect_cli_startup_blocker(cli_type, _startup_blocker_text(session_id)),
        "permission_view_state": permission_view_state,
    })


def _terminal_tail_handoff(session_id: str, old_cli: str, new_cli: str) -> str:
    """Handoff context from the recent terminal output (no workspace memory)."""
    raw_output = capture_proc.get_buffer(session_id, 30)
    if isinstance(raw_output, bytes):
        raw_output = raw_output.decode("utf-8", errors="replace")
    tail = strip_ansi(raw_output or "")[-2000:].strip()
    if not tail:
        return ""
    return (
        f"[Session handoff] Switching from {old_cli.upper()} to "
        f"{new_cli.upper()}.\n\n```\n{tail}\n```"
    )


async def switch_session_cli(request: web.Request) -> web.Response:
    """Switch a session between active CLI profiles.

    Flow:
    1. Read last N lines of session output → build context summary
    2. Ask the session supervisor to stop, update, and restart atomically
    3. Return success only after the old PTY is gone and replacement is alive
    """
    session_id = request.match_info["id"]
    body = await request.json()
    new_cli_type = body.get("cli_type")
    if not is_active_cli(new_cli_type):
        allowed = ", ".join(profile.id for profile in active_profiles())
        return web.json_response({"error": f"cli_type must be one of: {allowed}"}, status=400)

    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "session not found"}, status=404)
        current = dict(row)
        if not _session_visible_to_request(current, request):
            return web.json_response({"error": "session not found"}, status=404)
    finally:
        await db.close()

    # Pick sensible defaults for the new CLI
    new_profile = get_profile(new_cli_type)
    default_model = _profile_default_model_for_role(new_profile, current.get("session_type"))
    default_mode = new_profile.default_permission_mode
    new_model = _model_for_storage(new_profile, body.get("model", default_model), current.get("session_type"))
    same_cli_switch = new_cli_type == (current.get("cli_type") or "claude").lower()
    from permission_mode_policy import is_agent_origin
    if is_agent_origin(request):
        if not same_cli_switch:
            return web.json_response({"error": "Only the user can change this session's CLI provider", "code": "model_choice_locked"}, status=403)
        from model_policy import switching_enabled, switch_error
        db_policy = await get_db()
        try:
            reason = switch_error(current, new_model, await switching_enabled(db_policy))
        finally:
            await db_policy.close()
        if reason:
            return web.json_response({"error": reason, "code": "model_choice_locked"}, status=403)
    new_mode = body.get("permission_mode", current.get("permission_mode") if same_cli_switch else default_mode) or default_mode
    _mode_err = _permission_mode_error(new_profile, new_mode)
    if _mode_err is not None:
        if "permission_mode" in body:
            return _mode_err
        new_mode = default_mode
    new_effort = _effort_for_storage(new_profile, body.get("effort", current.get("effort") if same_cli_switch else None))

    # Keep exact source records on disk instead of injecting another transcript.
    context_summary = ""
    if not same_cli_switch:
        try:
            handoff = await _prepare_session_handoff(session_id)
            context_summary = handoff["prompt"]
        except Exception as exc:
            logger.warning("Failed to save session handoff for %s: %s", session_id[:8], exc)
            return web.json_response({"error": "Could not save the handoff; the current session was kept."}, status=500)

    from session_worktree import resolve_worktree
    updates = {
        "cli_type": new_cli_type,
        "worktree": resolve_worktree(new_cli_type, default=current.get("worktree", False)),
        "model": new_model,
        "permission_mode": new_mode,
        "effort": new_effort,
    }
    if not same_cli_switch:
        updates.update({
            "native_session_id": None,
            "native_slug": None,
            "system_prompt": context_summary or None,
        })
    expected = {key: current.get(key) for key in updates}

    import session_supervisor
    restart_result = await session_supervisor.restart(
        session_id,
        updates=updates,
        expected=expected,
    )
    if not restart_result.get("ok"):
        return web.json_response(
            {
                "error": restart_result.get("error") or "session switch failed",
                "restart": restart_result,
            },
            status=409,
        )

    result = {**current, **updates}
    await broadcast({
        "type": "session_switched",
        "session_id": session_id,
        "cli_type": new_cli_type,
        "model": new_model,
    })
    return web.json_response(result)


async def switch_model(request: web.Request) -> web.Response:
    """Switch a session's active model using the profile-appropriate path."""
    session_id = request.match_info["id"]
    # MCP-S5: only commander or the session itself can flip its model. The
    # MCP gate at switch_model is meaningless if any worker can hit this
    # route directly and bump a peer to opus mid-run.
    caller = await _resolve_caller(request)
    if caller and caller["session_type"] != "commander" and caller["session_id"] != session_id:
        return web.json_response(
            {"error": "forbidden: only commander or the session itself can switch its model"},
            status=403,
        )
    body = await request.json()
    model_name = body.get("model", "").strip()
    if not model_name:
        return web.json_response({"error": "model required"}, status=400)

    config = await get_session_config(session_id)
    if not config:
        return web.json_response({"error": "session not found"}, status=404)
    if not _session_visible_to_request(config, request):
        return web.json_response({"error": "session not found"}, status=404)
    from permission_mode_policy import is_agent_origin
    if is_agent_origin(request):
        from model_policy import switching_enabled, switch_error
        db_policy = await get_db()
        try:
            reason = switch_error(config, model_name, await switching_enabled(db_policy))
        finally:
            await db_policy.close()
        if reason:
            return web.json_response({"error": reason, "code": "model_choice_locked"}, status=403)
    cli_type = (config.get("cli_type") or "claude").lower()

    if cli_type == "antigravity":
        running = pty_mgr.is_alive(session_id)
        if running:
            native_sid = await _resolve_antigravity_native_session(
                session_id,
                config,
                wait_timeout=5.0,
            )
            if not native_sid:
                return web.json_response({
                    "error": (
                        "Antigravity conversation is not detected yet; wait "
                        "until the first prompt finishes before switching model."
                    ),
                    "session_id": session_id,
                }, status=409)

        try:
            extra_env = await _prepare_session_cli_env(config, session_id)
            from antigravity_runtime import apply_model as _apply_agy_model
            _apply_agy_model(model_name, home=extra_env.get("HOME"))
        except Exception as exc:
            logger.warning("Failed to apply Antigravity model %s: %s", model_name, exc)
            return web.json_response({
                "error": f"failed to apply Antigravity model: {exc}",
                "session_id": session_id,
            }, status=500)

        db = await get_db()
        try:
            await db.execute(
                "UPDATE sessions SET model = ? WHERE id = ?",
                (model_name, session_id),
            )
            await db.commit()
        finally:
            await db.close()

        await broadcast({
            "type": "model_changed",
            "session_id": session_id,
            "model": model_name,
        })

        restarted = False
        if running:
            await broadcast({
                "session_id": session_id,
                "type": "status",
                "status": "running",
                "pty_alive": True,
            })
            await _stop_session_expected(session_id)
            for _ in range(40):
                if not pty_mgr.is_alive(session_id):
                    break
                await _asyncio.sleep(0.1)
            if pty_mgr.is_alive(session_id):
                return web.json_response({
                    "error": "Antigravity did not stop in time for model restart",
                    "session_id": session_id,
                }, status=503)
            await _asyncio.sleep(0.2)
            outcome = await _autostart_session_pty(session_id)
            if not outcome or not outcome.get("ok"):
                return web.json_response({"error": (outcome or {}).get("reason") or "model restart failed", "session_id": session_id}, status=503)
            restarted = True

        return web.json_response({
            "ok": True,
            "session_id": session_id,
            "model": model_name,
            "restarted": restarted,
        })

    if not pty_mgr.is_alive(session_id):
        return web.json_response({"error": "session not running"}, status=400)

    # Inject /model command into PTY (short command, no newlines)
    cmd = f"/model {model_name}"
    pty_mgr.write(session_id, cmd.encode("utf-8") + b"\r")

    # Update DB so UI reflects new model
    db = await get_db()
    try:
        await db.execute(
            "UPDATE sessions SET model = ? WHERE id = ?",
            (model_name, session_id),
        )
        await db.commit()
    finally:
        await db.close()

    # Broadcast model change to frontend
    await broadcast({
        "type": "model_changed",
        "session_id": session_id,
        "model": model_name,
    })

    return web.json_response({"ok": True, "session_id": session_id, "model": model_name})


def _compact_cli_text(text: str) -> str:
    return re.sub(r"\s+", "", (text or "").lower())


_AUTH_BLOCKER_TYPES = frozenset({"auth_required", "auth_error"})
# Fallback when no screen emulator is available: roughly one screen of output.
_STARTUP_BLOCKER_FALLBACK_LINES = 40


def _startup_blocker_text(session_id: str) -> str:
    """Text to scan for startup blockers: the current visible screen.

    Never the long scrollback, which contains arbitrary agent output.
    """
    try:
        screen = capture_proc.get_screen(session_id)
    except Exception:
        screen = ""
    if screen and screen.strip():
        return screen
    return capture_proc.get_buffer(session_id, _STARTUP_BLOCKER_FALLBACK_LINES)


def _has_codex_trust_prompt_text(text: str) -> bool:
    """Codex 0.16x workspace-trust menu ("Trust this folder? ... Trust and continue")."""
    lower = (text or "").lower()
    compact = re.sub(r"\s+", "", lower)
    return (
        "trust this folder?" in lower
        or "trustthisfolder?" in compact
        or "trust and continue" in lower
        or "trustandcontinue" in compact
    )


# Codex draws selection menus with the same "›" glyph as its composer:
# "› 1. Trust and continue", "› 1. Yes, proceed (y)". A "›" followed by a
# numbered item is a menu cursor, never the input line.
_CODEX_MENU_CURSOR_RE = re.compile(r"›\s*\d+[.)]")


def _codex_composer_ready(tail: str) -> bool:
    """True when the newest "›" in ``tail`` is Codex's input line.

    It must come after every menu cursor and after any trust prompt text,
    so a pending trust/approval/update menu is never mistaken for "ready".
    """
    composer_at = -1
    for match in re.finditer("›", tail):
        if not _CODEX_MENU_CURSOR_RE.match(tail, match.start()):
            composer_at = match.start()
    if composer_at < 0:
        return False
    menu_at = max((m.start() for m in _CODEX_MENU_CURSOR_RE.finditer(tail)), default=-1)
    trust_at = max(tail.rfind("trust this folder?"), tail.rfind("trust and continue"))
    return composer_at > menu_at and composer_at > trust_at


def _detect_cli_startup_blocker(cli_type: str, text: str) -> dict | None:
    lower = (text or "").lower()
    compact = _compact_cli_text(text)
    cli = (cli_type or "claude").lower()
    trust_menu = _trust_prompt_selection(text)

    if cli == "claude" and "errorcreatingworktree" in compact and "workspacetrustnotyetaccepted" in compact:
        return {
            "type": "trust_required",
            "label": "Trust this workspace before creating a worktree",
            "detail": "Open a regular Claude session in this project first to confirm folder trust, then restart this worktree session.",
        }
    if trust_menu and trust_menu["cli_type"] == cli:
        return {
            "type": "trust_required",
            "label": "Workspace trust confirmation required",
            "detail": "The agent is waiting for folder trust confirmation before it can accept messages.",
        }

    # A resumed TUI redraws old errors above its current composer. Only
    # text after that composer can describe a live login/setup screen.
    auth_lower = lower
    marker = r"(?m)^\s*[❯>]\s*(?![0-9]+[.)])" if cli == "claude" else r"(?m)^\s*›(?!\s*[0-9]+[.)])"
    for prompt in re.finditer(marker, lower):
        auth_lower = lower[prompt.end():]
    auth_compact = _compact_cli_text(auth_lower)

    if cli == "claude":
        if "selectloginmethod" in auth_compact or "claudeaccountwithsubscription" in auth_compact:
            return {
                "type": "auth_required",
                "label": "Claude login required",
                "detail": "Claude Code is waiting at the login-method prompt, so agent prompts cannot run yet.",
            }
        # A bare "API Error: 401" can be test output; require Claude's own
        # auth wording next to it.
        if (
            ("apierror:401" in auth_compact and (
                "authentication_error" in auth_compact
                or "pleaserun/login" in auth_compact
                or "oauthtokenhasexpired" in auth_compact
            ))
            or "invalidauthenticationcredentials" in auth_compact
            or "oauthtokenhasexpired" in auth_compact
            or "pleaserun/login" in auth_compact
        ):
            return {
                "type": "auth_error",
                "label": "Claude API auth error (401)",
                "detail": "Claude Code is returning a 401 invalid-credentials error — the API key is invalid or expired. Run /login to re-authenticate.",
            }
        if "choosethetextstyle" in compact:
            return {
                "type": "setup_required",
                "label": "Claude first-run setup required",
                "detail": "Claude Code is waiting for first-run theme/setup selection.",
            }
        if ("doyoutrust" in compact or "trustthisfolder?" in compact) and not re.search(r"(?m)^\s*[❯›>]\s*$", text or ""):
            return {
                "type": "trust_required",
                "label": "Workspace trust prompt",
                "detail": "Claude Code is waiting for workspace trust confirmation.",
            }

    if cli == "codex":
        if "folderaccess" in compact and "trustthisfolder?" in compact and "trustandcontinue" not in compact:
            return {
                "type": "trust_required",
                "label": "Workspace trust confirmation required",
                "detail": "Codex is preparing its folder trust prompt. Wait for trust confirmation before sending a message.",
            }
        if (
            "access token could not be refreshed" in auth_lower
            or "authentication session could not be refreshed" in auth_lower
            or "run codex login again" in auth_lower
            or (
                "stream disconnected" in auth_lower
                and ("401" in auth_lower or "unauthorized" in auth_lower)
            )
        ):
            return {
                "type": "auth_error",
                "label": "Codex login expired",
                "detail": "Codex cannot refresh its login. Restart the session to reload credentials, then run codex login if it still fails.",
            }
        # Codex's own sign-in screen, not any text mentioning "login".
        if (
            "sign in with chatgpt" in auth_lower
            or "provide your own api key" in auth_lower
            or ("not logged in" in auth_lower and "codex login" in auth_lower)
        ):
            return {
                "type": "auth_required",
                "label": "Codex login required",
                "detail": "Codex is waiting for authentication before it can accept agent prompts.",
            }
        if _has_codex_trust_prompt_text(text) and not _codex_composer_ready(lower[-3000:]):
            return {
                "type": "trust_required",
                "label": "Workspace trust prompt",
                "detail": "Codex is asking whether to trust this folder; IVE answers it like Claude's.",
            }
        if _has_codex_update_prompt_text(lower):
            return {
                "type": "update_required",
                "label": "Codex update prompt",
                "detail": "Codex is showing an update prompt before the agent input line.",
            }

    if cli == "antigravity":
        tail = lower[-4000:]
        last_ready = max(tail.rfind("\n>"), tail.rfind("\r\n>"), tail.rfind("? for shortcuts"))
        active_tail = tail[last_ready:] if last_ready >= 0 else tail
        if "signing in" in active_tail or "sign in" in active_tail or "oauth" in active_tail:
            return {
                "type": "auth_required",
                "label": "Antigravity login required",
                "detail": "Antigravity is waiting for authentication before it can accept agent prompts.",
            }

    return None


def _is_startup_control_input(input_data: str) -> bool:
    stripped = (input_data or "").strip().lower()
    if stripped in {"1", "2", "3", "4", "5", "6", "7", "y", "yes", "n", "no"}:
        return True
    if input_data in {"\x1b", "\x15", "\x03"}:
        return True
    if input_data.startswith("\x1b") and set(input_data[1:]) <= {"\x7f"}:
        return True
    if input_data in {"\x1b[A", "\x1b[B", "\x1b[C", "\x1b[D"}:
        return True
    return False


def _looks_antigravity_busy(cli_type: str, text: str) -> bool:
    if (cli_type or "").lower() != "antigravity":
        return False
    tail = (text or "").lower()[-4000:]
    if not tail:
        return False
    last_ready = max(tail.rfind("\n>"), tail.rfind("\r\n>"), tail.rfind("? for shortcuts"))
    active_span = tail[last_ready:] if last_ready >= 0 else tail
    active_tail = active_span[-1600:]
    busy_markers = (
        "loading...",
        "loading…",
        "generating...",
        "generating…",
        "▸ thought for",
        "calling ",
        "thinking ",
    )
    return any(marker in active_tail for marker in busy_markers)


def _looks_codex_busy(cli_type: str, text: str) -> bool:
    if (cli_type or "").lower() != "codex":
        return False
    tail = (text or "").lower()[-5000:]
    if not tail:
        return False
    last_prompt = max(tail.rfind("›"), tail.rfind("\n>"), tail.rfind("\r\n>"))
    busy_markers = (
        "starting mcp servers",
        "esc to interrupt",
    )
    return any((idx := tail.rfind(marker)) >= 0 and idx > last_prompt for marker in busy_markers)


def _looks_ready_for_input(cli_type: str, text: str) -> bool:
    lower = (text or "").lower()
    if not lower:
        return False
    if _detect_cli_startup_blocker(cli_type, text):
        return False
    if cli_type == "codex":
        tail = lower[-3000:]
        if _has_codex_update_prompt_text(lower):
            return False
        if _looks_codex_busy(cli_type, text):
            return False
        if "please restart codex" in tail or "update ran successfully" in tail:
            return False
        if "starting mcp servers" in tail and "›" not in tail:
            return False
        if "›" in tail:
            return _codex_composer_ready(tail)
        return "\n>" in tail or "\r\n>" in tail
    if cli_type == "gemini":
        return "type your message" in lower or "yolo" in lower or "\n>" in lower or "\r\n>" in lower
    if cli_type == "antigravity":
        tail = lower[-2000:]
        if _looks_antigravity_busy(cli_type, text):
            return False
        if "signing in" in tail and "\n>" not in tail and "\r\n>" not in tail:
            return False
        return "\n>" in tail or "\r\n>" in tail or "? for shortcuts" in tail
    if cli_type == "claude":
        # Startup banners and error text are not an input prompt. In
        # particular, never clear a first-run menu just because it printed.
        # Claude renders its placeholder after a NBSP. Accept horizontal
        # Unicode whitespace, while keeping the marker on its own line.
        return bool(re.search(r"(?m)^[^\S\r\n\v\f\x85\u2028\u2029]*[❯>](?:[^\S\r\n\v\f\x85\u2028\u2029]|$)", text or ""))
    return True


async def _wait_for_cli_input_ready(session_id: str, cli_type: str, timeout: float) -> bool:
    # TUIs redraw in fragments. Their latest raw output often contains only
    # spinner/title updates, while the input prompt remains on the screen.
    # Use the emulated screen for both checks so follow-up Overview messages
    # do not sit in a queue waiting for an already-visible prompt to reprint.
    if timeout <= 0:
        return _looks_ready_for_input(cli_type, _startup_blocker_text(session_id))
    loop = _asyncio.get_event_loop()
    deadline = loop.time() + timeout
    while loop.time() < deadline:
        if not pty_mgr.is_alive(session_id):
            return False
        try:
            from hooks import get_session_logical_status
            if get_session_logical_status(session_id, True, "idle") == "running":
                await _asyncio.sleep(0.25)
                continue
        except Exception:
            pass
        if _looks_ready_for_input(cli_type, _startup_blocker_text(session_id)):
            if cli_type in {"antigravity", "codex", "claude"}:
                await _asyncio.sleep(0.5)
                if not pty_mgr.is_alive(session_id):
                    return False
                if not _looks_ready_for_input(cli_type, _startup_blocker_text(session_id)):
                    continue
            return True
        await _asyncio.sleep(0.25)
    return False


async def _session_cli_type(session_id: str) -> str:
    try:
        config = await get_session_config(session_id)
        if config:
            return config.get("cli_type", "claude")
    except Exception:
        pass
    return "claude"


def _canonical_prompt_screen(screen: str) -> str:
    return screen.replace("\r\n", "\n").strip()


def _session_permission_menu(screen: str) -> dict | None:
    """Recognize only a complete, currently displayed Claude permission menu."""
    text = re.sub(r"[^\S\r\n\v\f\x85\u2028\u2029]", " ", screen)
    lines = text.splitlines()
    questions = [i for i, line in enumerate(lines) if line.strip() == "Do you want to proceed?"]
    if not questions:
        return None
    # A status spinner/previous transcript can redraw above the dialog without
    # changing what the user is approving. Anchor to a complete dialog header,
    # while retaining every tool name, argument, description and choice below
    # it. A cropped menu without its request must never be auto-confirmed.
    # Hook confirmation dialogs use a tool-name header (e.g. ToolSearch).
    # Match the corresponding notice below it so cropped/arbitrary text is
    # never treated as the missing request header.
    hook_headers = {}
    for i in range(questions[-1]):
        match = re.fullmatch(r"\s*[│|]?\s*Hook PreToolUse:([A-Za-z][\w:.-]*) requires confirmation for this tool:\s*", lines[i])
        if match:
            hook_headers[match.group(1)] = i
    headers = [i for i in range(questions[-1])
               if re.fullmatch(r"\s*(?:Tool use|Bash command|Run command)\s*", lines[i])
               or hook_headers.get(lines[i].strip(), -1) > i]
    if not headers:
        return None
    dialog_start = headers[-1]
    start = questions[-1] + 1
    footers = [i for i in range(start, len(lines)) if re.fullmatch(r"\s*Esc to cancel(?:\s*·\s*Tab to amend)?\s*", lines[i])]
    if not footers or any(line.strip() for line in lines[footers[-1] + 1:]):
        return None
    choices, selected = [], []
    identity = list(lines)
    for i in range(start, footers[-1]):
        match = re.fullmatch(r"\s*([❯›>])?\s*([1-3])\.\s+(.+)", lines[i])
        if not match:
            continue
        number, label = match.group(2), match.group(3).strip()
        choices.append((number, label))
        if match.group(1):
            selected.append(number)
        # Selection changes are expected; the complete request must stay put.
        identity[i] = f"{number}. {label}"
    if ([number for number, _ in choices] not in (["1", "2"], ["1", "2", "3"])
            or choices[0][1] != "Yes"
            or (len(choices) == 3 and not choices[1][1].startswith("Yes"))
            or choices[-1][1] != "No" or len(selected) != 1):
        return None
    return {"choices": tuple(number for number, _ in choices), "selected": selected[0],
            "identity": "\n".join(identity[dialog_start:]).strip()}


def _is_incomplete_permission_screen(screen: str) -> bool:
    return bool(re.search(r"(?m)^\s*Do you want to proceed\?\s*$", screen or "")
                and re.search(r"(?:^|\n)\s*Esc to cancel(?:\s*·\s*Tab to amend)?\s*$", screen or "")
                and not _session_permission_menu(screen))


async def _expand_overview_permission_screen(session_id: str) -> str:
    """Resize only an unowned PTY and wait for its actual current redraw."""
    lifetime = _terminal_streams.get(session_id)
    result = pty_mgr.expand_unowned_geometry(session_id)
    if not result:
        return "unavailable"
    if not result["changed"]:
        return result["state"]
    previous = None
    for _ in range(30):
        await _asyncio.sleep(0.05)
        if not pty_mgr.is_alive(session_id) or _terminal_streams.get(session_id) is not lifetime:
            return "unavailable"
        menu = _session_permission_menu(capture_proc.get_screen(session_id))
        if menu and previous == menu["identity"]:
            return "ready"
        previous = menu["identity"] if menu else None
    return "incomplete"


_session_prompt_replies: dict[str, tuple] = {}


async def _send_guarded_session_prompt(session_id: str, body: dict, delivery_failed) -> web.Response:
    """Reply to the screen the user reviewed, without clearing a TUI question."""
    expected = body.get("expected_screen")
    message = body["message"].strip()
    if (not isinstance(expected, str) or not expected.strip() or body.get("raw")
            or not message or len(message) > 2000 or not body["message"].isprintable()):
        return web.json_response({"error": "A current screen and a single printable reply are required.",
                                  "code": "invalid_session_prompt_reply"}, status=400)
    expected = _canonical_prompt_screen(expected)
    lifetime = _terminal_streams.get(session_id)

    def current_screen():
        if not pty_mgr.is_alive(session_id) or _terminal_streams.get(session_id) is not lifetime:
            return ""
        try:
            return _canonical_prompt_screen(capture_proc.get_screen(session_id) or "")
        except Exception:
            return ""

    def stale(*, partial=False):
        return web.json_response({
            "error": ("The question changed after input was typed. Review the current session before replying again."
                      if partial else "The question changed. Review the current session before replying."),
            "code": "stale_session_prompt", "session_id": session_id, "partial": partial,
        }, status=409)

    screen = current_screen()
    menu = _session_permission_menu(screen)
    expected_menu = _session_permission_menu(expected)
    same_request = (menu and expected_menu and menu["identity"] == expected_menu["identity"])
    if ((screen != expected and not same_request)
            or _session_prompt_replies.get(session_id) == (lifetime, expected)):
        return stale()
    if _is_incomplete_permission_screen(screen):
        return web.json_response({"error": "The complete permission request is not visible yet. Refresh before replying.",
                                  "code": "incomplete_session_prompt"}, status=409)
    if (menu and message not in menu["choices"]) or (not menu and body.get("prompt_reply") is not True):
        return web.json_response({"error": "Choose an option from the current question, or enter an explicit manual reply.",
                                  "code": "invalid_session_prompt_reply"}, status=400)

    # Claim this exact screen before the first write so double clicks cannot
    # confirm a second question while the CLI is still redrawing the first.
    if len(_session_prompt_replies) >= 256:
        _session_prompt_replies.pop(next(iter(_session_prompt_replies)))
    _session_prompt_replies[session_id] = (lifetime, expected)

    if menu:
        target = int(message)
        while int(menu["selected"]) != target:
            screen = current_screen()
            current = _session_permission_menu(screen)
            if not current or current["identity"] != menu["identity"] or current["selected"] != menu["selected"]:
                return stale()
            direction = 1 if target > int(current["selected"]) else -1
            if not pty_mgr.write(session_id, b"\x1b[B" if direction > 0 else b"\x1b[A"):
                _session_prompt_replies.pop(session_id, None)
                return delivery_failed("selection")
            next_selection = str(int(current["selected"]) + direction)
            for _ in range(20):
                await _asyncio.sleep(0.05)
                redrawn = _session_permission_menu(current_screen())
                if redrawn and redrawn["identity"] == menu["identity"] and redrawn["selected"] == next_selection:
                    menu = redrawn
                    break
                if redrawn and redrawn["identity"] != menu["identity"]:
                    return stale()
            else:
                return stale()
        # No await between the final exact menu check and Enter.
        current = _session_permission_menu(current_screen())
        if not current or current["identity"] != menu["identity"] or current["selected"] != message:
            return stale()
        if not pty_mgr.write(session_id, b"\r"):
            _session_prompt_replies.pop(session_id, None)
            return delivery_failed("submit")
    else:
        if current_screen() != expected:
            return stale()
        if not pty_mgr.write(session_id, message.encode("utf-8")):
            _session_prompt_replies.pop(session_id, None)
            return delivery_failed("text")
        await _asyncio.sleep(0.2)
        screen = current_screen()
        # A text question may echo the reply before Enter. Only that one
        # insertion is allowed; a different prompt never receives Enter.
        unchanged = screen == expected
        echoed = any(_canonical_prompt_screen(screen[:m.start()] + screen[m.end():]) == expected
                     for m in re.finditer(re.escape(message), screen))
        if not unchanged and not echoed:
            return stale(partial=True)
        if not pty_mgr.write(session_id, b"\r"):
            return delivery_failed("submit", partial=True)
    return web.json_response({"ok": True, "session_id": session_id})


async def send_session_input(request: web.Request) -> web.Response:
    """Type text into a running session's PTY. Used by MCP server's send_message tool."""
    import shell_session as _shell_session  # plain terminals (cli_type "shell")
    session_id = request.match_info["id"]
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid JSON body"}, status=400)
    if not isinstance(body, dict):
        return web.json_response({"error": "expected JSON object"}, status=400)
    message = body.get("message", "")
    if not isinstance(message, str) or not message:
        return web.json_response({"error": "message required"}, status=400)

    def delivery_failed(phase: str, *, partial: bool = False) -> web.Response:
        return web.json_response({
            "error": (
                "Input was typed but could not be submitted. Check the session before trying again."
                if partial else "The session could not accept this input. Your message was not submitted."
            ),
            "code": "input_delivery_failed",
            "session_id": session_id,
            "phase": phase,
            "partial": partial,
        }, status=503)

    config = await _get_visible_session_for_request(session_id, request)
    if not config:
        return web.json_response({"error": "session not found"}, status=404)

    ctx = get_auth(request)
    mode_reason = _terminal_control_violation(ctx, config, "input")
    if mode_reason:
        await _record_terminal_mode_violation(
            ctx, config, "input", mode_reason, request.path
        )
        return web.json_response(
            {"error": f"Mode-blocked: {mode_reason}"}, status=403
        )

    if _shell_session.is_shell_session(config):
        # Plain terminal: type the line and press Enter (raw: as given).
        if not pty_mgr.is_alive(session_id):
            return web.json_response({"error": "session not running"}, status=400)
        data = message if body.get("raw") else message.rstrip("\r\n") + "\r"
        if not pty_mgr.write(session_id, data.encode("utf-8")):
            return delivery_failed("text")
        return web.json_response({"ok": True, "session_id": session_id})

    cli_type = await _session_cli_type(session_id)
    if message.strip().split(maxsplit=1)[:1] == ["/compact"]:
        from hooks import get_session_logical_status
        state = get_session_logical_status(session_id, pty_mgr.is_alive(session_id), "idle")
        if state not in {"idle", "stopped"} or not pty_mgr.is_alive(session_id):
            return web.json_response({"error": "Wait until this session is idle before compacting context.", "code": "session_busy"}, status=409)
    if "expected_screen" in body or body.get("prompt_reply"):
        if not pty_mgr.is_alive(session_id):
            return web.json_response({"error": "session not running"}, status=400)
        return await _send_guarded_session_prompt(session_id, body, delivery_failed)
    if _is_auth_recovery_input(message):
        await _broadcast_auth_recovery(
            session_id,
            cli_type,
            intercepted_login=True,
        )
        return web.json_response({
            "ok": True,
            "session_id": session_id,
            "intercepted": True,
            "message": "Opened IVE login recovery actions.",
        })

    if not pty_mgr.is_alive(session_id):
        return web.json_response({"error": "session not running"}, status=400)

    # Look up CLI type — Gemini's TUI handles escape sequences differently
    # than Claude Code's Ink-based TUI, so we use CLI-specific input strategies.
    # Keep this path behaviorally aligned with frontend sendTerminalCommand:
    # clear input first, send text, then submit Enter in a separate write.
    # Combining text + CR lets some Ink-style TUIs treat the CR as pasted
    # content and leave the prompt sitting unsubmitted.
    raw = bool(body.get("raw"))
    if raw:
        if not pty_mgr.write(session_id, message.encode("utf-8")):
            return delivery_failed("text")
        return web.json_response({"ok": True, "session_id": session_id})

    control_reply = message.strip().lower() in {"1", "2", "3", "y", "yes", "n", "no"}
    if control_reply:
        if not pty_mgr.write(session_id, message.encode("utf-8")):
            return delivery_failed("text")
        await _asyncio.sleep(0.2)
        if not pty_mgr.write(session_id, b"\r"):
            return delivery_failed("submit", partial=True)
        return web.json_response({"ok": True, "session_id": session_id})

    ready_timeout = body.get("ready_timeout")
    if ready_timeout is None:
        ready_timeout = 8 if cli_type in {"antigravity", "codex"} else 0
    try:
        ready_timeout = max(0.0, min(float(ready_timeout), 30.0))
    except (TypeError, ValueError):
        ready_timeout = 0
    ready = await _wait_for_cli_input_ready(session_id, cli_type, ready_timeout)
    startup_blocker = _detect_cli_startup_blocker(cli_type, _startup_blocker_text(session_id))
    if startup_blocker and startup_blocker.get("type") == "auth_error":
        startup_blocker = None  # native CLI validates current credentials; replay cannot lock input
    if startup_blocker and not body.get("allow_startup_prompt"):
        if cli_type == "codex" and startup_blocker.get("type") == "update_required":
            for _ in range(3):
                if not pty_mgr.is_alive(session_id):
                    break
                pty_mgr.write(session_id, b"\x1b")
                await _asyncio.sleep(0.15)
            return web.json_response({
                "error": "Codex update prompt dismissed; waiting for input prompt.",
                "session_id": session_id,
                "state": "busy",
                "startup_blocker": startup_blocker,
            }, status=409)
        return web.json_response({
            "error": "session_startup_blocked",
            "session_id": session_id,
            "startup_blocker": startup_blocker,
        }, status=409)
    if ready_timeout > 0 and not ready:
        return web.json_response({
            "error": f"{cli_type} is still generating; wait until it returns to the prompt.",
            "session_id": session_id,
            "state": "busy",
        }, status=409)

    if cli_type == "gemini":
        if not pty_mgr.write(session_id, b"\x15"):  # Ctrl-U; safe line clear for Gemini.
            return delivery_failed("clear")
        clean = message.replace("\n", " ").replace("\r", " ")
        payload = clean.encode("utf-8")
    else:
        if not pty_mgr.write(session_id, b"\x1b" + b"\x7f" * 50):
            return delivery_failed("clear")
        payload = message.encode("utf-8")
        if "\n" in message or "\r" in message:
            payload = b"\x1b[200~" + payload + b"\x1b[201~"

    await _asyncio.sleep(0.3)
    if not pty_mgr.write(session_id, payload):
        return delivery_failed("text")
    submit_delay = 0.3
    if cli_type in {"codex", "antigravity"}:
        submit_delay = 0.8
    if len(payload) > 120:
        submit_delay = max(submit_delay, min(1.5, len(payload) / 600))
    await _asyncio.sleep(submit_delay)
    if not pty_mgr.write(session_id, b"\r"):
        return delivery_failed("submit", partial=True)
    return web.json_response({"ok": True, "session_id": session_id})


async def broadcast_input(request: web.Request) -> web.Response:
    """Type text into multiple sessions' PTYs."""
    body = await request.json()
    session_ids = body.get("session_ids", [])
    message = body.get("message", "")
    if not isinstance(message, str) or not message or not isinstance(session_ids, list) or not session_ids or not all(isinstance(sid, str) for sid in session_ids):
        return web.json_response({"error": "session_ids and message required"}, status=400)

    sent = []
    accepted = []
    failed = []
    mode_blocked = []
    msg_bytes = message.encode("utf-8")
    for sid in dict.fromkeys(session_ids):
        config = await get_session_config(sid)
        if not config or not _session_visible_to_request(config, request):
            failed.append(sid)
            continue
        ctx = get_auth(request)
        mode_reason = _terminal_control_violation(ctx, config, "broadcast")
        if mode_reason:
            mode_blocked.append(sid)
            await _record_terminal_mode_violation(
                ctx, config, "broadcast", mode_reason, request.path
            )
            continue
        if pty_mgr.is_alive(sid):
            # Split text and \r — a combined blob can be paste-detected
            # by Ink and the trailing CR dropped, leaving the prompt
            # typed but never submitted.
            payload = msg_bytes
            if config.get("cli_type") == "gemini":
                payload = message.replace("\r", " ").replace("\n", " ").encode("utf-8")
            elif "\n" in message or "\r" in message:
                payload = b"\x1b[200~" + msg_bytes + b"\x1b[201~"
            if pty_mgr.write(sid, payload):
                accepted.append(sid)
            else:
                failed.append(sid)
        else:
            failed.append(sid)
    if accepted:
        await _asyncio.sleep(0.4)
        for sid in accepted:
            if pty_mgr.is_alive(sid) and pty_mgr.write(sid, b"\r"):
                sent.append(sid)
            else:
                failed.append(sid)
    if sent:
        await bus.emit(CommanderEvent.COMMANDER_BROADCAST, {
            "session_ids": sent,
            "session_count": len(sent),
            "message_length": len(message),
        }, source="api", actor="user")
    if mode_blocked and not sent and not failed:
        return web.json_response(
            {"error": "Mode-blocked", "blocked": mode_blocked}, status=403
        )
    result = {"ok": bool(sent) and not failed and not mode_blocked, "sent_to": sent,
              "mode_blocked": mode_blocked, "failed": failed,
              "partially_delivered": [sid for sid in accepted if sid in failed]}
    if not result["ok"]:
        result["error"] = "Some messages were not delivered. Check each session before retrying."
    return web.json_response(result, status=200 if sent else 409)


# ─── REST: URL Screenshot ─────────────────────────────────────────────

def _check_screenshot_tools() -> str | None:
    """Return the available screenshot tool name, or None if nothing is installed."""
    import shutil
    if shutil.which("webkit2png"):
        return "webkit2png"
    # Check if playwright + chromium are importable
    import subprocess
    from helper_command import python_command
    try:
        proc = subprocess.run(
            python_command("-c", "from playwright.sync_api import sync_playwright"),
            capture_output=True, timeout=5
        )
        if proc.returncode == 0:
            return "playwright"
    except (FileNotFoundError, subprocess.TimeoutExpired):
        pass
    return None


# ─── REST: Preview Proxy ──────────────────────────────────────────────

async def preview_proxy(request: web.Request) -> web.Response:
    """Reverse-proxy a URL stripping X-Frame-Options / CSP so it loads in an iframe.
    Sub-resources resolve against the original server via an injected <base> tag."""
    from urllib.parse import urlparse, urljoin
    import re

    url = request.query.get("url", "").strip()
    if not url:
        return web.json_response({"error": "url required"}, status=400)
    if not url.startswith(("http://", "https://")):
        url = "https://" + url

    parsed = urlparse(url)
    base_origin = f"{parsed.scheme}://{parsed.netloc}"

    try:
        timeout = aiohttp.ClientTimeout(total=15)
        async with aiohttp.ClientSession(timeout=timeout) as session:
            async with session.get(url, allow_redirects=True, ssl=False) as resp:
                body = await resp.read()
                ct = resp.content_type or "text/html"

                # Build response headers — copy safe ones, drop frame-blockers
                drop = {
                    "x-frame-options", "content-security-policy",
                    "content-security-policy-report-only",
                    "content-type", "content-length",
                    "transfer-encoding", "content-encoding",
                }
                headers = {
                    k: v for k, v in resp.headers.items()
                    if k.lower() not in drop
                }

                # For HTML: inject <base> + fetch/XHR interceptor so the
                # proxied page can load sub-resources and make API calls
                if "html" in ct:
                    html = body.decode("utf-8", errors="replace")
                    import json as _json
                    base_tag = f'<base href="{base_origin}/">'
                    # Intercept fetch/XHR so JS API calls to the remote
                    # origin go through our proxy instead of being CORS-blocked
                    intercept_script = (
                        '<script data-preview-proxy>'
                        '(function(){'
                        'var R=' + _json.dumps(base_origin) + ';'
                        'var P=window.location.origin+"/api/preview-proxy?url=";'
                        'function rw(u){'
                        'try{var o=new URL(u,R);if(o.origin===R)return P+encodeURIComponent(o.href)}catch(e){}'
                        'return null}'
                        'var oF=window.fetch;'
                        'window.fetch=function(i,n){'
                        'if(typeof i==="string"){var r=rw(i);if(r)i=r}'
                        'else if(i instanceof Request){var r=rw(i.url);if(r)i=new Request(r,i)}'
                        'return oF.call(this,i,n)};'
                        'var oO=XMLHttpRequest.prototype.open;'
                        'XMLHttpRequest.prototype.open=function(m,u){'
                        'var r=rw(u);if(r)arguments[1]=r;'
                        'return oO.apply(this,arguments)};'
                        '})();'
                        '</script>'
                    )
                    inject = base_tag + intercept_script
                    if "<head" in html.lower():
                        html = re.sub(
                            r"(<head[^>]*>)", r"\1" + inject, html, count=1, flags=re.IGNORECASE
                        )
                    elif "<html" in html.lower():
                        html = re.sub(
                            r"(<html[^>]*>)", r"\1<head>" + inject + "</head>", html, count=1, flags=re.IGNORECASE
                        )
                    else:
                        html = inject + html
                    body = html.encode("utf-8")

                return web.Response(
                    body=body,
                    status=resp.status,
                    content_type=ct,
                    headers=headers,
                )
    except aiohttp.ClientConnectorError:
        return web.json_response({"error": f"Cannot connect to {base_origin}"}, status=502)
    except aiohttp.ClientError as e:
        return web.json_response({"error": str(e)}, status=502)
    except Exception as e:
        return web.json_response({"error": f"Proxy error: {e}"}, status=500)


def _capture_url_to_png(url: str, filepath) -> dict:
    """Capture `url` to `filepath` (PNG). Tries webkit2png then playwright.
    Returns {"ok": True} on success, or {"error": str, "reason": "no_tools"|"unreachable"|"timeout"|"capture_failed"}."""
    import subprocess

    # Sanitize: reject URLs with characters that could break subprocess args
    if any(c in url for c in ("'", '"', ';', '`', '$', '\\', '\n', '\r')):
        return {"error": f"Invalid characters in URL", "reason": "capture_failed"}

    try:
        # Method 1: macOS webkit2png (if installed)
        subprocess.run(
            ["webkit2png", "--fullsize", "--filename", str(filepath).replace('.png', ''), url],
            capture_output=True, timeout=30
        )
        fullpath = filepath.parent / (filepath.stem + "-full.png")
        if fullpath.exists():
            fullpath.rename(filepath)
        elif not filepath.exists():
            raise FileNotFoundError("webkit2png failed")
        return {"ok": True}
    except (FileNotFoundError, subprocess.TimeoutExpired):
        pass

    # Method 2: playwright — pass URL and filepath via env to avoid injection
    import os
    env = {**os.environ, "_SCREENSHOT_URL": url, "_SCREENSHOT_PATH": str(filepath)}
    from helper_command import python_command
    try:
        proc = subprocess.run(
            python_command("-c", """
import asyncio, os
from playwright.async_api import async_playwright
async def main():
    url = os.environ["_SCREENSHOT_URL"]
    path = os.environ["_SCREENSHOT_PATH"]
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        page = await browser.new_page(viewport={"width": 1280, "height": 800})
        await page.goto(url, wait_until="networkidle", timeout=15000)
        await page.screenshot(path=path, full_page=False)
        await browser.close()
asyncio.run(main())
"""),
            capture_output=True, text=True, timeout=30, env=env,
        )
        if filepath.exists():
            return {"ok": True}
        # Playwright ran but failed — parse stderr for clues
        stderr = (proc.stderr or "").strip()
        if "ERR_CONNECTION_REFUSED" in stderr or "ERR_NAME_NOT_RESOLVED" in stderr or "NS_ERROR_UNKNOWN_HOST" in stderr:
            host = url.split("//")[-1].split("/")[0]
            return {"error": f"Site unreachable: {host}", "reason": "unreachable"}
        if "Timeout" in stderr or "timeout" in stderr:
            return {"error": f"Page load timed out for {url}", "reason": "timeout"}
        if "Executable doesn't exist" in stderr or "browserType.launch" in stderr:
            return {"error": "Chromium not installed. Run: playwright install chromium", "reason": "no_tools"}
        return {"error": f"Screenshot capture failed", "reason": "capture_failed", "detail": stderr[-300:] if stderr else ""}
    except FileNotFoundError:
        return {"error": "No screenshot tool available. Install playwright: pip3 install playwright && playwright install chromium", "reason": "no_tools"}
    except subprocess.TimeoutExpired:
        return {"error": f"Screenshot timed out after 30s for {url}", "reason": "timeout"}


async def _run_capture(url: str, filepath) -> dict:
    """Run _capture_url_to_png in a thread so we don't block the event loop."""
    import asyncio
    loop = asyncio.get_event_loop()
    return await loop.run_in_executor(None, _capture_url_to_png, url, filepath)


async def take_screenshot(request: web.Request) -> web.Response:
    """Take a screenshot of a URL using macOS webkit or playwright if available."""
    import time

    url = request.query.get("url", "").strip()
    if not url:
        return web.json_response({"error": "url required"}, status=400)
    # Normalize: add https:// if no protocol specified
    if not url.startswith(("http://", "https://")):
        url = "https://" + url

    from config import DATA_DIR
    paste_dir = DATA_DIR / "pastes"
    paste_dir.mkdir(parents=True, exist_ok=True)
    filename = f"screenshot_{int(time.time())}.png"
    filepath = paste_dir / filename

    result = await _run_capture(url, filepath)
    if not result.get("ok"):
        status = 502 if result.get("reason") == "unreachable" else 504 if result.get("reason") == "timeout" else 500
        return web.json_response({"error": result["error"], "reason": result.get("reason", "capture_failed")}, status=status)

    return web.FileResponse(filepath, headers={
        "Content-Type": "image/png",
        "Content-Disposition": f'attachment; filename="{filename}"',
    })


async def get_workspace_preview_screenshot(request: web.Request) -> web.Response:
    """Screenshot the preview_url configured for a workspace.
    Convenience endpoint so the Commander MCP only needs a workspace_id."""
    import time
    ws_id = request.match_info["id"]
    db = await get_db()
    try:
        cur = await db.execute("SELECT preview_url FROM workspaces WHERE id = ?", (ws_id,))
        row = await cur.fetchone()
    finally:
        await db.close()
    if not row:
        return web.json_response({"error": "workspace not found"}, status=404)
    url = (row["preview_url"] or "").strip()
    if not url:
        return web.json_response({"error": "no preview_url set for this workspace"}, status=400)
    # Normalize: add https:// if no protocol specified
    if not url.startswith(("http://", "https://")):
        url = "https://" + url

    from config import DATA_DIR
    paste_dir = DATA_DIR / "pastes"
    paste_dir.mkdir(parents=True, exist_ok=True)
    filename = f"preview_{ws_id}_{int(time.time())}.png"
    filepath = paste_dir / filename

    result = await _run_capture(url, filepath)
    if not result.get("ok"):
        status = 502 if result.get("reason") == "unreachable" else 504 if result.get("reason") == "timeout" else 500
        return web.json_response({"error": result["error"], "reason": result.get("reason", "capture_failed")}, status=status)

    return web.FileResponse(filepath, headers={
        "Content-Type": "image/png",
        "Content-Disposition": f'inline; filename="{filename}"',
    })


async def get_workspace_runtime_env(request: web.Request) -> web.Response:
    ws_id = request.match_info["id"]
    db = await get_db()
    try:
        cur = await db.execute("SELECT path FROM workspaces WHERE id = ?", (ws_id,))
        row = await cur.fetchone()
    finally:
        await db.close()
