async def list_workspace_ports(request: web.Request) -> web.Response:
    ws_id = request.match_info["id"]
    scan = str(request.query.get("scan", "")).lower() in {"1", "true", "yes", "on"}
    active_only = str(request.query.get("active_only", "1")).lower() not in {"0", "false", "no"}
    db = await get_db()
    try:
        cur = await db.execute("SELECT id FROM workspaces WHERE id = ?", (ws_id,))
        if not await cur.fetchone():
            return web.json_response({"error": "workspace not found"}, status=404)
        import port_leases
        leases = await port_leases.list_leases(db, ws_id, active_only=active_only)
        await db.commit()
    finally:
        await db.close()

    blocked_ports = []
    if scan:
        import port_leases
        start_port = int(request.query.get("start_port") or port_leases.DEFAULT_START_PORT)
        end_port = int(request.query.get("end_port") or port_leases.DEFAULT_END_PORT)
        if end_port < start_port:
            start_port, end_port = end_port, start_port
        # Keep ad hoc scans bounded; lease requests still search the full requested range.
        end_port = min(end_port, start_port + 100)
        active_ports = {int(lease["port"]) for lease in leases if lease.get("status") == "active"}
        for port in range(start_port, end_port + 1):
            probe = port_leases.probe_port(port)
            if probe.get("occupied") or port in active_ports:
                if port in active_ports:
                    probe = {"port": port, "occupied": True, "reason": "leased"}
                blocked_ports.append(probe)

    return web.json_response({
        "workspace_id": ws_id,
        "leases": leases,
        "blocked_ports": blocked_ports,
    })


async def lease_workspace_port(request: web.Request) -> web.Response:
    ws_id = request.match_info["id"]
    try:
        body = await request.json()
    except Exception:
        body = {}
    body = body if isinstance(body, dict) else {}
    db = await get_db()
    try:
        cur = await db.execute("SELECT id FROM workspaces WHERE id = ?", (ws_id,))
        if not await cur.fetchone():
            return web.json_response({"error": "workspace not found"}, status=404)
        import port_leases
        result = await port_leases.lease_port(
            db,
            workspace_id=ws_id,
            session_id=body.get("session_id"),
            task_id=body.get("task_id"),
            preferred_port=body.get("preferred_port") or body.get("port"),
            start_port=body.get("start_port"),
            end_port=body.get("end_port"),
            label=body.get("label"),
            ttl_seconds=body.get("ttl_seconds"),
            metadata=body.get("metadata") if isinstance(body.get("metadata"), dict) else {},
            strict=bool(body.get("strict")),
        )
        await db.commit()
    finally:
        await db.close()
    status = 201 if result.get("ok") else 409
    return web.json_response(result, status=status)


async def heartbeat_port_lease(request: web.Request) -> web.Response:
    lease_id = request.match_info["lease_id"]
    try:
        body = await request.json()
    except Exception:
        body = {}
    body = body if isinstance(body, dict) else {}
    db = await get_db()
    try:
        import port_leases
        lease = await port_leases.heartbeat_lease(db, lease_id, body.get("ttl_seconds"))
        await db.commit()
    finally:
        await db.close()
    if not lease or lease.get("status") != "active":
        return web.json_response({"error": "active lease not found"}, status=404)
    return web.json_response({"ok": True, "lease": lease})


async def release_port_lease(request: web.Request) -> web.Response:
    lease_id = request.match_info["lease_id"]
    db = await get_db()
    try:
        import port_leases
        lease = await port_leases.release_lease(db, lease_id)
        await db.commit()
    finally:
        await db.close()
    if not lease:
        return web.json_response({"error": "lease not found"}, status=404)
    return web.json_response({"ok": True, "lease": lease})


async def fleet_ports_overview(request: web.Request) -> web.Response:
    """Read-only fleet-wide port/sandbox-allocation overview (Wave 5).

    Lists ALL active port leases across every workspace (port_leases.list_leases
    already supports workspace_id=None => whole fleet), grouped by workspace.
    Optional ?runtime=1 appends a read-only capability probe of the configured
    sandbox runtime + egress/daytona backings (no side effects, no spawn). GET
    only; no writes beyond the lease-cleanup the list path already performs.
    """
    active_only = str(request.query.get("active_only", "1")).lower() not in {"0", "false", "no"}
    want_runtime = str(request.query.get("runtime", "")).lower() in {"1", "true", "yes", "on"}
    db = await get_db()
    try:
        import port_leases
        leases = await port_leases.list_leases(db, workspace_id=None, active_only=active_only)
        await db.commit()
    finally:
        await db.close()

    # Group by workspace, surfacing only non-sensitive lease fields.
    by_workspace: dict[str, list] = {}
    safe_leases: list[dict] = []
    for lease in leases:
        ws_id = lease.get("workspace_id") or "_unassigned"
        slim = {
            "id": lease.get("id"),
            "workspace_id": lease.get("workspace_id"),
            "session_id": lease.get("session_id"),
            "task_id": lease.get("task_id"),
            "port": lease.get("port"),
            "host": lease.get("host"),
            "label": lease.get("label"),
            "status": lease.get("status"),
            "preview_url": lease.get("preview_url"),
            "expires_at": lease.get("expires_at"),
        }
        safe_leases.append(slim)
        by_workspace.setdefault(ws_id, []).append(slim)

    payload = {
        "leases": safe_leases,
        "by_workspace": by_workspace,
        "count": len(safe_leases),
    }

    if want_runtime:
        # Read-only capability probe — no spawn, no network, no install.
        import os as _os
        runtime = (_os.environ.get("SANDBOX_RUNTIME") or "process").strip().lower()
        daytona_available = False
        try:
            import sandbox_daytona
            daytona_available = sandbox_daytona.available()
        except Exception:
            daytona_available = False
        egress_fmt = None
        try:
            import egress_policy
            egress_enforced = egress_policy.is_egress_enforced()
            fmt, _path = egress_policy.detect_proxy()
            egress_fmt = fmt
        except Exception:
            egress_enforced = False
        try:
            import shutil as _shutil
            docker_available = bool(_shutil.which("docker"))
        except Exception:
            docker_available = False
        payload["runtime"] = {
            "sandbox_runtime": runtime,
            "egress_enforced": bool(egress_enforced),
            "egress_proxy_detected": egress_fmt,
            "docker_available": docker_available,
            "daytona_available": daytona_available,
        }

    return web.json_response(payload)


async def fleet_sandbox_exec(request: web.Request) -> web.Response:
    """One-shot confined command exec through the SELECTED sandbox runtime (Wave 5).

    This is the real runtime caller for sandbox_runtime.run_sandboxed (which had
    none): it dispatches via select_runtime() so 'process' uses the in-process
    confined subprocess and 'daytona' uses the (inert) adapter. NON-interactive
    only — the PTY path stays on wrap_command_for_sandbox.

    FAIL-CLOSED + gated: this endpoint is DISABLED unless SANDBOX_EXEC_API is
    truthy (default off => 404), so it adds no exec surface by default. When the
    selected runtime can't provide isolation it returns its own 126/127 deny dict
    (run_sandboxed never raises across the boundary).
    """
    import os as _os
    if _os.environ.get("SANDBOX_EXEC_API", "").strip().lower() not in {"1", "true", "yes", "on"}:
        return web.json_response({"error": "sandbox exec API disabled"}, status=404)
    try:
        body = await request.json()
    except Exception:
        body = {}
    body = body if isinstance(body, dict) else {}
    cmd = body.get("cmd")
    if not cmd:
        return web.json_response({"error": "cmd required"}, status=400)
    cwd = body.get("cwd")
    # Confine cwd to a workspace path when one is supplied; never honor an
    # arbitrary absolute path outside known workspaces.
    ws_id = body.get("workspace_id")
    if ws_id:
        db = await get_db()
        try:
            cur = await db.execute("SELECT path FROM workspaces WHERE id = ?", (ws_id,))
            row = await cur.fetchone()
        finally:
            await db.close()
        if not row:
            return web.json_response({"error": "workspace not found"}, status=404)
        cwd = dict(row).get("path") or cwd

    try:
        timeout = float(body.get("timeout") or 30)
    except (TypeError, ValueError):
        timeout = 30.0
    env_allowlist = body.get("env_allowlist") or ()
    allowed_hosts = body.get("allowed_hosts") or ()
    network = body.get("network") or "none"

    import sandbox_runtime
    # Runs OFF the event loop so the confined subprocess can't block the server.
    result = await asyncio.to_thread(
        sandbox_runtime.run_in_selected_runtime,
        cmd,
        cwd=cwd,
        env_allowlist=tuple(env_allowlist) if isinstance(env_allowlist, (list, tuple)) else (),
        timeout=timeout,
        network=str(network),
        allowed_hosts=tuple(allowed_hosts) if isinstance(allowed_hosts, (list, tuple)) else (),
    )
    return web.json_response({"ok": result.get("returncode") == 0, "result": result})


# ─── Alloy Runtime Registry + Dynamic MCP Bridge ─────────────────────────

async def _alloy_workspace_for_request(request: web.Request, workspace_id: str) -> tuple[dict | None, web.Response | None]:
    caller = await _resolve_caller(request)
    if caller and caller.get("workspace_id") and caller["workspace_id"] != workspace_id:
        return None, web.json_response({"error": "workspace mismatch"}, status=403)
    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT id, path, alloy_enabled FROM workspaces WHERE id = ?",
            (workspace_id,),
        )
        row = await cur.fetchone()
    finally:
        await db.close()
    if not row:
        return None, web.json_response({"error": "workspace not found"}, status=404)
    ws = dict(row)
    if not ws.get("alloy_enabled"):
        return None, web.json_response({"error": "alloy disabled for workspace"}, status=403)
    return ws, None


def _alloy_decode_row(row, *, redact: bool = True) -> dict:
    from alloy_runtime import parse_json_dict, parse_json_list, redact_env
    item = dict(row)
    item["args"] = parse_json_list(item.get("args"))
    env = parse_json_dict(item.get("env"))
    item["env"] = redact_env(env) if redact else env
    cache = item.get("tool_cache")
    try:
        item["tool_cache"] = json.loads(cache) if cache else None
    except Exception:
        item["tool_cache"] = None
    return item


async def _get_alloy_server_row(workspace_id: str, server_ref: str):
    db = await get_db()
    try:
        cur = await db.execute(
            """SELECT * FROM alloy_servers
               WHERE workspace_id = ? AND (id = ? OR slug = ?)""",
            (workspace_id, server_ref, server_ref),
        )
        row = await cur.fetchone()
    finally:
        await db.close()
    return row


def _alloy_manifest_payload(server: dict, workspace_path: str) -> dict:
    from alloy_runtime import redact_env
    root = _Path(workspace_path).expanduser().resolve()

    def rel(path_value):
        if not path_value:
            return None
        try:
            return str(_Path(path_value).expanduser().resolve().relative_to(root))
        except Exception:
            return path_value

    return {
        "schema_version": 1,
        "id": server["id"],
        "slug": server["slug"],
        "name": server["name"],
        "description": server.get("description"),
        "command": server["command"],
        "args": server.get("args") or [],
        "cwd": rel(server.get("cwd")),
        "env": redact_env(server.get("env") or {}),
        "paths": {
            "manifest": rel(server.get("manifest_path")),
            "raw_spec": rel(server.get("raw_spec_path")),
            "normalized_spec": rel(server.get("normalized_spec_path")),
            "sdk": rel(server.get("sdk_path")),
            "mcp": rel(server.get("mcp_path")),
        },
        "status": server.get("status") or "registered",
        "updated_at": _utc_now_iso(),
    }


async def list_alloy_servers(request: web.Request) -> web.Response:
    workspace_id = request.match_info["id"]
    _, err = await _alloy_workspace_for_request(request, workspace_id)
    if err:
        return err
    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT * FROM alloy_servers WHERE workspace_id = ? ORDER BY updated_at DESC, created_at DESC",
            (workspace_id,),
        )
        rows = await cur.fetchall()
    finally:
        await db.close()
    return web.json_response([_alloy_decode_row(row) for row in rows])






async def register_alloy_server(request: web.Request) -> web.Response:
    workspace_id = request.match_info["id"]
    ws, err = await _alloy_workspace_for_request(request, workspace_id)
    if err:
        return err
    try:
        body = await request.json()
    except Exception:
        body = {}
    body = body if isinstance(body, dict) else {}
    command = str(body.get("command") or "").strip()
    if not command:
        return web.json_response({"error": "command required"}, status=400)

    from alloy_runtime import resolve_workspace_path, slugify
    caller = await _resolve_caller(request)
    name = str(body.get("name") or body.get("slug") or "Generated API").strip()
    slug = slugify(str(body.get("slug") or name))
    args = body.get("args") or []
    if not isinstance(args, list):
        return web.json_response({"error": "args must be an array"}, status=400)
    env = body.get("env") or {}
    if not isinstance(env, dict):
        return web.json_response({"error": "env must be an object"}, status=400)
    workspace_path = ws["path"]
    try:
        cwd = resolve_workspace_path(workspace_path, body.get("cwd") or ".")
        manifest_path = resolve_workspace_path(
            workspace_path,
            body.get("manifest_path") or f".ive/alloy/{slug}/alloy.json",
        )
        raw_spec_path = resolve_workspace_path(workspace_path, body.get("raw_spec_path")) if body.get("raw_spec_path") else None
        normalized_spec_path = resolve_workspace_path(workspace_path, body.get("normalized_spec_path")) if body.get("normalized_spec_path") else None
        sdk_path = resolve_workspace_path(workspace_path, body.get("sdk_path")) if body.get("sdk_path") else None
        mcp_path = resolve_workspace_path(workspace_path, body.get("mcp_path")) if body.get("mcp_path") else None
    except ValueError as exc:
        return web.json_response({"error": str(exc)}, status=400)

    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT id FROM alloy_servers WHERE workspace_id = ? AND slug = ?",
            (workspace_id, slug),
        )
        existing = await cur.fetchone()
        server_id = (existing["id"] if existing else None) or body.get("id") or str(uuid.uuid4())
        if existing:
            await db.execute(
                """UPDATE alloy_servers
                   SET name = ?, description = ?, command = ?, args = ?, cwd = ?, env = ?,
                       manifest_path = ?, raw_spec_path = ?, normalized_spec_path = ?,
                       sdk_path = ?, mcp_path = ?, status = 'registered', last_error = NULL,
                       created_by_session_id = COALESCE(created_by_session_id, ?),
                       updated_at = datetime('now')
                   WHERE id = ?""",
                (
                    name, body.get("description"), command, json.dumps(args), cwd, json.dumps(env),
                    manifest_path, raw_spec_path, normalized_spec_path, sdk_path, mcp_path,
                    (caller or {}).get("session_id"), server_id,
                ),
            )
        else:
            await db.execute(
                """INSERT INTO alloy_servers
                   (id, workspace_id, slug, name, description, command, args, cwd, env,
                    manifest_path, raw_spec_path, normalized_spec_path, sdk_path, mcp_path,
                    status, created_by_session_id)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'registered', ?)""",
                (
                    server_id, workspace_id, slug, name, body.get("description"), command,
                    json.dumps(args), cwd, json.dumps(env), manifest_path, raw_spec_path,
                    normalized_spec_path, sdk_path, mcp_path, (caller or {}).get("session_id"),
                ),
            )
        await db.commit()
        cur = await db.execute("SELECT * FROM alloy_servers WHERE id = ?", (server_id,))
        row = await cur.fetchone()
        server = _alloy_decode_row(row, redact=False)
        # Wave 1 build→reuse loop: fold the just-registered Alloy row into the
        # Brain's routable pool + emit CAPABILITY_REGISTERED (brain-on gated,
        # swallowed — must never fail the HTTP response). Done on the open db before
        # close so the upsert sees the committed row.
        if extension_host.available("company"):
            await _brain_emit_alloy_capability(db, server_id)
    finally:
        await db.close()

    if body.get("write_manifest", True) is not False and manifest_path:
        payload = _alloy_manifest_payload(server, workspace_path)
        path = _Path(manifest_path)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")

    return web.json_response(_alloy_decode_row(server), status=201)


async def get_alloy_server(request: web.Request) -> web.Response:
    workspace_id = request.match_info["id"]
    server_ref = request.match_info["server_id"]
    _, err = await _alloy_workspace_for_request(request, workspace_id)
    if err:
        return err
    row = await _get_alloy_server_row(workspace_id, server_ref)
    if not row:
        return web.json_response({"error": "alloy server not found"}, status=404)
    return web.json_response(_alloy_decode_row(row))


