async def _run_alloy_mcp_operation(
    workspace_id: str,
    server_ref: str,
    operation: str,
    *,
    tool_name: str | None = None,
    arguments: dict | None = None,
    timeout: float = 30.0,
) -> tuple[dict, int]:
    row = await _get_alloy_server_row(workspace_id, server_ref)
    if not row:
        return {"ok": False, "error": "alloy server not found"}, 404
    server = _alloy_decode_row(row, redact=False)
    from alloy_runtime import call_mcp_once
    result = await call_mcp_once(
        command=server["command"],
        args=server.get("args") or [],
        cwd=server.get("cwd"),
        env=server.get("env") or {},
        operation=operation,
        tool_name=tool_name,
        arguments=arguments or {},
        timeout=timeout,
    )
    db = await get_db()
    try:
        if result.get("ok"):
            tool_cache = result.get("tools") if operation in {"list_tools", "healthcheck"} else None
            if tool_cache is not None:
                await db.execute(
                    """UPDATE alloy_servers
                       SET status = 'healthy', last_error = NULL, tool_cache = ?,
                           last_healthcheck_at = datetime('now'), updated_at = datetime('now')
                       WHERE id = ?""",
                    (json.dumps(tool_cache), server["id"]),
                )
            else:
                await db.execute(
                    """UPDATE alloy_servers
                       SET status = 'healthy', last_error = NULL, updated_at = datetime('now')
                       WHERE id = ?""",
                    (server["id"],),
                )
        else:
            await db.execute(
                """UPDATE alloy_servers
                   SET status = 'error', last_error = ?, updated_at = datetime('now')
                   WHERE id = ?""",
                (result.get("error") or "MCP bridge call failed", server["id"]),
            )
        await db.commit()
        # Wave 1 build→reuse loop: a successful healthcheck/list_tools is the tool's
        # verify-COMPLETION moment — the row is now status='healthy' with a real
        # tool_cache, so the descriptor enters the pool at io_schema_fidelity='full'
        # ("just-built tool composed immediately"). Brain-on gated + swallowed so a
        # registry failure never affects the healthcheck HTTP response.
        if result.get("ok"):
            if extension_host.available("company"):
                await _brain_emit_alloy_capability(db, server["id"])
            # Optional learned-memory sink; local tool health remains independent.
            if (extension_host.available("myelin")
                    and operation in {"list_tools", "healthcheck"}
                    and result.get("tools") is not None):
                await _alloy_write_capability_memory(db, workspace_id, server, result.get("tools"))
    finally:
        await db.close()
    return result, 200 if result.get("ok") else 502


# ── MCP proxy — authenticated stdio↔HTTP adapter ──
#
# HTTP MCP clients can use Alloy's workspace-local STDIO servers. This is the shim in
# between: one JSON-RPC POST surface per Alloy server that terminates HTTP here
# and drives the stdio process behind it (spawn → initialize → op → terminate,
# via alloy_runtime.call_mcp_once — the same one-shot lifecycle every other
# Alloy caller uses). An authenticated remote client can use the configured tunnel:
#   https://<tunnel>/api/mcp-proxy/<workspace_id>/<server_ref>
# AUTH: a dedicated shared secret, independent of the
# UI session auth — set MCP_PROXY_TOKEN and the caller must present it as
# ``Authorization: Bearer <token>`` or ``X-MCP-Token``. With NO token configured
# the shim only accepts OWNER-authenticated local calls — it is never open.

def _mcp_proxy_authorized(request: web.Request) -> bool:
    expected = (os.environ.get("MCP_PROXY_TOKEN") or "").strip()
    if expected:
        auth = request.headers.get("Authorization", "")
        if auth.startswith("Bearer ") and hmac.compare_digest(auth[7:].strip(), expected):
            return True
        supplied = request.headers.get("X-MCP-Token", "")
        return bool(supplied) and hmac.compare_digest(supplied, expected)
    # No dedicated token → owner-only (never an open shim).
    try:
        return bool(get_auth(request).is_owner)
    except Exception:
        return False


def _jsonrpc_error(req_id, code: int, message: str, status: int = 200) -> web.Response:
    return web.json_response(
        {"jsonrpc": "2.0", "id": req_id,
         "error": {"code": code, "message": message}},
        status=status)


async def mcp_proxy_handler(request: web.Request) -> web.Response:
    """POST /api/mcp-proxy/{workspace_id}/{server_ref} — Streamable-HTTP MCP.

    Implements the standard JSON-RPC MCP methods (initialize /
    tools/list / tools/call, plus the initialized notification) over ONE Alloy
    stdio server. Responses are plain application/json (the client accepts
    json-or-SSE; json is the simple, sufficient half)."""
    if not _mcp_proxy_authorized(request):
        return web.json_response({"error": "unauthorized"}, status=401)
    workspace_id = request.match_info["workspace_id"]
    server_ref = request.match_info["server_ref"]
    try:
        msg = await request.json()
    except Exception:
        return _jsonrpc_error(None, -32700, "parse error", status=400)
    if not isinstance(msg, dict) or msg.get("jsonrpc") != "2.0":
        return _jsonrpc_error(None, -32600, "invalid request", status=400)
    method = msg.get("method")
    req_id = msg.get("id")
    params = msg.get("params") if isinstance(msg.get("params"), dict) else {}

    # Notifications (no id) → 202 Accepted with no body (Streamable HTTP).
    if req_id is None and isinstance(method, str) and method.startswith("notifications/"):
        return web.Response(status=202)

    if method == "initialize":
        return web.json_response({
            "jsonrpc": "2.0", "id": req_id,
            "result": {
                "protocolVersion": params.get("protocolVersion") or "2024-11-05",
                "capabilities": {"tools": {}},
                "serverInfo": {"name": f"ive-mcp-proxy/{server_ref}",
                               "version": "1.0.0"},
            },
        })

    if method == "tools/list":
        result, _status = await _run_alloy_mcp_operation(
            workspace_id, server_ref, "list_tools")
        if not result.get("ok"):
            return _jsonrpc_error(
                req_id, -32000, result.get("error") or "list_tools failed")
        return web.json_response({
            "jsonrpc": "2.0", "id": req_id,
            "result": {"tools": result.get("tools") or []},
        })

    if method == "tools/call":
        tool_name = params.get("name")
        if not tool_name:
            return _jsonrpc_error(req_id, -32602, "params.name required")
        arguments = params.get("arguments") if isinstance(
            params.get("arguments"), dict) else {}
        result, _status = await _run_alloy_mcp_operation(
            workspace_id, server_ref, "call_tool",
            tool_name=str(tool_name), arguments=arguments,
            timeout=float(os.environ.get("MCP_PROXY_CALL_TIMEOUT_S") or 60.0),
        )
        if not result.get("ok"):
            return _jsonrpc_error(
                req_id, -32000, result.get("error") or "tools/call failed")
        # call_mcp_once returns the RAW MCP tools/call result — pass it through.
        return web.json_response({
            "jsonrpc": "2.0", "id": req_id,
            "result": result.get("result") or {"content": []},
        })

    return _jsonrpc_error(req_id, -32601, f"method not found: {method}")


