async def alloy_call_tool(request: web.Request) -> web.Response:
    workspace_id = request.match_info["id"]
    server_ref = request.match_info["server_id"]
    _, err = await _alloy_workspace_for_request(request, workspace_id)
    if err:
        return err
    try:
        body = await request.json()
    except Exception:
        body = {}
    body = body if isinstance(body, dict) else {}
    tool_name = str(body.get("tool_name") or "").strip()
    if not tool_name:
        return web.json_response({"error": "tool_name required"}, status=400)
    arguments = body.get("arguments") or {}
    if not isinstance(arguments, dict):
        return web.json_response({"error": "arguments must be an object"}, status=400)
    timeout = float(body.get("timeout") or 30.0)
    timeout = max(1.0, min(timeout, 120.0))
    result, status = await _run_alloy_mcp_operation(
        workspace_id,
        server_ref,
        "call_tool",
        tool_name=tool_name,
        arguments=arguments,
        timeout=timeout,
    )
    return web.json_response(result, status=status)


async def register_workspace_preview(request: web.Request) -> web.Response:
    ws_id = request.match_info["id"]
    try:
        body = await request.json()
    except Exception:
        body = {}
    body = body if isinstance(body, dict) else {}
    db = await get_db()
    try:
        cur = await db.execute("SELECT id FROM workspaces WHERE id = ?", (ws_id,))
        if not await cur.fetchone():
            return web.json_response({"error": "workspace not found"}, status=404)
        import port_leases
        result = await port_leases.register_preview(
            db,
            workspace_id=ws_id,
            lease_id=body.get("lease_id"),
            port=body.get("port"),
            url=body.get("url"),
            session_id=body.get("session_id"),
            task_id=body.get("task_id"),
        )
        await db.commit()
    finally:
        await db.close()
    status = int(result.pop("status", 200)) if not result.get("ok") else 200
    if result.get("ok"):
        await broadcast({
            "type": "workspace_preview_registered",
            "workspace_id": ws_id,
            "preview_url": result.get("preview_url"),
            "lease": result.get("lease"),
        })
    return web.json_response(result, status=status)


# ─── REST: Install Screenshot Tools ──────────────────────────────────

async def install_screenshot_tools(request: web.Request) -> web.Response:
    """Install the full Playwright stack used across IVE.

    Two consumers share `~/Library/Caches/ms-playwright/` but pin their own
    chromium builds, so a single click has to provision both:

    - Python Playwright (in-process screenshots, preview browser, auth cycler)
    - Node `@playwright/mcp` (Tester sessions). Pre-fetched here so the first
      Tester launch doesn't pay the npx download + browser install cost.
    """
    import subprocess
    import shutil
    from helper_command import python_command
    from resource_path import is_frozen

    steps = []

    # Step 1: pip install playwright (Python — in-process consumers). Try a
    # plain install first; on PEP 668 (Homebrew / Debian managed Python), retry
    # as a --user install with --break-system-packages so a one-click install
    # works on common dev setups without forcing the user into a venv.
    pip_attempts = [
        ["pip3", "install", "playwright"],
        ["pip3", "install", "--user", "--break-system-packages", "playwright"],
    ]
    pip_ok = is_frozen()  # Python Playwright is already inside the desktop bundle.
    if pip_ok:
        pip_attempts = []
        steps.append({"step": "Bundled Python Playwright", "ok": True, "output": "Included in IVE"})
    for cmd in pip_attempts:
        try:
            proc = subprocess.run(cmd, capture_output=True, text=True, timeout=180)
            out = (proc.stdout + proc.stderr).strip()[-500:]
            steps.append({"step": " ".join(cmd), "ok": proc.returncode == 0, "output": out})
            if proc.returncode == 0:
                pip_ok = True
                break
            if "externally-managed-environment" not in out:
                break
        except Exception as e:
            steps.append({"step": " ".join(cmd), "ok": False, "output": str(e)})
            break
    if not pip_ok:
        return web.json_response({"ok": False, "steps": steps}, status=500)

    # Step 2: python -m playwright install chromium (Python Playwright's chromium build)
    try:
        proc = subprocess.run(
            python_command("-m", "playwright", "install", "chromium"),
            capture_output=True, text=True, timeout=300,
        )
        steps.append({
            "step": "playwright install chromium (python)",
            "ok": proc.returncode == 0,
            "output": (proc.stdout + proc.stderr).strip()[-500:],
        })
        if proc.returncode != 0:
            return web.json_response({"ok": False, "steps": steps}, status=500)
    except Exception as e:
        steps.append({"step": "playwright install chromium (python)", "ok": False, "output": str(e)})
        return web.json_response({"ok": False, "steps": steps}, status=500)

    # Steps 3+4: Node side — Tester MCP. Best-effort: Tester still works without
    # these (npx lazy-fetches on first launch), so don't 500 the whole install
    # if npx is missing or these steps fail.
    if shutil.which("npx"):
        try:
            proc = subprocess.run(
                ["npx", "-y", "@playwright/mcp@latest", "--version"],
                capture_output=True, text=True, timeout=180,
            )
            steps.append({
                "step": "prefetch @playwright/mcp (tester)",
                "ok": proc.returncode == 0,
                "output": (proc.stdout + proc.stderr).strip()[-500:],
            })
        except Exception as e:
            steps.append({"step": "prefetch @playwright/mcp (tester)", "ok": False, "output": str(e)})

        try:
            proc = subprocess.run(
                ["npx", "-y", "playwright@latest", "install", "chromium"],
                capture_output=True, text=True, timeout=300,
            )
            steps.append({
                "step": "playwright install chromium (node)",
                "ok": proc.returncode == 0,
                "output": (proc.stdout + proc.stderr).strip()[-500:],
            })
        except Exception as e:
            steps.append({"step": "playwright install chromium (node)", "ok": False, "output": str(e)})
    else:
        steps.append({
            "step": "prefetch @playwright/mcp (tester)",
            "ok": False,
            "output": "npx not found on PATH — Tester MCP will lazy-fetch on first launch",
        })

    return web.json_response({"ok": True, "steps": steps})


# ─── REST: Chat context (files/folders for the composer's @ picker) ───

async def _chat_context_root(session_id: str) -> _Path | None:
    """The folder the session's CLI works in: its worktree, else the workspace."""
    config = await get_session_config(session_id)
    if not config:
        return None
    for key in ("worktree_path", "workspace_path"):
        raw = config.get(key)
        if raw and _Path(raw).expanduser().is_dir():
            return _Path(raw).expanduser().resolve()
    raw = config.get("workspace_path")
    return _Path(raw).expanduser() if raw else _Path("/nonexistent-session-folder")


def _chat_context_attachments(session_id: str) -> _Path:
    from config import ATTACHMENTS_DIR
    return ATTACHMENTS_DIR / "sessions" / session_id / "context"


# ─── REST: Paste Image ────────────────────────────────────────────────

async def paste_image(request: web.Request) -> web.Response:
    """Save a pasted clipboard image, return its file path for Claude Code."""
    import os
    import time
    from config import DATA_DIR

    paste_dir = DATA_DIR / "pastes"
    paste_dir.mkdir(parents=True, exist_ok=True)

    reader = await request.multipart()
    field = await reader.next()
    if not field:
        return web.json_response({"error": "no file"}, status=400)

    # Determine extension from content type
    ct = field.headers.get('Content-Type', 'image/png')
    ext_map = {'image/png': 'png', 'image/jpeg': 'jpg', 'image/gif': 'gif', 'image/webp': 'webp', 'image/svg+xml': 'svg'}
    ext = ext_map.get(ct, 'png')

    filename = f"paste_{int(time.time())}_{uuid.uuid4().hex[:6]}.{ext}"
    filepath = paste_dir / filename

    with open(filepath, 'wb') as f:
        while True:
            chunk = await field.read_chunk()
            if not chunk:
                break
            f.write(chunk)

    return web.json_response({
        "path": str(filepath),
        "url": f"/api/pastes/{filename}",
        "filename": filename,
        "size": os.path.getsize(filepath),
    }, status=201)


async def serve_paste(request: web.Request) -> web.Response:
    from config import DATA_DIR
    filename = request.match_info["filename"]
    base_dir = (DATA_DIR / "pastes").resolve()
    filepath = (base_dir / filename).resolve()
    if not filepath.is_relative_to(base_dir):
        return web.json_response({"error": "invalid path"}, status=400)
    try:
        return web.FileResponse(filepath)
    except (FileNotFoundError, IsADirectoryError):
        return web.json_response({"error": "not found"}, status=404)


_FILE_PREVIEW_TEXT_BYTES = 160 * 1024
_FILE_PREVIEW_INLINE_BYTES = 40 * 1024 * 1024
_FILE_PREVIEW_TEXT_EXTS = {
    ".c", ".cc", ".cfg", ".conf", ".cpp", ".cs", ".css", ".csv", ".env",
    ".go", ".h", ".hpp", ".htm", ".html", ".ini", ".java", ".js", ".json",
    ".jsx", ".kt", ".log", ".lua", ".md", ".mdx", ".php", ".py", ".rb",
    ".rs", ".sass", ".scss", ".sh", ".sql", ".svelte", ".toml", ".ts",
    ".tsx", ".txt", ".vue", ".xml", ".yaml", ".yml",
}


def _looks_like_text(data: bytes) -> bool:
    if not data:
        return True
    if b"\x00" in data:
        return False
    control = 0
    sample = data[:4096]
    for b in sample:
        if b < 32 and b not in (9, 10, 12, 13):
            control += 1
    return (control / max(len(sample), 1)) < 0.08


def _read_preview_text(path: _Path, limit: int) -> tuple[str, bool]:
    with open(path, "rb") as f:
        data = f.read(limit + 1)
    truncated = len(data) > limit
    data = data[:limit]
    try:
        return data.decode("utf-8"), truncated
    except UnicodeDecodeError:
        return data.decode("utf-8", errors="replace"), truncated


def _read_preview_bytes(path: _Path, limit: int) -> tuple[bytes, bool]:
    with open(path, "rb") as f:
        data = f.read(limit + 1)
    return data[:limit], len(data) > limit


async def _resolve_session_file_preview_path(session_id: str, raw_path: str) -> tuple[_Path | None, str | None, int]:
    """Resolve a preview path for a session without exposing arbitrary home files."""
    import os as _os_preview
    from config import ATTACHMENTS_DIR, DATA_DIR

    file_path = (raw_path or "").strip()
    if not session_id:
        return None, "session_id required", 400
    if not file_path:
        return None, "path query param required", 400

    db = await get_db()
    try:
        cur = await db.execute(
            """SELECT s.id, w.path AS workspace_path
               FROM sessions s
               LEFT JOIN workspaces w ON s.workspace_id = w.id
               WHERE s.id = ?""",
            (session_id,),
        )
        row = await cur.fetchone()
    finally:
        await db.close()

    if not row:
        return None, "session not found", 404

    workspace_path = row["workspace_path"]
    workspace_root = _Path(workspace_path).expanduser().resolve() if workspace_path else None
    if _os_preview.path.isabs(file_path) or file_path.startswith("~"):
        candidate = _Path(_os_preview.path.expanduser(file_path)).resolve()
    elif workspace_root:
        candidate = (workspace_root / file_path).resolve()
    else:
        return None, "relative paths need a workspace", 400

    allowed_roots = [
        root for root in (
            workspace_root,
            (DATA_DIR / "pastes").resolve(),
            (ATTACHMENTS_DIR / "sessions" / session_id).resolve(),
        ) if root
    ]

    if not any(candidate == root or candidate.is_relative_to(root) for root in allowed_roots):
        return None, "path is outside previewable roots", 403
    return candidate, None, 200


async def get_session_file_preview(request: web.Request) -> web.Response:
    """Return safe, bounded metadata and text snippets for a session file."""
    import mimetypes
    import urllib.parse

    session_id = request.match_info["id"]
    raw_path = request.query.get("path", "")
    path, error, status = await _resolve_session_file_preview_path(
        session_id,
        raw_path,
    )
    if error:
        return web.json_response({"error": error}, status=status)

    try:
        stat = await asyncio.to_thread(path.stat)
    except FileNotFoundError:
        return web.json_response({"error": "not found"}, status=404)
    except OSError as e:
        return web.json_response({"error": str(e)}, status=500)

    if not path.is_file():
        return web.json_response({"error": "not a file"}, status=400)

    mime_type = mimetypes.guess_type(str(path))[0] or "application/octet-stream"
    suffix = path.suffix.lower()
    size = stat.st_size

    kind = "binary"
    text = None
    truncated = False
    content_url = f"/api/sessions/{urllib.parse.quote(session_id)}/file-preview/content?path={urllib.parse.quote(raw_path)}"

    if mime_type.startswith("image/"):
        kind = "image"
    elif mime_type.startswith("video/"):
        kind = "video"
    elif mime_type.startswith("audio/"):
        kind = "audio"
    elif mime_type == "application/pdf":
        kind = "pdf"
    else:
        sample, sample_truncated = await asyncio.to_thread(_read_preview_bytes, path, min(8192, _FILE_PREVIEW_TEXT_BYTES))
        if mime_type.startswith("text/") or suffix in _FILE_PREVIEW_TEXT_EXTS or _looks_like_text(sample):
            kind = "text"
            if sample_truncated or size > min(8192, _FILE_PREVIEW_TEXT_BYTES):
                text, truncated = await asyncio.to_thread(_read_preview_text, path, _FILE_PREVIEW_TEXT_BYTES)
            else:
                try:
                    text = sample.decode("utf-8")
                except UnicodeDecodeError:
                    text = sample.decode("utf-8", errors="replace")
                truncated = False

    return web.json_response({
        "path": str(path),
        "name": path.name,
        "size": size,
        "mime_type": mime_type,
        "kind": kind,
        "text": text,
        "truncated": truncated,
        "content_url": content_url if kind in ("image", "video", "audio", "pdf") else None,
    })


async def serve_session_file_preview(request: web.Request) -> web.Response:
    """Serve previewable media inline for a session file path."""
    import mimetypes

    session_id = request.match_info["id"]
    path, error, status = await _resolve_session_file_preview_path(
        session_id,
        request.query.get("path", ""),
    )
    if error:
        return web.json_response({"error": error}, status=status)

    try:
        stat = await asyncio.to_thread(path.stat)
    except FileNotFoundError:
        return web.json_response({"error": "not found"}, status=404)
    except OSError as e:
        return web.json_response({"error": str(e)}, status=500)

    if not path.is_file():
        return web.json_response({"error": "not a file"}, status=400)
    if stat.st_size > _FILE_PREVIEW_INLINE_BYTES:
        return web.json_response({"error": "file too large for inline preview"}, status=413)

    mime_type = mimetypes.guess_type(str(path))[0] or "application/octet-stream"
    return web.FileResponse(path, headers={
        "Content-Type": mime_type,
        "Content-Disposition": f'inline; filename="{path.name}"',
    })


# ─── REST: Attachments ────────────────────────────────────────────────

async def upload_attachment(request: web.Request) -> web.Response:
    """Upload an image/file attachment for a task."""
    import os
    from config import ATTACHMENTS_DIR

    task_id = request.match_info["id"]
    # Validate task exists. Without this, any UUID would create
    # ~/.ive/attachments/<random>/<file> — disk-fill DoS (BUG H3).
    _check_db = await get_db()
    try:
        cur = await _check_db.execute("SELECT id FROM tasks WHERE id = ?", (task_id,))
        if not await cur.fetchone():
            return web.json_response({"error": "task not found"}, status=404)
    finally:
        await _check_db.close()

    reader = await request.multipart()

    ATTACHMENTS_DIR.mkdir(parents=True, exist_ok=True)
    task_dir = ATTACHMENTS_DIR / task_id
    task_dir.mkdir(exist_ok=True)

    files_saved = []
    while True:
        field = await reader.next()
        if field is None:
            break
        if field.name == 'file':
            filename = field.filename or f"upload_{uuid.uuid4().hex[:8]}"
            # Sanitize filename
            safe_name = "".join(c for c in filename if c.isalnum() or c in '._-')
            if safe_name in {"", ".", ".."}:
                safe_name = f"upload_{uuid.uuid4().hex[:8]}"
            filepath = task_dir / safe_name
            with open(filepath, 'wb') as f:
                while True:
                    chunk = await field.read_chunk()
                    if not chunk:
                        break
                    f.write(chunk)
            files_saved.append({
                "filename": safe_name,
                "url": f"/api/attachments/{task_id}/{safe_name}",
                "path": str(filepath),
                "size": os.path.getsize(filepath),
            })

    return web.json_response({"files": files_saved}, status=201)


