# ─── REST: Research DB ────────────────────────────────────────────────

import research_extensions

_RESEARCH_MODE_KEYS = {"technical_decision", "papers", "repos", "competitors"}
_RESEARCH_SCOPE_KEYS = {"workspace", "company"}


def _normalize_research_modes(value) -> list[str]:
    values = value if isinstance(value, list) else [value]
    modes = []
    for item in values:
        key = str(item or "").strip()
        if key in _RESEARCH_MODE_KEYS and key not in modes:
            modes.append(key)
    return modes or ["technical_decision"]


def _parse_research_row(row) -> dict:
    data = research_extensions.project_row("entry", row)
    try:
        data["modes"] = _normalize_research_modes(json.loads(data.get("modes") or "[]"))
    except (TypeError, json.JSONDecodeError):
        data["modes"] = _normalize_research_modes(data.get("feature_tag"))
    return data


async def list_research(request: web.Request) -> web.Response:
    workspace_id = request.query.get("workspace_id") or request.query.get("workspace")
    feature = request.query.get("feature")
    # Reuse-check filters: bound the candidate pool so an agent can scan it and
    # decide "does this research already exist?" without pulling the whole DB.
    status = request.query.get("status")            # e.g. 'complete'
    recency_days = request.query.get("recency_days")  # int — only recent entries
    limit = request.query.get("limit")              # int — cap the pool
    db = await get_db()
    try:
        query = "SELECT * FROM research_entries"
        params = []
        conditions = []
        if workspace_id:
            conditions.append("(scope = 'company' OR (scope = 'workspace' AND workspace_id = ?))")
            params.append(workspace_id)
        if feature:
            conditions.append(
                "(feature_tag = ? OR EXISTS "
                "(SELECT 1 FROM json_each(research_entries.modes) WHERE value = ?))"
            )
            params.append(feature)
            params.append(feature)
        if status:
            conditions.append("status = ?")
            params.append(status)
        if recency_days:
            try:
                conditions.append("updated_at >= datetime('now', ?)")
                params.append(f"-{int(recency_days)} days")
            except (TypeError, ValueError):
                pass
        if conditions:
            query += " WHERE " + " AND ".join(conditions)
        query += " ORDER BY updated_at DESC"
        if limit:
            try:
                query += " LIMIT ?"
                params.append(int(limit))
            except (TypeError, ValueError):
                params = params  # ignore bad limit, return unbounded
        cur = await db.execute(query, params)
        rows = await cur.fetchall()
        return web.json_response([_parse_research_row(r) for r in rows])
    finally:
        await db.close()


async def create_research(request: web.Request) -> web.Response:
    body = await request.json()
    topic = body.get("topic", "").strip()
    if not topic:
        return web.json_response({"error": "topic required"}, status=400)
    scope = str(body.get("scope") or "workspace").strip().lower()
    if scope not in _RESEARCH_SCOPE_KEYS:
        return web.json_response({"error": "scope must be workspace or company"}, status=400)
    workspace_id = None if scope == "company" else body.get("workspace_id")
    modes = _normalize_research_modes(body.get("modes") or body.get("feature_tag"))

    entry_id = str(uuid.uuid4())
    db = await get_db()
    try:
        entry_values = {
            "id": entry_id, "scope": scope, "workspace_id": workspace_id, "topic": topic,
            "query": body.get("query", topic), "feature_tag": modes[0], "modes": json.dumps(modes),
            "status": body.get("status", "pending"), "session_id": body.get("session_id"),
            "findings_summary": body.get("findings_summary"),
            **research_extensions.values("entry", "create", body),
        }
        await db.execute(
            f"INSERT INTO research_entries ({', '.join(entry_values)}) "
            f"VALUES ({', '.join('?' for _ in entry_values)})",
            tuple(entry_values.values()),
        )
        await db.commit()
        cur = await db.execute("SELECT * FROM research_entries WHERE id = ?", (entry_id,))
        row = await cur.fetchone()
        return web.json_response(_parse_research_row(row), status=201)
    finally:
        await db.close()


async def update_research(request: web.Request) -> web.Response:
    entry_id = request.match_info["id"]
    body = await request.json()
    db = await get_db()
    row_d = None
    terminal_status = None
    ws_id = None
    try:
        allowed = (
            "topic", "query", "feature_tag", "status", "findings_summary",
            "session_id",
        )
        fields, values = [], []
        for key in allowed:
            if key in body:
                fields.append(f"{key} = ?")
                values.append(body[key])
        for key, value in research_extensions.values("entry", "update", body).items():
            fields.append(f"{key} = ?")
            values.append(value)
        if "modes" in body:
            modes = _normalize_research_modes(body["modes"])
            fields.extend(("modes = ?", "feature_tag = ?"))
            values.extend((json.dumps(modes), modes[0]))
        if not fields:
            return web.json_response({"error": "no fields"}, status=400)
        fields.append("updated_at = datetime('now')")
        values.append(entry_id)
        await db.execute(f"UPDATE research_entries SET {', '.join(fields)} WHERE id = ?", values)
        await db.commit()
        cur = await db.execute("SELECT * FROM research_entries WHERE id = ?", (entry_id,))
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "research entry not found"}, status=404)
        row_d = _parse_research_row(row)
        # Agent-driven completion (finish_research → PUT here) and any direct
        # status edit bypass the job-runner's emit sites, so fire the bus event
        # ourselves on a terminal transition — otherwise a task parked on this
        # entry would stay blocked until the CLI loop happens to re-poll.
        new_status = body.get("status")
        if isinstance(new_status, str) and new_status in ("complete", "failed", "cancelled"):
            terminal_status = new_status
            ws_id = row_d.get("workspace_id")
    finally:
        await db.close()
    if terminal_status:
        await _emit_research_completed(entry_id, terminal_status, ws_id)
    return web.json_response(row_d)


async def get_research_with_sources(request: web.Request) -> web.Response:
    entry_id = request.match_info["id"]
    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM research_entries WHERE id = ?", (entry_id,))
        entry = await cur.fetchone()
        if not entry:
            return web.json_response({"error": "not found"}, status=404)
        entry = _parse_research_row(entry)

        cur = await db.execute(
            "SELECT * FROM research_sources WHERE entry_id = ? ORDER BY relevance_score DESC, created_at",
            (entry_id,),
        )
        sources = [dict(r) for r in await cur.fetchall()]
        entry["sources"] = sources
        return web.json_response(entry)
    finally:
        await db.close()


async def add_research_source(request: web.Request) -> web.Response:
    entry_id = request.match_info["id"]
    body = await request.json()
    db = await get_db()
    try:
        await db.execute(
            """INSERT INTO research_sources (entry_id, url, title, content_summary, raw_content, relevance_score)
               VALUES (?, ?, ?, ?, ?, ?)""",
            (entry_id, body.get("url"), body.get("title"), body.get("content_summary"),
             body.get("raw_content"), body.get("relevance_score", 0)),
        )
        await db.commit()
        return web.json_response({"ok": True})
    finally:
        await db.close()


async def delete_research(request: web.Request) -> web.Response:
    entry_id = request.match_info["id"]
    # Un-park any task blocked on this entry BEFORE deleting. The FK is
    # ON DELETE SET NULL, so the link would clear on delete anyway — but that
    # cascade fires no status transition or dispatch, leaving the task stuck in
    # backlog. Emitting first lets _on_research_completed un-park it cleanly.
    await _emit_research_completed(entry_id, "cancelled")
    db = await get_db()
    try:
        cur = await db.execute("DELETE FROM research_entries WHERE id = ?", (entry_id,))
        await db.commit()
        if cur.rowcount == 0:
            return web.json_response({"error": "research entry not found"}, status=404)
        return web.json_response({"ok": True})
    finally:
        await db.close()


async def search_research(request: web.Request) -> web.Response:
    """Full-text search across research entries and sources."""
    q = request.query.get("q", "").strip()
    workspace_id = request.query.get("workspace_id") or request.query.get("workspace")
    if not q:
        return web.json_response([])
    db = await get_db()
    try:
        query = """
            SELECT DISTINCT e.* FROM research_entries e
            LEFT JOIN research_sources s ON e.id = s.entry_id
            WHERE (e.topic LIKE ? OR e.findings_summary LIKE ? OR s.content_summary LIKE ? OR s.title LIKE ?)
        """
        params = [f"%{q}%"] * 4
        if workspace_id:
            query += " AND (e.scope = 'company' OR (e.scope = 'workspace' AND e.workspace_id = ?))"
            params.append(workspace_id)
        query += " ORDER BY e.updated_at DESC LIMIT 50"
        cur = await db.execute(query, params)
        rows = await cur.fetchall()
        return web.json_response([_parse_research_row(r) for r in rows])
    finally:
        await db.close()


# ─── REST: AGENTS.md ──────────────────────────────────────────────────

async def get_agents_md(request: web.Request) -> web.Response:
    """Read AGENTS.md files from workspace directory hierarchy."""
    workspace_id = request.match_info["id"]
    db = await get_db()
    try:
        cur = await db.execute("SELECT path FROM workspaces WHERE id = ?", (workspace_id,))
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "workspace not found"}, status=404)
        ws_path = row["path"]
    finally:
        await db.close()

    import os
    agents_files = []
    scan_dir = ws_path
    for _ in range(10):
        agents_file = os.path.join(scan_dir, "AGENTS.md")
        if os.path.isfile(agents_file):
            try:
                with open(agents_file, "r") as f:
                    agents_files.append({
                        "path": agents_file,
                        "relative": os.path.relpath(agents_file, ws_path),
                        "content": f.read(),
                    })
            except (OSError, IOError):
                pass
        parent = os.path.dirname(scan_dir)
        if parent == scan_dir:
            break
        scan_dir = parent

    return web.json_response({
        "workspace_id": workspace_id,
        "workspace_path": ws_path,
        "files": agents_files,
    })


async def save_agents_md(request: web.Request) -> web.Response:
    """Create or update AGENTS.md in the workspace root."""
    workspace_id = request.match_info["id"]
    body = await request.json()
    content = body.get("content", "")

    db = await get_db()
    try:
        cur = await db.execute("SELECT path FROM workspaces WHERE id = ?", (workspace_id,))
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "workspace not found"}, status=404)
        ws_path = row["path"]
    finally:
        await db.close()

    import os
    agents_file = os.path.join(ws_path, "AGENTS.md")
    try:
        with open(agents_file, "w") as f:
            f.write(content)
        return web.json_response({"ok": True, "path": agents_file})
    except (OSError, IOError) as e:
        return web.json_response({"error": str(e)}, status=500)


