# Voice control is a normal strict registry consumer. Its deterministic parser
# remains the feature-level fallback; provider/model fallback is not invented
# here.
VOICE_CONTROL_MODEL = "gemini_api:gemini-3.1-flash-lite"
VOICE_SESSION_MODEL = "Gemini 3.5 Flash (High)"
VOICE_TTS_MODEL = "gemini-2.5-flash-preview-tts"
VOICE_TTS_VOICE = "Iapetus"
# gemini-3.1-flash-tts-preview was tried here but consistently returns HTTP 500
# (broken preview as of 2026-05), so it's excluded — a dead model in this list
# just burns a 3-5s round-trip before falling through. pro is the working backup.
VOICE_TTS_FALLBACK_MODELS = (
    "gemini-2.5-flash-preview-tts",
    "gemini-2.5-pro-preview-tts",
)
VOICE_TTS_COOLDOWN_UNTIL = 0.0

# Gemini Live (bidi streaming) models for low-latency spoken output. The
# REST TTS path above stays as the automatic fallback when Live is
# unavailable (quota, network, model 500). 3.1-flash-live is preview-only
# (no stable variant exists yet); native-audio-latest is the steadier
# backup. Both verified to accept the Iapetus voice.
VOICE_LIVE_MODEL = "gemini-3.1-flash-live-preview"
VOICE_LIVE_FALLBACK_MODELS = (
    "gemini-2.5-flash-native-audio-latest",
)
VOICE_LIVE_WS_URL = (
    "wss://generativelanguage.googleapis.com/ws/"
    "google.ai.generativelanguage.v1beta.GenerativeService.BidiGenerateContent"
)


def _voice_tts_retry_seconds(message: str) -> float:
    match = re.search(r"retry in\s+([0-9.]+)s", str(message or ""), re.I)
    if match:
        try:
            return max(5.0, min(120.0, float(match.group(1))))
        except Exception:
            pass
    return 60.0

VOICE_INTENTS = {
    "workspace_status",
    "list_feedback",
    "start_research",
    "create_session",
    "switch_model",
    "create_candidate_task",
    "send_to_commander",
    "session_overview",
    "inspect_session",
    "read_next",
    "read_output",
    "read_research",
    "confirm",
    "cancel",
    "unknown",
}


def _voice_compact(text: str, limit: int = 220) -> str:
    text = re.sub(r"\s+", " ", str(text or "")).strip()
    return text[:limit].rstrip() if len(text) > limit else text


# Keys, in priority order, that carry human-readable speech in a readout payload.
_VOICE_SPEECH_KEYS = (
    "findings_summary", "summary", "result_summary", "current_focus",
    "task_summary", "lessons_learned", "description", "findings", "answer",
    "result", "speech", "recent_output", "message", "focus", "topic", "title", "text",
)


def _voice_collect_speech_strings(node, out: list, depth: int = 0) -> None:
    if depth > 4 or len(out) >= 6:
        return
    if isinstance(node, dict):
        for key in _VOICE_SPEECH_KEYS:
            val = node.get(key)
            if isinstance(val, str):
                cleaned = re.sub(r"\s+", " ", val).strip()
                if cleaned and cleaned not in out:
                    out.append(cleaned)
                    if len(out) >= 6:
                        return
        for val in node.values():
            if isinstance(val, (dict, list)):
                _voice_collect_speech_strings(val, out, depth + 1)
    elif isinstance(node, list):
        for val in node[:6]:
            _voice_collect_speech_strings(val, out, depth + 1)


def _voice_fallback_speech(text: str, limit: int = 260) -> str:
    """Degraded summary when the LLM call fails. Never echo raw JSON braces:
    if the input is a stringified payload, pull out readable fields instead."""
    stripped = str(text or "").strip()
    if stripped[:1] in ("{", "["):
        try:
            parsed = json.loads(stripped)
        except Exception:
            parsed = None
        if parsed is not None:
            collected: list = []
            _voice_collect_speech_strings(parsed, collected)
            # Parsed JSON: return extracted text, never the raw braces.
            return _voice_compact(" ".join(collected), max(limit, 320)) if collected else "No readable detail available."
    lines = [ln.strip() for ln in stripped.splitlines() if ln.strip()]
    return _voice_compact(" ".join(lines[-4:]) or "No output available.", limit)


def _voice_model_from_text(text: str, *, session: bool = False) -> str:
    lower = (text or "").lower()
    if "opus" in lower:
        return "opus"
    if "sonnet" in lower:
        return "sonnet"
    if "haiku" in lower:
        return "haiku"
    if "3.5" in lower or "three point five" in lower or "flash" in lower:
        return VOICE_SESSION_MODEL if session else VOICE_CONTROL_MODEL
    return VOICE_SESSION_MODEL if session else VOICE_CONTROL_MODEL


async def _voice_context_snapshot(
    workspace_id: str,
    active_session_id: str | None,
    request: web.Request,
) -> dict:
    db = await get_db()
    try:
        cur = await db.execute("SELECT id, name FROM workspaces WHERE id = ?", (workspace_id,))
        ws = await cur.fetchone()
        if not ws:
            return {"error": "workspace not found"}

        cur = await db.execute(
            """SELECT s.id, s.name, s.status, s.session_type, s.cli_type, s.model,
                      s.tags, s.task_id, s.active_ticket_id, s.last_active_at,
                      d.task_summary, d.current_focus, d.decisions, d.discoveries
                 FROM sessions s
                 LEFT JOIN session_digests d ON s.id = d.session_id
                WHERE s.workspace_id = ? AND COALESCE(s.archived, 0) = 0
                ORDER BY s.last_active_at DESC NULLS LAST, s.created_at DESC
                LIMIT 16""",
            (workspace_id,),
        )
        session_rows = await cur.fetchall()

        cur = await db.execute(
            """SELECT id, title, status, priority, assigned_session_id, labels,
                      result_summary, updated_at
                 FROM tasks
                WHERE workspace_id = ?
                ORDER BY updated_at DESC, created_at DESC
                LIMIT 40""",
            (workspace_id,),
        )
        task_rows = await cur.fetchall()

        cur = await db.execute(
            """SELECT id, topic, query, feature_tag, status, findings_summary, updated_at
                 FROM research_entries
                WHERE workspace_id = ?
                ORDER BY updated_at DESC, created_at DESC
                LIMIT 12""",
            (workspace_id,),
        )
        research_rows = await cur.fetchall()
    finally:
        await db.close()

    from hooks import get_session_logical_status
    sessions = []
    active_session = None
    for row in session_rows:
        raw = dict(row)
        if not _session_visible_to_request(raw, request):
            continue
        tags = _parse_json_field(raw.get("tags"), [])
        decisions = _parse_json_field(raw.get("decisions"), [])
        discoveries = _parse_json_field(raw.get("discoveries"), [])
        pty_alive = pty_mgr.is_alive(raw["id"])
        item = {
            "id": raw["id"],
            "name": raw.get("name"),
            "status": get_session_logical_status(raw["id"], pty_alive, raw.get("status") or "idle"),
            "session_type": raw.get("session_type") or "worker",
            "cli_type": raw.get("cli_type") or "claude",
            "model": raw.get("model") or "",
            "tags": tags[:8] if isinstance(tags, list) else [],
            "task_id": raw.get("task_id"),
            "active_ticket_id": raw.get("active_ticket_id"),
            "task_summary": _voice_compact(raw.get("task_summary") or "", 180),
            "current_focus": _voice_compact(raw.get("current_focus") or "", 180),
            "decisions": decisions[:4] if isinstance(decisions, list) else [],
            "discoveries": discoveries[:4] if isinstance(discoveries, list) else [],
        }
        sessions.append(item)
        if raw["id"] == active_session_id:
            active_session = item

    tasks = [dict(r) for r in task_rows]
    for task in tasks:
        task["labels"] = _parse_json_field(task.get("labels"), task.get("labels") or [])
        task["result_summary"] = _voice_compact(task.get("result_summary") or "", 220)

    open_statuses = {"backlog", "todo", "planning", "in_progress", "review", "blocked"}
    pending_feedback = [
        {
            "id": t.get("id"),
            "title": t.get("title"),
            "status": t.get("status"),
            "summary": _voice_compact(t.get("result_summary") or "", 160),
        }
        for t in tasks
        if (t.get("status") or "backlog") in {"review", "blocked", "planning"}
    ][:8]

    research_entries = [dict(r) for r in research_rows]
    for entry in research_entries:
        entry["findings_summary"] = _voice_compact(entry.get("findings_summary") or "", 260)

    research_jobs = []
    for jid, job in list(_research_jobs.items())[-12:]:
        research_jobs.append({
            "job_id": jid,
            "query": job.get("query"),
            "status": job.get("status"),
            "model": job.get("model"),
            "entry_id": job.get("entry_id"),
            "error": _voice_compact(job.get("error") or "", 180),
        })

    return {
        "workspace": {"id": ws["id"], "name": ws["name"]},
        "active_session_id": active_session_id,
        "active_session": active_session,
        "sessions": sessions[:12],
        "task_counts": {
            "open": sum(1 for t in tasks if (t.get("status") or "backlog") in open_statuses),
            "review": sum(1 for t in tasks if t.get("status") == "review"),
            "blocked": sum(1 for t in tasks if t.get("status") == "blocked"),
            "in_progress": sum(1 for t in tasks if t.get("status") == "in_progress"),
        },
        "pending_feedback": pending_feedback,
        "recent_tasks": tasks[:12],
        "research_jobs": research_jobs,
        "research_entries": research_entries,
    }


def _fallback_voice_parse(transcript: str, context: dict) -> dict:
    lower = transcript.lower().strip()
    active_session = context.get("active_session") or {}
    if re.fullmatch(r"(yes|yeah|yep|confirm|confirmed|do it|go ahead|proceed|start)", lower):
        return {"intent": "confirm", "speech": "Confirmed.", "args": {}, "confidence": 0.9}
    if re.fullmatch(r"(no|nope|cancel|stop|never mind|nevermind)", lower):
        return {"intent": "cancel", "speech": "Cancelled.", "args": {}, "confidence": 0.9}
    if lower == "next" or lower.startswith("next ") or lower.startswith("read next"):
        target = re.sub(r"^(read\s+)?next\b", "", lower).strip()
        detail = "full" if any(w in lower for w in ("full", "complete", "details", "detailed")) else "brief"
        target = re.sub(r"\b(full|complete|details|detailed|summary|brief)\b", " ", target)
        target = re.sub(r"\s+", " ", target).strip()
        return {
            "intent": "read_next",
            "speech": "Reading the next queued item.",
            "args": {"target": target or None, "detail": detail},
            "confidence": 0.8,
        }
    if any(w in lower for w in ("status", "what's happening", "what is happening", "feedback", "waiting", "pending")):
        counts = context.get("task_counts") or {}
        pending = context.get("pending_feedback") or []
        speech = f"{counts.get('in_progress', 0)} active, {counts.get('review', 0)} in review, {counts.get('blocked', 0)} blocked."
        if pending:
            speech += f" {len(pending)} need feedback."
        return {"intent": "workspace_status", "speech": speech, "args": {}, "confidence": 0.7}
    if "research" in lower:
        query = re.sub(r"\b(run|start|do|research|with|using|gemini|flash|3\.5|three point five)\b", " ", lower)
        query = re.sub(r"\s+", " ", query).strip() or transcript
        return {
            "intent": "start_research",
            "speech": "Starting research with Gemini 3.5 Flash.",
            "args": {"query": query, "model": VOICE_CONTROL_MODEL, "depth": "standard"},
            "confidence": 0.72,
        }
    if any(w in lower for w in ("read output", "summarize output", "last output", "what did it say")):
        return {
            "intent": "read_output",
            "speech": "Reading the active session output.",
            "args": {"session_id": active_session.get("id")},
            "confidence": 0.72,
        }
    if any(w in lower for w in ("all sessions", "session overview", "what are sessions", "workers doing")):
        return {
            "intent": "session_overview",
            "speech": "Reading the session overview.",
            "args": {},
            "confidence": 0.72,
        }
    if any(w in lower for w in ("zoom", "inspect session", "look at session", "what did worker", "what is worker")):
        return {
            "intent": "inspect_session",
            "speech": "Inspecting that session.",
            "args": {"session_id": active_session.get("id"), "target": transcript},
            "confidence": 0.68,
        }
    if any(w in lower for w in ("new session", "open session", "create session", "new worker", "new brainstorm")):
        is_brainstormer = "brainstorm" in lower
        return {
            "intent": "create_session",
            "speech": "Create a Gemini 3.5 Flash session? Say confirm.",
            "args": {
                "session_type": "brainstormer" if is_brainstormer else "worker",
                "cli_type": "antigravity",
                "model": VOICE_SESSION_MODEL,
                "name": "Voice Brainstormer" if is_brainstormer else "Voice Worker",
            },
            "needs_confirmation": True,
            "confidence": 0.7,
        }
    if "switch" in lower and "model" in lower:
        return {
            "intent": "switch_model",
            "speech": "Switch the active session model? Say confirm.",
            "args": {"session_id": active_session.get("id"), "model": _voice_model_from_text(transcript, session=True)},
            "needs_confirmation": True,
            "confidence": 0.68,
        }
    if any(w in lower for w in ("implement", "fix", "ship", "commander")):
        return {
            "intent": "send_to_commander",
            "speech": "Send this to Commander for routing? Say confirm.",
            "args": {"message": transcript, "model_preference": _voice_model_from_text(transcript, session=True)},
            "needs_confirmation": True,
            "confidence": 0.65,
        }
    return {
        "intent": "unknown",
        "speech": "I did not catch a clear command.",
        "args": {},
        "confidence": 0.2,
    }


def _normalize_voice_command(raw: dict, transcript: str, context: dict) -> dict:
    if not isinstance(raw, dict):
        raw = {}
    intent = str(raw.get("intent") or "unknown").strip()
    if intent not in VOICE_INTENTS:
        intent = "unknown"
    args = raw.get("args") if isinstance(raw.get("args"), dict) else {}
    active_session = context.get("active_session") or {}

    if intent == "start_research":
        args["query"] = _voice_compact(args.get("query") or transcript, 500)
        args["model"] = args.get("model") or VOICE_CONTROL_MODEL
        args["depth"] = args.get("depth") if args.get("depth") in {"quick", "standard", "deep"} else "standard"
    elif intent == "create_session":
        stype = str(args.get("session_type") or "worker").strip().lower()
        args["session_type"] = "brainstormer" if "brainstorm" in stype else "worker"
        args["cli_type"] = args.get("cli_type") or "antigravity"
        args["model"] = args.get("model") or VOICE_SESSION_MODEL
        args["name"] = _voice_compact(args.get("name") or ("Voice Brainstormer" if args["session_type"] == "brainstormer" else "Voice Worker"), 80)
    elif intent == "switch_model":
        args["session_id"] = args.get("session_id") or active_session.get("id")
        args["model"] = args.get("model") or _voice_model_from_text(transcript, session=True)
    elif intent == "create_candidate_task":
        args["title"] = _voice_compact(args.get("title") or transcript, 120)
        args["description"] = _voice_compact(args.get("description") or transcript, 1000)
    elif intent == "send_to_commander":
        args["message"] = _voice_compact(args.get("message") or transcript, 2000)
        args["model_preference"] = args.get("model_preference") or _voice_model_from_text(transcript, session=True)
    elif intent == "inspect_session":
        args["session_id"] = args.get("session_id") or active_session.get("id")
        args["target"] = _voice_compact(args.get("target") or transcript, 180)
    elif intent == "read_next":
        args["target"] = _voice_compact(args.get("target") or "", 180)
        detail = str(args.get("detail") or "").strip().lower()
        if detail not in {"brief", "full"}:
            detail = "full" if any(w in transcript.lower() for w in ("full", "complete", "details", "detailed")) else "brief"
        args["detail"] = detail
    elif intent in {"read_output", "read_research"}:
        args["session_id"] = args.get("session_id") or active_session.get("id")

    needs_confirmation_default = intent in {"create_session", "switch_model", "send_to_commander"}
    needs_confirmation = bool(raw.get("needs_confirmation", needs_confirmation_default))
    if intent in {"workspace_status", "list_feedback", "session_overview", "inspect_session", "read_next", "read_output", "read_research", "start_research", "create_candidate_task", "confirm", "cancel", "unknown"}:
        needs_confirmation = False

    speech = _voice_compact(raw.get("speech") or "", 180)
    if not speech:
        speech = _fallback_voice_parse(transcript, context).get("speech") or "Ready."

    confidence = raw.get("confidence", 0)
    try:
        confidence = max(0.0, min(1.0, float(confidence)))
    except Exception:
        confidence = 0.0

    return {
        "intent": intent,
        "args": args,
        "needs_confirmation": needs_confirmation,
        "speech": speech,
        "confidence": confidence,
    }


async def voice_command(request: web.Request) -> web.Response:
    workspace_id = request.match_info["id"]
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid JSON"}, status=400)
    transcript = (body.get("transcript") or "").strip()
    if not transcript:
        return web.json_response({"error": "transcript required"}, status=400)
    active_session_id = (body.get("active_session_id") or "").strip() or None

    context = await _voice_context_snapshot(workspace_id, active_session_id, request)
    if context.get("error"):
        return web.json_response({"error": context["error"]}, status=404)

    system = (
        "You are IVE Voice Controller, optimized for car use. Parse a spoken "
        "developer control command into one JSON object. Keep speech dense, "
        "calm, and under 12 words. No markdown. Use only these intents: "
        + ", ".join(sorted(VOICE_INTENTS)) + ". "
        "The speaker may use German-accented English or mixed German-English; infer the intended developer command. "
        f"Do not invent ids. For research/API model default to {VOICE_CONTROL_MODEL}. "
        "For Antigravity sessions use Gemini 3.5 Flash (High). "
        "Voice may directly start research and create candidate backlog tickets. "
        "Implementation/fix/ship requests must use send_to_commander and need confirmation. "
        "Session creation and model switching need confirmation. "
        "Use session_overview for all-session status/readout. Use inspect_session to zoom into one session by id/name/role. "
        "Use read_next when the user says next, next item, or next plus a topic/session/task/research name. "
        "Return exactly JSON with keys: intent, confidence, needs_confirmation, speech, args."
    )
    prompt = json.dumps({
        "transcript": transcript,
        "active_session_id": active_session_id,
        "context": context,
        "args_by_intent": {
            "start_research": {"query": "string", "model": VOICE_CONTROL_MODEL, "depth": "quick|standard|deep"},
            "create_session": {"session_type": "worker|brainstormer", "cli_type": "antigravity", "model": "Gemini 3.5 Flash (High)", "name": "string"},
            "switch_model": {"session_id": "id", "model": "model id"},
            "create_candidate_task": {"title": "string", "description": "string"},
            "send_to_commander": {"message": "string", "model_preference": "string"},
            "session_overview": {},
            "inspect_session": {"session_id": "id optional", "target": "spoken session name optional"},
            "read_next": {"target": "optional spoken target after next", "detail": "brief|full"},
            "read_output": {"session_id": "id"},
            "read_research": {"entry_id": "id optional"},
        },
    }, ensure_ascii=False)

    parse_error = None
    raw = None
    source = "fallback"
    from llm_router import call_json
    try:
        raw = await call_json(
            model_id=VOICE_CONTROL_MODEL,
            prompt=prompt,
            system=system,
            timeout_s=30,
            allow_fallback=False,
        )
        source = VOICE_CONTROL_MODEL
    except Exception as exc:
        logger.warning("voice command model parse failed (%s): %s", VOICE_CONTROL_MODEL, exc)
        parse_error = str(exc)
    if raw is None:
        raw = _fallback_voice_parse(transcript, context)
        source = "fallback"

    action = _normalize_voice_command(raw, transcript, context)
    return web.json_response({
        "ok": True,
        "model": source,
        "transcript": transcript,
        "action": action,
        "speech": action["speech"],
        "parse_error": parse_error,
        "context": {
            "task_counts": context.get("task_counts"),
            "pending_feedback": context.get("pending_feedback", [])[:5],
            "active_session": context.get("active_session"),
        },
    })


async def voice_summarize(request: web.Request) -> web.Response:
    workspace_id = request.match_info["id"]
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid JSON"}, status=400)
    text = str(body.get("text") or "").strip()
    purpose = _voice_compact(body.get("purpose") or "output", 80)
    if not text:
        return web.json_response({"error": "text required"}, status=400)

    mode = str(body.get("mode") or body.get("detail") or "brief").strip().lower()
    full = mode in {"full", "detailed", "details"}
    purpose_lower = purpose.lower()
    session_readout = "session" in purpose_lower
    system = (
        "Summarize for hands-free car use. Be direct, dense, and "
        + ("under 90 words. " if full else ("under 65 words. " if session_readout else "under 32 words. "))
        + "Lead with state, blocker, or result. Use speech-friendly wording for model names and versions. "
        + ("For session summaries, name the exact session label or short id before each item; never identify a session only as Claude Code, Claude, Gemini, or Antigravity. " if session_readout else "")
        + 'No markdown. Return exactly {"text":"spoken summary"}.'
    )
    prompt = json.dumps({
        "workspace_id": workspace_id,
        "purpose": purpose,
        "text": text[-16000:],
    }, ensure_ascii=False)
    try:
        from llm_router import call_json
        result = await call_json(
            model_id=VOICE_CONTROL_MODEL,
            prompt=prompt,
            system=system,
            timeout_s=30,
            allow_fallback=False,
        )
        speech = str(result.get("text") or "").strip()
        if not speech:
            raise RuntimeError("voice summary provider returned no text")
        speech = _voice_compact(speech, 560 if full else (420 if session_readout else 260))
        source = VOICE_CONTROL_MODEL
    except Exception as exc:
        logger.warning("voice summarize Gemini call failed: %s", exc)
        speech = _voice_fallback_speech(text, 560 if full else (420 if session_readout else 260))
        source = "fallback"
    return web.json_response({"ok": True, "speech": speech, "model": source})


def _voice_pcm_to_wav_base64(
    pcm: bytes,
    *,
    channels: int = 1,
    rate: int = 24000,
    sample_width: int = 2,
) -> str:
    buf = io.BytesIO()
    with wave.open(buf, "wb") as wf:
        wf.setnchannels(channels)
        wf.setsampwidth(sample_width)
        wf.setframerate(rate)
        wf.writeframes(pcm)
    return base64.b64encode(buf.getvalue()).decode("ascii")


async def voice_tts(request: web.Request) -> web.Response:
    global VOICE_TTS_COOLDOWN_UNTIL
    workspace_id = request.match_info["id"]
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid JSON"}, status=400)

    text = _voice_compact(body.get("text") or "", 700)
    if not text:
        return web.json_response({"error": "text required"}, status=400)

    voice = _voice_compact(body.get("voice") or VOICE_TTS_VOICE, 40) or VOICE_TTS_VOICE
    model = _voice_compact(body.get("model") or VOICE_TTS_MODEL, 80) or VOICE_TTS_MODEL
    language_code = _voice_compact(body.get("language_code") or body.get("language") or "", 16) or None
    cooldown_remaining = VOICE_TTS_COOLDOWN_UNTIL - time.monotonic()
    if cooldown_remaining > 0:
        return web.json_response({
            "error": "Gemini TTS quota cooldown active",
            "provider": "gemini-tts",
            "retry_after": round(cooldown_remaining, 1),
        }, status=429)

    # Keep the transcript exact, but use Gemini TTS prompting to make short
    # control readouts intelligible in noisy, hands-free contexts.
    prompt = (
        "Say clearly in a fast developer control-center voice. "
        "Keep it clipped, intelligible, and natural for German-English technical pronunciation. "
        "Avoid dramatic pauses. "
        "Read exactly this transcript:\n"
        f"{text}"
    )

    from llm_router import gemini_tts_pcm
    model_candidates = []
    for candidate in (model, *VOICE_TTS_FALLBACK_MODELS):
        if candidate and candidate not in model_candidates:
            model_candidates.append(candidate)

    audio = None
    wav_b64 = None
    last_error = None
    for candidate in model_candidates:
        try:
            audio = await gemini_tts_pcm(
                prompt,
                model=candidate,
                voice_name=voice,
                language_code=language_code,
                timeout=30,
            )
            wav_b64 = _voice_pcm_to_wav_base64(
                audio["pcm"],
                channels=audio.get("channels") or 1,
                rate=audio.get("rate") or 24000,
                sample_width=audio.get("sample_width") or 2,
            )
            model = audio.get("model") or candidate
            break
        except Exception as exc:
            last_error = exc
            message = str(exc)
            logger.warning("voice Gemini TTS model %s failed for workspace %s: %s", candidate, workspace_id, message)
            if "429" in message or "quota" in message.lower():
                retry_after = _voice_tts_retry_seconds(message)
                VOICE_TTS_COOLDOWN_UNTIL = max(VOICE_TTS_COOLDOWN_UNTIL, time.monotonic() + retry_after)
                return web.json_response({
                    "error": message,
                    "provider": "gemini-tts",
                    "retry_after": round(retry_after, 1),
                }, status=429)

    if not audio or not wav_b64:
        return web.json_response({"error": str(last_error or "Gemini TTS failed"), "provider": "gemini-tts"}, status=502)

    return web.json_response({
        "ok": True,
        "provider": "gemini-tts",
        "model": model,
        "voice": voice,
        "language_code": language_code,
        "mime_type": "audio/wav",
        "pcm_mime_type": audio.get("mime_type"),
        "audio": wav_b64,
    })


class _LiveBrowserGone(Exception):
    """Raised when the browser WS is closed mid-stream so we stop trying
    upstream Live models instead of treating it as a model failure."""


async def _live_send(client_ws: web.WebSocketResponse, payload: dict) -> None:
    if client_ws.closed:
        raise _LiveBrowserGone()
    try:
        await client_ws.send_json(payload)
    except (ConnectionResetError, ConnectionError, RuntimeError) as exc:
        raise _LiveBrowserGone() from exc


async def _voice_live_run_model(
    client_ws: web.WebSocketResponse,
    url: str,
    model: str,
    voice: str,
    language_code: "str | None",
    prompt: str,
) -> bool:
    """Open one upstream Gemini Live session, drive a single turn, and
    relay 24kHz PCM chunks to the browser. Returns True if audio streamed."""
    speech_config: dict = {"voiceConfig": {"prebuiltVoiceConfig": {"voiceName": voice}}}
    if language_code:
        speech_config["languageCode"] = language_code
    setup = {
        "setup": {
            "model": f"models/{model}",
            "generationConfig": {
                "responseModalities": ["AUDIO"],
                "speechConfig": speech_config,
            },
        }
    }
    session = aiohttp.ClientSession()
    got_audio = False
    try:
        async with session.ws_connect(url, timeout=20, heartbeat=20.0) as up:
            await up.send_str(json.dumps(setup))
            while True:
                try:
                    msg = await asyncio.wait_for(up.receive(), timeout=30)
                except asyncio.TimeoutError:
                    break
                if msg.type in (
                    aiohttp.WSMsgType.CLOSED,
                    aiohttp.WSMsgType.CLOSING,
                    aiohttp.WSMsgType.ERROR,
                ):
                    break
                if msg.type == aiohttp.WSMsgType.TEXT:
                    raw = msg.data
                elif msg.type == aiohttp.WSMsgType.BINARY:
                    raw = msg.data.decode("utf-8", errors="replace")
                else:
                    continue
                try:
                    data = json.loads(raw)
                except json.JSONDecodeError:
                    continue
                if "setupComplete" in data:
                    turn = {
                        "clientContent": {
                            "turns": [{"role": "user", "parts": [{"text": prompt}]}],
                            "turnComplete": True,
                        }
                    }
                    await up.send_str(json.dumps(turn))
                    await _live_send(client_ws, {"type": "start", "model": model, "voice": voice})
                    continue
                server_content = data.get("serverContent") or {}
                for part in (server_content.get("modelTurn") or {}).get("parts", []) or []:
                    inline = part.get("inlineData")
                    if inline and inline.get("data"):
                        got_audio = True
                        mime = inline.get("mimeType") or ""
                        rate_match = re.search(r"rate=(\d+)", mime)
                        await _live_send(client_ws, {
                            "type": "audio",
                            "data": inline["data"],
                            "rate": int(rate_match.group(1)) if rate_match else 24000,
                        })
                if server_content.get("turnComplete"):
                    break
        if got_audio:
            await _live_send(client_ws, {"type": "done", "model": model})
        return got_audio
    finally:
        await session.close()


async def _voice_live_stream_one(
    client_ws: web.WebSocketResponse,
    key: str,
    *,
    text: str,
    voice: str,
    model: str,
    language_code: "str | None",
    workspace_id: str,
) -> bool:
    prompt = (
        "Say clearly in a fast developer control-center voice. "
        "Keep it clipped, intelligible, and natural for German-English technical pronunciation. "
        "Avoid dramatic pauses. Read exactly this transcript:\n"
        f"{text}"
    )
    candidates: list[str] = []
    for candidate in (model, *VOICE_LIVE_FALLBACK_MODELS):
        if candidate and candidate not in candidates:
            candidates.append(candidate)
    url = f"{VOICE_LIVE_WS_URL}?key={key}"
    last_error: "Exception | None" = None
    for candidate in candidates:
        try:
            if await _voice_live_run_model(client_ws, url, candidate, voice, language_code, prompt):
                return True
        except _LiveBrowserGone:
            return False
        except Exception as exc:  # try the next model, then REST blob
            last_error = exc
            logger.warning("voice Live model %s failed for workspace %s: %s", candidate, workspace_id, exc)
    # Every Live candidate failed — tell the browser to use the REST blob path.
    try:
        await _live_send(client_ws, {
            "type": "error",
            "error": str(last_error or "Live unavailable"),
            "fallback": True,
            "model": candidates[0] if candidates else model,
        })
    except _LiveBrowserGone:
        pass
    return False


async def voice_live(request: web.Request) -> web.WebSocketResponse:
    """WS proxy: /api/workspaces/{id}/voice/live

    Bridges the browser to Gemini's Live (bidi) API so spoken output
    streams as PCM with sub-second time-to-first-audio. The API key stays
    server-side. One utterance per browser 'speak' message; the frontend
    opens a fresh socket per readout and closes the old one to interrupt
    ("latest wins"), so a closed browser side tears down the upstream
    Gemini session here via _LiveBrowserGone."""
    workspace_id = request.match_info["id"]
    ws = web.WebSocketResponse(heartbeat=30.0)
    await ws.prepare(request)

    from llm_router import _resolve_gemini_key
    key = await _resolve_gemini_key()
    if not key:
        try:
            await _live_send(ws, {"type": "error", "error": "Gemini API key not configured", "fallback": True})
        except _LiveBrowserGone:
            pass
        await ws.close()
        return ws

    try:
        async for msg in ws:
            if msg.type != aiohttp.WSMsgType.TEXT:
                continue
            try:
                data = json.loads(msg.data)
            except json.JSONDecodeError:
                continue
            if data.get("type") not in (None, "speak"):
                continue
            text = _voice_compact(data.get("text") or "", 700)
            if not text:
                try:
                    await _live_send(ws, {"type": "error", "error": "text required", "fallback": False})
                except _LiveBrowserGone:
                    break
                continue
            voice = _voice_compact(data.get("voice") or VOICE_TTS_VOICE, 40) or VOICE_TTS_VOICE
            model = _voice_compact(data.get("model") or VOICE_LIVE_MODEL, 80) or VOICE_LIVE_MODEL
            language_code = _voice_compact(data.get("language_code") or data.get("language") or "", 16) or None
            await _voice_live_stream_one(
                ws, key,
                text=text, voice=voice, model=model,
                language_code=language_code, workspace_id=workspace_id,
            )
    except (ConnectionResetError, ConnectionError):
        pass
    finally:
        if not ws.closed:
            await ws.close()
    return ws


# ─── Voice helper: inject a message into a session PTY (used by ask_brainstormer) ──
async def _voice_inject_session(session_id: str, message: str) -> bool:
    """Type a message into a running session's PTY (CLI-aware), mirroring
    send_session_input's write dance. Best-effort; returns False if the
    session isn't running."""
    if not message or not pty_mgr.is_alive(session_id):
        return False
    cli_type = await _session_cli_type(session_id)
    ready_timeout = 6.0 if cli_type in {"antigravity", "codex"} else 2.0
    await _wait_for_cli_input_ready(session_id, cli_type, ready_timeout)
    if cli_type == "gemini":
        pty_mgr.write(session_id, b"\x15")  # Ctrl-U line clear
        payload = message.replace("\n", " ").replace("\r", " ").encode("utf-8")
    else:
        pty_mgr.write(session_id, b"\x1b" + b"\x7f" * 50)
        payload = message.encode("utf-8")
    await asyncio.sleep(0.3)
    if pty_mgr.write(session_id, payload) is False:
        return False  # never submit a stale or partial input line
    submit_delay = 0.8 if cli_type in {"codex", "antigravity"} else 0.3
    if len(payload) > 120:
        submit_delay = max(submit_delay, min(1.5, len(payload) / 600))
    await asyncio.sleep(submit_delay)
    return pty_mgr.write(session_id, b"\r") is not False




