# ── Shared memory_entries keyword search ────────────────────────────────
# The query lives in ``memory_manager.search_memory_entries_rows`` — ONE
# implementation behind BOTH memory-search surfaces here:
#   • GET /api/memory/search                 → search_memory_entries
#   • GET /api/workspaces/{id}/memory-search → unified_memory_search ('memory')
# and behind ``MemoryManager.search()``, the storage-layer variant catchup.py
# uses for prompt-time recall. All three used to carry their own copy of the
# SELECT. That split is exactly how the default-type drift in the unified
# surface stayed invisible: a fix applied to one query never reached the
# others. The SCOPING genuinely differs between the surfaces (see each route's
# docstring) so it stays parameterised on the helper — but the LIKE columns,
# the type filter and the ordering are shared and change once.
# It sits in memory_manager because the third caller is not an HTTP surface;
# server imports memory_manager, never the reverse.


async def search_memory_entries(request: web.Request) -> web.Response:
    """GET /api/memory/search?q=... — the entries-only surface for the Memory window.

    One of TWO memory-search routes, deliberately scoped differently; keep them
    in lockstep. The other is ``unified_memory_search``
    (``GET /api/workspaces/{id}/memory-search``) — the workspace-wide
    multi-bucket search workers use, which spans tasks/digests/knowledge/
    messages/files/memory/brain and whose ``memory`` bucket is scoped
    ``(workspace_id = ? OR workspace_id IS NULL)`` so a worker also sees
    machine-wide facts.

    THIS route returns ``memory_entries`` rows and nothing else, and mirrors
    ``/api/memory`` scoping rather than the unified bucket's: NULL-scoped
    (global) rows are EXCLUDED when a workspace is supplied unless
    ``?include_global=1`` is passed, so the Memory window never displays an
    entry the user did not file under the workspace they are looking at.

    Both routes run the same SQL via
    ``memory_manager.search_memory_entries_rows``; only the scoping and column
    arguments differ.
    """
    from memory_manager import search_memory_entries_rows
    query = request.query.get("q", "").strip()
    if not query:
        return web.json_response({"error": "q parameter required"}, status=400)
    workspace_id = request.query.get("workspace") or request.query.get("workspace_id")
    include_global = request.query.get("include_global", "0").lower() in ("1", "true", "yes")
    entries = await search_memory_entries_rows(
        query,
        workspace_id=workspace_id,
        include_global=include_global,
        types=request.query.get("types", "").split(",") if request.query.get("types") else None,
    )
    return web.json_response(entries)


async def unified_memory_search(request: web.Request) -> web.Response:
    """Core MCP search: explicit workspace records, independent of Myelin."""
    from workspace_context_search import SEARCH_TYPES, search_workspace_context
    workspace_id = request.match_info["id"]
    ctx = get_auth(request)
    if not _workspace_visible_to_auth(workspace_id, ctx):
        return web.json_response({"error": "workspace not found"}, status=404)
    caller = await _resolve_caller(request)
    if request.headers.get("X-IVE-Session-Id") and not caller:
        return web.json_response({"error": "session not found"}, status=403)
    if caller and caller["workspace_id"] != workspace_id:
        return web.json_response({"error": "workspace not found"}, status=404)
    query = request.query.get("q", "").strip()
    if not query or len(query) > 500:
        return web.json_response({"error": "q must contain 1 to 500 characters"}, status=400)
    types = list(dict.fromkeys(part.strip() for part in request.query.get("types", ",".join(SEARCH_TYPES)).split(",") if part.strip()))
    if not types or any(kind not in SEARCH_TYPES for kind in types):
        return web.json_response({"error": "unsupported search types"}, status=400)
    try:
        limit = int(request.query.get("limit", "5"))
        if not 1 <= limit <= 25:
            raise ValueError
    except (TypeError, ValueError):
        return web.json_response({"error": "limit must be between 1 and 25"}, status=400)
    db = await get_db()
    try:
        row = await (await db.execute("SELECT id FROM workspaces WHERE id = ?", (workspace_id,))).fetchone()
        if not row:
            return web.json_response({"error": "workspace not found"}, status=404)
    finally:
        await db.close()
    result = await search_workspace_context(workspace_id, query, types, limit,
                                            include_global=bool(ctx.is_owner))
    return web.json_response(result)


async def import_memory_from_cli(request: web.Request) -> web.Response:
    """POST /api/memory/import — import from a CLI's native memory format."""
    from memory_manager import memory_manager
    body = await request.json()
    if not isinstance(body, dict):
        return web.json_response({"error": "request must be an object"}, status=400)
    workspace_id = body.get("workspace_id")
    consent = body.get("consent") is True
    from memory_sync import native_memory_allowed
    if not await native_memory_allowed(workspace_id, consent=consent):
        return web.json_response({"error": "Confirm importing existing CLI memories into IVE.",
                                  "code": "native_memory_consent_required"}, status=403)
    workspace_path = body.get("workspace_path")
    cli = (body.get("cli") or body.get("cli_type") or "claude").strip().lower()
    if cli == "gemini" and is_active_cli("antigravity"):
        cli = "antigravity"
    if not is_active_cli(cli):
        allowed = ", ".join(profile.id for profile in active_profiles())
        return web.json_response(
            {"error": f"unsupported cli '{cli}', expected one of: {allowed}"},
            status=400,
        )

    if not workspace_path and workspace_id:
        ws_path = await _get_workspace_path(workspace_id)
        if not ws_path:
            return web.json_response({"error": "workspace not found"}, status=404)
        workspace_path = ws_path

    if not workspace_path:
        return web.json_response({"error": "workspace_path or workspace_id required"}, status=400)

    count = await memory_manager.import_from_provider_memory(
        cli, workspace_path, workspace_id=workspace_id, consent=consent,
    )
    return web.json_response({"imported": count, "cli": cli})


async def export_memory_prompt(request: web.Request) -> web.Response:
    """GET /api/memory/prompt?workspace=... — preview the prompt injection text."""
    from memory_manager import memory_manager
    from output_styles import resolve_output_style
    ws_id = request.query.get("workspace")
    # Resolve compact mode from workspace/global output style
    compact = False
    if ws_id:
        db_os = await get_db()
        try:
            _c = await db_os.execute("SELECT output_style FROM workspaces WHERE id = ?", (ws_id,))
            _r = await _c.fetchone()
            _ws_os = _r["output_style"] if _r else None
            _c2 = await db_os.execute("SELECT value FROM app_settings WHERE key = 'output_style'")
            _r2 = await _c2.fetchone()
            _gl_os = _r2["value"] if _r2 else None
            compact = resolve_output_style(None, _ws_os, _gl_os) not in ("default", "lite")
        except Exception:
            pass
        finally:
            await db_os.close()
    text = await memory_manager.export_for_prompt(
        workspace_id=ws_id,
        max_chars=int(request.query.get("max_chars", "4000")),
        compact=compact,
    )
    return web.json_response({"prompt": text, "length": len(text)})






# ─── REST: Commander ─────────────────────────────────────────────────

def _render_alloy_commander_prompt(ws_dict: dict) -> str:
    if not bool(ws_dict.get("alloy_enabled")):
        return (
            "\n\nWorkspace Alloy: disabled. Treat SDK/OpenAPI/MCP generation "
            "requests as normal product discussion unless the user explicitly "
            "asks to enable Alloy in Workspace Settings."
        )
    return (
        "\n\nWorkspace Alloy: enabled. Alloy is for SDK/MCP generation for "
        "the software being developed in this workspace, not for IVE's own "
        "backend unless explicitly requested. For Alloy requests, create one "
        "Feature Board ticket labeled 'alloy' plus relevant labels such as "
        "'openapi', 'sdk', or 'mcp'. Keep the default flow Worker-only: the "
        "Worker generates, integrates, and smoke-tests project-owned artifacts. "
        "Set pipeline=false unless the user explicitly wants a visible pipeline "
        "run. Set test_with_agent=true only when the generated SDK/MCP surface "
        "will be relied on by agents, shipped, promoted, or reused. Treat "
        "Documentor as optional docs refinement for README/examples/docstrings, "
        "not a required gate."
    )


def _build_commander_dynamic_prompt(ws_dict: dict) -> str:
    max_w = ws_dict.get("commander_max_workers") or 3
    max_t = ws_dict.get("tester_max_workers") or 2
    try:
        from orchestration_policy import render_policy_for_prompt
        policy_prompt = "\n\n" + render_policy_for_prompt(ws_dict.get("orchestration_policy"))
    except Exception:
        policy_prompt = ""
    return COMMANDER_SYSTEM_PROMPT + (
        f"\n\nWorkspace Limits: max_workers={max_w}, max_testers={max_t}. "
        "Do not exceed these concurrency limits when creating sessions."
    ) + _render_alloy_commander_prompt(ws_dict) + policy_prompt


async def _ensure_workspace_commander(workspace_id: str) -> dict | None:
    """Ensure a workspace has one dormant Commander session row.

    This is infrastructure provisioning, not a user-visible "start" action:
    it creates/heals the row and MCP attachment but does not start the PTY.
    """
    db = await get_db()
    try:
        # Serialize the check/create pair with explicit deletion, including
        # its persistent opt-out. A startup task must not resurrect a deleted
        # Commander based on a snapshot taken before that deletion committed.
        await db.execute("BEGIN IMMEDIATE")
        cur = await db.execute("SELECT * FROM workspaces WHERE id = ?", (workspace_id,))
        ws = await cur.fetchone()
        if not ws:
            return None
        ws_dict = dict(ws)
        if ws_dict.get("inherit_orchestration_policy_from"):
            from db import resolve_workspace_orchestration_policy
            ws_dict["orchestration_policy"] = await resolve_workspace_orchestration_policy(db, workspace_id)

        cur = await db.execute(
            """SELECT * FROM sessions
               WHERE workspace_id = ? AND session_type = 'commander'
               ORDER BY created_at DESC LIMIT 1""",
            (workspace_id,),
        )
        existing = await cur.fetchone()
        if existing:
            await db.execute(
                "UPDATE sessions SET auto_approve_mcp = 1 WHERE id = ?",
                (existing["id"],),
            )
            await db.execute(
                "INSERT OR IGNORE INTO session_mcp_servers (session_id, mcp_server_id, auto_approve_override) VALUES (?, ?, 1)",
                (existing["id"], "builtin-commander"),
            )
            await db.commit()
            cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (existing["id"],))
            row = await cur.fetchone()
            return dict(row) if row else None

        cur = await db.execute(
            "SELECT value FROM app_settings WHERE key = ?",
            (_commander_provision_suppression_key(workspace_id),),
        )
        suppressed = await cur.fetchone()
        if suppressed and suppressed["value"] == "1":
            return None

        policy_cli, policy_model = None, None
        try:
            from orchestration_policy import role_model
            policy_cli, policy_model = role_model(ws_dict.get("orchestration_policy"), "brain")
        except Exception:
            pass

        cli_type = policy_cli if policy_cli and is_active_cli(policy_cli) else None
        if not cli_type:
            active = active_profiles()
            cli_type = active[0].id if active else "claude"
        if not is_active_cli(cli_type):
            logger.debug("Default Commander not provisioned for %s: CLI %s inactive", workspace_id, cli_type)
            return None

        profile = get_profile(cli_type)
        if policy_model:
            valid_model_ids = {
                str(m.get("id")) for m in getattr(profile, "available_models", [])
                if isinstance(m, dict) and m.get("id") is not None
            }
            if valid_model_ids and str(policy_model) not in valid_model_ids:
                policy_model = None

        default_model = profile.default_commander_model or _profile_default_model_for_role(profile, "commander")
        model = _model_for_storage(profile, policy_model or default_model, "commander")
        permission_mode = profile.default_permission_mode
        effort = "max" if profile.effort_levels else None
        dynamic_prompt = _build_commander_dynamic_prompt(ws_dict)

        session_id = str(uuid.uuid4())
        await db.execute(
            """INSERT INTO sessions (id, workspace_id, name, model, permission_mode, effort,
               system_prompt, session_type, auto_approve_mcp, cli_type, disallowed_tools)
               VALUES (?, ?, ?, ?, ?, ?, ?, 'commander', 1, ?, ?)""",
            (
                session_id,
                workspace_id,
                f"Commander ({profile.label}) — {ws_dict['name']}",
                model,
                permission_mode,
                effort,
                dynamic_prompt,
                cli_type,
                json.dumps(COMMANDER_DISALLOWED_TOOLS),
            ),
        )
        await db.execute(
            "INSERT OR IGNORE INTO session_mcp_servers (session_id, mcp_server_id, auto_approve_override) VALUES (?, ?, 1)",
            (session_id, "builtin-commander"),
        )
        await db.commit()
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
        return dict(row) if row else None
    finally:
        await db.close()


async def _ensure_commanders_for_all_workspaces():
    db = await get_db()
    try:
        cur = await db.execute("SELECT id FROM workspaces")
        ids = [row["id"] for row in await cur.fetchall()]
    finally:
        await db.close()
    for workspace_id in ids:
        try:
            await _ensure_workspace_commander(workspace_id)
        except Exception as exc:
            logger.debug("Default Commander provisioning skipped for %s: %s", workspace_id, exc)


async def _ensure_worker_board_for_all_workers():
    db = await get_db()
    try:
        await db.execute(
            """INSERT OR IGNORE INTO session_mcp_servers
               (session_id, mcp_server_id, auto_approve_override)
               SELECT id, 'builtin-worker-board', 1
               FROM sessions
               WHERE session_type != 'commander'"""
        )
        await db.commit()
    finally:
        await db.close()


async def _ensure_workspace_commander_safely(workspace_id: str):
    try:
        await _ensure_workspace_commander(workspace_id)
    except Exception as exc:
        logger.debug("Default Commander provisioning skipped for %s: %s", workspace_id, exc)


async def create_commander(request: web.Request) -> web.Response:
    workspace_id = request.match_info["id"]
    # Accept optional body to override CLI/model
    body = {}
    try:
        body = await request.json()
    except Exception:
        pass
    requested_cli_type = body.get("cli_type")
    requested_model = body.get("model")
    db = await get_db()
    try:
        # Verify workspace exists
        cur = await db.execute("SELECT * FROM workspaces WHERE id = ?", (workspace_id,))
        ws = await cur.fetchone()
        if not ws:
            return web.json_response({"error": "workspace not found"}, status=404)
        ws_dict = dict(ws)
        if ws_dict.get("inherit_orchestration_policy_from"):
            from db import resolve_workspace_orchestration_policy
            ws_dict["orchestration_policy"] = await resolve_workspace_orchestration_policy(db, workspace_id)

        policy_cli, policy_model = None, None
        try:
            from orchestration_policy import role_model
            policy_cli, policy_model = role_model(ws_dict.get("orchestration_policy"), "brain")
        except Exception:
            pass

        cli_type = requested_cli_type or policy_cli or "claude"
        if not is_active_cli(cli_type):
            return _inactive_cli_response(cli_type)

        # Auto-install safety_gate hook so the Commander delegation deny in
        # /api/safety/evaluate actually fires. Idempotent: skips if already
        # installed.
        try:
            from hook_installer import (
                install_safety_gate_hooks,
                check_safety_gate_installation,
            )
            gate_state = check_safety_gate_installation()
            if not (gate_state.get("claude") and gate_state.get("script_exists")):
                install_safety_gate_hooks()
                logger.info("Safety gate hooks auto-installed for Commander deny enforcement")
        except Exception as gate_err:
            logger.warning("Safety gate auto-install skipped: %s", gate_err)

        profile = get_profile(cli_type)
        if policy_model:
            valid_model_ids = {
                str(m.get("id")) for m in getattr(profile, "available_models", [])
                if isinstance(m, dict) and m.get("id") is not None
            }
            if valid_model_ids and str(policy_model) not in valid_model_ids:
                policy_model = None

        default_model = profile.default_commander_model or _profile_default_model_for_role(profile, "commander")
        model = _model_for_storage(
            profile,
            requested_model if requested_model not in (None, "") else (policy_model or default_model),
            "commander",
        )
        default_mode = profile.default_permission_mode
        permission_mode = body.get("permission_mode", default_mode)
        _mode_err = _permission_mode_error(profile, permission_mode)
        if _mode_err is not None:
            return _mode_err
        effort = body.get("effort", "max") if profile.effort_levels else None

        # Check if a commander session already exists for this workspace
        cur = await db.execute(
            """SELECT * FROM sessions
               WHERE workspace_id = ? AND session_type = 'commander' AND cli_type = ?
               ORDER BY created_at DESC LIMIT 1""",
            (workspace_id, cli_type),
        )
        cli_label = profile.label
        name = f"Commander ({cli_label}) — {ws_dict['name']}"

        # Inject dynamic workspace limits and feature flags into Commander system prompt
        dynamic_prompt = _build_commander_dynamic_prompt(ws_dict)

        existing = await cur.fetchone()
        if existing:
            # Heal older Commander rows on every click: rewrite name, system
            # prompt, auto_approve_mcp, and disallowed_tools, and ensure
            # builtin-commander is attached. Older rows can have NULL
            # system_prompt, auto_approve_mcp=0, or NULL disallowed_tools
            # (created before the orchestrator wiring), which silently breaks
            # Commander tool routing or lets it implement instead of delegate.
            await db.execute(
                """UPDATE sessions
                   SET name = ?, model = ?, permission_mode = ?, effort = ?,
                       system_prompt = ?, auto_approve_mcp = 1,
                       disallowed_tools = ?
                   WHERE id = ?""",
                (name, model, permission_mode, effort,
                 dynamic_prompt, json.dumps(COMMANDER_DISALLOWED_TOOLS),
                 existing["id"]),
            )
            await db.execute(
                "INSERT OR IGNORE INTO session_mcp_servers (session_id, mcp_server_id, auto_approve_override) VALUES (?, ?, 1)",
                (existing["id"], "builtin-commander"),
            )
            await db.execute(
                "DELETE FROM app_settings WHERE key = ?",
                (_commander_provision_suppression_key(workspace_id),),
            )
            await db.commit()
            cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (existing["id"],))
            row = await cur.fetchone()
            from hooks import get_session_logical_status
            d = dict(row)
            d["status"] = get_session_logical_status(d["id"], pty_mgr.is_alive(d["id"]), d.get("status") or "idle")
            return web.json_response(d)

        # Commander sessions use the dynamic MCP server system.
        # The builtin-commander MCP server is attached via session_mcp_servers
        # instead of writing a raw config file. PTY start handles registration.
        session_id = str(uuid.uuid4())

        await db.execute(
            """INSERT INTO sessions (id, workspace_id, name, model, permission_mode, effort,
               system_prompt, session_type, auto_approve_mcp, cli_type,
               disallowed_tools)
               VALUES (?, ?, ?, ?, ?, ?, ?, 'commander', 1, ?, ?)""",
            (session_id, workspace_id, name, model, permission_mode, effort,
             dynamic_prompt, cli_type,
             json.dumps(COMMANDER_DISALLOWED_TOOLS)),
        )
        # Attach builtin-commander MCP server with auto-approve
        await db.execute(
            "INSERT OR IGNORE INTO session_mcp_servers (session_id, mcp_server_id, auto_approve_override) VALUES (?, ?, 1)",
            (session_id, "builtin-commander"),
        )
        await db.execute(
            "DELETE FROM app_settings WHERE key = ?",
            (_commander_provision_suppression_key(workspace_id),),
        )
        await db.commit()
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
        return web.json_response(dict(row), status=201)
    finally:
        await db.close()


async def get_commander(request: web.Request) -> web.Response:
    workspace_id = request.match_info["id"]
    db = await get_db()
    try:
        cur = await db.execute(
            """SELECT * FROM sessions
               WHERE workspace_id = ? AND session_type = 'commander'
               ORDER BY created_at DESC LIMIT 1""",
            (workspace_id,),
        )
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "no commander session found"}, status=404)
        from hooks import get_session_logical_status
        d = dict(row)
        d["status"] = get_session_logical_status(d["id"], pty_mgr.is_alive(d["id"]), d.get("status") or "idle")
        return web.json_response(d)
    finally:
        await db.close()


async def _ensure_workspace_brainstormer(
    workspace_id: str,
    ctx,
    body: dict | None = None,
) -> tuple[dict | None, int]:
    body = body or {}
    owner_kind, owner_id = _brainstormer_owner_key(ctx)
    actor_label = _brainstormer_owner_label(ctx)
    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM workspaces WHERE id = ?", (workspace_id,))
        ws = await cur.fetchone()
        if not ws:
            return None, 404
        ws_dict = dict(ws)
        if ws_dict.get("inherit_orchestration_policy_from"):
            from db import resolve_workspace_orchestration_policy
            ws_dict["orchestration_policy"] = await resolve_workspace_orchestration_policy(db, workspace_id)

        cur = await db.execute(
            """SELECT * FROM sessions
               WHERE workspace_id = ?
                 AND session_type = 'brainstormer'
                 AND COALESCE(owner_actor_kind, '') = ?
                 AND COALESCE(owner_actor_id, '') = ?
               ORDER BY created_at DESC LIMIT 1""",
            (workspace_id, owner_kind, owner_id),
        )
        existing = await cur.fetchone()
        if existing:
            existing_dict = dict(existing)
            existing_prompt = existing_dict.get("system_prompt") or ""
            cur = await db.execute(
                """SELECT auto_approve_override FROM session_mcp_servers
                   WHERE session_id = ? AND mcp_server_id = ?""",
                (existing_dict["id"], "builtin-worker-board"),
            )
            mcp_row = await cur.fetchone()
            needs_prompt_heal = "You are the Brainstormer" not in existing_prompt
            needs_auto_approve = int(existing_dict.get("auto_approve_mcp") or 0) != 1
            needs_mcp_heal = not mcp_row or int(mcp_row["auto_approve_override"] or 0) != 1
            if not (needs_prompt_heal or needs_auto_approve or needs_mcp_heal):
                return _decorate_session_dict(existing_dict), 200

            lock = _brainstormer_ensure_lock(workspace_id, owner_kind, owner_id)
            try:
                async with lock:
                    if needs_prompt_heal:
                        healed_prompt = BRAINSTORMER_SYSTEM_PROMPT + (
                            "\n\n" + existing_prompt if existing_prompt else ""
                        )
                        await db.execute(
                            """UPDATE sessions
                               SET system_prompt = ?, auto_approve_mcp = 1
                               WHERE id = ?""",
                            (healed_prompt, existing_dict["id"]),
                        )
                    elif needs_auto_approve:
                        await db.execute(
                            "UPDATE sessions SET auto_approve_mcp = 1 WHERE id = ?",
                            (existing_dict["id"],),
                        )
                    if needs_mcp_heal:
                        await db.execute(
                            """INSERT INTO session_mcp_servers
                               (session_id, mcp_server_id, auto_approve_override)
                               VALUES (?, ?, 1)
                               ON CONFLICT(session_id, mcp_server_id)
                               DO UPDATE SET auto_approve_override = 1""",
                            (existing_dict["id"], "builtin-worker-board"),
                        )
                    await db.commit()
                    cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (existing_dict["id"],))
                    row = await cur.fetchone()
                    return (_decorate_session_dict(dict(row)) if row else None), 200
            except Exception as exc:
                if "database is locked" in str(exc).lower():
                    logger.debug("Brainstormer heal skipped while database is locked: %s", exc)
                    return _decorate_session_dict(existing_dict), 200
                raise

        policy_cli, policy_model = None, None
        try:
            from orchestration_policy import role_model
            policy_cli, policy_model = role_model(ws_dict.get("orchestration_policy"), "brainstormer")
        except Exception:
            pass

        requested_cli_type = body.get("cli_type")
        requested_model = body.get("model")
        cli_type = requested_cli_type or policy_cli
        if not cli_type:
            active = active_profiles()
            cli_type = active[0].id if active else "claude"
        if not is_active_cli(cli_type):
            return {"error": f"CLI '{cli_type}' is deprecated or unavailable"}, 400

        profile = get_profile(cli_type)
        if policy_model:
            valid_model_ids = {
                str(m.get("id")) for m in getattr(profile, "available_models", [])
                if isinstance(m, dict) and m.get("id") is not None
            }
            if valid_model_ids and str(policy_model) not in valid_model_ids:
                policy_model = None

        default_model = profile.default_commander_model or _profile_default_model_for_role(profile, "brainstormer")
        model = _model_for_storage(
            profile,
            requested_model if requested_model not in (None, "") else (policy_model or default_model),
            "brainstormer",
        )
        permission_mode = body.get("permission_mode", profile.default_permission_mode)
        _mode_err = _permission_mode_error(profile, permission_mode)
        if _mode_err is not None:
            return _mode_err
        effort = _effort_for_storage(profile, body.get("effort"))
        name = body.get("name") or f"Brainstormer - {actor_label} - {ws_dict['name']}"
        session_id = str(uuid.uuid4())
        lock = _brainstormer_ensure_lock(workspace_id, owner_kind, owner_id)
        async with lock:
            cur = await db.execute(
                """SELECT * FROM sessions
                   WHERE workspace_id = ?
                     AND session_type = 'brainstormer'
                     AND COALESCE(owner_actor_kind, '') = ?
                     AND COALESCE(owner_actor_id, '') = ?
                   ORDER BY created_at DESC LIMIT 1""",
                (workspace_id, owner_kind, owner_id),
            )
            concurrent = await cur.fetchone()
            if concurrent:
                return _decorate_session_dict(dict(concurrent)), 200
            await db.execute(
                """INSERT INTO sessions (id, workspace_id, name, model, permission_mode, effort,
                   system_prompt, session_type, auto_approve_mcp, cli_type,
                   disallowed_tools, purpose, owner_actor_kind, owner_actor_id, owner_mode)
                   VALUES (?, ?, ?, ?, ?, ?, ?, 'brainstormer', 1, ?, ?, ?, ?, ?, ?)""",
                (
                    session_id,
                    workspace_id,
                    name,
                    model,
                    permission_mode,
                    effort,
                    BRAINSTORMER_SYSTEM_PROMPT,
                    cli_type,
                    json.dumps(COMMANDER_DISALLOWED_TOOLS),
                    "Explore ideas, research context, and create candidate backlog proposals.",
                    owner_kind,
                    owner_id,
                    ctx.mode,
                ),
            )
            await db.execute(
                """INSERT INTO session_mcp_servers
                   (session_id, mcp_server_id, auto_approve_override)
                   VALUES (?, ?, 1)
                   ON CONFLICT(session_id, mcp_server_id)
                   DO UPDATE SET auto_approve_override = 1""",
                (session_id, "builtin-worker-board"),
            )
            await db.commit()
            cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
            row = await cur.fetchone()
        result = _decorate_session_dict(dict(row)) if row else None
        if result and result.get("session_type") != "brainstormer":
            await broadcast({"type": "session_created", "session": result})
        return result, 201
    finally:
        await db.close()


def _brainstormer_assistant_messages(session: dict) -> list[str]:
    """Return ordered assistant text turns from a Brainstormer's transcript.

    Reads the CLI-native JSONL/JSON transcript (same resolution path as
    list_messages), normalizes each entry, and extracts the plain-text portion
    of every assistant turn. This is the SETTLED-reply source — far more
    reliable than scraping the ~700-char terminal buffer the voice tool uses.
    """
    native_sid = session.get("native_session_id")
    workspace_path = session.get("workspace_path")
    if not native_sid or not workspace_path:
        return []
    transcript_file = _get_native_transcript_path(
        session.get("cli_type"),
        workspace_path,
        native_sid,
        cli_home=_session_transcript_home(session),
    )
    if not transcript_file or not transcript_file.exists():
        return []
    try:
        messages = read_session_messages(str(transcript_file))
    except Exception as exc:
        logger.debug("Brainstormer transcript read failed: %s", exc)
        return []

    out: list[str] = []
    for idx, msg in enumerate(messages):
        normalized = normalize_jsonl_entry(msg)
        if normalized is None:
            continue
        role, content = normalized
        if role != "assistant":
            continue
        if _is_ive_managed_context_message(role, content, idx):
            continue
        text = _brainstormer_text_from_content(content)
        if text:
            out.append(text)
    return out


def _brainstormer_text_from_content(content) -> str:
    """Pull plain assistant text out of normalized content (str or blocks)."""
    if isinstance(content, str):
        return content.strip()
    if isinstance(content, list):
        parts: list[str] = []
        for block in content:
            if isinstance(block, dict):
                if block.get("type") in (None, "text") and block.get("text"):
                    parts.append(str(block["text"]))
            elif isinstance(block, str):
                parts.append(block)
        return "\n".join(p for p in parts if p).strip()
    return ""


async def _brainstormer_session_row(session_id: str) -> dict | None:
    db = await get_db()
    try:
        cur = await db.execute(
            """SELECT s.*, w.path AS workspace_path
               FROM sessions s
               LEFT JOIN workspaces w ON s.workspace_id = w.id
               WHERE s.id = ?""",
            (session_id,),
        )
        row = await cur.fetchone()
    finally:
        await db.close()
    return dict(row) if row else None


async def ask_brainstormer(request: web.Request) -> web.Response:
    """POST /api/workspaces/{id}/brainstormer/ask  body: {message, timeout_secs?}

    Deliver a question to the caller's per-person Brainstormer and return a
    SETTLED structured reply. Reuses _ensure_workspace_brainstormer for owner
    resolution + session delivery, but instead of scraping the terminal buffer
    (the fragile terminal-buffer-scrape path) it waits for the turn to
    settle — the session goes idle AND a fresh assistant turn appears in the
    native transcript — then returns that assistant text.

    Owner guards: _ensure_workspace_brainstormer keys on _brainstormer_owner_key
    so the resolved session belongs to THIS caller's owner, and
    _session_readable_to_request gates the resolved session so one operator's
    Brainstormer never leaks to another.
    """
    workspace_id = request.match_info["id"]
    try:
        body = await request.json()
    except Exception:
        body = {}
    message = (body.get("message") or "").strip()
    if not message:
        return web.json_response({"ok": False, "error": "message required"}, status=400)

    try:
        timeout_secs = int(body.get("timeout_secs") or 90)
    except (TypeError, ValueError):
        timeout_secs = 90
    timeout_secs = max(10, min(timeout_secs, 240))  # clamp

    result, status = await _ensure_workspace_brainstormer(workspace_id, get_auth(request))
    if not result:
        return web.json_response({"ok": False, "error": "workspace not found"}, status=status)
    bid = result["id"]

    # Owner guard: the resolved Brainstormer must be OWNED by this caller's auth.
    # _ensure_workspace_brainstormer already resolves strictly by the caller's
    # owner key, so this re-check confirms owner-match (rejecting a cross-owner
    # reach) WITHOUT the _session_readable_to_request self-read check — that one
    # compares caller_session_id == this session's id, which is always false for
    # an agent-origin call (the caller is the Commander/GI, not the Brainstormer),
    # and was 403-ing the primary MCP path.
    sess_row = await _brainstormer_session_row(bid)
    if not sess_row or not _session_owned_by_auth(sess_row, get_auth(request)):
        return web.json_response({"ok": False, "error": "brainstormer not accessible"}, status=403)

    # Boot the PTY if needed; the caller should retry once it's up.
    if not pty_mgr.is_alive(bid):
        try:
            await _autostart_session_pty(bid)
        except Exception as exc:
            logger.warning("ask_brainstormer autostart failed: %s", exc)
        return web.json_response(
            {"ok": True, "status": "starting",
             "note": "Brainstormer is booting; ask again in a moment."},
            status=202,
        )

    # Snapshot the assistant-turn count before injecting so we can detect the
    # NEW reply (not echo an earlier turn).
    before_row = await _brainstormer_session_row(bid)
    before_count = len(_brainstormer_assistant_messages(before_row)) if before_row else 0

    injected = await _voice_inject_session(bid, message)
    if not injected:
        return web.json_response(
            {"ok": True, "status": "unavailable",
             "note": "could not deliver to Brainstormer"},
            status=202,
        )

    # Settle loop: wait for (a) a new assistant turn to land in the transcript
    # AND (b) the session to be idle (turn complete). Bounded by timeout_secs.
    from hooks import get_session_logical_status
    import time as _time
    deadline = _time.monotonic() + timeout_secs
    reply = ""
    settled = False
    # Require the assistant turn to be stable across two idle polls so we don't
    # return a half-streamed message.
    stable_idle = 0
    while _time.monotonic() < deadline:
        await asyncio.sleep(1.5)
        row = await _brainstormer_session_row(bid)
        if not row:
            break
        msgs = _brainstormer_assistant_messages(row)
        has_new = len(msgs) > before_count and msgs[-1].strip()
        alive = pty_mgr.is_alive(bid)
        logical = get_session_logical_status(bid, alive, row.get("status") or "idle")
        if has_new:
            reply = msgs[-1].strip()
            if logical == "idle":
                stable_idle += 1
                if stable_idle >= 2:
                    settled = True
                    break
            else:
                stable_idle = 0

    if reply:
        return web.json_response({
            "ok": True,
            "settled": settled,
            "reply": reply,
            "brainstormer_session_id": bid,
            "note": None if settled else "Returned latest assistant turn before full settle.",
        })
    return web.json_response({
        "ok": True,
        "settled": False,
        "reply": "",
        "brainstormer_session_id": bid,
        "note": "Brainstormer has not produced a reply yet; ask again shortly.",
    }, status=202)


