async def update_brainstormer_privacy(request: web.Request) -> web.Response:
    workspace_id = request.match_info["id"]
    try:
        body = await request.json()
    except Exception:
        body = {}
    make_public = bool(body.get("public", body.get("is_public", False)))
    result, status = await _ensure_workspace_brainstormer(workspace_id, get_auth(request))
    if not result:
        return web.json_response({"error": "workspace not found"}, status=status)
    session_id = result["id"]
    tags = _session_tags_from_value(result.get("tags"))
    if make_public and BRAINSTORMER_PUBLIC_TAG not in tags:
        tags.append(BRAINSTORMER_PUBLIC_TAG)
    if not make_public:
        tags = [t for t in tags if t != BRAINSTORMER_PUBLIC_TAG]

    db = await get_db()
    try:
        await db.execute(
            "UPDATE sessions SET tags = ? WHERE id = ?",
            (json.dumps(tags), session_id),
        )
        await db.commit()
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
    finally:
        await db.close()
    return web.json_response(_decorate_readable_session_dict(dict(row), request))


async def list_public_brainstormers(request: web.Request) -> web.Response:
    workspace_id = request.match_info["id"]
    db = await get_db()
    try:
        cur = await db.execute(
            """SELECT * FROM sessions
               WHERE workspace_id = ? AND session_type = 'brainstormer'
               ORDER BY last_active_at DESC NULLS LAST, created_at DESC""",
            (workspace_id,),
        )
        rows = await cur.fetchall()
    finally:
        await db.close()

    result = []
    ctx = get_auth(request)
    for row in rows:
        session = dict(row)
        if not _brainstormer_is_public(session):
            continue
        if _session_owned_by_auth(session, ctx):
            continue
        if not _session_readable_to_request(session, request):
            continue
        result.append(_decorate_readable_session_dict(session, request))
    return web.json_response(result)


def _docs_parse_timestamp(value) -> datetime.datetime | None:
    if not value:
        return None
    if isinstance(value, (int, float)):
        return datetime.datetime.fromtimestamp(value, datetime.timezone.utc)
    text = str(value).strip()
    if not text:
        return None
    candidates = [text.replace("Z", "+00:00"), text.replace(" ", "T").replace("Z", "+00:00")]
    for candidate in candidates:
        try:
            dt = datetime.datetime.fromisoformat(candidate)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except ValueError:
            continue
    return None


def _docs_timestamp_iso(value) -> str | None:
    dt = _docs_parse_timestamp(value)
    return dt.isoformat() if dt else None


def _read_doc_title(path: str, fallback: str) -> str:
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            lines = [next(f, "") for _ in range(24)]
    except Exception:
        return fallback

    in_frontmatter = False
    for line in lines:
        stripped = line.strip()
        if stripped == "---":
            in_frontmatter = not in_frontmatter
            continue
        if in_frontmatter and stripped.lower().startswith("title:"):
            return stripped.partition(":")[2].strip().strip("\"'") or fallback
        if stripped.startswith("# "):
            return stripped[2:].strip() or fallback
    return fallback


async def get_docs_status(request: web.Request) -> web.Response:
    """GET /api/workspaces/{id}/docs — docs manifest, tree, and coverage stats."""
    workspace_id = request.match_info["id"]
    db = await get_db()
    try:
        cur = await db.execute("SELECT id, name, path FROM workspaces WHERE id = ?", (workspace_id,))
        ws = await cur.fetchone()
        if not ws:
            return web.json_response({"error": "workspace not found"}, status=404)
        ws_row = dict(ws)
        ws_path = ws_row["path"]
    finally:
        await db.close()

    import os as _os

    docs_dir = _os.path.join(ws_path, "docs")
    manifest_path = _os.path.join(docs_dir, "docs_manifest.json")

    # Read manifest
    manifest = {}
    if _os.path.isfile(manifest_path):
        try:
            with open(manifest_path) as f:
                manifest = json.load(f)
        except Exception:
            pass
    manifest_pages = manifest.get("pages") if isinstance(manifest.get("pages"), dict) else {}
    documented_tasks = set(manifest.get("documented_tasks", []) if isinstance(manifest.get("documented_tasks"), list) else [])
    documented_commits = set(manifest.get("documented_commits", []) if isinstance(manifest.get("documented_commits"), list) else [])

    # Count files
    page_count = 0
    screenshot_count = 0
    gif_count = 0
    pages: list[dict] = []
    screenshots: list[dict] = []
    gifs: list[dict] = []
    tree: list[str] = []
    latest_docs_activity: datetime.datetime | None = None

    if _os.path.isdir(docs_dir):
        for root, dirs, files in _os.walk(docs_dir):
            dirs[:] = [d for d in dirs if d not in ("node_modules", "cache", "dist", ".vitepress")]
            level = root.replace(docs_dir, "").count(_os.sep)
            folder = _os.path.basename(root) or "docs"
            tree.append("  " * level + folder + "/")
            for fn in sorted(files):
                tree.append("  " * (level + 1) + fn)
                full = _os.path.join(root, fn)
                rel = _os.path.relpath(full, docs_dir).replace(_os.sep, "/")
                try:
                    stat = _os.stat(full)
                    modified = datetime.datetime.fromtimestamp(stat.st_mtime, datetime.timezone.utc)
                    if latest_docs_activity is None or modified > latest_docs_activity:
                        latest_docs_activity = modified
                except Exception:
                    stat = None
                    modified = None
                if fn.endswith(".md"):
                    page_count += 1
                    manifest_meta = manifest_pages.get(rel) if isinstance(manifest_pages.get(rel), dict) else {}
                    pages.append({
                        "path": rel,
                        "name": fn,
                        "title": manifest_meta.get("title") or _read_doc_title(full, rel),
                        "tracked": rel in manifest_pages,
                        "updated_at": manifest_meta.get("updated_at"),
                        "modified_at": modified.isoformat() if modified else None,
                        "size_kb": round((stat.st_size if stat else _os.path.getsize(full)) / 1024, 1),
                    })
                elif fn.lower().endswith((".png", ".jpg", ".jpeg", ".webp")):
                    screenshot_count += 1
                    screenshots.append({
                        "name": fn,
                        "path": rel,
                        "size_kb": round((stat.st_size if stat else _os.path.getsize(full)) / 1024, 1),
                        "modified_at": modified.isoformat() if modified else None,
                    })
                elif fn.lower().endswith(".gif"):
                    gif_count += 1
                    gifs.append({
                        "name": fn,
                        "path": rel,
                        "size_kb": round((stat.st_size if stat else _os.path.getsize(full)) / 1024, 1),
                        "modified_at": modified.isoformat() if modified else None,
                    })
    pages.sort(key=lambda p: p["path"])
    screenshots.sort(key=lambda item: item.get("modified_at") or "", reverse=True)
    gifs.sort(key=lambda item: item.get("modified_at") or "", reverse=True)

    # Undocumented features
    undocumented: list[dict] = []
    completed_features: list[dict] = []
    latest_feature_change: datetime.datetime | None = None
    try:
        db2 = await get_db()
        try:
            cur = await db2.execute(
                """SELECT id, title, status, labels, updated_at, completed_at
                   FROM tasks
                   WHERE workspace_id = ? AND status IN ('done', 'review')
                   ORDER BY COALESCE(completed_at, updated_at, created_at) DESC""",
                (workspace_id,),
            )
            rows = await cur.fetchall()
            for r in rows:
                task = {
                    "id": r["id"],
                    "title": r["title"],
                    "status": r["status"],
                    "labels": _parse_json_field(r["labels"]),
                    "updated_at": r["updated_at"],
                    "completed_at": r["completed_at"],
                }
                completed_features.append(task)
                changed_at = _docs_parse_timestamp(r["completed_at"] or r["updated_at"])
                if changed_at and (latest_feature_change is None or changed_at > latest_feature_change):
                    latest_feature_change = changed_at
                if r["id"] not in documented_tasks:
                    undocumented.append(task)
        finally:
            await db2.close()
    except Exception:
        pass

    page_paths = {p["path"] for p in pages}
    missing_pages = [
        {"path": path, **(meta if isinstance(meta, dict) else {})}
        for path, meta in sorted(manifest_pages.items())
        if path not in page_paths
    ]
    untracked_pages = [p for p in pages if not p["tracked"]]
    stale_pages = []
    if latest_feature_change:
        for page in pages:
            page_updated = _docs_parse_timestamp(page.get("updated_at") or page.get("modified_at"))
            if page["tracked"] and page_updated and page_updated < latest_feature_change:
                stale_pages.append(page)

    documented_completed = len({task["id"] for task in completed_features} & documented_tasks)
    completed_count = len(completed_features)
    recent_commits: list[dict] = []
    undocumented_commits: list[dict] = []
    try:
        commits = await git_ops.git_log(ws_path, count=50)
        for commit in commits:
            full_hash = commit.get("hash") or ""
            short_hash = commit.get("short_hash") or full_hash[:8]
            documented = full_hash in documented_commits or short_hash in documented_commits
            item = {**commit, "documented": documented}
            recent_commits.append(item)
            if not documented:
                undocumented_commits.append(item)
    except Exception:
        pass
    documented_recent_commits = len([c for c in recent_commits if c.get("documented")])
    commit_coverage_pct = round((documented_recent_commits / len(recent_commits)) * 100) if recent_commits else 100

    # Calculate overall coverage as a composite of features, commits, and page health
    components = []
    if completed_count > 0:
        components.append(documented_completed / completed_count)
    if recent_commits:
        components.append(documented_recent_commits / len(recent_commits))

    total_pages_count = len(pages) + len(missing_pages)
    if total_pages_count > 0:
        proper_pages = len(pages) - len(untracked_pages)
        components.append(proper_pages / total_pages_count)

    if components:
        coverage_pct = round((sum(components) / len(components)) * 100)
    else:
        coverage_pct = 100

    # Read VitePress dev port if running
    dev_port = None
    dev_port_file = _os.path.join(docs_dir, ".dev-port")
    if _os.path.isfile(dev_port_file):
        try:
            with open(dev_port_file) as f:
                dev_port = int(f.read().strip())
        except Exception:
            pass

    dist_index = _os.path.join(docs_dir, ".vitepress", "dist", "index.html")
    health: list[dict] = []
    if not _os.path.isdir(docs_dir):
        health.append({"level": "missing", "label": "No docs directory", "detail": "Start a Documentor pass to scaffold docs/."})
    elif not _os.path.isfile(manifest_path):
        health.append({"level": "warning", "label": "No manifest", "detail": "Documentor has not tracked page/task coverage yet."})
    if undocumented:
        health.append({"level": "warning", "label": f"{len(undocumented)} undocumented feature(s)", "detail": "Completed or review-ready tasks are not in docs_manifest.json."})
    if undocumented_commits:
        health.append({"level": "info", "label": f"{len(undocumented_commits)} recent commit(s) unmarked", "detail": "Documentor can mark covered commits in docs_manifest.json."})
    if missing_pages:
        health.append({"level": "error", "label": f"{len(missing_pages)} tracked page(s) missing", "detail": "Manifest points at files that are no longer present."})
    if untracked_pages:
        health.append({"level": "info", "label": f"{len(untracked_pages)} untracked page(s)", "detail": "Markdown files exist but are not recorded in docs_manifest.json."})
    if _os.path.isdir(docs_dir) and not _os.path.isfile(dist_index):
        health.append({"level": "info", "label": "Site not built", "detail": "Run Build Site to produce docs/.vitepress/dist."})

    prompt_context = {
        "workspace_name": ws_row.get("name"),
        "pages": page_count,
        "screenshots": screenshot_count,
        "gifs": gif_count,
        "coverage_pct": coverage_pct,
        "undocumented_features": undocumented[:12],
        "undocumented_commits": undocumented_commits[:12],
        "stale_pages": stale_pages[:12],
        "missing_pages": missing_pages[:12],
        "untracked_pages": untracked_pages[:12],
        "last_build_at": manifest.get("last_build_at"),
        "latest_feature_change_at": latest_feature_change.isoformat() if latest_feature_change else None,
    }

    return web.json_response({
        "exists": _os.path.isdir(docs_dir),
        "workspace": {"id": workspace_id, "name": ws_row.get("name"), "path": ws_path},
        "manifest": manifest,
        "pages": page_count,
        "page_list": pages,
        "screenshots": screenshot_count,
        "gifs": gif_count,
        "screenshot_list": screenshots[:50],
        "gif_list": gifs[:50],
        "tree": tree,
        "completed_features": completed_features[:200],
        "undocumented_features": undocumented,
        "recent_commits": recent_commits,
        "undocumented_commits": undocumented_commits,
        "stale_pages": stale_pages,
        "missing_pages": missing_pages,
        "untracked_pages": untracked_pages,
        "coverage": {
            "completed_features": completed_count,
            "documented_completed_features": documented_completed,
            "pct": coverage_pct,
            "recent_commits": len(recent_commits),
            "documented_recent_commits": documented_recent_commits,
            "undocumented_recent_commits": len(undocumented_commits),
            "commit_pct": commit_coverage_pct,
        },
        "health": health,
        "prompt_context": prompt_context,
        "last_build": manifest.get("last_build_at"),
        "latest_docs_activity": latest_docs_activity.isoformat() if latest_docs_activity else None,
        "latest_feature_change": latest_feature_change.isoformat() if latest_feature_change else None,
        "built": _os.path.isfile(dist_index),
        "docs_path": docs_dir,
        "dev_port": dev_port,
    })


async def serve_docs_file(request: web.Request) -> web.StreamResponse:
    """Serve a file from docs/ for screenshots/GIFs/previews."""
    workspace_id = request.match_info["id"]
    rel_path = request.match_info.get("path", "")
    db = await get_db()
    try:
        cur = await db.execute("SELECT path FROM workspaces WHERE id = ?", (workspace_id,))
        ws = await cur.fetchone()
        if not ws:
            return web.json_response({"error": "workspace not found"}, status=404)
        ws_path = ws["path"]
    finally:
        await db.close()

    import os as _os
    import urllib.parse as _urlparse

    docs_root = _os.path.realpath(_os.path.join(ws_path, "docs"))
    requested = _urlparse.unquote(rel_path).lstrip("/\\")
    candidate = _os.path.realpath(_os.path.join(docs_root, requested))
    if candidate != docs_root and not candidate.startswith(docs_root + _os.sep):
        return web.json_response({"error": "path escapes docs directory"}, status=403)
    if not _os.path.isfile(candidate):
        return web.json_response({"error": "file not found"}, status=404)
    return web.FileResponse(candidate)


async def trigger_docs_build(request: web.Request) -> web.Response:
    """POST /api/workspaces/{id}/docs/build — trigger VitePress build."""
    workspace_id = request.match_info["id"]
    db = await get_db()
    try:
        cur = await db.execute("SELECT path FROM workspaces WHERE id = ?", (workspace_id,))
        ws = await cur.fetchone()
        if not ws:
            return web.json_response({"error": "workspace not found"}, status=404)
        ws_path = ws["path"]
    finally:
        await db.close()

    import os as _os

    docs_dir = _os.path.join(ws_path, "docs")
    if not _os.path.isdir(docs_dir):
        return web.json_response({"error": "no docs/ directory found"}, status=404)

    # Auto-install if needed
    if _os.path.isfile(_os.path.join(docs_dir, "package.json")) and not _os.path.isdir(_os.path.join(docs_dir, "node_modules")):
        try:
            proc = await asyncio.create_subprocess_exec(
                "npm", "install", cwd=docs_dir,
                stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,
            )
            await asyncio.wait_for(proc.communicate(), timeout=120)
        except Exception as e:
            return web.json_response({"error": f"npm install failed: {e}"}, status=500)

    try:
        proc = await asyncio.create_subprocess_exec(
            "npx", "vitepress", "build", cwd=docs_dir,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=120)
        if proc.returncode != 0:
            return web.json_response({"error": stderr.decode()[:1000]}, status=500)

        # Update manifest
        manifest_path = _os.path.join(docs_dir, "docs_manifest.json")
        manifest = {}
        if _os.path.isfile(manifest_path):
            try:
                with open(manifest_path) as f:
                    manifest = json.load(f)
            except Exception:
                pass
        manifest["last_build_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        with open(manifest_path, "w") as f:
            json.dump(manifest, f, indent=2)

        # Emit event
        try:
            from event_bus import bus
            await bus.emit(CommanderEvent.DOCS_BUILD_COMPLETED, {
                "workspace_id": workspace_id,
                "docs_path": docs_dir,
            }, source="api", actor="user")
        except Exception:
            pass

        dist_path = _os.path.join(docs_dir, ".vitepress", "dist")
        return web.json_response({
            "ok": True,
            "dist_path": dist_path,
            "stdout": stdout.decode()[-500:],
        })
    except asyncio.TimeoutError:
        return web.json_response({"error": "build timed out after 120s"}, status=500)
    except Exception as e:
        return web.json_response({"error": str(e)}, status=500)


# ─── REST: Observatory ───────────────────────────────────────────────

async def list_observatory_findings(request: web.Request) -> web.Response:
    """GET /api/observatory/findings"""
    import observatory
    params = {
        "workspace_id": request.query.get("workspace_id"),
        "source": request.query.get("source"),
        "status": request.query.get("status"),
        "min_score": float(request.query.get("min_score", 0)),
    }
    params = {k: v for k, v in params.items() if v}
    findings = await observatory.get_findings(**params)
    return web.json_response(findings)


# ─── REST: Observatory Profile + Search Targets ─────────────────────

async def get_observatory_profile(request: web.Request) -> web.Response:
    """GET /api/observatory/profile?workspace_id=...&scope=workspace|company"""
    import observatory_profile
    workspace_id = request.query.get("workspace_id")
    scope = request.query.get("scope", "workspace")
    if scope not in observatory_profile.VALID_SCOPES:
        return web.json_response({"error": "scope must be workspace or company"}, status=400)
    if scope == "workspace" and not workspace_id:
        return web.json_response({"error": "workspace_id required"}, status=400)
    row = await observatory_profile.get_profile(workspace_id, scope=scope)
    return web.json_response(row or {"profile": {}, "scope": scope})


async def regenerate_observatory_profile(request: web.Request) -> web.Response:
    """POST /api/observatory/profile/regenerate body: {workspace_id}"""
    import observatory_profile
    body = await request.json()
    workspace_id = body.get("workspace_id")
    if not workspace_id:
        return web.json_response({"error": "workspace_id required"}, status=400)
    try:
        row = await observatory_profile.build_profile(workspace_id)
    except Exception as exc:
        logger.exception("profile regenerate failed")
        return web.json_response({"error": str(exc)}, status=500)
    return web.json_response(row)


async def update_observatory_profile(request: web.Request) -> web.Response:
    """PUT profile prose for a workspace or the shared company scope."""
    import observatory_profile
    body = await request.json()
    workspace_id = body.get("workspace_id")
