async def test_api_key(request: web.Request) -> web.Response:
    """POST /api/api-keys/test — validate an API key against its service."""
    import api_keys
    body = await request.json()
    name = body.get("name")
    if not name:
        return web.json_response({"error": "name required"}, status=400)

    key = await api_keys.resolve(name)
    if not key:
        return web.json_response({"ok": False, "error": "no key configured"})

    try:
        async with aiohttp.ClientSession() as session:
            if name == "github":
                async with session.get(
                    "https://api.github.com/rate_limit",
                    headers={"Authorization": f"token {key}", "Accept": "application/vnd.github.v3+json"},
                    timeout=aiohttp.ClientTimeout(total=10),
                ) as resp:
                    if resp.status == 200:
                        data = await resp.json()
                        limit = data.get("rate", {}).get("limit", 0)
                        remaining = data.get("rate", {}).get("remaining", 0)
                        return web.json_response({"ok": True, "rate_limit": limit, "remaining": remaining})
                    return web.json_response({"ok": False, "error": f"HTTP {resp.status}"})

            elif name == "producthunt":
                query = '{ viewer { id } }'
                async with session.post(
                    "https://api.producthunt.com/v2/api/graphql",
                    json={"query": query},
                    headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"},
                    timeout=aiohttp.ClientTimeout(total=10),
                ) as resp:
                    return web.json_response({"ok": resp.status == 200, "status": resp.status})

            elif name == "brave":
                async with session.get(
                    "https://api.search.brave.com/res/v1/web/search?q=test&count=1",
                    headers={"Accept": "application/json", "X-Subscription-Token": key},
                    timeout=aiohttp.ClientTimeout(total=10),
                ) as resp:
                    return web.json_response({"ok": resp.status == 200, "status": resp.status})

            elif name == "anthropic":
                async with session.get(
                    "https://api.anthropic.com/v1/models",
                    headers={"x-api-key": key, "anthropic-version": "2023-06-01"},
                    timeout=aiohttp.ClientTimeout(total=10),
                ) as resp:
                    return web.json_response({"ok": resp.status == 200, "status": resp.status})

            elif name == "google":
                async with session.get(
                    f"https://generativelanguage.googleapis.com/v1beta/models?key={key}",
                    timeout=aiohttp.ClientTimeout(total=10),
                ) as resp:
                    return web.json_response({"ok": resp.status == 200, "status": resp.status})

            elif name == "huggingface":
                async with session.get(
                    "https://huggingface.co/api/whoami-v2",
                    headers={"Authorization": f"Bearer {key}"},
                    timeout=aiohttp.ClientTimeout(total=10),
                ) as resp:
                    return web.json_response({"ok": resp.status == 200, "status": resp.status})

            elif name == "searxng":
                # SearXNG is a URL, not a token — test connectivity
                url = key.rstrip("/") + "/search?q=test&format=json&engines=duckduckgo"
                async with session.get(
                    url,
                    timeout=aiohttp.ClientTimeout(total=10),
                ) as resp:
                    return web.json_response({"ok": resp.status == 200, "status": resp.status})

        return web.json_response({"ok": False, "error": "unknown service"})
    except Exception as e:
        return web.json_response({"ok": False, "error": str(e)})


async def create_observatorist(request: web.Request) -> web.Response:
    """POST /api/workspaces/{id}/observatorist — Create or return the Observatorist session."""
    import observatory
    workspace_id = request.match_info["id"]

    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM workspaces WHERE id = ?", (workspace_id,))
        ws = await cur.fetchone()
        if not ws:
            return web.json_response({"error": "workspace not found"}, status=404)

        # Check for existing observatorist session
        cur = await db.execute(
            "SELECT * FROM sessions WHERE workspace_id = ? AND session_type = 'observatorist' "
            "ORDER BY created_at DESC LIMIT 1",
            (workspace_id,),
        )
        existing = await cur.fetchone()
        if existing:
            d = dict(existing)
            from hooks import get_session_logical_status
            d["status"] = get_session_logical_status(d["id"], pty_mgr.is_alive(d["id"]), d.get("status") or "idle")
            return web.json_response(d)

        session_id = str(uuid.uuid4())
        name = f"Observatorist — {dict(ws)['name']}"
        await db.execute(
            "INSERT INTO sessions (id, workspace_id, name, model, permission_mode, effort, "
            "system_prompt, session_type, auto_approve_mcp, cli_type) "
            "VALUES (?, ?, ?, 'sonnet', 'default', 'high', ?, 'observatorist', 1, 'claude')",
            (session_id, workspace_id, name, observatory.OBSERVATORIST_SYSTEM_PROMPT),
        )
        # Attach Deep Research MCP for search tools
        await db.execute(
            "INSERT OR IGNORE INTO session_mcp_servers (session_id, mcp_server_id, auto_approve_override) "
            "VALUES (?, 'builtin-deep-research', 1)",
            (session_id,),
        )
        # Attach Commander MCP for accessing observatory data
        await db.execute(
            "INSERT OR IGNORE INTO session_mcp_servers (session_id, mcp_server_id, auto_approve_override) "
            "VALUES (?, 'builtin-commander', 1)",
            (session_id,),
        )
        await db.commit()

        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        row = await cur.fetchone()
        d = dict(row)
        d["status"] = "idle"

        await broadcast({"type": "session_created", "session": d})
        return web.json_response(d, status=201)
    finally:
        await db.close()


# ─── REST: Test Queue ────────────────────────────────────────────────

async def _insert_test_queue_entry(
    db,
    *,
    workspace_id: str,
    task_id: str | None,
    task_revision: int | None,
    title: str,
    description: str | None,
    acceptance_criteria: str | None,
) -> tuple[dict, bool]:
    """Insert once per task revision and return (entry, was_created)."""
    if task_id:
        cur = await db.execute(
            """SELECT * FROM test_queue
                WHERE workspace_id = ? AND task_id = ?
                  AND status IN ('queued', 'running')
                ORDER BY created_at ASC LIMIT 1""",
            (workspace_id, task_id),
        )
        active = await cur.fetchone()
        if active:
            return dict(active), False

    entry_id = str(uuid.uuid4())
    await db.execute(
        """INSERT OR IGNORE INTO test_queue
               (id, workspace_id, task_id, task_revision, title, description,
                acceptance_criteria)
           VALUES (?, ?, ?, ?, ?, ?, ?)""",
        (
            entry_id, workspace_id, task_id, task_revision, title,
            description, acceptance_criteria,
        ),
    )
    cur = await db.execute("SELECT * FROM test_queue WHERE id = ?", (entry_id,))
    row = await cur.fetchone()
    if row:
        return dict(row), True

    cur = await db.execute(
        """SELECT * FROM test_queue
            WHERE workspace_id = ? AND task_id = ? AND task_revision = ?
            ORDER BY created_at ASC LIMIT 1""",
        (workspace_id, task_id, task_revision),
    )
    existing = await cur.fetchone()
    if not existing:
        raise RuntimeError("test queue idempotency conflict without an existing entry")
    return dict(existing), False


async def _auto_enqueue_test_for_task(db, task: dict) -> dict | None:
    cur = await db.execute(
        "SELECT auto_test_enabled FROM workspaces WHERE id = ?",
        (task["workspace_id"],),
    )
    workspace = await cur.fetchone()
    if not workspace or not workspace["auto_test_enabled"]:
        return None

    entry, created = await _insert_test_queue_entry(
        db,
        workspace_id=task["workspace_id"],
        task_id=task["id"],
        task_revision=task.get("iteration") or 1,
        title=task["title"],
        description=task.get("description"),
        acceptance_criteria=task.get("acceptance_criteria"),
    )
    return entry if created else None


async def _publish_test_queue_entry(entry: dict) -> None:
    await _broadcast_test_queue_entry(entry)
    asyncio.create_task(_process_test_queue(entry["workspace_id"]))


async def _broadcast_test_queue_entry(entry: dict) -> None:
    # Through broadcast() so the workspace_id scopes delivery: joiners of other
    # workspaces must not see this queue's tests.
    try:
        await broadcast({
            "type": "test_queue_update",
            "workspace_id": entry["workspace_id"],
            "entry": entry,
        })
    except Exception:
        pass


async def list_test_queue(request: web.Request) -> web.Response:
    """GET /api/workspaces/{id}/test-queue — list queued/running tests."""
    workspace_id = request.match_info["id"]
    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT * FROM test_queue WHERE workspace_id = ? ORDER BY created_at ASC",
            (workspace_id,),
        )
        rows = await cur.fetchall()
        return web.json_response([dict(r) for r in rows])
    finally:
        await db.close()


async def get_test_queue_attention(request: web.Request) -> web.Response:
    """GET /api/test-queue/attention — failed/parked tests needing a human."""
    ctx = get_auth(request)
    try:
        limit = max(1, min(int(request.query.get("limit", "50") or 50), 200))
    except (TypeError, ValueError):
        return web.json_response({"error": "limit must be an integer"}, status=400)

    db = await get_db()
    try:
        marks = ",".join("?" for _ in TEST_QUEUE_ATTENTION_STATUSES)
        where = f"status IN ({marks})"
        params: list = list(TEST_QUEUE_ATTENTION_STATUSES)
        if not ctx.is_owner:
            where += " AND workspace_id = ?"
            params.append(ctx.workspace_id)

        cur = await db.execute(
            f"SELECT status, COUNT(*) AS total FROM test_queue "
            f"WHERE {where} GROUP BY status",
            params,
        )
        by_status = {status: 0 for status in TEST_QUEUE_ATTENTION_STATUSES}
        for row in await cur.fetchall():
            by_status[row["status"]] = row["total"]

        cur = await db.execute(
            f"""SELECT id, workspace_id, task_id, task_revision, title, status,
                       assigned_session_id, result_summary, attempt_count,
                       started_at, completed_at
                  FROM test_queue
                 WHERE {where}
                 ORDER BY completed_at DESC, created_at DESC, id
                 LIMIT ?""",
            (*params, limit),
        )
        return web.json_response({
            "total": sum(by_status.values()),
            "by_status": by_status,
            "detail_limit": limit,
            "items": [dict(row) for row in await cur.fetchall()],
        })
    finally:
        await db.close()


async def enqueue_test(request: web.Request) -> web.Response:
    """POST /api/workspaces/{id}/test-queue — add a test to the queue.

    Body: { task_id?, title, description?, acceptance_criteria? }
    If task_id is provided, title/description/acceptance_criteria are pulled from the task.
    """
    workspace_id = request.match_info["id"]
    body = await request.json()
    task_id = body.get("task_id")

    db = await get_db()
    try:
        title = body.get("title", "")
        description = body.get("description", "")
        acceptance_criteria = body.get("acceptance_criteria", "")
        task_revision = None

        # If task_id provided, pull details from the task
        if task_id:
            cur = await db.execute(
                "SELECT * FROM tasks WHERE id = ? AND workspace_id = ?",
                (task_id, workspace_id),
            )
            task = await cur.fetchone()
            if not task:
                return web.json_response({"error": "task not found"}, status=404)
            task = dict(task)
            task_revision = task.get("iteration") or 1
            title = title or task.get("title", "")
            description = description or task.get("description", "")
            acceptance_criteria = acceptance_criteria or task.get("acceptance_criteria", "")

        if not title:
            return web.json_response({"error": "title required"}, status=400)

        entry, created = await _insert_test_queue_entry(
            db,
            workspace_id=workspace_id,
            task_id=task_id,
            task_revision=task_revision,
            title=title,
            description=description,
            acceptance_criteria=acceptance_criteria,
        )
        await db.commit()
    finally:
        await db.close()

    if created:
        await _publish_test_queue_entry(entry)
    return web.json_response(entry, status=201 if created else 200)


async def remove_from_test_queue(request: web.Request) -> web.Response:
    """DELETE /api/test-queue/{id} — remove a queued test."""
    entry_id = request.match_info["id"]
    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM test_queue WHERE id = ?", (entry_id,))
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "not found"}, status=404)
        workspace_id = dict(row)["workspace_id"]
        await db.execute("DELETE FROM test_queue WHERE id = ?", (entry_id,))
        await db.commit()

        try:
            await broadcast({"type": "test_queue_update", "workspace_id": workspace_id, "removed": entry_id})
        except Exception:
            pass

        return web.json_response({"ok": True})
    finally:
        await db.close()


def _test_queue_session_available(session_id: str, cli_type: str, db_status: str = "idle", *, check_draft: bool = True) -> bool:
    from hooks import get_session_logical_status
    import pipeline_engine
    if session_id in pipeline_engine._session_to_run:
        return False
    alive = pty_mgr.is_alive(session_id)
    status = get_session_logical_status(session_id, alive, db_status)
    if not alive:
        return status in {"idle", "exited", "stopped"}
    if status != "idle":
        return False
    screen = _startup_blocker_text(session_id)
    if _session_permission_menu(screen):
        return False
    if cli_type == "claude" and check_draft:
        # Never clear or submit a person's unfinished prompt for a background
        # test. Claude's built-in placeholder starts with "Try ".
        prompts = re.findall(r"(?m)^[^\S\r\n]*[❯>][^\S\r\n]*(.*)$", screen)
        if prompts and prompts[-1].strip() and not prompts[-1].strip().startswith("Try "):
            return False
    return True


async def _find_testing_worker(db, workspace_id: str) -> str | None:
    cur = await db.execute(
        """SELECT id, tags, cli_type, status FROM sessions
           WHERE workspace_id = ? AND session_type != 'commander'
           ORDER BY created_at DESC""",
        (workspace_id,),
    )
    for row in await cur.fetchall():
        try:
            tags = json.loads(row["tags"] or "[]")
        except Exception:
            tags = []
        if "capability_testing" in tags and _test_queue_session_available(
            row["id"], row["cli_type"] or "claude", row["status"],
        ):
            return row["id"]
    return None


async def _recheck_test_queue_after_timeout(workspace_id: str) -> None:
    """Wake the queue when a running test's lease can first be stale."""
    try:
        await asyncio.sleep(TEST_QUEUE_RUNNING_TIMEOUT_SECONDS)
        await _process_test_queue(workspace_id)
    except asyncio.CancelledError:
        raise
    except Exception:
        logger.exception("Timed test-queue recheck failed for %s", workspace_id)


_test_queue_dispatch_locks: dict[str, asyncio.Lock] = {}


async def _process_test_queue(workspace_id: str):
    lock = _test_queue_dispatch_locks.setdefault(workspace_id, asyncio.Lock())
    async with lock:
        await _process_test_queue_locked(workspace_id)


async def _process_test_queue_locked(workspace_id: str):
    """Background: pick the next queued test and dispatch to a testing-capable worker."""
    db = await get_db()
    try:
        timeout_modifier = f"-{TEST_QUEUE_RUNNING_TIMEOUT_SECONDS} seconds"
        cur = await db.execute(
            """SELECT test_queue.*,
                      (started_at IS NULL OR started_at <= datetime('now', ?)) AS timed_out
                 FROM test_queue
                WHERE workspace_id = ? AND status = 'running'
                ORDER BY started_at ASC, created_at ASC LIMIT 1""",
            (timeout_modifier, workspace_id),
        )
        running_row = await cur.fetchone()
        if running_row:
            running = dict(running_row)
            timed_out = bool(running.pop("timed_out"))
            if not timed_out:
                return

            attempts = max(1, int(running.get("attempt_count") or 0))
            timeout_minutes = TEST_QUEUE_RUNNING_TIMEOUT_SECONDS // 60
            if attempts >= TEST_QUEUE_MAX_ATTEMPTS:
                reason = (
                    f"IVE parked this test after {attempts} attempts exceeded "
                    f"the {timeout_minutes}-minute running limit. Human review "
                    "is required; it will not be retried automatically."
                )
                await db.execute(
                    """UPDATE test_queue
                          SET status = 'parked', result_summary = ?,
                              attempt_count = ?, completed_at = datetime('now')
                        WHERE id = ? AND status = 'running'""",
                    (reason, attempts, running["id"]),
                )
                logger.warning("Parked stuck test queue entry %s: %s", running["id"], reason)
            else:
                reason = (
                    f"IVE released this test after attempt {attempts} exceeded "
                    f"the {timeout_minutes}-minute running limit. It is queued "
                    f"for attempt {attempts + 1} of {TEST_QUEUE_MAX_ATTEMPTS}."
                )
                await db.execute(
                    """UPDATE test_queue
                          SET status = 'queued', assigned_session_id = NULL,
                              started_at = NULL, completed_at = NULL,
                              result_summary = ?, attempt_count = ?
                        WHERE id = ? AND status = 'running'""",
                    (reason, attempts, running["id"]),
                )
                logger.warning("Released stuck test queue entry %s: %s", running["id"], reason)
            await db.commit()
            cur = await db.execute("SELECT * FROM test_queue WHERE id = ?", (running["id"],))
            recovered = await cur.fetchone()
            if recovered:
                await _broadcast_test_queue_entry(dict(recovered))

            cur = await db.execute(
                "SELECT 1 FROM test_queue WHERE workspace_id = ? AND status = 'running' LIMIT 1",
                (workspace_id,),
            )
            if await cur.fetchone():
                return

        cur = await db.execute(
            """SELECT * FROM test_queue
                WHERE workspace_id = ? AND status = 'queued'
                ORDER BY COALESCE(attempt_count, 0) ASC, created_at ASC LIMIT 1""",
            (workspace_id,),
        )
        row = await cur.fetchone()
        if not row:
            return
        entry = dict(row)

        tester_id = await _find_testing_worker(db, workspace_id)
        if not tester_id:
            return
        if not pty_mgr.is_alive(tester_id):
            try:
                await _autostart_session_pty(tester_id)
                await asyncio.sleep(1.0)
            except Exception as e:
                logger.warning("Could not auto-start testing worker %s: %s", tester_id[:8], e)
        if not pty_mgr.is_alive(tester_id):
            return
        cli_type = await _session_cli_type(tester_id)
        if not await _wait_for_cli_input_ready(tester_id, cli_type, 30):
            return  # Keep queued while sign-in/startup/another turn blocks input.
        if not _test_queue_session_available(tester_id, cli_type):
            return

        cur = await db.execute(
            """UPDATE test_queue
                  SET status = 'running', assigned_session_id = ?,
                      started_at = datetime('now'), completed_at = NULL,
                      attempt_count = COALESCE(attempt_count, 0) + 1
                WHERE id = ? AND status = 'queued'""",
            (tester_id, entry["id"]),
        )
        await db.commit()
        if cur.rowcount != 1:
            return
        cur = await db.execute("SELECT * FROM test_queue WHERE id = ?", (entry["id"],))
        claimed_row = await cur.fetchone()
        if not claimed_row:
            return
        entry = dict(claimed_row)
        asyncio.create_task(_recheck_test_queue_after_timeout(workspace_id))

        task = None
        original_prompt = ""
        if entry.get("task_id"):
            try:
                cur = await db.execute("SELECT * FROM tasks WHERE id = ?", (entry["task_id"],))
                task_row = await cur.fetchone()
                task = dict(task_row) if task_row else None
                from review_brief import resolve_review_intent_sources
                original_prompt, resolved_task = await resolve_review_intent_sources(
                    db,
                    reviewed_session_id=(task or {}).get("assigned_session_id"),
                    task_id=entry.get("task_id"),
                )
                task = task or resolved_task
            except Exception:
                pass
        prompt = _build_test_prompt(
            entry,
            original_prompt=original_prompt,
            board_card=task,
            handoff_notes=(task or {}).get("result_summary"),
        )
        payload = prompt.encode("utf-8")
        if cli_type == "gemini":
            payload = prompt.replace("\r", " ").replace("\n", " ").encode("utf-8")
        elif "\n" in prompt or "\r" in prompt:
            payload = (b"Run this IVE test-queue assignment and submit its result: "
                       + b"\x1b[200~" + payload + b"\x1b[201~")
        failure = None
        if pty_mgr.write(tester_id, payload) is False:
            failure = "Test prompt was rejected before delivery. No test result was produced."
        else:
            await asyncio.sleep(max(0.8 if cli_type in {"codex", "antigravity"} else 0.4,
                                    min(1.5, len(payload) / 600)))
            current = await (await db.execute(
                "SELECT status, assigned_session_id FROM test_queue WHERE id = ?", (entry["id"],),
            )).fetchone()
            if not current or current["status"] != "running" or current["assigned_session_id"] != tester_id:
                return  # A user cancelled/reassigned the entry while it was being typed.
            if not _test_queue_session_available(tester_id, cli_type, check_draft=False):
                failure = "Tester became busy before submission. Check its pending input; no test result was produced."
            elif pty_mgr.write(tester_id, b"\r") is False:
                failure = "Test prompt could not be submitted. Check the tester input; no test result was produced."
        if failure:
            await db.execute(
                "UPDATE test_queue SET status='failed', result_summary=?, completed_at=datetime('now') "
                "WHERE id=? AND status='running' AND assigned_session_id=?",
                (failure, entry["id"], tester_id),
            )
            await db.commit()
            row = await (await db.execute("SELECT * FROM test_queue WHERE id=?", (entry["id"],))).fetchone()
            if row:
                entry = dict(row)
        await _broadcast_test_queue_entry(entry)
        if failure and entry.get("status") == "failed":
            await _continue_after_test_queue_terminal(entry)

    finally:
        await db.close()


def _build_test_prompt(
    entry: dict,
    *,
    original_prompt: str = "",
    board_card: dict | None = None,
    handoff_notes: str = "",
) -> str:
    """Build a test prompt from a queue entry."""
    parts = [f"Please test the following:\n\n## {entry['title']}"]
    if entry.get("description"):
        parts.append(f"\nDescription:\n{entry['description']}")
    if entry.get("acceptance_criteria"):
        parts.append(f"\nAcceptance Criteria:\n{entry['acceptance_criteria']}")
    parts.append(
        "\nThis is an authorized IVE test-queue assignment. Run the relevant tests now; "
        "include screenshots only when testing a visual interface. Do not edit project files. "
        "If the result tool is deferred, discover report_test_result using ToolSearch. When finished, "
        "you MUST call the report_test_result MCP tool with "
        f"test_queue_id={entry['id']!r}, outcome='pass' or 'fail', and a short "
        "result_summary. That report releases the test queue."
    )
    from review_brief import build_review_brief
    return build_review_brief(
        "\n".join(parts),
        original_prompt=original_prompt,
        board_card=board_card,
        handoff_notes=handoff_notes,
    )


async def _continue_after_test_queue_terminal(entry: dict) -> None:
    asyncio.create_task(_process_test_queue(entry["workspace_id"]))
    await bus.emit(CommanderEvent.TEST_QUEUE_ENTRY_COMPLETED, {
        "test_queue_id": entry["id"],
        "task_id": entry.get("task_id"),
        "workspace_id": entry.get("workspace_id"),
        "status": entry["status"],
        "result_summary": entry.get("result_summary"),
    }, source="test_queue")


async def report_test_queue_result(request: web.Request) -> web.Response:
    """PUT /api/test-queue/{id}/report — assigned tester pass/fail report."""
    entry_id = request.match_info["id"]
    caller_session_id = (request.headers.get("X-IVE-Session-Id") or "").strip()
    if not caller_session_id:
        return web.json_response({"error": "tester session identity required"}, status=403)
    try:
        body = await request.json()
    except (json.JSONDecodeError, TypeError, ValueError):
        return web.json_response({"error": "invalid JSON"}, status=400)
    outcome = str(body.get("outcome") or "").strip().lower()
    if outcome not in ("pass", "fail"):
        return web.json_response({"error": "outcome must be pass or fail"}, status=400)
    result_summary = body.get("result_summary")
    if not isinstance(result_summary, str) or not result_summary.strip():
        return web.json_response({"error": "result_summary required"}, status=400)
    result_summary = result_summary.strip()
    if len(result_summary) > 2000:
        return web.json_response({"error": "result_summary must be 2000 characters or fewer"}, status=400)

    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM test_queue WHERE id = ?", (entry_id,))
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "not found"}, status=404)
        current = dict(row)
        if current.get("assigned_session_id") != caller_session_id:
            return web.json_response({"error": "test is assigned to a different session"}, status=403)
        if current.get("status") != "running":
            return web.json_response({"error": "test is not running"}, status=409)
        cur = await db.execute(
            "SELECT workspace_id FROM sessions WHERE id = ?",
            (caller_session_id,),
        )
        caller = await cur.fetchone()
        if not caller or caller["workspace_id"] != current["workspace_id"]:
            return web.json_response({"error": "invalid tester session"}, status=403)

        status = "done" if outcome == "pass" else "failed"
        cur = await db.execute(
            """UPDATE test_queue
                  SET status = ?, result_summary = ?, completed_at = datetime('now')
                WHERE id = ? AND status = 'running' AND assigned_session_id = ?""",
            (status, result_summary, entry_id, caller_session_id),
        )
        if cur.rowcount != 1:
            await db.rollback()
            return web.json_response({"error": "test assignment changed"}, status=409)
        await db.commit()
        cur = await db.execute("SELECT * FROM test_queue WHERE id = ?", (entry_id,))
        entry = dict(await cur.fetchone())
        await _broadcast_test_queue_entry(entry)
        await _continue_after_test_queue_terminal(entry)
        return web.json_response(entry)
    finally:
        await db.close()


async def update_test_queue_entry(request: web.Request) -> web.Response:
    """PUT /api/test-queue/{id} — update a queue entry (e.g. mark done/failed with summary)."""
    entry_id = request.match_info["id"]
    body = await request.json()
    db = await get_db()
    try:
        allowed = ("status", "result_summary", "assigned_session_id")
        fields, values = [], []
        for key in allowed:
            if key in body:
                fields.append(f"{key} = ?")
                values.append(body[key])
        if not fields:
            return web.json_response({"error": "no fields"}, status=400)

        # Auto-set completed_at when moving to done/failed
        if body.get("status") in ("done", "failed"):
            fields.append("completed_at = datetime('now')")

        values.append(entry_id)
        await db.execute(f"UPDATE test_queue SET {', '.join(fields)} WHERE id = ?", values)
        await db.commit()

        cur = await db.execute("SELECT * FROM test_queue WHERE id = ?", (entry_id,))
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "not found"}, status=404)
        entry = dict(row)

        # Broadcast (workspace-scoped)
        await _broadcast_test_queue_entry(entry)

        # If this was the running test in direct mode and it's now done/failed, process next
        if body.get("status") in ("done", "failed"):
            await _continue_after_test_queue_terminal(entry)

        return web.json_response(entry)
    finally:
        await db.close()


# ─── REST: Session Tree ──────────────────────────────────────────────

async def get_session_tree(request: web.Request) -> web.Response:
    """Return a recursive tree of sessions rooted at the given session."""
    session_id = request.match_info["id"]
    db = await get_db()
    try:
        # Fetch root session
        cur = await db.execute("SELECT * FROM sessions WHERE id = ?", (session_id,))
        root = await cur.fetchone()
        if not root:
            return web.json_response({"error": "session not found"}, status=404)

        async def build_tree(sid: str) -> dict:
            cur2 = await db.execute("SELECT * FROM sessions WHERE id = ?", (sid,))
            row = await cur2.fetchone()
            if not row:
                return None
            node = dict(row)
            from hooks import get_session_logical_status
            node["status"] = get_session_logical_status(node["id"], pty_mgr.is_alive(node["id"]), node.get("status") or "idle")
            # Find children
            cur3 = await db.execute(
                "SELECT id FROM sessions WHERE parent_session_id = ? ORDER BY created_at",
                (sid,),
            )
            child_rows = await cur3.fetchall()
            children = []
            for child in child_rows:
                child_tree = await build_tree(child["id"])
                if child_tree:
                    children.append(child_tree)
            node["children"] = children
            return node

        tree = await build_tree(session_id)
        return web.json_response(tree)
    finally:
        await db.close()


# ─── REST: Session Subagents ─────────────────────────────────────────

async def get_session_subagents(request: web.Request) -> web.Response:
    """Return the in-memory sub-agent list for a session (from CLI hooks)."""
    from hooks import get_subagents
    session_id = request.match_info["id"]
    if not await _session_exists(session_id):
        return web.json_response({"error": "session not found"}, status=404)
    return web.json_response(get_subagents(session_id))


async def get_subagent_transcript(request: web.Request) -> web.Response:
    """Read and return a sub-agent's transcript as formatted markdown."""
    from hooks import get_subagents
    from history_reader import read_session_messages, export_session_as_markdown

    session_id = request.match_info["id"]
    agent_id = request.match_info["agent_id"]

    # Find the agent in hook state
    agents = get_subagents(session_id)
    agent = next((a for a in agents if a.get("id") == agent_id), None)
    if not agent:
        return web.json_response({"error": "Agent not found"}, status=404)

    transcript_path = agent.get("transcript_path")
    if not transcript_path or not os.path.isfile(transcript_path):
        return web.json_response({
            "markdown": None,
            "agent": agent,
            "error": "Transcript file not available",
        })

    messages = read_session_messages(transcript_path)
    markdown = export_session_as_markdown(messages)
    return web.json_response({
        "markdown": markdown,
        "agent": agent,
    })


# ─── REST: Accounts ──────────────────────────────────────────────────

async def _clear_expired_quota_cooldowns(db) -> None:
    """Reactivate accounts whose local quota cooldown has elapsed."""
    await db.execute(
        "UPDATE accounts SET quota_reset_at = NULL "
        "WHERE status != 'quota_exceeded' "
        "AND quota_reset_at IS NOT NULL"
    )
    await db.execute(
        "UPDATE accounts SET status = 'active', quota_reset_at = NULL "
        "WHERE status = 'quota_exceeded' "
        "AND quota_reset_at IS NOT NULL "
        "AND quota_reset_at <= datetime('now')"
    )


async def list_accounts(request):
    db = await get_db()
    try:
        await _clear_expired_quota_cooldowns(db)
        await db.commit()
        cur = await db.execute("SELECT * FROM accounts ORDER BY is_default DESC, name")
        rows = await cur.fetchall()
        from crypto import decrypt_secret
        from account_sandbox import verify_account_credentials
        oauth_rows = [
            dict(row) for row in rows
            if row["type"] == "oauth" and row["cli_type"]
        ]
        oauth_checks = await asyncio.gather(*[
            asyncio.to_thread(
                verify_account_credentials,
                row["id"],
                row["cli_type"],
            )
            for row in oauth_rows
        ])
        credentials_present = {
            row["id"]: bool(check.get("verified"))
            for row, check in zip(oauth_rows, oauth_checks)
        }
        # Mask API keys in response
        result = []
        for r in rows:
            d = dict(r)
            plain = decrypt_secret(d.get("api_key"))
            d["api_key_provider"] = _normalize_api_key_provider(
                d.get("api_key_provider"),
                plain,
            )
            if plain:
                d["api_key_masked"] = plain[:8] + "..." + plain[-4:] if len(plain) > 12 else "***"
            if d.get("type") == "oauth":
                d["credentials_present"] = credentials_present.get(d["id"], False)
            d.pop("api_key", None)  # Don't send raw (or encrypted) key in list
            result.append(d)
        return web.json_response(result)
    finally:
        await db.close()

async def create_account(request):
    body = await request.json()
    name = body.get("name", "").strip()
    if not name:
        return web.json_response({"error": "name required"}, status=400)

    account_type = (body.get("type") or "api_key").strip().lower()
    if account_type not in {"api_key", "oauth"}:
        return web.json_response({"error": "type must be api_key or oauth"}, status=400)
    cli_type = (body.get("cli_type") or "").strip().lower() or None
    if account_type == "oauth":
        if not cli_type or not is_active_cli(cli_type):
            return web.json_response({"error": "oauth accounts require an active cli_type"}, status=400)
        profile = get_profile(cli_type)
        isolation_supported = (
            profile.account_isolation == "home_only"
            and bool(profile.auth_dir_name)
        ) or (
            profile.account_isolation == "config_dir"
            and bool(
                profile.auth_dir_name
                and profile.config_dir_env
                and profile.config_dir_subpath
            )
        )
        if not isolation_supported:
            return web.json_response(
                {
                    "error": (
                        f"CLI profile '{cli_type}' does not declare a verified "
                        "account-isolation strategy"
                    ),
                    "code": "account_isolation_unsupported",
                },
                status=409,
            )
    else:
        cli_type = None

    acc_id = str(uuid.uuid4())
    api_key = body.get("api_key")
    if account_type == "oauth":
        api_key = None
    api_key_provider = _normalize_api_key_provider(body.get("api_key_provider"), api_key)
    base_url = _base_url_for_account({"base_url": body.get("base_url")}, api_key_provider) or None
    model_aliases = _normalize_model_aliases(body.get("model_aliases"), api_key_provider)
    db = await get_db()
    try:
        if body.get("is_default"):
            await db.execute("UPDATE accounts SET is_default = 0")
        from crypto import maybe_encrypt
        await db.execute(
            """INSERT INTO accounts
               (id, name, type, cli_type, status, api_key, api_key_provider,
                base_url, model_aliases, is_default, browser_path)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (acc_id, name, account_type, cli_type,
             "login_required" if account_type == "oauth" else "active",
             maybe_encrypt(api_key), api_key_provider,
             base_url, model_aliases, 1 if body.get("is_default") else 0,
             body.get("browser_path")),
        )
        await db.commit()
        cur = await db.execute("SELECT * FROM accounts WHERE id = ?", (acc_id,))
        row = await cur.fetchone()
        created = dict(row)
        created.pop("api_key", None)
        return web.json_response(created, status=201)
    finally:
        await db.close()

async def update_account(request):
    acc_id = request.match_info["id"]
    body = await request.json()
    db = await get_db()
    try:
        current_row = await (await db.execute(
            "SELECT * FROM accounts WHERE id = ?", (acc_id,)
        )).fetchone()
        if not current_row:
            return web.json_response({"error": "account not found"}, status=404)
        current = dict(current_row)
        if "type" in body or "cli_type" in body:
            return web.json_response(
                {"error": "account type and CLI identity are immutable; create a new account"},
                status=409,
            )
        if current.get("type") == "oauth" and {
            "api_key", "api_key_provider", "base_url", "model_aliases"
        }.intersection(body):
            return web.json_response(
                {"error": "OAuth accounts cannot be converted into API-key accounts"},
                status=409,
            )
        if "status" in body:
            requested_status = str(body.get("status") or "")
            allowed_statuses = {
                "active", "quota_exceeded", "login_required", "authenticating",
                "auth_failed", "duplicate_identity", "disabled",
            }
            if requested_status not in allowed_statuses:
                return web.json_response({"error": "invalid account status"}, status=400)
            if requested_status == "active" and current.get("type") == "oauth":
                if not current.get("cli_type"):
                    return web.json_response(
                        {"error": "OAuth account has no CLI identity; create a new account"},
                        status=409,
                    )
                from account_sandbox import verify_account_credentials
                verification = await asyncio.to_thread(
                    verify_account_credentials,
                    acc_id,
                    current["cli_type"],
                )
                if not current.get("credentials_verified_at") or not verification.get("verified"):
                    return web.json_response(
                        {"error": "OAuth account has no verified credentials in its own sandbox"},
                        status=409,
                    )
        if "api_key_provider" in body:
            body["api_key_provider"] = _normalize_api_key_provider(
                body.get("api_key_provider"),
                body.get("api_key"),
            )
            provider_spec = API_KEY_PROVIDERS.get(body["api_key_provider"]) or {}
            if _is_claude_gateway_provider(body["api_key_provider"]):
                if provider_spec.get("default_base_url"):
                    body.setdefault("base_url", provider_spec["default_base_url"])
                if provider_spec.get("default_models"):
                    body.setdefault("model_aliases", provider_spec["default_models"])
        if "base_url" in body:
            body["base_url"] = (body.get("base_url") or "").strip().rstrip("/") or None
            provider_spec = API_KEY_PROVIDERS.get(body.get("api_key_provider") or "") or {}
            if not body["base_url"] and provider_spec.get("default_base_url"):
                body["base_url"] = provider_spec["default_base_url"]
        if "model_aliases" in body:
            body["model_aliases"] = _normalize_model_aliases(
                body.get("model_aliases"),
                _normalize_api_key_provider(body.get("api_key_provider")),
            )
        if body.get("is_default"):
            await db.execute("UPDATE accounts SET is_default = 0 WHERE id != ?", (acc_id,))
        # Encrypt at write (no-op unless IVE_ENCRYPT_SECRETS is on). Done AFTER
        # provider detection above, which needs the plaintext key.
        if "api_key" in body:
            from crypto import maybe_encrypt
            body["api_key"] = maybe_encrypt(body["api_key"])
        allowed = ("name", "api_key", "api_key_provider", "base_url", "model_aliases",
                   "is_default", "status", "quota_reset_at", "browser_path")
        fields, values = [], []
        for key in allowed:
            if key in body:
                fields.append(f"{key} = ?")
                values.append(body[key])
        if not fields:
            return web.json_response({"error": "no fields"}, status=400)
        values.append(acc_id)
        await db.execute(f"UPDATE accounts SET {', '.join(fields)} WHERE id = ?", values)
        await db.commit()
        cur = await db.execute("SELECT * FROM accounts WHERE id = ?", (acc_id,))
        row = await cur.fetchone()
        updated = dict(row)
        updated.pop("api_key", None)
        return web.json_response(updated)
    finally:
        await db.close()

async def delete_account(request):
    acc_id = request.match_info["id"]
    from auth_cycler import auth_cycler
    if auth_cycler.is_auth_in_progress(acc_id):
        return web.json_response(
            {"error": "account login is still in progress"},
            status=409,
        )
    db = await get_db()
    try:
        cur = await db.execute("SELECT id FROM accounts WHERE id = ?", (acc_id,))
        if not await cur.fetchone():
            return web.json_response({"error": "account not found"}, status=404)
        cur = await db.execute("SELECT id FROM sessions WHERE account_id = ?", (acc_id,))
        live_sessions = [row["id"] for row in await cur.fetchall() if pty_mgr.is_alive(row["id"])]
        if live_sessions:
            return web.json_response(
                {"error": "account is in use by a live session", "session_ids": live_sessions},
                status=409,
            )
        await db.execute("DELETE FROM accounts WHERE id = ?", (acc_id,))
        await db.commit()
    finally:
        await db.close()
    from account_sandbox import delete_account_home
    await asyncio.to_thread(delete_account_home, acc_id)
    return web.json_response({"ok": True})

async def test_account(request):
    """Test an API key by making a simple API call."""
    acc_id = request.match_info["id"]
    db = await get_db()
    try:
        cur = await db.execute("SELECT api_key, api_key_provider, base_url, model_aliases FROM accounts WHERE id = ?", (acc_id,))
        row = await cur.fetchone()
        if not row or not row["api_key"]:
            return web.json_response({"error": "no API key"}, status=400)

        import urllib.request
        import urllib.error
        from crypto import decrypt_secret
        key = decrypt_secret(row["api_key"])
        provider = _normalize_api_key_provider(row["api_key_provider"], key)
        if _is_claude_gateway_provider(provider):
            base_url = _base_url_for_account(dict(row), provider)
            if not base_url:
                return web.json_response({"status": "error", "provider": provider, "message": "Gateway base URL required"})
            model = (_model_aliases_for_account(dict(row), provider) or ["sonnet"])[0]
            req = urllib.request.Request(
                f"{base_url}/v1/messages",
                headers={
                    "Authorization": f"Bearer {key}",
                    "anthropic-version": "2023-06-01",
                    "content-type": "application/json",
                },
                data=json.dumps({
                    "model": model,
                    "max_tokens": 1,
                    "messages": [{"role": "user", "content": "hi"}],
                }).encode(),
                method="POST",
            )
        elif provider == "google":
            req = urllib.request.Request(
                f"https://generativelanguage.googleapis.com/v1beta/models?key={key}",
                method="GET",
            )
        elif provider == "openai":
            req = urllib.request.Request(
                "https://api.openai.com/v1/models",
                headers={"Authorization": f"Bearer {key}"},
                method="GET",
            )
        else:
            req = urllib.request.Request(
                "https://api.anthropic.com/v1/messages",
                headers={
                    "x-api-key": key,
                    "anthropic-version": "2023-06-01",
                    "content-type": "application/json",
                },
                data=json.dumps({
                    "model": "claude-haiku-4-5-20251001",
                    "max_tokens": 1,
                    "messages": [{"role": "user", "content": "hi"}],
                }).encode(),
                method="POST",
            )
        try:
            urllib.request.urlopen(req, timeout=10)
            await db.execute("UPDATE accounts SET status = 'active', last_used_at = datetime('now') WHERE id = ?", (acc_id,))
            await db.commit()
            return web.json_response({
                "status": "ok",
                "provider": provider,
                "message": f"{API_KEY_PROVIDERS[provider]['label']} API key is valid",
            })
        except urllib.error.HTTPError as e:
            status_code = e.code
            if status_code == 401:
                return web.json_response({"status": "error", "provider": provider, "message": "Invalid API key"})
            if provider == "google" and status_code in (400, 403):
                return web.json_response({"status": "error", "provider": provider, "message": "Invalid or unauthorized Gemini API key"})
            elif status_code == 429:
                await db.execute(
                    "UPDATE accounts SET status = 'quota_exceeded', quota_reset_at = datetime('now', '+4 hours') WHERE id = ?",
                    (acc_id,),
                )
                await db.commit()
                return web.json_response({"status": "quota_exceeded", "provider": provider, "message": "Rate limited — 4h cooldown started"})
            return web.json_response({"status": "error", "provider": provider, "message": f"HTTP {status_code}"})
    finally:
        await db.close()


# ─── REST: Account Browser ───────────────────────────────────────────────

async def detect_browsers(request: web.Request) -> web.Response:
    """GET /api/browser/detect — find browsers with isolated-profile support."""
    import platform
    import shutil as _shutil

    browsers: list[dict] = []
    if platform.system() == "Darwin":
        candidates = [
            ("/Applications/Google Chrome.app", "Google Chrome"),
            ("/Applications/Brave Browser.app", "Brave Browser"),
            ("/Applications/Arc.app", "Arc"),
            ("/Applications/Microsoft Edge.app", "Microsoft Edge"),
            ("/Applications/Vivaldi.app", "Vivaldi"),
            ("/Applications/Opera.app", "Opera"),
            ("/Applications/Firefox.app", "Firefox"),
        ]
        for path, name in candidates:
            if os.path.exists(path):
                browsers.append({"path": path, "name": name})
    elif platform.system() == "Linux":
        for binary in ("google-chrome", "google-chrome-stable", "chromium",
                       "brave-browser", "firefox", "microsoft-edge"):
            p = _shutil.which(binary)
            if p:
                browsers.append({"path": p, "name": binary})
    return web.json_response({"browsers": browsers})


_SAFE_BROWSER_NAMES = {
    "google chrome", "chrome", "chromium", "brave browser", "firefox",
    "safari", "arc", "microsoft edge", "vivaldi", "opera",
}


def _is_safe_browser(path: str) -> bool:
    if not path:
        return True
    lp = path.lower().strip()
    if lp.endswith(".app") or ".app/" in lp:
        app_name = lp.rsplit("/", 1)[-1].replace(".app", "").strip()
        return app_name in _SAFE_BROWSER_NAMES or lp.startswith("/applications/")
    # Bare names ("Google Chrome", "Brave Browser") get routed to `open -a` on
    # macOS, which resolves them via LaunchServices regardless of $PATH.
    if lp in _SAFE_BROWSER_NAMES:
        return True
    import shutil
    return shutil.which(os.path.basename(path)) is not None


def _login_url_for_cli(cli_type: str) -> str | None:
    """Return only a profile-declared OAuth URL; never borrow another CLI's."""
    try:
        from cli_profiles import get_profile

        profile = get_profile((cli_type or "").lower().strip())
    except (UnknownCLIProfileError, TypeError):
        return None
    return profile.auth_login_url or None


async def open_account_browser(request: web.Request) -> web.Response:
    """Open a browser for an account using its IVE-owned isolated profile.

    Accepts optional `cli_type` and/or `url` in the JSON body. The selected
    profile must declare auth support even when the caller supplies a URL.
    """
    acc_id = request.match_info["id"]
    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM accounts WHERE id = ?", (acc_id,))
        row = await cur.fetchone()
        if not row:
            return web.json_response({"error": "account not found"}, status=404)
        acc = dict(row)
    finally:
        await db.close()

    browser_path = acc.get("browser_path") or ""
    body = await request.json() if request.content_length else {}
    cli_type = (body.get("cli_type") or acc.get("cli_type") or "claude").lower()
    declared_url = _login_url_for_cli(cli_type)
    if not declared_url:
        return web.json_response(
            {"error": f"login is unsupported for CLI profile '{cli_type}'", "code": "auth_unsupported"},
            status=409,
        )
    url = body.get("url") or declared_url

    if browser_path and not _is_safe_browser(browser_path):
        return web.json_response({"error": "unrecognized browser path"}, status=400)

    from auth_browser_driver import launch_local_isolated_browser
    result = await launch_local_isolated_browser(
        url,
        ACCOUNT_HOMES_DIR / acc_id / "browser",
        preferred=browser_path,
    )
    return web.json_response(
        {"ok": bool(result.get("opened")), "account": acc["name"], "browser": result},
        status=200 if result.get("opened") else 409,
    )


async def open_next_account(request: web.Request) -> web.Response:
    """Find the next usable non-API-key account and open its browser."""
    db = await get_db()
    try:
        await _clear_expired_quota_cooldowns(db)
        await db.commit()
        # Find OAuth accounts that are active, ordered by least recently used
        cur = await db.execute(
            "SELECT * FROM accounts WHERE type != 'api_key' AND status = 'active' "
            "ORDER BY last_used_at ASC NULLS FIRST, created_at ASC"
        )
        rows = await cur.fetchall()
        if not rows:
            # Fallback: try quota_exceeded accounts whose reset time has passed
            cur = await db.execute(
                "SELECT * FROM accounts WHERE type != 'api_key' AND status = 'quota_exceeded' "
                "AND quota_reset_at <= datetime('now') "
                "ORDER BY quota_reset_at ASC"
            )
            rows = await cur.fetchall()

        if not rows:
            return web.json_response({"error": "no available accounts", "message": "All non-API accounts are exhausted or none configured"}, status=404)

        acc = dict(rows[0])

        # Mark this account as used now
        await db.execute(
            "UPDATE accounts SET last_used_at = datetime('now') WHERE id = ?",
            (acc["id"],),
        )
        await db.commit()
    finally:
        await db.close()

    browser_path = acc.get("browser_path") or ""
    body = await request.json() if request.content_length else {}
    cli_type = (body.get("cli_type") or acc.get("cli_type") or "claude").lower()
    declared_url = _login_url_for_cli(cli_type)
    if not declared_url:
        return web.json_response(
            {"error": f"login is unsupported for CLI profile '{cli_type}'", "code": "auth_unsupported"},
            status=409,
        )
    url = body.get("url") or declared_url

    if browser_path and not _is_safe_browser(browser_path):
        return web.json_response({"error": "unrecognized browser path"}, status=400)
    from auth_browser_driver import launch_local_isolated_browser
    result = await launch_local_isolated_browser(
        url,
        ACCOUNT_HOMES_DIR / acc["id"] / "browser",
        preferred=browser_path,
    )
    return web.json_response({
        "ok": bool(result.get("opened")),
        "account_id": acc["id"],
        "account_name": acc["name"],
        "browser": result,
    }, status=200 if result.get("opened") else 409)


# ─── REST: Account OAuth ────────────────────────────────────────────────

async def _oauth_account_for_auth(
    account_id: str,
    requested_cli: str | None,
    *,
    require_idle: bool = False,
) -> tuple[dict | None, str | None, web.Response | None]:
    """Validate the account row before any account directory can be created."""
    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM accounts WHERE id = ?", (account_id,))
        row = await cur.fetchone()
        live_sessions: list[str] = []
        if require_idle:
            cur = await db.execute("SELECT id FROM sessions WHERE account_id = ?", (account_id,))
            live_sessions = [item["id"] for item in await cur.fetchall() if pty_mgr.is_alive(item["id"])]
    finally:
        await db.close()
    if not row:
        return None, None, web.json_response({"error": "account not found"}, status=404)
    account = dict(row)
    if live_sessions:
        return None, None, web.json_response(
            {
                "error": "account is in use by a live session; stop it before re-authenticating",
                "session_ids": live_sessions,
            },
            status=409,
        )
    if account.get("type") != "oauth":
        return None, None, web.json_response({"error": "account is not an OAuth account"}, status=400)
    cli_type = (account.get("cli_type") or "").lower()
    if not cli_type or not is_active_cli(cli_type):
        return None, None, web.json_response({"error": "account has no active CLI binding"}, status=409)
    if requested_cli and requested_cli.lower() != cli_type:
        return None, None, web.json_response(
            {"error": f"account belongs to {cli_type}, not {requested_cli.lower()}"},
            status=409,
        )
    return account, cli_type, None

async def playwright_setup_browser(request: web.Request) -> web.Response:
    """POST /api/accounts/{id}/setup-browser

    Start the CLI login in its account HOME and open only an isolated browser.
    Body: { "cli_type": "claude" | "codex" | "antigravity", "driver": "ive" | "auto" | "anyuse" }
    """
    from auth_cycler import auth_cycler
    acc_id = request.match_info["id"]
    body = await request.json() if request.content_length else {}
    account, cli_type, error = await _oauth_account_for_auth(
        acc_id,
        body.get("cli_type"),
        require_idle=True,
    )
    if error is not None:
        return error
    db = await get_db()
    try:
        await db.execute(
            "UPDATE accounts SET status = 'authenticating', verified_subject = NULL, "
            "credentials_verified_at = NULL WHERE id = ?",
            (acc_id,),
        )
        await db.commit()
    finally:
        await db.close()
    result = await auth_cycler.setup_browser(
        acc_id,
        cli_type=cli_type,
        driver=body.get("driver"),
        browser_path=account.get("browser_path"),
    )
    if not result.get("ok") and result.get("status") != "in_progress":
        db = await get_db()
        try:
            await db.execute(
                "UPDATE accounts SET status = 'auth_failed' WHERE id = ? "
                "AND status = 'authenticating'",
                (acc_id,),
            )
            await db.commit()
        finally:
            await db.close()
    status = (
        202 if result.get("status") in {"action_required", "verification_pending"}
        else 409 if result.get("status") == "in_progress"
        else 200 if result.get("ok")
        else 400
    )
    return web.json_response(result, status=status)


async def anyuse_auth(request: web.Request) -> web.Response:
    """Compatibility dispatcher for an optional account-automation provider."""
    if not extension_host.available("anyuse"):
        return web.json_response({"error": "account automation extension unavailable", "code": "extension_unavailable"}, status=409)
    provider = extension_host.load_backend_module("anyuse", "backend/account_routes.py")
    return await provider.anyuse_auth(request, get_db=get_db,
                                    oauth_account_for_auth=_oauth_account_for_auth)


async def account_auth_status(request: web.Request) -> web.Response:
    """GET /api/accounts/{id}/auth-status

    Re-check the account's own credential evidence; never infer host auth.
    """
    from auth_cycler import auth_cycler
    from account_sandbox import verify_account_credentials
    acc_id = request.match_info["id"]
    account, cli_type, error = await _oauth_account_for_auth(
        acc_id,
        request.query.get("cli_type"),
    )
    if error is not None:
        return error
    verification = await asyncio.to_thread(verify_account_credentials, acc_id, cli_type)
    credentials_verified = bool(
        verification.get("verified")
        and account.get("credentials_verified_at")
        and account.get("status") == "active"
    )
    return web.json_response({
        "account_id": acc_id,
        "cli_type": cli_type,
        "has_browser_context": auth_cycler.has_browser_context(acc_id),
        "account_status": account.get("status"),
        "credentials_verified": credentials_verified,
        "credentials_verified_at": account.get("credentials_verified_at"),
        "verified_subject": account.get("verified_subject"),
        **verification,
    })


def _is_usable_auth_recovery_account(
    account: dict,
    cli_type: str,
    verification: dict,
    *,
    current_account_id: str | None = None,
) -> bool:
    """Fail closed unless an OAuth identity is usable from its own sandbox."""
    return bool(
        account.get("id") != current_account_id
        and account.get("type") == "oauth"
        and (account.get("cli_type") or "").lower() == cli_type.lower()
        and account.get("status") == "active"
        and account.get("credentials_verified_at")
        and account.get("verified_subject")
        and verification.get("verified")
    )


def _auth_recovery_payload(
    session_id: str,
    cli_type: str,
    current_account_id: str | None,
    accounts: list[dict],
) -> dict:
    payload = {
        "session_id": session_id,
        "cli_type": cli_type,
        "current_account_id": current_account_id,
        "accounts": accounts,
    }
    if not accounts:
        payload["message"] = (
            f"No usable stored {cli_type} account is available. "
            "Log in a new account to continue."
        )
    return payload


async def _usable_auth_recovery_accounts(
    cli_type: str,
    current_account_id: str | None,
) -> list[dict]:
    from account_sandbox import verify_account_credentials

    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT id, name, type, status, cli_type, credentials_verified_at, "
            "verified_subject FROM accounts ORDER BY is_default DESC, name"
        )
        rows = [dict(row) for row in await cur.fetchall()]
    finally:
        await db.close()

    candidates = [
        account for account in rows
        if account.get("id") != current_account_id
        and account.get("type") == "oauth"
        and (account.get("cli_type") or "").lower() == cli_type.lower()
        and account.get("status") == "active"
        and account.get("credentials_verified_at")
        and account.get("verified_subject")
    ]
    checks = await asyncio.gather(*[
        asyncio.to_thread(
            verify_account_credentials,
            account["id"],
            cli_type,
        )
        for account in candidates
    ], return_exceptions=True)
    return [
        {
            "id": account["id"],
            "name": account["name"],
            "cli_type": account["cli_type"],
            "verified_subject": account["verified_subject"],
        }
        for account, check in zip(candidates, checks)
        if isinstance(check, dict) and _is_usable_auth_recovery_account(
            account,
            cli_type,
            check,
            current_account_id=current_account_id,
        )
    ]


async def get_auth_recovery(request: web.Request) -> web.Response:
    session_id = request.match_info["id"]
    session = await _get_visible_session_for_request(session_id, request)
    if not session:
        return web.json_response({"error": "session not found"}, status=404)
    cli_type = (session.get("cli_type") or "claude").lower()
    current_account_id = session.get("account_id")
    accounts = await _usable_auth_recovery_accounts(cli_type, current_account_id)
    return web.json_response(_auth_recovery_payload(
        session_id,
        cli_type,
        current_account_id,
        accounts,
    ))


async def _prepare_auth_recovery_restart(session: dict) -> tuple[str | None, str | None]:
    """Re-enable only a current OAuth account whose own sandbox still verifies."""
    account_id = session.get("account_id")
    if not account_id:
        return None, None

    db = await get_db()
    try:
        row = await (await db.execute(
            "SELECT * FROM accounts WHERE id = ?",
            (account_id,),
        )).fetchone()
    finally:
        await db.close()
    if not row:
        return None, "current account no longer exists; attach or log in another account"

    account = dict(row)
    cli_type = (session.get("cli_type") or "claude").lower()
    if account.get("type") != "oauth" or account.get("cli_type") != cli_type:
        return None, "current account cannot be safely re-synced; attach or log in another account"

    from account_sandbox import verify_account_credentials
    verification = (await asyncio.gather(
        asyncio.to_thread(
            verify_account_credentials,
            account_id,
            cli_type,
        ),
        return_exceptions=True,
    ))[0]
    if not (
        isinstance(verification, dict)
        and account.get("credentials_verified_at")
        and account.get("verified_subject")
        and verification.get("verified")
    ):
        return None, (
            "Current account credentials cannot be verified in their sandbox; "
            "attach or log in another account."
        )

    if account.get("status") == "auth_failed":
        db = await get_db()
        try:
            updated = await db.execute(
                "UPDATE accounts SET status = 'active' WHERE id = ? AND status = 'auth_failed'",
                (account_id,),
            )
            await db.commit()
        finally:
            await db.close()
        return account_id if getattr(updated, "rowcount", 0) else None, None
    if account.get("status") != "active":
        return None, f"current account is not restartable ({account.get('status')})"
    return None, None


async def restart_auth_recovery(request: web.Request) -> web.Response:
    session_id = request.match_info["id"]
    session = await _get_visible_session_for_request(session_id, request)
    if not session:
        return web.json_response({"error": "session not found"}, status=404)

    reactivated_account_id, error = await _prepare_auth_recovery_restart(session)
    if error:
        return web.json_response({"ok": False, "error": error}, status=409)

    import session_supervisor
    try:
        result = await session_supervisor.restart(
            session_id,
            expected={"account_id": session.get("account_id")},
        )
    except Exception as exc:
        result = {"ok": False, "error": str(exc)}

    if not result.get("ok") and reactivated_account_id:
        db = await get_db()
        try:
            await db.execute(
                "UPDATE accounts SET status = 'auth_failed' WHERE id = ? AND status = 'active'",
                (reactivated_account_id,),
            )
            await db.commit()
        finally:
            await db.close()
    return web.json_response(result, status=200 if result.get("ok") else 409)


async def _validated_account_switch(
    session_id: str,
    new_account_id: str,
) -> tuple[dict | None, str | None]:
    """Validate identity/CLI compatibility before stopping the current PTY."""
    db = await get_db()
    try:
        session_row = await (await db.execute(
            "SELECT s.cli_type, s.account_id, old.name AS old_account_name "
            "FROM sessions s LEFT JOIN accounts old ON old.id = s.account_id WHERE s.id = ?",
            (session_id,),
        )).fetchone()
        account_row = await (await db.execute(
            "SELECT * FROM accounts WHERE id = ?",
            (new_account_id,),
        )).fetchone()
    finally:
        await db.close()
    if not session_row:
        return None, "session not found"
    if not account_row:
        return None, "account not found"
    session = dict(session_row)
    account = dict(account_row)
    cli_type = (session.get("cli_type") or "claude").lower()
    if account.get("status") != "active":
        return None, f"account is not active ({account.get('status')})"
    if account.get("type") == "oauth":
        if account.get("cli_type") != cli_type:
            return None, f"account belongs to {account.get('cli_type') or 'no CLI'}, not {cli_type}"
        from account_sandbox import verify_account_credentials
        verification = await asyncio.to_thread(
            verify_account_credentials,
            new_account_id,
            cli_type,
        )
        if not account.get("credentials_verified_at") or not verification.get("verified"):
            return None, "account has no verified credentials in its own sandbox"
    elif account.get("api_key"):
        from crypto import decrypt_secret
        provider = _normalize_api_key_provider(
            account.get("api_key_provider"),
            decrypt_secret(account.get("api_key")),
        )
        provider_spec = API_KEY_PROVIDERS.get(provider) or {}
        if cli_type not in provider_spec.get("session_clis", set()):
            return None, f"{provider or 'API-key'} account is not compatible with {cli_type}"
    else:
        return None, "account has no usable credentials"
    return {
        "session": session,
        "account": account,
        "cli_type": cli_type,
    }, None


_UNSET_ACCOUNT = object()


async def _switch_session_account(
    session_id: str,
    new_account_id: str,
    *,
    expected_old_account_id=_UNSET_ACCOUNT,
) -> dict:
    switch, error = await _validated_account_switch(session_id, new_account_id)
    if error:
        return {"ok": False, "error": error}
    if (
        expected_old_account_id is not _UNSET_ACCOUNT
        and switch["session"].get("account_id") != expected_old_account_id
    ):
        return {"ok": False, "error": "session account changed before restart"}
    import session_supervisor
    restart_result = await session_supervisor.restart(
        session_id,
        updates={"account_id": new_account_id},
        expected={"account_id": switch["session"].get("account_id")},
    )
    if not restart_result.get("ok"):
        return {"ok": False, "error": restart_result.get("error"), "restart": restart_result}
    db = await get_db()
    try:
        await _sync_zai_mcp_servers_for_session(
            db,
            session_id,
            switch["cli_type"],
            new_account_id,
        )
        await db.execute(
            "UPDATE accounts SET last_used_at = datetime('now') WHERE id = ?",
            (new_account_id,),
        )
        await db.commit()
    finally:
        await db.close()
    payload = {
        "ok": True,
        "session_id": session_id,
        "old_account_id": switch["session"].get("account_id"),
        "old_account_name": switch["session"].get("old_account_name") or "system auth",
        "new_account_id": new_account_id,
        "new_account_name": switch["account"].get("name"),
        "restart": restart_result,
    }
    await broadcast({
        "type": "account_switched",
        **payload,
        "message": "Account switched after the replacement PTY started with verified auth.",
    })
    return payload


async def confirm_session_quota(request: web.Request) -> web.Response:
    """Confirm a terminal-text quota suspicion and perform an awaited switch."""
    session_id = request.match_info["id"]
    body = await request.json() if request.content_length else {}
    expected_account_id = body.get("account_id")
    db = await get_db()
    try:
        row = await (await db.execute(
            "SELECT * FROM sessions WHERE id = ?", (session_id,)
        )).fetchone()
    finally:
        await db.close()
    if not row or not _session_visible_to_request(dict(row), request):
        return web.json_response({"error": "session not found"}, status=404)
    current_account_id = row["account_id"]
    if expected_account_id != current_account_id:
        return web.json_response(
            {"error": "session account changed; review the current account before confirming"},
            status=409,
        )

    reset_at = None
    reset_unix = body.get("reset_unix")
    if reset_unix:
        try:
            from datetime import datetime, timezone
            reset_at = datetime.fromtimestamp(
                int(reset_unix), tz=timezone.utc
            ).strftime("%Y-%m-%d %H:%M:%S")
        except (TypeError, ValueError, OSError, OverflowError):
            return web.json_response({"error": "invalid reset_unix"}, status=400)

    from auth_cycler import auth_cycler
    selection = await auth_cycler.auto_failover(session_id, reset_at=reset_at)
    if not selection:
        await broadcast({
            "type": "quota_exceeded",
            "session_id": session_id,
            "message": "Quota confirmed; no alternate verified account is available.",
        })
        return web.json_response({"ok": True, "switched": False})
    if selection.get("old_account_id") != current_account_id:
        return web.json_response(
            {"error": "session account changed while quota confirmation was processed"},
            status=409,
        )
    switched = await _switch_session_account(
        session_id,
        selection["new_account_id"],
        expected_old_account_id=current_account_id,
    )
    return web.json_response(
        {**switched, "switched": bool(switched.get("ok"))},
        status=200 if switched.get("ok") else 409,
    )


async def restart_with_account(request: web.Request) -> web.Response:
    """Atomically stop and restart a session with a verified compatible account."""
    session_id = request.match_info["id"]
    body = await request.json()
    new_account_id = body.get("account_id")
    if not new_account_id:
        return web.json_response({"error": "account_id required"}, status=400)

    expected_account_id = (
        body["expected_account_id"]
        if "expected_account_id" in body
        else _UNSET_ACCOUNT
    )
    result = await _switch_session_account(
        session_id,
        new_account_id,
        expected_old_account_id=expected_account_id,
    )
    return web.json_response(result, status=200 if result.get("ok") else 409)


# ─── REST: Native Terminal Pop-Out ──────────────────────────────────────────

async def pop_out_session(request: web.Request) -> web.Response:
    """POST /api/sessions/{id}/pop-out

    Opens the session in a native OS terminal (Terminal.app / iTerm2 on macOS).
    Builds the same CLI command as start_pty would, but instead of spawning a
    PTY inside Commander, opens a real terminal window. Hooks still relay events
    back to Commander so session state, tool tracking, and subagent tracking
    all continue to work.

    The session is marked as is_external=1 so the frontend knows to show a
    status card instead of an xterm.js terminal.
    """
    import shlex
    import sys

    session_id = request.match_info["id"]

    config = await get_session_config(session_id)
    if not config:
        return web.json_response({"error": "Session not found"}, status=400)

    # Check workspace has native terminals enabled
    workspace_id = config.get("workspace_id", "")
    db_check = await get_db()
    try:
        cur = await db_check.execute(
            "SELECT native_terminals_enabled FROM workspaces WHERE id = ?",
            (workspace_id,),
        )
        ws_row = await cur.fetchone()
        if not ws_row or not ws_row["native_terminals_enabled"]:
            return web.json_response(
                {"error": "Native terminals not enabled for this workspace"},
                status=400,
            )
    finally:
        await db_check.close()

    # Stop existing PTY if running (can't have both)
    if pty_mgr.is_alive(session_id):
        await _stop_session_expected(session_id)

    # Build CLI command via UnifiedSession (same logic as start_pty)
    cli_type = config.get("cli_type", "claude")
    launch_config = await _launch_config_for_session(config)
    session_obj = UnifiedSession(cli_type, launch_config)
    workspace_path = config.get("workspace_path", os.path.expanduser("~"))
    profile_env = await _prepare_session_cli_env(config, session_id)
    try:
        from git_attribution import inject_git_attribution_env
        await inject_git_attribution_env(config, session_id, profile_env)
    except Exception as git_attr_exc:
        logger.debug("Git attribution env skipped (pop-out): %s", git_attr_exc)

    # Resume if native_session_id exists
    native_sid = config.get("native_session_id")
    if native_sid:
        profile_id = session_obj.profile.id
        if profile_id == "gemini":
            resume_arg = _resolve_gemini_resume_index(workspace_path, native_sid)
            if resume_arg:
                session_obj.set(Feature.RESUME_ID, resume_arg)
        else:
            _ensure_native_resume_files(profile_id, native_sid, workspace_path, profile_env)
            session_obj.set(Feature.RESUME_ID, native_sid)

    # Minimal system prompt for pop-out (guidelines omitted — user manages their own).
    # We MUST append the prompt even when resuming, because Claude Code does not
    # save `--append-system-prompt` in its transcript. Omitting it changes the
    # system prompt context and triggers "Invalid signature in thinking block".
    popout_prompt = config.get("system_prompt") or ""
    popout_type = (config.get("session_type") or "").strip()
    if popout_type == "planner" and "You are the Planner" not in popout_prompt:
        popout_prompt = PLANNER_SYSTEM_PROMPT + ("\n\n" + popout_prompt if popout_prompt else "")
    elif popout_type == "architect" and "You are the Architect" not in popout_prompt:
        popout_prompt = ARCHITECT_SYSTEM_PROMPT + ("\n\n" + popout_prompt if popout_prompt else "")
    elif popout_type == "brainstormer" and "You are the Brainstormer" not in popout_prompt:
        popout_prompt = BRAINSTORMER_SYSTEM_PROMPT + ("\n\n" + popout_prompt if popout_prompt else "")
    elif popout_type == "secure" and "You are the Secure agent" not in popout_prompt:
        popout_prompt = SECURE_SYSTEM_PROMPT + ("\n\n" + popout_prompt if popout_prompt else "")
    elif popout_type in ("", "worker", "test_worker") and WORKER_SYSTEM_PROMPT_FRAGMENT:
        if "## Git Commits and IVE Attribution" not in popout_prompt:
            popout_prompt = WORKER_SYSTEM_PROMPT_FRAGMENT + (
                "\n\n" + popout_prompt if popout_prompt else ""
            )
    if popout_prompt:
        session_obj.append_system_prompt(popout_prompt)

    cmd = session_obj.build_command()

    # Env vars for hook relay (critical — this is what keeps Commander connected)
    import session_proofs
    export_values = {
        **profile_env,
        "COMMANDER_SESSION_ID": session_id,
        session_proofs.ENV_VAR: session_proofs.issue(session_id),
        "COMMANDER_API_URL": f"http://{HOST}:{PORT}",
        "COMMANDER_WORKSPACE_ID": workspace_id,
        "COMMANDER_CLI_TYPE": cli_type,
    }
    env_exports = "".join(
        f"export {shlex.quote(k)}={shlex.quote(str(v))}; "
        for k, v in export_values.items()
        if v is not None
    )
    cli_cmd = " ".join(shlex.quote(c) for c in cmd)
    full_cmd = f'{env_exports}cd {shlex.quote(workspace_path)} && {cli_cmd}'

    # Open in native terminal (macOS)
    if sys.platform == "darwin":
        # Try iTerm2 first, fall back to Terminal.app
        iterm_script = (
            f'tell application "iTerm"\n'
            f'  create window with default profile\n'
            f'  tell current session of current window\n'
            f'    write text {json.dumps(full_cmd)}\n'
            f'  end tell\n'
            f'end tell'
        )
        terminal_script = (
            f'tell application "Terminal"\n'
            f'  do script {json.dumps(full_cmd)}\n'
            f'  activate\n'
            f'end tell'
        )

        # Prefer iTerm2 if installed
        try:
            proc = await _asyncio.create_subprocess_exec(
                "osascript", "-e", iterm_script,
                stdout=_asyncio.subprocess.PIPE,
                stderr=_asyncio.subprocess.PIPE,
            )
            _, stderr = await proc.communicate()
            if proc.returncode != 0:
                raise RuntimeError(stderr.decode())
            terminal_app = "iTerm2"
        except Exception:
            # Fall back to Terminal.app
            proc = await _asyncio.create_subprocess_exec(
                "osascript", "-e", terminal_script,
                stdout=_asyncio.subprocess.PIPE,
                stderr=_asyncio.subprocess.PIPE,
            )
            _, stderr = await proc.communicate()
            if proc.returncode != 0:
                return web.json_response(
                    {"error": f"Failed to open terminal: {stderr.decode()[:200]}"},
                    status=500,
                )
            terminal_app = "Terminal.app"
    else:
        return web.json_response(
            {"error": "Native terminal pop-out is currently macOS-only"},
            status=400,
        )

    # Mark session as external
    db_up = await get_db()
    try:
        await db_up.execute(
            "UPDATE sessions SET is_external = 1 WHERE id = ?",
            (session_id,),
        )
        await db_up.commit()
    finally:
        await db_up.close()

    await broadcast({
        "session_id": session_id,
        "type": "session_popped_out",
        "terminal": terminal_app,
    })

    return web.json_response({
        "ok": True,
        "session_id": session_id,
        "terminal": terminal_app,
        "command": cli_cmd,
    })


async def handle_pipeline_result(request: web.Request) -> web.Response:
    """POST /api/hooks/pipeline-result

    Called by agents (via worker MCP report_pipeline_result tool) to report
    structured pass/fail results for pipeline stages. This gives the pipeline
    engine a definitive signal instead of keyword-matching terminal output.
    """
    try:
        payload = await request.json()
    except Exception:
        return web.json_response({"error": "invalid JSON"}, status=400)

    session_id = payload.get("session_id")
    status = payload.get("status", "pass")   # 'pass' or 'fail'
    summary = payload.get("summary", "")
    details = payload.get("details", "")
    result_obj = payload.get("result")       # C1: optional typed result object

    if not session_id:
        return web.json_response({"error": "session_id required"}, status=400)

    # MCP-S6: reject body session_id that doesn't match the calling session.
    # Without this an attacker who knows another session's id can forge a
    # 'pass' result for that session's pipeline run.
    # Fail closed: /api/hooks/* skips token auth on localhost, so without a
    # caller identity anyone local could complete any stage.
    caller = await _resolve_caller(request)
    if not caller or caller["session_id"] != session_id:
        return web.json_response(
            {"error": "forbidden: pipeline-result session_id must match calling session"},
            status=403,
        )
    import session_proofs
    if (
        not caller.get("verified")
        and session_proofs.check(session_id, None) != session_proofs.LEGACY
    ):
        # A proof was issued at spawn: the caller must present it.
        return web.json_response(
            {"error": "forbidden: session proof required"}, status=403,
        )

    import pipeline_engine
    run_id = pipeline_engine._session_to_run.get(session_id)
    if not run_id:
        return web.json_response({"ok": False, "message": "session not in active pipeline"})

    run = await pipeline_engine.get_run(run_id)
    if not run:
        return web.json_response({"ok": False, "message": "run not found"})

    # Find the stage for this session
    stage_history = run.get("stage_history", {})
    if isinstance(stage_history, str):
        import json as _json
        stage_history = _json.loads(stage_history)
    stage_id = None
    for sid, sh in stage_history.items():
        if sh.get("session_id") == session_id and sh.get("status") == "running":
            stage_id = sid
            break

    if not stage_id:
        return web.json_response({"ok": False, "message": "no active stage for session"})

    # C1 typed agent contract: when a typed `result` object is supplied, validate
    # it against the stage's declared result_schema (if any) BEFORE completing the
    # stage. On mismatch, reject without advancing so the agent can retry. The
    # legacy pass/fail + __pipeline_result: path is unchanged when no result given.
    typed_result = None
    if result_obj is not None:
        if not isinstance(result_obj, dict):
            return web.json_response(
                {"ok": False, "validation_error": "result must be a JSON object"}
            )
        defn = await pipeline_engine.get_definition(run.get("pipeline_id"))
        stage = pipeline_engine._find_stage(defn, stage_id) if defn else None
        schema = None
        if stage:
            schema = stage.get("result_schema") or (stage.get("config") or {}).get("result_schema")
            # C2: fall back to the role template's schema for role-driven stages
            # that didn't declare one explicitly.
            if not schema:
                try:
                    import role_templates
                    _role = (stage.get("agent_config") or {}).get("role") or stage.get("session_type")
                    schema = role_templates.role_result_schema(_role)
                except Exception:
                    schema = None
        if schema:
            err = pipeline_engine.validate_against_schema(result_obj, schema)
            if err:
                logger.info("Pipeline result rejected (schema): session %s stage %s: %s",
                            session_id[:8], stage_id, err)
                return web.json_response({"ok": False, "validation_error": err})
        typed_result = result_obj
        # Derive pass/fail from the typed object when not explicitly provided, so
        # the legacy on_pass/on_fail transitions keep working for typed stages.
        if "status" not in payload:
            derived = result_obj.get("verdict") or result_obj.get("status")
            if isinstance(derived, str) and derived.lower() in ("pass", "fail"):
                status = derived.lower()
        if not summary:
            summary = str(result_obj.get("summary") or result_obj.get("verdict") or "")[:200]

    # Store the structured result — prefixed with __pipeline_result: so the
    # condition evaluator can detect it vs. raw terminal output
    result_output = f"__pipeline_result:{status}:{summary}"
    if details:
        result_output += f"\n{details[:1500]}"
    await pipeline_engine._update_stage_status(
        run_id, stage_id, "completed", output_summary=result_output, result=typed_result
    )

    logger.info("Pipeline result: session %s stage %s → %s: %s", session_id[:8], stage_id, status, summary[:100])

    # Complete the stage and advance the pipeline
    import asyncio as _asyncio
    _asyncio.ensure_future(pipeline_engine._complete_stage(run_id, stage_id))

    return web.json_response({"ok": True, "stage_id": stage_id, "status": status})


async def handle_acquire_claim(request: web.Request) -> web.Response:
    """POST /api/workspaces/{id}/claims — C5 hard file-claim (deadlock-safe).

    Grants an authoritative claim on a path, or 409 if a LIVE peer holds it.
    The claim carries a TTL and self-heals if the holder dies, so it can never
    permanently block. Caller identity comes from the session header."""
    workspace_id = request.match_info["id"]
    try:
        body = await request.json()
    except Exception:
        body = {}
    body = body if isinstance(body, dict) else {}
    caller = await _resolve_caller(request)
    session_id = (caller or {}).get("session_id") or body.get("session_id")
    if not session_id:
        return web.json_response({"error": "session_id required (no calling session)"}, status=400)
    path = str(body.get("path") or "").strip()
    if not path:
        return web.json_response({"error": "path required"}, status=400)
    import file_claims
    try:
        ttl = int(body.get("ttl_s") or file_claims.DEFAULT_TTL_S)
    except (TypeError, ValueError):
        ttl = file_claims.DEFAULT_TTL_S
    res = await file_claims.acquire(
        workspace_id, path, session_id,
        agent_id=body.get("agent_id"), intent=str(body.get("intent") or ""), ttl_s=ttl,
    )
    return web.json_response(res, status=200 if res.get("granted") else 409)


async def handle_release_claim(request: web.Request) -> web.Response:
    """DELETE /api/workspaces/{id}/claims — release your claim(s) by path/claim_id/all."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    body = body if isinstance(body, dict) else {}
    caller = await _resolve_caller(request)
    session_id = (caller or {}).get("session_id") or body.get("session_id")
    if not session_id:
        return web.json_response({"error": "session_id required"}, status=400)
    import file_claims
    res = await file_claims.release(session_id, path=body.get("path"), claim_id=body.get("claim_id"))
    return web.json_response(res)


async def handle_list_claims(request: web.Request) -> web.Response:
    """GET /api/workspaces/{id}/claims — list active (live, unexpired) claims."""
    workspace_id = request.match_info["id"]
    import file_claims
    res = await file_claims.list_claims(workspace_id)
    return web.json_response({"claims": res})


async def handle_git_attribution(request: web.Request) -> web.Response:
    """POST /api/hooks/git-attribution

    Called by the process-scoped git wrapper inside IVE-managed sessions after a
    commit-producing git command succeeds. The wrapper sends an HMAC-derived
    session key; raw session metadata stays in SQLite, not Git history.
    """
    try:
        payload = await request.json()
    except Exception:
        return web.json_response({"error": "invalid JSON"}, status=400)

    from git_attribution import AttributionError, record_commit_attributions

    db = await get_db()
    try:
        try:
            result = await record_commit_attributions(db, payload)
        except AttributionError as exc:
            return web.json_response({"error": str(exc)}, status=exc.status)
    finally:
        await db.close()

    return web.json_response(result)


async def handle_hook_discover(request: web.Request) -> web.Response:
    """POST /api/hooks/discover

    Called by the hook relay script when COMMANDER_SESSION_ID is NOT set but
    auto-register is enabled. The hook sends the workspace path (CWD) and
    CLI process PID. Commander matches the path to a workspace and, if
    auto_register_terminals is enabled, creates a session and returns the
    session_id so subsequent hook calls can include it.

    The hook script caches the returned session_id in a temp file keyed by
    PID so it only calls discover once per CLI process lifetime.
    """
    try:
        payload = await request.json()
    except Exception:
        return web.json_response({"error": "invalid JSON"}, status=400)

    cwd = payload.get("cwd", "")
    pid = payload.get("pid", "")
    cli_type = payload.get("cli_type", "claude")
    hook_event = payload.get("hook_event_name", "")

    if not cwd or not is_active_cli(cli_type):
        return web.json_response({})

    # Normalize the CWD path
    cwd = os.path.realpath(cwd)

    # Find workspace matching this CWD
    db = await get_db()
    try:
        cur = await db.execute("SELECT * FROM workspaces WHERE auto_register_terminals = 1")
        rows = await cur.fetchall()

        matched_ws = None
        for ws in rows:
            ws_path = os.path.realpath(ws["path"])
            if cwd == ws_path or cwd.startswith(ws_path + os.sep):
                matched_ws = dict(ws)
                break

        if not matched_ws:
            return web.json_response({})  # No matching workspace — ignore

        # Check if we already have a session for this PID
        cur2 = await db.execute(
            "SELECT id FROM sessions WHERE is_external = 1 AND external_pid = ? AND workspace_id = ?",
            (str(pid), matched_ws["id"]),
        )
        existing = await cur2.fetchone()
        if existing:
            return web.json_response({"session_id": existing["id"]})

        # Create a new external session
        session_id = str(uuid.uuid4())
        name = f"External {cli_type.title()} {session_id[:6]}"
        default_model = get_profile(cli_type).default_model

        await db.execute(
            """INSERT INTO sessions
               (id, workspace_id, name, model, cli_type, is_external, external_pid, effort)
               VALUES (?, ?, ?, ?, ?, 1, ?, NULL)""",
            (session_id, matched_ws["id"], name, default_model, cli_type, str(pid)),
        )
        await db.commit()

        logger.info(
            "Auto-registered external %s session %s (PID %s) in workspace %s",
            cli_type, session_id[:8], pid, matched_ws["name"],
        )

        await broadcast({
            "type": "session_created",
            "session_id": session_id,
            "workspace_id": matched_ws["id"],
            "name": name,
            "is_external": True,
        })

        return web.json_response({"session_id": session_id})
    finally:
        await db.close()


