async def get_cli_info(request: web.Request) -> web.Response:
    from cli_session import build_feature_matrix

    matrix = build_feature_matrix()
    available_clis = await _registered_cli_availability()
    return web.json_response({
        "version": VERSION,
        "models": _discovered_models.get("claude") or AVAILABLE_MODELS,
        "permission_modes": PERMISSION_MODES,
        "effort_levels": EFFORT_LEVELS,
        "cli_types": [
            {"id": profile.id, "label": profile.label}
            for profile in active_profiles()
        ],
        "available_clis": available_clis,
        "deprecated_clis": {
            p.id: True for p in all_profiles()
            if getattr(p, "deprecated", False) or not getattr(p, "active", True)
        },
        "profiles": _with_effort_defaults(matrix.get("profiles", {})),
    })


def _with_effort_defaults(profiles: dict) -> dict:
    """Attach what an empty effort really means, so the UI can say
    "Default (xhigh, your Claude settings)" instead of pretending "high"."""
    try:
        from effort_defaults import resolve_claude_effort_default, default_label
        claude = profiles.get("claude")
        if isinstance(claude, dict):
            resolved = resolve_claude_effort_default()
            claude["effort_default"] = dict(resolved, label=default_label(resolved))
    except Exception as exc:  # never break /api/cli-info over a settings read
        logger.debug("effort default lookup failed: %s", exc)
    return profiles


async def get_cli_feature_matrix(request: web.Request) -> web.Response:
    """Return the unified feature compatibility matrix.

    Driven entirely by cli_profiles.py so CLI-capability information has a
    single source of truth. Consumed by the marketplace UI to render
    compatibility badges and by plugin tooling to check feature support.
    """
    from cli_session import build_feature_matrix
    matrix = build_feature_matrix()
    available_clis = await _registered_cli_availability()
    matrix["available_clis"] = available_clis
    for profile_id, profile in matrix.get("profiles", {}).items():
        profile["available"] = available_clis.get(profile_id, False)
    matrix["profiles"] = _with_effort_defaults(matrix.get("profiles", {}))
    return web.json_response(matrix)


