def _safety_decision_payload(row) -> dict:
    """Render a durable safety row for why/audit surfaces."""
    from safety_learning import redact_safety_audit_text

    source = dict(row)
    payload = {
        key: source.get(key)
        for key in (
            "id", "tool_use_id", "session_id", "workspace_id", "tool_name",
            "tool_input_summary", "matched_rule_id", "decision", "reason",
            "user_response", "latency_ms", "precedent_decision_ids",
            "precedent_reason", "precedent_class", "precedent_mode", "created_at",
        )
    }
    for key, limit in (
        ("tool_input_summary", 500),
        ("reason", 500),
        ("precedent_reason", 500),
        ("precedent_class", 120),
    ):
        if payload.get(key) is not None:
            payload[key] = redact_safety_audit_text(payload[key], limit=limit)
    raw_ids = payload.get("precedent_decision_ids")
    if isinstance(raw_ids, str) and raw_ids:
        try:
            parsed = json.loads(raw_ids)
            payload["precedent_decision_ids"] = [
                int(value) for value in parsed if int(value) > 0
            ] if isinstance(parsed, list) else []
        except (TypeError, ValueError, json.JSONDecodeError):
            payload["precedent_decision_ids"] = []
    elif not isinstance(raw_ids, list):
        payload["precedent_decision_ids"] = []

    row_precedent_mode = payload.get("precedent_mode")
    # Rows written before mode configurability shipped are legacy verdict rows.
    if payload["precedent_decision_ids"] and row_precedent_mode in (None, "", "verdict"):
        payload["governance"] = "precedent"
    elif payload.get("matched_rule_id") not in (None, "", "llm_classifier"):
        payload["governance"] = "rule"
    elif payload.get("matched_rule_id") == "llm_classifier":
        payload["governance"] = "classifier"
    else:
        payload["governance"] = "default"
    return payload


async def get_safety_decisions(request: web.Request) -> web.Response:
    """GET /api/safety/decisions — query the decision audit log."""
    session_id = request.query.get("session_id")
    workspace_id = request.query.get("workspace_id")
    try:
        limit = max(1, min(int(request.query.get("limit", "100")), 500))
        offset = max(0, int(request.query.get("offset", "0")))
    except (TypeError, ValueError):
        return web.json_response({"error": "limit and offset must be integers"}, status=400)

    where_parts = []
    params: list = []
    if session_id:
        where_parts.append("session_id = ?")
        params.append(session_id)
    if workspace_id:
        where_parts.append("workspace_id = ?")
        params.append(workspace_id)

    where = f"WHERE {' AND '.join(where_parts)}" if where_parts else ""
    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT id, tool_use_id, session_id, workspace_id, tool_name, "
            "tool_input_summary, matched_rule_id, decision, reason, user_response, "
            "latency_ms, precedent_decision_ids, precedent_reason, precedent_class, "
            f"precedent_mode, created_at FROM safety_decisions {where} "
            "ORDER BY id DESC LIMIT ? OFFSET ?",
            params + [limit, offset],
        )
        rows = await cur.fetchall()
        return web.json_response([_safety_decision_payload(r) for r in rows])
    finally:
        await db.close()


async def suggest_safety_allows(request: web.Request) -> web.Response:
    """POST /api/safety/suggest-allows — LLM-grounded allow-rule proposals."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    workspace_id = body.get("workspace_id")
    if workspace_id is not None and not isinstance(workspace_id, str):
        return web.json_response({"error": "workspace_id must be a string"}, status=400)
    workspace_id = (workspace_id or "").strip() or None

    db = await get_db()
    try:
        from safety_precedent import get_safety_precedent_mode
        precedent_mode = await get_safety_precedent_mode(db)
        if precedent_mode == "off":
            return web.json_response({
                "suggestions": [],
                "candidate_count": 0,
                "empty_message": "Past approvals are ignored while precedent is off",
            })
        from safety_learning import (
            is_allow_evidence,
            load_suggestion_candidates,
            suggest_allow_rules,
        )

        setting_rows = await db.execute_fetchall(
            "SELECT key, value FROM app_settings WHERE key IN "
            "('safety_classifier_model', 'safety_precedent_window_days')"
        )
        suggestion_settings = {
            row["key"]: row["value"] for row in setting_rows
        }
        try:
            lookback_days = max(
                1,
                min(
                    int(suggestion_settings.get("safety_precedent_window_days") or 30),
                    365,
                ),
            )
        except (TypeError, ValueError):
            lookback_days = 30
        candidates = await load_suggestion_candidates(
            db,
            workspace_id=workspace_id,
            lookback_days=lookback_days,
        )
        approved_count = sum(is_allow_evidence(row) for row in candidates)
        if approved_count < 3:
            return web.json_response({
                "suggestions": [],
                "candidate_count": len(candidates),
                "empty_message": "Three approved examples are needed before suggesting a rule",
            })

        raw_model = suggestion_settings.get("safety_classifier_model")
        if raw_model == "":
            return web.json_response({
                "suggestions": [],
                "candidate_count": len(candidates),
                "empty_message": "The safety LLM is disabled",
            })
        model = raw_model or None

        # Test-only injection seam follows the classifier's llm_json convention;
        # production apps never set this key.
        llm_json = request.app.get("_safety_suggest_llm_json")
        suggestions = await suggest_allow_rules(
            db,
            workspace_id=workspace_id,
            model=model,
            llm_json=llm_json,
            candidates=candidates,
        )
        return web.json_response({
            "suggestions": suggestions,
            "candidate_count": len(candidates),
            "empty_message": None,
        })
    except Exception as exc:
        logger.warning("Safety auto-allow suggestion failed: %s", exc)
        return web.json_response(
            {"error": "Could not generate auto-allow suggestions"},
            status=502,
        )
    finally:
        await db.close()


