async def _proactively_suggest_safety_allows(workspace_id: Optional[str]) -> None:
    """Emit LLM-grounded three-approval suggestions onto the event spine."""
    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT key, value FROM app_settings WHERE key IN "
            "('safety_classifier_model', 'safety_precedent_mode', "
            "'safety_precedent_window_days')"
        )
        settings = {row["key"]: row["value"] for row in await cur.fetchall()}
        from safety_precedent import resolve_safety_precedent_mode
        precedent_mode = resolve_safety_precedent_mode(
            settings.get("safety_precedent_mode")
        )
        if precedent_mode == "off":
            return
        raw_model = settings.get("safety_classifier_model")
        if raw_model == "":
            return
        model = raw_model or None
        try:
            lookback_days = max(
                1, min(int(settings.get("safety_precedent_window_days") or 30), 365)
            )
        except (TypeError, ValueError):
            lookback_days = 30
        from safety_learning import emit_proactive_allow_suggestions

        async def _emit(payload: dict) -> None:
            await bus.emit(CommanderEvent.SAFETY_RULE_PROPOSED, payload)

        await emit_proactive_allow_suggestions(
            db,
            workspace_id=workspace_id,
            emit_fn=_emit,
            model=model,
            precedent_mode=precedent_mode,
            lookback_days=lookback_days,
        )
    except Exception as exc:
        logger.debug("Proactive safety suggestion skipped: %s", exc)
    finally:
        await db.close()


async def report_safety_approved(request: web.Request) -> web.Response:
    """Consume the signed one-time decision returned to the matching pre-hook."""
    try:
        data = await request.json()
    except Exception:
        return web.json_response({"ok": False, "error": "invalid JSON"}, status=400)
    if not isinstance(data, dict):
        return web.json_response({"ok": False, "error": "invalid payload"}, status=400)

    tool_use_id = data.get("tool_use_id", "")
    decision_token = data.get("decision_token", "")
    if not isinstance(tool_use_id, str) or not tool_use_id.strip():
        return web.json_response({"ok": False, "error": "tool_use_id required"}, status=400)
    if not isinstance(decision_token, str) or not decision_token:
        return web.json_response(
            {"ok": False, "error": "signed decision token required"}, status=401
        )

    db = await get_db()
    try:
        from safety_approvals import InvalidDecisionToken, approve_decision_token

        try:
            claims = await approve_decision_token(
                db,
                decision_token,
                tool_use_id=tool_use_id.strip(),
            )
        except InvalidDecisionToken as exc:
            return web.json_response(
                {"ok": False, "error": str(exc)},
                status=403,
            )
        from safety_precedent import get_safety_precedent_mode
        if await get_safety_precedent_mode(db) != "off":
            _fire_and_forget(
                _proactively_suggest_safety_allows(claims["workspace_id"])
            )
    except Exception:
        logger.exception("Safety approval report failed")
        return web.json_response(
            {"ok": False, "error": "approval ledger unavailable"}, status=503
        )
    finally:
        await db.close()

    return web.json_response({"ok": True})


