async def list_pipeline_definitions(request: web.Request) -> web.Response:
    import pipeline_engine
    workspace_id = request.query.get("workspace_id")
    defs = await pipeline_engine.list_definitions(workspace_id)
    return web.json_response(defs)


def _pipeline_stage_command(stage: dict) -> str:
    config = stage.get("config") if isinstance(stage.get("config"), dict) else {}
    return str(config.get("command") or stage.get("prompt_template") or "").strip()


def _sanitize_pipeline_safety_exclusions(body: dict, *, old_definition: dict | None) -> dict:
    """Keep command-stage safety exclusions command-bound.

    The UI resets safety_excluded when command text changes. This mirrors that
    in the API so agents or stale clients cannot preserve a bypass while
    changing the command.
    """
    if not isinstance(body, dict):
        return body
    stages = body.get("stages")
    if not isinstance(stages, list):
        return body
    old_by_id = {
        str(stage.get("id")): stage
        for stage in (old_definition or {}).get("stages", [])
        if isinstance(stage, dict) and stage.get("id") is not None
    }
    for stage in stages:
        if not isinstance(stage, dict) or stage.get("type") != "command":
            continue
        config = stage.get("config")
        if not isinstance(config, dict):
            config = {}
            stage["config"] = config
        policy = config.get("policy")
        if not isinstance(policy, dict):
            continue
        if policy.get("mode") != "safety_excluded":
            policy.pop("safety_excluded_command", None)
            continue
        command = _pipeline_stage_command(stage)
        old_stage = old_by_id.get(str(stage.get("id")))
        old_command = _pipeline_stage_command(old_stage) if old_stage else None
        command_changed = old_stage is not None and command != old_command
        approved_command = str(policy.get("safety_excluded_command") or "").strip()
        if not command or (command_changed and approved_command != command):
            policy["mode"] = "safety_checked"
            policy.pop("safety_excluded_command", None)
        else:
            policy["safety_excluded_command"] = command
    return body


async def create_pipeline_definition(request: web.Request) -> web.Response:
    import pipeline_engine
    body = await request.json()
    body = _sanitize_pipeline_safety_exclusions(
        body if isinstance(body, dict) else {},
        old_definition=None,
    )
    defn = await pipeline_engine.create_definition(body)
    return web.json_response(defn, status=201)


