async def auth_login(request: web.Request) -> web.Response:
    """POST /auth — validate token from login form, set cookie."""
    remote_ip = _auth_context.client_ip(
        request, _proxy_trust_config()
    ) or "unknown"

    if _is_rate_limited(remote_ip):
        return web.Response(
            status=429, content_type="text/html",
            text=_LOGIN_RATE_LIMITED_HTML.format(seconds=_AUTH_LOCKOUT_SECS),
        )

    data = await request.post()
    token = data.get("token", "").strip()

    if not _tokens_equal(token, AUTH_TOKEN):
        _record_auth_failure(remote_ip)
        attempts = len([t for t in _auth_failures.get(remote_ip, [])
                        if _auth_time.time() - t < _AUTH_WINDOW_SECS])
        remaining = _AUTH_MAX_ATTEMPTS - attempts
        error_msg = (
            f'<p style="color:#f87171;font-size:13px;margin:0 0 16px">'
            f'Invalid token ({remaining} attempt{"s" if remaining != 1 else ""} remaining)</p>'
        )
        return web.Response(
            status=401, content_type="text/html",
            text=_LOGIN_HTML.format(error=error_msg),
        )

    resp = web.HTTPFound("/")
    # For any remote caller (LAN or proxy) the legacy ive_token cookie is
    # intentionally ignored by resolve_auth (so revoking a joiner_session
    # can't be circumvented by a bookmarked token). Mint a per-row
    # joiner_session instead so the form login still works AND remains
    # revocable from the Sharing panel.
    if not _auth_context._is_real_localhost(request, _proxy_trust_config()):
        try:
            cookie_value, sess = await _joiner_sessions.create_session(
                mode="full",
                actor_kind="owner_legacy",
                ttl_seconds=86400,
                label="Owner (form login)",
                last_ip=remote_ip,
                last_user_agent=request.headers.get("User-Agent"),
            )
            resp.set_cookie(
                _auth_context.SESSION_COOKIE,
                cookie_value,
                **_make_cookie_params(request),
            )
            resp.del_cookie(_auth_context.LEGACY_COOKIE)
            _fire_and_forget(bus.emit(
                CommanderEvent.SESSION_MINTED,
                {
                    "session_id": sess.id,
                    "actor_kind": sess.actor_kind,
                    "mode": sess.mode,
                    "via": "tunnel_form_login",
                },
                source="commander",
            ))
            return resp
        except Exception:
            logger.exception("Failed to mint joiner session for tunnel form login; falling back to legacy cookie")
    resp.set_cookie("ive_token", AUTH_TOKEN, **_make_cookie_params(request))
    return resp


import joiner_sessions as _joiner_sessions


def _exempt_path(request: web.Request) -> bool:
    """Paths reachable WITHOUT a valid AuthContext (login, redeem, PWA, device pairing)."""
    p = request.path
    # No blanket prefix exemptions: core registers no /connectors/ routes, and
    # an extension that adds a self-authenticating route must not inherit an
    # auth bypass for everything under a shared prefix.
    if p.startswith("/api/hooks/"):
        if _auth_context._is_real_localhost(request, _proxy_trust_config()):
            return True
    if p == "/auth" and request.method == "POST":
        return True
    if p == "/api/invite/redeem" and request.method == "POST":
        return True
    if p == "/join":
        return True
    if p == "/ready":
        return True
    if p in ("/sw.js", "/manifest.webmanifest", "/favicon.svg"):
        return True
    # Phone pairing: the connect page and its script carry no data; the
    # one-time code posted to pair/complete IS the auth (rate-limited,
    # single use, burned after a few wrong guesses).
    if p in ("/pair", "/pair.js") and request.method == "GET":
        return True
    if p == "/api/phone/pair/complete" and request.method == "POST":
        return True
    return False


async def _requested_workspace_ids(request: web.Request) -> set[str]:
    """Collect explicit workspace targets before a scoped request is routed."""
    workspace_ids: set[str] = set()
    if request.path.startswith("/api/workspaces/"):
        path_workspace_id = (
            request.match_info.get("workspace_id")
            or request.match_info.get("id")
        )
        if path_workspace_id:
            workspace_ids.add(str(path_workspace_id).strip())
    for key in ("workspace_id", "workspace", "context_workspace_id"):
        value = request.query.get(key)
        if value:
            workspace_ids.add(str(value).strip())
    header_workspace_id = request.headers.get("X-IVE-Workspace-Id")
    if header_workspace_id:
        workspace_ids.add(header_workspace_id.strip())
    if (
        request.method in {"POST", "PUT", "PATCH", "DELETE"}
        and request.content_type == "application/json"
        and request.can_read_body
    ):
        try:
            body = await request.json()
        except (json.JSONDecodeError, ValueError):
            body = None
        if isinstance(body, dict):
            for key in ("workspace_id", "context_workspace_id"):
                value = body.get(key)
                if value:
                    workspace_ids.add(str(value).strip())
    workspace_ids.discard("")
    return workspace_ids


async def _resource_workspace_id(request: web.Request) -> str | None:
    """Resolve workspace ownership for ID-addressed session/task routes."""
    resource_id = request.match_info.get("id")
    if not resource_id:
        return None
    table = None
    if request.path.startswith("/api/sessions/"):
        table = "sessions"
    elif request.path.startswith("/api/tasks/"):
        table = "tasks"
    if table is None:
        return None
    db = await get_db()
    try:
        cur = await db.execute(
            f"SELECT workspace_id FROM {table} WHERE id = ?", (resource_id,)
        )
        row = await cur.fetchone()
        return row["workspace_id"] if row else None
    finally:
        await db.close()


@web.middleware
async def token_auth_middleware(request: web.Request, handler):
    if not _origin_allowed(request):
        return web.json_response(
            {"error": "Cross-origin request refused."}, status=403,
        )
    if not AUTH_TOKEN:
        # Authentication configuration is a deployment prerequisite.  Never
        # synthesize an owner when it is absent: doing so turns every owner/admin
        # route into a public endpoint on non-loopback binds.
        if _exempt_path(request):
            return await handler(request)
        return web.json_response(
            {"error": "Authentication is not configured."}, status=503,
        )

    if _exempt_path(request):
        return await handler(request)

    # Behind cloudflared every socket peer is 127.0.0.1; key the failure
    # limiter on the real client so one stranger can't lock out everyone.
    remote_ip = _auth_context.client_ip(request, _proxy_trust_config()) or "unknown"

    from desktop_security import desktop_proxy_config
    ctx = await _auth_context.resolve_auth(
        request,
        auth_token=AUTH_TOKEN,
        proxy_config=desktop_proxy_config(request, _proxy_trust_config()),
    )
    # The failure limiter throttles guessing, not working credentials: a
    # paired phone behind the same NAT/tunnel as a scanner keeps working.
    if ctx is None and _is_rate_limited(remote_ip):
        if request.headers.get("Accept", "").startswith("text/html"):
            return _connect_page(status=429)
        return web.json_response(
            {"error": "Too many auth attempts. Try again later."},
            status=429,
        )
    if ctx is None:
        # Token-link exchange for a FIRST visit: in tunnel mode resolve_auth
        # (correctly) refuses the raw ?token= as a blanket grant — but the
        # whole point of a pairing link/QR (gi-hub remote panel, SharingPanel)
        # is that a fresh visitor presents ?token= and gets a REVOCABLE
        # joiner session minted. Without this branch the exchange below is
        # unreachable for exactly the visitor it exists for (first visit →
        # 401 login form instead of landing signed in).
        if _is_token_link(request):
            return await _token_link_redirect(request, remote_ip)
        _record_auth_failure(remote_ip)
        if request.headers.get("Accept", "").startswith("text/html"):
            return _connect_page(status=401)
        return web.json_response({"error": "Unauthorized"}, status=401)

    request["auth"] = ctx

    if ctx.actor_kind == "owner_device":
        blocked = _phone_lock_response(request, ctx)
        if blocked is not None:
            return blocked

    if _is_token_link(request):
        return await _token_link_redirect(request, remote_ip)

    if not ctx.is_owner:
        for workspace_id in await _requested_workspace_ids(request):
            if not _workspace_visible_to_auth(workspace_id, ctx):
                return web.json_response(
                    {"error": "workspace not found"}, status=404
                )
        resource_workspace_id = await _resource_workspace_id(request)
        if resource_workspace_id and not _workspace_visible_to_auth(
            resource_workspace_id, ctx
        ):
            return web.json_response({"error": "not found"}, status=404)

    return await handler(request)


def _is_token_link(request: web.Request) -> bool:
    """A GET on a page path carrying a valid ?token= — the pairing-link shape."""
    return bool(
        request.query.get("token")
        and request.method == "GET"
        and not request.path.startswith(("/api/", "/ws", "/preview/"))
        and _tokens_equal(request.query.get("token"), AUTH_TOKEN)
    )


async def _token_link_redirect(request: web.Request, remote_ip: str) -> web.StreamResponse:
    """Exchange a valid token link for auth + a clean-URL redirect.

    In external-proxy mode, mint a per-row joiner_session so the visitor shows
    up in /api/sessions/auth and can be revoked individually. Locally
    we keep the legacy cookie path (single-user dev convenience)."""
    clean_query = {k: v for k, v in request.query.items() if k != "token"}
    clean_url = request.url.with_query(clean_query)
    # Behind cloudflared TLS terminates at the edge, so request.url says http;
    # redirecting a phone to http:// would strand it (Secure cookie unsent,
    # mixed-content WS). Honor the edge's forwarded scheme.
    xf_proto = _auth_context.forwarded_value(
        request, _proxy_trust_config(), "X-Forwarded-Proto"
    )
    if xf_proto in ("http", "https"):
        clean_url = clean_url.with_scheme(xf_proto)
    resp = web.HTTPFound(str(clean_url))
    if not _auth_context._is_real_localhost(request, _proxy_trust_config()):
        try:
            cookie_value, sess = await _joiner_sessions.create_session(
                mode="full",
                actor_kind="owner_legacy",
                ttl_seconds=86400,
                label="Token link visitor",
                last_ip=remote_ip,
                last_user_agent=request.headers.get("User-Agent"),
            )
            resp.set_cookie(
                _auth_context.SESSION_COOKIE,
                cookie_value,
                **_make_cookie_params(request),
            )
            resp.del_cookie(_auth_context.LEGACY_COOKIE)
            _fire_and_forget(bus.emit(
                CommanderEvent.SESSION_MINTED,
                {
                    "session_id": sess.id,
                    "actor_kind": sess.actor_kind,
                    "mode": sess.mode,
                    "via": "tunnel_token_link",
                },
                source="commander",
            ))
            return resp
        except Exception:
            logger.exception("Failed to mint joiner session for tunnel token link; falling back to legacy cookie")
    resp.set_cookie("ive_token", AUTH_TOKEN, **_make_cookie_params(request))
    return resp


def get_auth(request: web.Request) -> _auth_context.AuthContext:
    """Route handler accessor for the middleware-attached AuthContext.
    Synthesizes a localhost/full context if missing (hook routes, tests)."""
    ctx = request.get("auth")
    if ctx is None:
        ctx = _auth_context.AuthContext(
            actor_kind="localhost", actor_id=None, mode="full",
            brief_subscope=None, label=None, expires_at=None,
        )
    return ctx


# ─── Workspace-scoped invite routes ─────────────────────────────────────

import invites as _invites


def _invite_to_listing(row: dict) -> dict:
    """Strip the token_hash and return display-safe fields only."""
    if not row:
        return {}
    return {
        "id": row.get("id"),
        "workspace_id": row.get("workspace_id"),
        "encoded_speakable": row.get("encoded_speakable"),
        "encoded_compact": row.get("encoded_compact"),
        "mode": row.get("mode"),
        "brief_subscope": row.get("brief_subscope"),
        "ttl_seconds": row.get("ttl_seconds"),
        "label": row.get("label"),
        "redemption_attempts": row.get("redemption_attempts"),
        "redeemed_at": row.get("redeemed_at"),
        "redeemed_by_session_id": row.get("redeemed_by_session_id"),
        "burned_at": row.get("burned_at"),
        "expires_at": row.get("expires_at"),
        "created_at": row.get("created_at"),
        "created_by": row.get("created_by"),
    }


async def create_invite_handler(request: web.Request) -> web.Response:
    body = await request.json()
    workspace_id = (body.get("workspace_id") or "").strip()
    mode = (body.get("mode") or "").strip().lower()
    ttl_seconds = body.get("ttl_seconds")
    label = (body.get("label") or "").strip() or None
    brief_subscope = body.get("brief_subscope")
    if isinstance(brief_subscope, str):
        brief_subscope = brief_subscope.strip().lower() or None

    try:
        ttl_seconds = int(ttl_seconds)
    except (TypeError, ValueError):
        return web.json_response({"error": "ttl_seconds must be an integer"}, status=400)

    try:
        created = await _invites.create_invite(
            workspace_id=workspace_id,
            mode=mode,
            ttl_seconds=ttl_seconds,
            label=label,
            brief_subscope=brief_subscope,
            created_by="owner",
        )
    except ValueError as e:
        return web.json_response({"error": str(e)}, status=400)

    await bus.emit(
        CommanderEvent.INVITE_CREATED,
        {
            "invite_id": created.id,
            "workspace_id": created.workspace_id,
            "mode": created.mode,
            "brief_subscope": created.brief_subscope,
            "ttl_seconds": created.ttl_seconds,
            "label": created.label,
            "expires_at": created.expires_at,
        },
        source="commander",
    )

    return web.json_response({
        "id": created.id,
        "workspace_id": created.workspace_id,
        "mode": created.mode,
        "brief_subscope": created.brief_subscope,
        "ttl_seconds": created.ttl_seconds,
        "label": created.label,
        "expires_at": created.expires_at,
        # Three projections — the secret is returned exactly once.
        "secret_speakable": created.encoded_speakable,
        "secret_compact": created.encoded_compact,
        "secret_qr": created.encoded_qr_secret,
    })


async def list_invites_handler(request: web.Request) -> web.Response:
    rows = await _invites.list_invites()
    return web.json_response({"invites": [_invite_to_listing(r) for r in rows]})


async def revoke_invite_handler(request: web.Request) -> web.Response:
    invite_id = request.match_info.get("id", "").strip()
    if not invite_id:
        return web.json_response({"error": "missing id"}, status=400)
    burned = await _invites.revoke_invite(invite_id)
    if burned:
        await bus.emit(
            CommanderEvent.INVITE_BURNED,
            {"invite_id": invite_id, "reason": "owner_revoked"},
            source="commander",
        )
    return web.json_response({"ok": True, "burned": bool(burned)})


async def redeem_invite_handler(request: web.Request) -> web.Response:
    """Unauthenticated. Rate-limited via middleware."""
    try:
        body = await request.json()
    except (json.JSONDecodeError, ValueError):
        body = {}
    token_input = (body.get("token") or "").strip()
    if not token_input:
        return web.json_response({"error": "missing token"}, status=400)

    peername = request.transport.get_extra_info("peername")
    remote_ip = peername[0] if peername else "unknown"

    try:
        result = await _invites.redeem_invite(token_input)
    except _invites.InviteRedeemError as e:
        await bus.emit(
            CommanderEvent.INVITE_REDEEM_FAILED,
            {"reason": e.code, "remote_ip": remote_ip},
            source="commander",
        )
        # Map to HTTP. Unknown tokens hide existence; unusable credentials are gone.
        status = 404 if e.code in ("not_found", "invalid_token") else 410
        return web.json_response({"error": e.code, "message": str(e)}, status=status)

    await bus.emit(
        CommanderEvent.INVITE_REDEEMED,
        {
            "invite_id": result.invite_id,
            "workspace_id": result.workspace_id,
            "mode": result.mode,
            "brief_subscope": result.brief_subscope,
            "ttl_seconds": result.ttl_seconds,
            "label": result.label,
            "remote_ip": remote_ip,
        },
        source="commander",
    )

    # Mint a per-row joiner session and opaque cookie. Only its hash persists;
    # invite-backed expiry remains absolute at the owner-selected TTL.
    user_agent = request.headers.get("User-Agent")
    cookie_value, sess = await _joiner_sessions.create_session(
        mode=result.mode,
        actor_kind="joiner_session",
        ttl_seconds=result.ttl_seconds,
        label=result.label,
        brief_subscope=result.brief_subscope,
        invite_id=result.invite_id,
        workspace_id=result.workspace_id,
        last_ip=remote_ip,
        last_user_agent=user_agent,
    )

    payload = {
        "ok": True,
        "mode": result.mode,
        "workspace_id": result.workspace_id,
        "brief_subscope": result.brief_subscope,
        "ttl_seconds": result.ttl_seconds,
        "label": result.label,
        "session_id": sess.id,
        "expires_at": sess.expires_at,
    }

    await bus.emit(
        CommanderEvent.SESSION_MINTED,
        {
            "session_id": sess.id,
            "actor_kind": sess.actor_kind,
            "mode": sess.mode,
            "invite_id": result.invite_id,
            "workspace_id": result.workspace_id,
        },
        source="commander",
    )

    resp = web.json_response(payload)
    resp.set_cookie(
        _auth_context.SESSION_COOKIE,
        cookie_value,
        **_make_cookie_params(
            request,
            max_age=result.ttl_seconds if result.ttl_seconds > 0 else None,
        ),
    )
    resp.del_cookie(_auth_context.LEGACY_COOKIE)
    return resp


