# ─── Runtime tunnel + multiplayer controls ──────────────────────────────
# Owner-only toggles for the cloudflared subprocess and the multiplayer
# preview-proxy mount. Boot-time CLI flags remain the source of truth at
# launch; these endpoints let the owner stop/start the tunnel and the
# multiplayer proxy without restarting the whole server.

_runtime_tunnel_url: str | None = None  # last known tunnel URL


async def runtime_status_handler(request: web.Request) -> web.Response:
    """GET /api/runtime/status — current tunnel + multiplayer state."""
    ctx = get_auth(request)
    if not ctx.is_owner:
        return web.json_response({"error": "owner only"}, status=403)
    proc_alive = bool(_tunnel_proc and _tunnel_proc.returncode is None)
    return web.json_response({
        "tunnel": {
            "enabled": _TUNNEL_MODE,
            "running": proc_alive,
            "url": _runtime_tunnel_url if proc_alive else None,
            # Surface the auth token so the runtime-controls UI can render
            # a QR that lands the visitor authenticated. Owner-only handler
            # so the token never leaks to a joiner.
            # Owner-at-the-Mac only: a paired phone or remote session must
            # not be able to copy the non-revocable master token.
            "token": (
                AUTH_TOKEN
                if proc_alive and AUTH_TOKEN and _is_local_owner(request, ctx)
                else None
            ),
        },
        "multiplayer": {
            "enabled": _MULTIPLAYER_MODE,
        },
        "online": {
            "count": len(ws_peers),
            "socket_count": len(ws_clients),
            "peers": [
                _runtime_peer_payload(cid, info)
                for cid, info in ws_peers.items()
            ],
        },
        "cloudflared_installed": bool(_find_cloudflared()),
    })


async def runtime_tunnel_start_handler(request: web.Request) -> web.Response:
    """POST /api/runtime/tunnel/start — launch the cloudflared subprocess.

    Mints a Cloudflare quick tunnel pointing at the local bind port. Sets
    _TUNNEL_MODE so the auth middleware stops blanket-trusting localhost
    (cloudflared connects as 127.0.0.1)."""
    global _TUNNEL_MODE, _runtime_tunnel_url, AUTH_TOKEN
    ctx = get_auth(request)
    if not ctx.is_owner:
        return web.json_response({"error": "owner only"}, status=403)
    if _tunnel_proc and _tunnel_proc.returncode is None:
        return web.json_response({
            "ok": True, "running": True, "url": _runtime_tunnel_url,
            "token": (AUTH_TOKEN or None) if _is_local_owner(request, ctx) else None,
            "message": "tunnel already running",
        })
    # Pre-flight: cloudflared must be installed (PATH-robust lookup).
    if not _find_cloudflared():
        return web.json_response(
            {
                "ok": False,
                "error": "cloudflared is not installed. Install with: brew install cloudflare/cloudflare/cloudflared",
            },
            status=500,
        )
    # Auto-generate an AUTH_TOKEN if none exists. Without one, flipping
    # _TUNNEL_MODE = True would leave the public URL completely open
    # (the auth middleware short-circuits to owner_legacy when no token
    # is configured). We mint one on first runtime tunnel-up so the
    # owner can ship invites instead of a bare URL.
    if not AUTH_TOKEN:
        AUTH_TOKEN = _generate_token()
        logger.info("Auto-generated AUTH_TOKEN for runtime tunnel")
    bind_port = _BIND_PORT or PORT
    # Engage tunnel mode BEFORE spawning so a request that races in
    # via cloudflared doesn't sneak past the localhost-trust path.
    _TUNNEL_MODE = True
    url = await _start_cloudflare_tunnel(bind_port)
    if not url:
        _TUNNEL_MODE = False
        return web.json_response(
            {
                "ok": False,
                "error": "cloudflared started but no tunnel URL was emitted within 60s. Check network access and try again.",
            },
            status=500,
        )
    _runtime_tunnel_url = url
    # Kick off a background `npm run build` if no dist exists. Visitors
    # will see the proxy-to-Vite path until the build lands; once dist is
    # written, the SPA fallback transparently switches to serving it.
    _fire_and_forget(_ensure_frontend_built())
    return web.json_response({
        "ok": True, "running": True, "url": url,
        "token": AUTH_TOKEN if _is_local_owner(request, ctx) else None,
    })


async def _ensure_frontend_built():
    """Run `npm run build` in frontend/ if frontend/dist/ is missing.
    No-op if a build is already underway or dist already exists."""
    global _frontend_build_proc
    try:
        from resource_path import project_root as _rp
        dist = _rp() / "frontend" / "dist"
        if dist.is_dir() and (dist / "index.html").is_file():
            return
        if _frontend_build_proc and _frontend_build_proc.returncode is None:
            return
        frontend_dir = _rp() / "frontend"
        if not (frontend_dir / "package.json").is_file():
            logger.warning("frontend/package.json missing — can't auto-build")
            return
        logger.info("Auto-building frontend for runtime tunnel (dist missing)")
        _frontend_build_proc = await asyncio.create_subprocess_exec(
            "npm", "run", "build",
            cwd=str(frontend_dir),
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.STDOUT,
        )
        out, _ = await _frontend_build_proc.communicate()
        rc = _frontend_build_proc.returncode
        if rc == 0:
            logger.info("Frontend build complete")
        else:
            logger.error("Frontend build failed (rc=%s):\n%s", rc, (out or b"").decode("utf-8", "replace")[-2000:])
    except Exception as e:
        logger.error("Frontend auto-build error: %s", e)


_frontend_build_proc = None


async def runtime_tunnel_stop_handler(request: web.Request) -> web.Response:
    """POST /api/runtime/tunnel/stop — terminate the cloudflared subprocess.

    If the stop request is coming through the tunnel itself, we can't
    kill cloudflared synchronously — the response would never reach the
    client (502 from the edge). Detach the kill so the response flushes
    cleanly first."""
    global _TUNNEL_MODE, _runtime_tunnel_url, _tunnel_proc
    ctx = get_auth(request)
    if not ctx.is_owner:
        return web.json_response({"error": "owner only"}, status=403)
    via_tunnel = _auth_context.is_forwarded_request(
        request, _proxy_trust_config()
    )
    proc = _tunnel_proc
    _tunnel_proc = None
    _runtime_tunnel_url = None
    _TUNNEL_MODE = False

    async def _kill_after_response():
        if via_tunnel:
            await asyncio.sleep(0.5)
        if not proc:
            return
        try:
            proc.terminate()
            await asyncio.wait_for(proc.wait(), timeout=3)
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass

    _fire_and_forget(_kill_after_response())
    return web.json_response({"ok": True, "running": False})




async def runtime_mode_handler(request: web.Request) -> web.Response:
    """POST /api/runtime/mode — body {mode: 'off' | 'local' | 'tunnel'}.

    Single atomic switch consolidating multiplayer + tunnel:
      - off:    multiplayer=False, tunnel=False
      - local:  multiplayer=True,  tunnel=False  (LAN preview proxy)
      - tunnel: multiplayer=True,  tunnel=True   (public via cloudflared)
    """
    global _MULTIPLAYER_MODE, _TUNNEL_MODE, AUTH_TOKEN, _runtime_tunnel_url, _tunnel_proc
    ctx = get_auth(request)
    if not ctx.is_owner:
        return web.json_response({"error": "owner only"}, status=403)
    try:
        body = await request.json()
    except (json.JSONDecodeError, ValueError):
        body = {}
    mode = (body.get("mode") or "").strip().lower()
    if mode not in ("off", "local", "tunnel"):
        return web.json_response(
            {"error": "mode must be one of: off, local, tunnel"}, status=400,
        )

    target_multiplayer = mode in ("local", "tunnel")
    target_tunnel = mode == "tunnel"

    # Tear down cloudflared when leaving tunnel mode.
    if not target_tunnel and _tunnel_proc and _tunnel_proc.returncode is None:
        proc = _tunnel_proc
        _tunnel_proc = None
        _runtime_tunnel_url = None
        async def _kill():
            try:
                proc.terminate()
                await asyncio.wait_for(proc.wait(), timeout=3)
            except Exception:
                try: proc.kill()
                except Exception: pass
        _fire_and_forget(_kill())

    _MULTIPLAYER_MODE = target_multiplayer
    _TUNNEL_MODE = target_tunnel

    if target_tunnel and not (_tunnel_proc and _tunnel_proc.returncode is None):
        if not _find_cloudflared():
            _TUNNEL_MODE = False
            return web.json_response(
                {
                    "ok": False,
                    "error": "cloudflared is not installed. Install with: brew install cloudflare/cloudflare/cloudflared",
                },
                status=500,
            )
        if not AUTH_TOKEN:
            AUTH_TOKEN = _generate_token()
            logger.info("Auto-generated AUTH_TOKEN for runtime tunnel")
        bind_port = _BIND_PORT or PORT
        url = await _start_cloudflare_tunnel(bind_port)
        if not url:
            _TUNNEL_MODE = False
            return web.json_response(
                {
                    "ok": False,
                    "error": "cloudflared started but no tunnel URL was emitted within 60s. Check network access and try again.",
                },
                status=500,
            )
        _runtime_tunnel_url = url
        _fire_and_forget(_ensure_frontend_built())

    proc_alive = _tunnel_proc is not None and _tunnel_proc.returncode is None
    return web.json_response({
        "ok": True,
        "mode": mode,
        "multiplayer": {"enabled": _MULTIPLAYER_MODE},
        "tunnel": {
            "running": proc_alive,
            "url": _runtime_tunnel_url if proc_alive else None,
            "token": (
                AUTH_TOKEN
                if proc_alive and AUTH_TOKEN and _is_local_owner(request, ctx)
                else None
            ),
        },
    })


async def runtime_multiplayer_toggle_handler(request: web.Request) -> web.Response:
    """POST /api/runtime/multiplayer — body {enabled: bool}.

    Flipping multiplayer at runtime only changes the soft gate that
    `_should_serve_preview` checks. The route is mounted at boot if
    EITHER tunnel or multiplayer was set; if neither was set at boot
    the preview proxy is not on the router and re-enabling here only
    flips the flag so the app advertises multiplayer features."""
    global _MULTIPLAYER_MODE
    ctx = get_auth(request)
    if not ctx.is_owner:
        return web.json_response({"error": "owner only"}, status=403)
    try:
        body = await request.json()
    except Exception:
        body = {}
    enabled = bool(body.get("enabled"))
    _MULTIPLAYER_MODE = enabled
    return web.json_response({"ok": True, "enabled": _MULTIPLAYER_MODE})


async def catchup_handler(request: web.Request) -> web.Response:
    """GET /api/catchup?since=&until=&workspace_id=&limit=&llm=&model=

    Returns a structured digest of events the caller missed. The `summary`
    field is an LLM-generated 2-4 sentence briefing by default; pass
    `?llm=false` to get the deterministic count summary. `summary_basic`
    always carries the deterministic fallback.
    """
    import catchup
    ctx = get_auth(request)
    since = request.query.get("since")
    until = request.query.get("until")
    workspace_id = request.query.get("workspace_id")
    try:
        limit = int(request.query.get("limit", "500"))
    except ValueError:
        limit = 500
    use_llm = request.query.get("llm", "true").lower() not in ("0", "false", "no")
    include_commits = request.query.get("commits", "true").lower() not in ("0", "false", "no")
    include_memory = request.query.get("memory", "true").lower() not in ("0", "false", "no")
    if "cli" in request.query:
        return web.json_response(
            {
                "error": "use one provider-qualified model id; the separate cli field was removed",
                "code": "legacy_model_shape",
            },
            status=400,
        )
    from model_providers import ModelProviderError
    try:
        digest = await catchup.build_digest(
            since_iso=since,
            until_iso=until,
            mode=ctx.mode,
            workspace_id=workspace_id,
            limit=limit,
            use_llm=use_llm,
            model_id=request.query.get("model"),
            include_commits=include_commits,
            include_memory=include_memory,
        )
    except ModelProviderError as exc:
        return web.json_response(
            {"error": str(exc), "code": exc.code, "field": "model"},
            status=400,
        )
    return web.json_response(digest)


async def catchup_chat_handler(request: web.Request) -> web.Response:
    """POST /api/catchup/chat — agentic, READ-ONLY chat about a briefing.

    The model can investigate the briefing's memory / events / git commits via read-only tools,
    then answer grounded in what it found. Body: {digest:{...} | summary:str,
    messages:[{role,content}], model?}. Returns {answer}.
    """
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid json"}, status=400)
    digest = body.get("digest")
    if not isinstance(digest, dict):
        digest = {"summary": (body.get("summary") or "").strip()}
    messages = body.get("messages") or []
    if not isinstance(messages, list) or not messages:
        return web.json_response({"error": "messages required"}, status=400)
    if not (digest.get("summary") or digest.get("events") or digest.get("memory_changes")):
        return web.json_response({"error": "digest or summary required"}, status=400)
    if "cli" in body:
        return web.json_response(
            {
                "error": "use one provider-qualified model id; the separate cli field was removed",
                "code": "legacy_model_shape",
            },
            status=400,
        )
    model_id = body.get("model")
    if not model_id:
        model_db = await get_db()
        try:
            model_cur = await model_db.execute(
                "SELECT value FROM app_settings WHERE key = 'catchup_model'"
            )
            model_row = await model_cur.fetchone()
            model_id = (
                model_row["value"] if model_row and model_row["value"]
                else "claude:haiku"
            )
        finally:
            await model_db.close()
    from llm_router import resolve_model
    from model_providers import ModelProviderError
    try:
        await resolve_model(model_id, required_capability="json")
    except ModelProviderError as exc:
        return web.json_response(
            {"error": str(exc), "code": exc.code, "field": "model"},
            status=400,
        )
    import catchup
    answer = await catchup.catchup_chat(
        digest, messages, model_id=model_id,
    )
    return web.json_response({"answer": answer or "(no response)"})


async def push_subscribe_handler(request: web.Request) -> web.Response:
    """POST /api/push/subscribe — register a Web Push endpoint."""
    import push
    ctx = get_auth(request)
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid json"}, status=400)
    endpoint = (body or {}).get("endpoint")
    keys = (body or {}).get("keys") or {}
    p256dh = keys.get("p256dh")
    auth = keys.get("auth")
    if not (endpoint and p256dh and auth):
        return web.json_response({"error": "endpoint+keys required"}, status=400)
    sub = await push.upsert_subscription(
        actor_kind=ctx.actor_kind,
        actor_id=ctx.actor_id,
        endpoint=endpoint,
        p256dh=p256dh,
        auth=auth,
        user_agent=request.headers.get("User-Agent"),
    )
    return web.json_response({"ok": True, "subscription": sub})


async def push_unsubscribe_handler(request: web.Request) -> web.Response:
    """POST /api/push/unsubscribe — drop a Web Push endpoint."""
    import push
    ctx = get_auth(request)
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid json"}, status=400)
    endpoint = (body or {}).get("endpoint", "").strip()
    if not endpoint:
        return web.json_response({"error": "endpoint required"}, status=400)
    removed = await push.remove_subscription(
        actor_kind=ctx.actor_kind,
        actor_id=ctx.actor_id,
        endpoint=endpoint,
    )
    return web.json_response({"ok": True, "removed": bool(removed)})


async def push_vapid_pubkey_handler(request: web.Request) -> web.Response:
    """GET /api/push/vapid-pubkey — public key for frontend subscribe()."""
    import push
    pk = push.get_public_key()
    return web.json_response({"public_key": pk, "configured": bool(pk)})


# ─── Phone access: pairing code → owner device, PIN lock ────────────────
# See backend/phone_access.py for the security model.

import phone_access as _phone_access
from phone_setup import PhoneSetup
from phone_availability import PhoneAvailability

_PHONE_SETUP = web.AppKey("phone_setup", PhoneSetup)
_PHONE_AVAILABILITY = web.AppKey("phone_availability", PhoneAvailability)

_BIND_HOST: str = HOST
_BIND_PORT: int | None = None


def _clean_public_url(value: str | None) -> str | None:
    """An operator-declared address for phones (Tailscale, named tunnel, proxy)."""
    value = (value or "").strip().rstrip("/")
    if not value:
        return None
    parts = urllib.parse.urlsplit(value)
    if parts.scheme not in ("http", "https") or not parts.netloc or parts.path or parts.query:
        raise ValueError(f"public URL must look like https://host[:port], got {value!r}")
    return value


_PUBLIC_URL: str | None = _clean_public_url(os.getenv("IVE_PUBLIC_URL"))

# Paths an owner_device may still reach while its PIN lock is engaged.
_PHONE_LOCK_EXEMPT = (
    "/api/phone/unlock", "/api/phone/status", "/api/whoami", "/api/auth/logout",
    "/pair.js", "/sw.js", "/manifest.webmanifest", "/favicon.svg",
)
# Changes to access itself need a PIN entered within the last few minutes.
_PHONE_SENSITIVE_PREFIXES = (
    "/api/invite/create", "/api/runtime/", "/api/phone/devices/",
    "/api/sessions/auth/",
)


def _is_local_owner(request: web.Request, ctx) -> bool:
    """True for the owner sitting at the Mac (not a phone, not via a proxy)."""
    if ctx is None:
        return False
    if ctx.actor_kind == "localhost":
        return True
    if ctx.actor_kind != "owner_legacy":
        return False
    for header in ("Cf-Connecting-Ip", "X-Forwarded-For", "Forwarded", "X-Real-Ip"):
        if request.headers.get(header):
            return False
    if _auth_context.is_forwarded_request(request, _proxy_trust_config()):
        return False
    return _auth_context._socket_peer_ip(request) in _auth_context._LOCALHOST_ADDRS


def _local_owner_only(request: web.Request):
    ctx = get_auth(request)
    if not _is_local_owner(request, ctx):
        return web.json_response(
            {"error": "Only possible on the Mac itself."}, status=403,
        )
    return None


def _phone_lock_response(request: web.Request, ctx) -> web.StreamResponse | None:
    """Enforce the PIN lock for a paired phone. None → let the request through."""
    lock = _phone_access.lock
    if not lock.pin_enabled():
        return None
    path = request.path
    if path in _PHONE_LOCK_EXEMPT or path.startswith("/assets/"):
        return None
    if lock.is_locked(ctx.actor_id):
        if request.headers.get("Upgrade", "").lower() == "websocket":
            return web.json_response({"error": "locked"}, status=423)
        if (
            request.method == "GET"
            and not path.startswith(("/api/", "/ws"))
            and "text/html" in request.headers.get("Accept", "")
        ):
            return _connect_page(status=423, mode="unlock")
        return web.json_response(
            {"error": "locked", "reason": "idle",
             "idle_minutes": lock.idle_seconds() // 60},
            status=423,
        )
    lock.touch(ctx.actor_id)
    if (
        request.method not in ("GET", "HEAD", "OPTIONS")
        and path.startswith(_PHONE_SENSITIVE_PREFIXES)
        and lock.needs_reauth(ctx.actor_id)
    ):
        return web.json_response(
            {"error": "reauth_required", "reason": "sensitive"}, status=423,
        )
    return None


async def _close_sockets_for_sessions(session_ids, reason: bytes) -> None:
    ids = set(session_ids or ())
    if not ids:
        return
    doomed = [w for w in list(ws_clients) if getattr(w, "_ive_actor_id", None) in ids]
    for w in doomed:
        try:
            await w.close(code=1008, message=reason)
        except Exception:
            pass


async def _revoke_phone_device(device_id: str, ctx) -> bool:
    revoked, session_ids = await _phone_access.revoke_device(device_id)
    await _close_sockets_for_sessions(session_ids, b"device revoked")
    if revoked:
        await bus.emit(
            CommanderEvent.DEVICE_UNPAIRED,
            {"device_id": device_id, "revoked_by": getattr(ctx, "actor_kind", None)},
            source="commander",
        )
    return bool(revoked)


def _phone_reachable_urls(request: web.Request) -> list[dict]:
    """URLs a phone can open: running tunnel first, then the LAN address."""
    urls: list[dict] = []
    desktop = bool(os.environ.get("IVE_DESKTOP_INSTANCE"))
    if _PUBLIC_URL and not desktop:
        urls.append({
            "kind": "public", "label": "Your address",
            "url": _PUBLIC_URL, "secure": _PUBLIC_URL.startswith("https://"),
        })
    proc_alive = bool(_tunnel_proc and _tunnel_proc.returncode is None)
    if proc_alive and _runtime_tunnel_url:
        urls.append({
            "kind": "tunnel", "label": "Internet (Cloudflare tunnel)",
            "url": _runtime_tunnel_url.rstrip("/"), "secure": True,
        })
    # The desktop boundary permits only the exact active, owned tunnel.
    # Inherited public/LAN settings must not produce unusable pairing links.
    if desktop:
        return urls
    port = _BIND_PORT or int(os.environ.get("PORT") or PORT)
    host = (_BIND_HOST or "").strip()
    loopback = host in ("127.0.0.1", "localhost", "::1", "")
    if not loopback:
        lan_hosts: list[str] = []
        if host in ("0.0.0.0", "::"):
            lan_hosts.extend(_get_lan_ips())
        else:
            lan_hosts.append(host)
        for ip in lan_hosts:
            urls.append({
                "kind": "lan", "label": "Same Wi-Fi (LAN)",
                "url": f"http://{ip}:{port}", "secure": False,
            })
    return urls


def _phone_bind_info() -> dict:
    host = (_BIND_HOST or "").strip()
    return {
        "host": host,
        "port": _BIND_PORT or int(os.environ.get("PORT") or PORT),
        "lan": host not in ("127.0.0.1", "localhost", "::1", ""),
    }


def _apns_configured() -> bool:
    try:
        import apns
        return apns.load_config() is not None
    except Exception:
        return False


async def phone_status_handler(request: web.Request) -> web.Response:
    """GET /api/phone/status — what the Settings screen / phone needs to know."""
    ctx = get_auth(request)
    lock = _phone_access.lock
    is_device = ctx.actor_kind == "owner_device"
    payload = {
        "actor_kind": ctx.actor_kind,
        "is_local_owner": _is_local_owner(request, ctx),
        "is_device": is_device,
        "device_id": ctx.device_id if is_device else None,
        "pin_enabled": lock.pin_enabled(),
        "idle_minutes": lock.idle_seconds() // 60,
        "locked": lock.is_locked(ctx.actor_id) if is_device else False,
        "pin_min_length": _phone_access.PIN_MIN_LEN,
    }
    if ctx.is_owner:
        import push
        active = _phone_access.codes.active()
        payload.update({
            "bind": _phone_bind_info(),
            "desktop": bool(os.environ.get("IVE_DESKTOP_INSTANCE")),
            "setup": request.app[_PHONE_SETUP].status(desktop=bool(os.environ.get("IVE_DESKTOP_INSTANCE"))),
            "availability": await request.app[_PHONE_AVAILABILITY].status(),
            "tunnel": {
                "running": bool(_tunnel_proc and _tunnel_proc.returncode is None),
                "url": _runtime_tunnel_url if (_tunnel_proc and _tunnel_proc.returncode is None) else None,
                "cloudflared_installed": bool(_find_cloudflared()),
            },
            "urls": _phone_reachable_urls(request),
            "pairing_active": bool(active),
            "push_configured": bool(push.get_public_key()),
            "apns_configured": _apns_configured(),
        })
    return web.json_response(payload)


async def phone_setup_handler(request: web.Request) -> web.Response:
    denied = _local_owner_only(request)
    if denied is not None:
        return denied
    try:
        body = await request.json()
        setup = request.app[_PHONE_SETUP]
        previous = setup.read()
        accepted = setup.accept(body)
    except (ValueError, TypeError):
        return web.json_response({"error": "Review and explicitly accept the iPhone control and Mac availability choices."}, status=400)
    restricted = (previous.get("closed_lid") and not accepted["closed_lid"]
                  or previous.get("allow_battery") and not accepted["allow_battery"])
    if restricted:
        # Permission withdrawal must take effect even if the UI closes or its
        # subsequent tunnel request fails. The daemon independently retries a
        # failed restore and expires any lease whose heartbeat stops.
        state = await request.app[_PHONE_AVAILABILITY].stop_phone()
        if state["state"] in {"active", "restoring", "restore_failed"}:
            return web.json_response({"error": "Your new choices were saved, but normal Mac sleep has not yet been verified. Keep the lid open and check availability status.", "setup": setup.status(desktop=bool(os.environ.get("IVE_DESKTOP_INSTANCE"))), "availability": state}, status=409)
    return web.json_response(setup.status(desktop=bool(os.environ.get("IVE_DESKTOP_INSTANCE"))))


async def phone_availability_handler(request: web.Request) -> web.Response:
    # A phone can use its sessions, but cannot grant itself new OS permissions.
    denied = _local_owner_only(request)
    if denied is not None:
        return denied
    controller = request.app[_PHONE_AVAILABILITY]
    action = request.match_info["action"]
    try:
        if action == "start":
            consent = request.app[_PHONE_SETUP].read()
            if not consent.get("closed_lid"):
                return web.json_response({"error": "Review and enable Mac availability in iPhone setup first."}, status=409)
            result = await controller.start(allow_battery=consent.get("allow_battery", False))
        elif action == "stop":
            result = await controller.stop()
        elif action == "approval":
            if not request.app[_PHONE_SETUP].read().get("closed_lid"):
                return web.json_response({"error": "Review Mac availability in iPhone setup first."}, status=409)
            result = await controller.open_approval()
        else:
            return web.json_response({"error": "Unknown availability action."}, status=404)
        return web.json_response(result)
    except (ValueError, RuntimeError) as exc:
        return web.json_response({"error": str(exc)}, status=409)
    except Exception:
        logger.exception("Phone availability operation failed")
        return web.json_response({"error": "Mac availability could not be updated. Check macOS approval and try again."}, status=503)


async def mac_power_handler(request: web.Request) -> web.Response:
    """One shared, local-owner-only power lease; independent of phone access."""
    denied = _local_owner_only(request)
    if denied is not None:
        return denied
    controller = request.app[_PHONE_AVAILABILITY]
    action = request.match_info.get("action", "status")
    try:
        if action == "status" and request.method == "GET":
            return web.json_response(await controller.status())
        if action == "start":
            body = await request.json()
            if not isinstance(body, dict) or set(body) != {"allow_battery", "duration_seconds", "lid_low_power", "pause_apps"}:
                raise ValueError("Choose the timer, battery use and lid actions before starting.")
            result = await controller.start(purpose="agent", **body)
        elif action == "stop":
            result = await controller.stop()
        elif action == "approval":
            result = await controller.open_approval()
        else:
            return web.json_response({"error": "Unknown Mac power action."}, status=404)
        return web.json_response(result)
    except ValueError as exc:
        return web.json_response({"error": str(exc)}, status=400)
    except RuntimeError as exc:
        return web.json_response({"error": str(exc)}, status=409)
    except Exception:
        logger.exception("Mac power operation failed")
        return web.json_response({"error": "Could not verify Mac power status. Check status before starting again."}, status=503)


async def _broadcast_to_owners(event: dict) -> None:
    """Send an instance-level event only to owner-equivalent WebSocket clients."""
    data = json.dumps(event)
    for ws in list(ws_clients):
        ctx = getattr(ws, "_ive_auth_ctx", None)
        if not bool(getattr(ctx, "is_owner", False)):
            continue
        try:
            await ws.send_str(data)
        except (ConnectionResetError, ConnectionError, RuntimeError):
            ws_clients.discard(ws)


async def phone_pair_start_handler(request: web.Request) -> web.Response:
    """POST /api/phone/pair/start — Mac-only. Mint a one-time pairing code."""
    denied = _local_owner_only(request)
    if denied is not None:
        return denied
    if request.app[_PHONE_SETUP].status(desktop=bool(os.environ.get("IVE_DESKTOP_INSTANCE")))["required"]:
        return web.json_response({"error": "Complete the iPhone setup on this Mac before creating a pairing code.", "code": "phone_setup_required"}, status=409)
    code, expires = _phone_access.codes.create()
    urls = _phone_reachable_urls(request)
    for entry in urls:
        # Fragment, not query: the code never reaches server/proxy logs or
        # the Referer header; /pair.js reads it and POSTs it.
        entry["pair_url"] = f"{entry['url']}/pair#{code}"
    return web.json_response({
        "code": code,
        "code_display": _phone_access.display_code(code),
        "expires_at": _phone_access.iso_from_epoch(expires),
        "ttl_seconds": _phone_access.PAIR_CODE_TTL_SECONDS,
        "urls": urls,
        "bind": _phone_bind_info(),
    })


async def phone_pair_cancel_handler(request: web.Request) -> web.Response:
    denied = _local_owner_only(request)
    if denied is not None:
        return denied
    _phone_access.codes.cancel()
    return web.json_response({"ok": True})


async def phone_pair_complete_handler(request: web.Request) -> web.Response:
    """POST /api/phone/pair/complete — unauth; the one-time code is the auth."""
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid json"}, status=400)
    if not isinstance(body, dict):
        return web.json_response({"error": "invalid json"}, status=400)
    remote_ip = _auth_context.client_ip(request, _proxy_trust_config()) or "unknown"
    user_agent = request.headers.get("User-Agent")
    result = await _phone_access.complete_pairing(
        code=str(body.get("code") or ""),
        label=str(body.get("label") or ""),
        user_agent=user_agent,
        remote_ip=remote_ip,
    )
    if result is None:
        _record_auth_failure(remote_ip)
        await bus.emit(
            CommanderEvent.INVITE_REDEEM_FAILED,
            {"reason": "phone_pair_failed", "remote_ip": remote_ip},
            source="commander",
        )
        return web.json_response(
            {"error": "invalid_code",
             "message": "Code is wrong, used or expired. Create a new one on the Mac."},
            status=401,
        )
    cookie_value, device, sess = result
    await bus.emit(
        CommanderEvent.DEVICE_PAIRED,
        {"device_id": device["id"], "label": device["label"],
         "session_id": sess.id, "remote_ip": remote_ip, "via": "pairing_code"},
        source="commander",
    )
    try:
        # Owner-only: the device name must not reach invited joiners, and the
        # event has no session/workspace that broadcast() could scope by.
        await _broadcast_to_owners({"type": "phone_paired", "device_id": device["id"], "label": device["label"]})
    except Exception:
        pass
    resp = web.json_response({
        "ok": True,
        "device": {"id": device["id"], "label": device["label"]},
        "expires_at": sess.expires_at,
    })
    resp.set_cookie(
        _auth_context.SESSION_COOKIE, cookie_value,
        **_make_cookie_params(request, max_age=_phone_access.DEVICE_COOKIE_MAX_AGE),
    )
    resp.del_cookie(_auth_context.LEGACY_COOKIE)
    return resp


async def phone_devices_handler(request: web.Request) -> web.Response:
    ctx = get_auth(request)
    if not ctx.is_owner:
        return web.json_response({"error": "owner only"}, status=403)
    rows = await _phone_access.list_devices()
    return web.json_response({
        "devices": rows,
        "current_device_id": ctx.device_id if ctx.actor_kind == "owner_device" else None,
    })


async def phone_device_revoke_handler(request: web.Request) -> web.Response:
    ctx = get_auth(request)
    if not ctx.is_owner:
        return web.json_response({"error": "owner only"}, status=403)
    device_id = (request.match_info.get("id") or "").strip()
    if not device_id:
        return web.json_response({"error": "missing id"}, status=400)
    revoked = await _revoke_phone_device(device_id, ctx)
    resp = web.json_response({"ok": True, "revoked": revoked})
    if ctx.actor_kind == "owner_device" and ctx.device_id == device_id:
        resp.del_cookie(_auth_context.SESSION_COOKIE)
    return resp


async def phone_pin_set_handler(request: web.Request) -> web.Response:
    """POST /api/phone/pin {pin, idle_minutes} — Mac-only."""
    denied = _local_owner_only(request)
    if denied is not None:
        return denied
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid json"}, status=400)
    try:
        _phone_access.lock.set_pin(
            str((body or {}).get("pin") or ""),
            idle_minutes=(body or {}).get("idle_minutes"),
        )
    except (TypeError, ValueError) as e:
        return web.json_response({"error": str(e)}, status=400)
    return web.json_response({"ok": True, **_phone_access.lock.state(None)})


async def phone_pin_clear_handler(request: web.Request) -> web.Response:
    denied = _local_owner_only(request)
    if denied is not None:
        return denied
    _phone_access.lock.clear_pin()
    return web.json_response({"ok": True, **_phone_access.lock.state(None)})


async def phone_unlock_handler(request: web.Request) -> web.Response:
    """POST /api/phone/unlock {pin} — paired phone re-authenticates."""
    ctx = get_auth(request)
    if ctx.actor_kind != "owner_device" or not ctx.actor_id:
        return web.json_response({"error": "not a paired device"}, status=400)
    lock = _phone_access.lock
    if not lock.pin_enabled():
        lock.mark_unlocked(ctx.actor_id)
        return web.json_response({"ok": True, "locked": False})
    try:
        body = await request.json()
    except Exception:
        body = {}
    if lock.check_pin(str((body or {}).get("pin") or "")):
        lock.mark_unlocked(ctx.actor_id)
        return web.json_response({"ok": True, "locked": False})
    left = lock.register_failure(ctx.actor_id)
    if left <= 0:
        if ctx.device_id:
            await _revoke_phone_device(ctx.device_id, ctx)
        else:
            await _joiner_sessions.revoke(ctx.actor_id)
        resp = web.json_response(
            {"error": "revoked", "message": "Too many wrong PINs. This phone was disconnected; pair it again on the Mac."},
            status=401,
        )
        resp.del_cookie(_auth_context.SESSION_COOKIE)
        return resp
    return web.json_response(
        {"error": "wrong_pin", "attempts_left": left}, status=401,
    )


async def phone_lock_handler(request: web.Request) -> web.Response:
    ctx = get_auth(request)
    if ctx.actor_kind != "owner_device" or not ctx.actor_id:
        return web.json_response({"error": "not a paired device"}, status=400)
    _phone_access.lock.lock_now(ctx.actor_id)
    return web.json_response({"ok": True, "locked": _phone_access.lock.is_locked(ctx.actor_id)})


# ─── Native push (APNs) for the iPhone app ──────────────────────────────
# See backend/apns.py. The .p8 key and the JWT never leave this process.


async def phone_apns_token_handler(request: web.Request) -> web.Response:
    """POST /api/phone/apns-token {token, environment, bundle_id?, device?}

    Only a paired phone (owner_device with a device row) may register; the
    token is bound to that device and removed when the device is revoked.
    DELETE drops this phone's token.
    """
    import apns
    ctx = get_auth(request)
    if ctx.actor_kind != "owner_device" or not ctx.device_id:
        return web.json_response({"error": "only a paired phone can register for push"}, status=403)
    if request.method == "DELETE":
        removed = apns.remove_token(ctx.device_id)
        return web.json_response({"ok": True, "removed": removed})
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid json"}, status=400)
    if not isinstance(body, dict):
        return web.json_response({"error": "invalid json"}, status=400)
    try:
        entry = apns.register_token(
            ctx.device_id, str(body.get("token") or ""), str(body.get("environment") or ""),
            bundle_id=str(body.get("bundle_id") or "") or None,
            model=str(body.get("device") or "") or None,
        )
    except apns.ApnsConfigError as e:
        return web.json_response({"error": str(e)}, status=400)
    return web.json_response({
        "ok": True,
        "environment": entry["environment"],
        "apns_configured": apns.load_config() is not None,
    })


async def phone_apns_status_handler(request: web.Request) -> web.Response:
    """GET /api/phone/apns — owner: config status (never the key) + per-device state."""
    import apns
    ctx = get_auth(request)
    if not ctx.is_owner:
        return web.json_response({"error": "owner only"}, status=403)
    rows = await _phone_access.list_devices()
    return web.json_response({
        **apns.public_status(),
        "can_edit": _is_local_owner(request, ctx),
        "devices": [{"device_id": d["id"], "label": d["label"], "apns": apns.device_status(d["id"])} for d in rows],
    })


async def phone_apns_config_handler(request: web.Request) -> web.Response:
    """POST /api/phone/apns {key_p8?, key_id, team_id, bundle_id} — Mac-only.

    DELETE removes the key. key_p8 is the text of the AuthKey_XXXX.p8 file;
    omit it to change only the ids.
    """
    import apns
    denied = _local_owner_only(request)
    if denied is not None:
        return denied
    if request.method == "DELETE":
        apns.clear_config()
        return web.json_response({"ok": True, **apns.public_status()})
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid json"}, status=400)
    if not isinstance(body, dict):
        return web.json_response({"error": "invalid json"}, status=400)
    key_p8 = body.get("key_p8")
    try:
        status = apns.save_config(
            key_pem=str(key_p8) if key_p8 else None,
            key_id=str(body.get("key_id") or ""),
            team_id=str(body.get("team_id") or ""),
            bundle_id=str(body.get("bundle_id") or ""),
        )
    except apns.ApnsConfigError as e:
        return web.json_response({"error": str(e)}, status=400)
    return web.json_response({"ok": True, **status})


async def phone_apns_test_handler(request: web.Request) -> web.Response:
    """POST /api/phone/apns/test {device_id?} — owner: send a test notification."""
    import apns
    ctx = get_auth(request)
    if not ctx.is_owner:
        return web.json_response({"error": "owner only"}, status=403)
    try:
        body = await request.json()
    except Exception:
        body = {}
    device_id = str((body or {}).get("device_id") or "").strip() or None
    if apns.load_config() is None:
        return web.json_response({"error": "Add the APNs key first."}, status=400)
    result = await apns.send_to_devices(
        title="IVE", body="Test notification from your Mac. Push works.",
        path="/", tag="ive-test",
        device_ids={device_id} if device_id else None,
    )
    if not result["results"]:
        return web.json_response(
            {"error": "No paired iPhone app has registered for push yet. Open the IVE app on the phone once."},
            status=400,
        )
    return web.json_response({"ok": result["sent"] > 0, **result})


_CONNECT_HTML = """<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-title" content="IVE">
<meta name="theme-color" content="#0a0a0a">
<link rel="manifest" href="/manifest.webmanifest">
<link rel="icon" href="/favicon.svg">
<title>IVE · Connect</title>
<style>
:root{color-scheme:dark}
*{box-sizing:border-box}
body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;
font-family:system-ui,-apple-system,sans-serif;background:#0a0a0a;color:#e5e5e5;padding:24px 16px}
main{width:100%;max-width:340px}
h1{margin:0 0 4px;font-size:22px;color:#22d3ee}
p{margin:0;font-size:14px;line-height:1.5;color:#a3a3a3}
.sub{margin-bottom:24px}
form{display:flex;flex-direction:column;gap:10px;margin-top:8px}
label{font-size:13px;color:#d4d4d4}
input{background:#141414;border:1px solid #333;border-radius:10px;padding:13px 14px;color:#f5f5f5;
font-size:20px;letter-spacing:.12em;text-align:center;font-family:ui-monospace,SFMono-Regular,monospace;outline:none}
input:focus{border-color:#22d3ee}
button{background:#22d3ee;color:#0a0a0a;border:0;border-radius:10px;padding:13px;font-size:16px;font-weight:600}
button[disabled]{opacity:.5}
.msg{min-height:20px;font-size:13px;margin-top:4px}
.err{color:#f87171}.ok{color:#4ade80}
.card{background:#141414;border:1px solid #2a2a2a;border-radius:12px;padding:14px;margin-top:16px}
.card p{font-size:13px}
details{margin-top:28px}
summary{font-size:12px;color:#737373}
details input{font-size:14px;letter-spacing:0;text-align:left}
[hidden]{display:none!important}
</style></head>
<body data-mode="{mode}" data-idle="{idle}">
<main>
<section id="pair-view">
<h1>IVE</h1>
<p class="sub">Connect this phone to IVE on your Mac.</p>
<form id="pair-form" autocomplete="off">
<label for="code">Pairing code</label>
<input id="code" name="code" inputmode="text" autocapitalize="characters" autocomplete="one-time-code"
 spellcheck="false" maxlength="12" placeholder="XXXX-XXXX" required>
<button id="pair-btn" type="submit">Connect</button>
<div id="pair-msg" class="msg" role="status"></div>
</form>
<div class="card"><p>On the Mac: Settings, then <b>iPhone &amp; Devices</b>, then <b>Show pairing code</b>. Scan the QR code or type the code shown there.</p></div>
<details><summary>Use the access token instead</summary>
<form method="POST" action="/auth">
<input type="password" name="token" placeholder="Access token" autocomplete="off">
<button type="submit">Sign in</button>
</form></details>
</section>
<section id="done-view" hidden>
<h1>Connected</h1>
<p class="sub" id="done-label">This phone is now paired with your Mac.</p>
<div class="card" id="ios-hint" hidden>
<p><b>For notifications:</b> tap the Share button, then <b>Add to Home Screen</b>, and open IVE from there (iOS 16.4 or newer). If the Home Screen app asks for a code, create a new one on the Mac.</p>
</div>
<button id="open-btn" type="button" style="width:100%;margin-top:16px">Open IVE</button>
</section>
<section id="unlock-view" hidden>
<h1>IVE is locked</h1>
<p class="sub">Enter the PIN you set on the Mac.</p>
<form id="unlock-form" autocomplete="off">
<label for="pin">PIN</label>
<input id="pin" name="pin" type="password" inputmode="numeric" pattern="[0-9]*" maxlength="12" required>
<button id="unlock-btn" type="submit">Unlock</button>
<div id="unlock-msg" class="msg" role="status"></div>
</form>
</section>
</main>
<script src="/pair.js"></script>
</body></html>"""


_PAIR_JS = r"""(function () {
  var body = document.body
  var $ = function (id) { return document.getElementById(id) }
  var standalone = (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) || window.navigator.standalone === true
  var ios = /iPad|iPhone|iPod/.test(navigator.userAgent)
  function show(id) {
    ['pair-view', 'done-view', 'unlock-view'].forEach(function (v) { $(v).hidden = v !== id })
  }
  function post(url, data) {
    return fetch(url, {
      method: 'POST', credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    }).then(function (res) {
      return res.json().catch(function () { return {} }).then(function (json) { return { status: res.status, json: json } })
    })
  }
  if (body.getAttribute('data-mode') === 'unlock') {
    show('unlock-view')
    $('unlock-form').addEventListener('submit', function (e) {
      e.preventDefault()
      var msg = $('unlock-msg'); msg.className = 'msg'; msg.textContent = ''
      $('unlock-btn').disabled = true
      post('/api/phone/unlock', { pin: $('pin').value }).then(function (r) {
        $('unlock-btn').disabled = false
        if (r.status === 200) { location.reload(); return }
        msg.className = 'msg err'
        if (r.status === 429) msg.textContent = 'Too many attempts. Wait a minute.'
        else if (r.json.error === 'revoked') msg.textContent = r.json.message
        else msg.textContent = 'Wrong PIN' + (r.json.attempts_left ? ' (' + r.json.attempts_left + ' tries left)' : '')
        $('pin').value = ''
      }, function () { $('unlock-btn').disabled = false; msg.className = 'msg err'; msg.textContent = 'Mac not reachable.' })
    })
    return
  }
  show('pair-view')
  var label = ios ? (/iPad/.test(navigator.userAgent) ? 'iPad' : 'iPhone') : ''
  function pair(code) {
    var msg = $('pair-msg'); msg.className = 'msg'; msg.textContent = 'Connecting…'
    $('pair-btn').disabled = true
    post('/api/phone/pair/complete', { code: code, label: label }).then(function (r) {
      $('pair-btn').disabled = false
      if (r.status === 200) {
        if (standalone) { location.replace('/'); return }
        $('done-label').textContent = 'Paired as "' + ((r.json.device && r.json.device.label) || 'Phone') + '". You can revoke it any time on the Mac.'
        $('ios-hint').hidden = !ios
        show('done-view')
        return
      }
      msg.className = 'msg err'
      msg.textContent = r.status === 429 ? 'Too many attempts. Wait a minute.' : (r.json.message || 'Could not connect.')
    }, function () { $('pair-btn').disabled = false; msg.className = 'msg err'; msg.textContent = 'Mac not reachable.' })
  }
  $('open-btn').addEventListener('click', function () { location.replace('/') })
  $('pair-form').addEventListener('submit', function (e) { e.preventDefault(); pair($('code').value) })
  var fromLink = (location.hash || '').replace(/^#/, '')
  if (fromLink) {
    history.replaceState(null, '', location.pathname)
    $('code').value = fromLink
    pair(fromLink)
  }
})()
"""


def _connect_page(*, status: int = 200, mode: str = "pair") -> web.Response:
    html = (
        _CONNECT_HTML
        .replace("{mode}", "unlock" if mode == "unlock" else "pair")
        .replace("{idle}", str(_phone_access.lock.idle_seconds() // 60))
    )
    return web.Response(
        status=status, content_type="text/html", text=html,
        headers={"Cache-Control": "no-store"},
    )


async def phone_connect_page_handler(request: web.Request) -> web.Response:
    """GET /pair — the connect page (also what an unpaired phone sees)."""
    return _connect_page()


async def phone_pair_js_handler(request: web.Request) -> web.Response:
    return web.Response(
        text=_PAIR_JS, content_type="application/javascript",
        headers={"Cache-Control": "no-store"},
    )


# ─── Cloudflare-tunnel-aware preview proxy ──────────────────────────────
# Forwards `GET /preview/<port>/<path>` to `http://127.0.0.1:<port>/<path>` so
# tunnel/multiplayer collaborators can view localhost dev servers running on
# the host. HTML responses get a `<base href>` injected so root-relative
# assets resolve under the `/preview/<port>/` prefix.

_PREVIEW_PROXY_DENY_PORTS = {
    5111,   # backend default port
    PORT,   # backend itself (COMMANDER_PORT may differ from the default)
    5173,   # Vite dev server (frontend)
    22,     # ssh
    3306,   # MySQL
    5432,   # PostgreSQL
    6379,   # Redis
    27017,  # MongoDB
}
_PREVIEW_PROXY_TIMEOUT = 30  # seconds, applied per upstream request
# Headers that should not be relayed upstream — hop-by-hop and tunnel artifacts.
_PREVIEW_PROXY_STRIP_REQ_HEADERS = {
    "host", "connection", "keep-alive", "proxy-authenticate",
    "proxy-authorization", "te", "trailers", "transfer-encoding", "upgrade",
}
# Response headers we drop because aiohttp's StreamResponse manages framing,
# OR because they would block embedding the proxied dev server in IVE's
# same-origin iframe (LivePreview). The CSP middleware also force-overwrites
# the security headers on /preview/* paths, but stripping at the proxy
# level keeps the response object clean so a downstream handler doesn't
# accidentally read the upstream values.
_PREVIEW_PROXY_STRIP_RESP_HEADERS = {
    "content-length", "content-encoding", "transfer-encoding", "connection",
    "keep-alive",
    "x-frame-options",
    "content-security-policy",
    "content-security-policy-report-only",
}


def _preview_port_allowed(port: int) -> bool:
    if port < 1024 or port > 65535:
        return False
    if port in _PREVIEW_PROXY_DENY_PORTS:
        return False
    return True


async def proxy_localhost(request: web.Request) -> web.StreamResponse:
    """Reverse-proxy a request to `127.0.0.1:<port>/<path>`.

    Streams the upstream response back so SSE / large assets work. For
    `text/html` responses a `<base href="/preview/<port>/">` tag is injected
    so root-relative URLs resolve back through the proxy.
    """
    # Live-gated on the runtime flags so toggling tunnel/multiplayer at
    # runtime actually opens up the preview proxy without restart. The
    # disabled-mode handler is still mounted as a fallback when neither
    # tunnel nor multiplayer was set at boot AND no client session has
    # one — see route registration below.
    if not (_TUNNEL_MODE or _MULTIPLAYER_MODE):
        return web.json_response(
            {
                "error": "preview proxy is disabled — enable tunnel or multiplayer "
                         "from Settings → Tunnel & Multiplayer first",
            },
            status=403,
        )
    port_str = request.match_info.get("port", "")
    try:
        port = int(port_str)
    except ValueError:
        return web.json_response({"error": "invalid port"}, status=400)
    if not _preview_port_allowed(port):
        return web.json_response(
            {"error": f"port {port} is not allowed by the preview proxy"},
            status=403,
        )

    path = request.match_info.get("path", "")
    upstream_path = "/" + path if path else "/"

    # Build upstream URL — explicitly hard-pinned to 127.0.0.1, never an
    # arbitrary host. Preserve query string verbatim.
    upstream_url = f"http://127.0.0.1:{port}{upstream_path}"
    if request.query_string:
        upstream_url = f"{upstream_url}?{request.query_string}"

    # WebSocket upgrade → return 501 for now. Bidirectional WS pumping is
    # tracked as a TODO; the HTML/HTTP path is the priority and most dev
    # servers (Vite, Next.js) gracefully degrade without the WS channel.
    if request.headers.get("Upgrade", "").lower() == "websocket":
        return web.json_response(
            {"error": "websocket proxying not yet implemented"},
            status=501,
        )

    # Build upstream headers: drop hop-by-hop, Cloudflare tunnel artifacts,
    # and pin Host to the loopback target so virtual-hosted upstreams see
    # the right name.
    upstream_headers: dict[str, str] = {}
    for name, value in request.headers.items():
        lname = name.lower()
        if lname in _PREVIEW_PROXY_STRIP_REQ_HEADERS:
            continue
        if lname.startswith("cf-"):
            continue
        upstream_headers[name] = value
    upstream_headers["Host"] = f"127.0.0.1:{port}"

    session: aiohttp.ClientSession = request.app.get("preview_proxy_session")
    if session is None:
        # Lazily create the upstream session — it's only built at startup
        # when --tunnel/--multiplayer was set at boot, but a runtime toggle
        # can flip the flags later. Build on first preview request so that
        # works without a server restart.
        session = aiohttp.ClientSession(
            timeout=aiohttp.ClientTimeout(total=_PREVIEW_PROXY_TIMEOUT),
            auto_decompress=False,
        )
        request.app["preview_proxy_session"] = session

    # Stream the request body so large uploads don't buffer in memory.
    has_body = request.method not in {"GET", "HEAD", "OPTIONS"}
    body = request.content if has_body else None
    timeout = aiohttp.ClientTimeout(total=_PREVIEW_PROXY_TIMEOUT)

    try:
        upstream = await session.request(
            request.method,
            upstream_url,
            headers=upstream_headers,
            data=body,
            allow_redirects=False,
            timeout=timeout,
        )
    except (aiohttp.ClientConnectorError, aiohttp.ServerDisconnectedError,
            aiohttp.ClientOSError, asyncio.TimeoutError) as e:
        return web.json_response(
            {"error": "upstream connection failed",
             "detail": str(e), "port": port},
            status=502,
        )
    except aiohttp.ClientError as e:
        return web.json_response(
            {"error": "upstream request failed",
             "detail": str(e), "port": port},
            status=502,
        )

    try:
        content_type = (upstream.headers.get("Content-Type") or "").lower()
        is_html = content_type.startswith("text/html")

        # ── Text/HTML branch — buffer + rewrite ──────────────────────
        # We need the full body to inject <base href> reliably, so for HTML
        # we read it eagerly. Streaming would be possible but the rewrite
        # is fragile if <head> spans chunk boundaries.
        if is_html:
            try:
                raw = await upstream.read()
            except (aiohttp.ClientError, asyncio.TimeoutError) as e:
                return web.json_response(
                    {"error": "upstream read failed",
                     "detail": str(e), "port": port},
                    status=502,
                )

            base_tag = f'<base href="/preview/{port}/">'.encode()
            # Inject right after opening <head> tag (case-insensitive). Fall
            # back to "before the first '<' in body" if no <head> found —
            # tolerates fragments and stripped-down html.
            head_match = _re.search(rb"<head[^>]*>", raw, _re.IGNORECASE)
            if head_match:
                idx = head_match.end()
                rewritten = raw[:idx] + base_tag + raw[idx:]
            else:
                first_lt = raw.find(b"<")
                if first_lt >= 0:
                    rewritten = raw[:first_lt] + base_tag + raw[first_lt:]
                else:
                    rewritten = base_tag + raw

            resp = web.StreamResponse(status=upstream.status)
            for name, value in upstream.headers.items():
                if name.lower() in _PREVIEW_PROXY_STRIP_RESP_HEADERS:
                    continue
                resp.headers[name] = value
            resp.content_length = len(rewritten)
            await resp.prepare(request)
            await resp.write(rewritten)
            await resp.write_eof()
            return resp

        # ── Streaming pass-through for everything else ───────────────
        resp = web.StreamResponse(status=upstream.status)
        for name, value in upstream.headers.items():
            if name.lower() in _PREVIEW_PROXY_STRIP_RESP_HEADERS:
                continue
            resp.headers[name] = value
        # SSE / chunked: don't set Content-Length, let aiohttp chunk-encode.
        await resp.prepare(request)
        try:
            async for chunk in upstream.content.iter_any():
                if not chunk:
                    continue
                await resp.write(chunk)
        except (aiohttp.ClientError, asyncio.TimeoutError) as e:
            logger.debug("preview proxy stream interrupted (port %s): %s", port, e)
        await resp.write_eof()
        return resp
    finally:
        upstream.release()


async def proxy_localhost_disabled(request: web.Request) -> web.Response:
    """Stub used in single-player local mode — preview proxy is unnecessary
    because collaborators always reach localhost directly."""
    return web.json_response(
        {"error": "preview proxy is only available in --tunnel or "
                  "--multiplayer mode"},
        status=404,
    )


def _auth_failure_hint(cli_type: str) -> str:
    cli = (cli_type or "claude").lower()
    return (
        f"{cli.capitalize()} login expired. Recover it here: restart / re-sync, "
        "attach a verified stored account, or log in a new account in an isolated browser."
    )


def _is_auth_recovery_input(raw: str) -> bool:
    """Recognize the login command the message composer cannot execute as a TUI."""
    return raw.strip().lower() == "/login"


async def _broadcast_auth_recovery(
    session_id: str,
    cli_type: str,
    *,
    intercepted_login: bool = False,
) -> None:
    hint = _auth_failure_hint(cli_type)
    if intercepted_login:
        hint = (
            "`/login` in IVE's message box is not a CLI TUI command. "
            "Use these in-product recovery actions instead."
        )
    await broadcast({
        "type": "auth_failed",
        "session_id": session_id,
        "cli": cli_type,
        "hint": hint,
        "message": hint,
        "intercepted_login": intercepted_login,
    })


async def _handle_auth_failed_capture(session_id: str, capture: dict) -> None:
    """Pause only on verified live evidence, never on terminal replay."""
    if capture.get("evidence_source") != "verified_live_auth":
        return
    row: dict = {}
    db = None
    try:
        db = await get_db()
        cur = await db.execute(
            "SELECT s.account_id, s.cli_type, a.type AS acct_type, a.name AS acct_name "
            "FROM sessions s LEFT JOIN accounts a ON s.account_id = a.id WHERE s.id = ?",
            (session_id,),
        )
        found = await cur.fetchone()
        row = dict(found) if found else {}
        await db.execute(
            "UPDATE sessions SET status = 'auth_failed' WHERE id = ?",
            (session_id,),
        )
        if row.get("account_id"):
            await db.execute(
                "UPDATE accounts SET status = 'auth_failed' WHERE id = ?",
                (row["account_id"],),
            )
        await db.commit()
    except Exception:
        # Stopping the retry storm and notifying the user remain essential even
        # if state persistence is temporarily unavailable.
        logger.exception("Could not persist auth_failed state for session %s", session_id)
    finally:
        if db is not None:
            await db.close()

    cli_type = str(
        row.get("cli_type") or _session_cli_type_cache.get(session_id) or "claude"
    ).lower()

    # Reuse the normal PTY stop path (SIGINT -> SIGTERM -> SIGKILL). Wait for
    # its public liveness signal so an immediately-clicked Restart cannot race
    # the dying process and merely replay its stale terminal buffer.
    try:
        await _stop_session_expected(session_id)
        for _ in range(60):
            if not pty_mgr.is_alive(session_id):
                break
            await _asyncio.sleep(0.1)
    except Exception:
        logger.exception("Could not stop auth-failed session %s", session_id)

    await _broadcast_auth_recovery(session_id, cli_type)

    # Preserve the existing optional OAuth-account self-heal. Host-login
    # sessions have no account row; restarting launches the CLI with its normal
    # host credential lookup through _prepare_session_cli_env instead.
    if extension_host.available("anyuse") and row.get("account_id") and row.get("acct_type") == "oauth":
        try:
            from auth_cycler import (
                auth_cycler as _ac,
                _is_feature_enabled as _feature_enabled,
            )
            if await _feature_enabled() and _ac.has_browser_context(row["account_id"]):
                asyncio.create_task(_ac.anyuse_auth(
                    row["account_id"],
                    cli_type=cli_type,
                    headless=True,
                ))
        except Exception as exc:
            logger.error("auth_failed reauth kick failed: %s", exc)


async def _clear_auth_failed_session_state(session_id: str) -> None:
    """Clear the blocking session state after a replacement PTY is spawned."""
    db = None
    try:
        db = await get_db()
        await db.execute(
            "UPDATE sessions SET status = 'idle' WHERE id = ? AND status = 'auth_failed'",
            (session_id,),
        )
        await db.commit()
    except Exception:
        logger.exception("Could not clear auth_failed state after spawning %s", session_id)
    finally:
        if db is not None:
            await db.close()


async def on_startup(app: web.Application):
    global _server_stopping
    _server_stopping = False
    # Fail before opening the service if an enum, producer, consumer, dispatch
    # mode, or payload declaration has drifted outside the central event contract.
    from event_registry import validate_registry
    validate_registry()
    # Browser-facing bus events reuse broadcast()'s workspace/session scoping.
    bus.set_client_sink(_broadcast_commander_event)

    # Shared aiohttp session for the preview proxy. Only created when the
    # proxy is actually mounted, but we always assign to keep handler code
    # simple.
    if _TUNNEL_MODE or _MULTIPLAYER_MODE:
        app["preview_proxy_session"] = aiohttp.ClientSession(
            timeout=aiohttp.ClientTimeout(total=_PREVIEW_PROXY_TIMEOUT),
            auto_decompress=False,  # passthrough compressed bytes
        )

    await init_db()
    try:
        _qs_db = await get_db()
        try:
            await _quick_start.load_cache(_qs_db)
        finally:
            await _qs_db.close()
    except Exception as exc:
        logger.warning("Quick start state could not be loaded: %s", exc)
    from hooks import refresh_profile_hook_bindings
    refresh_profile_hook_bindings()

    # Deliberately resolve without inserting a row: operators can see that an
    # absent key now means propose, and the startup log makes the rollout clear.
    db_precedent = await get_db()
    try:
        from safety_precedent import resolve_safety_precedent_mode
        mode_rows = await db_precedent.execute_fetchall(
            "SELECT value FROM app_settings WHERE key = 'safety_precedent_mode'"
        )
        raw_precedent_mode = mode_rows[0]["value"] if mode_rows else None
        resolved_precedent_mode = resolve_safety_precedent_mode(raw_precedent_mode)
        mode_source = "configured" if raw_precedent_mode == resolved_precedent_mode else "default; key absent or invalid"
        logger.info(
            "Safety precedent mode resolved: %s (%s; app setting safety_precedent_mode)",
            resolved_precedent_mode,
            mode_source,
        )
    finally:
        await db_precedent.close()

    # The hard-deny tier is mandatory, not experimental.  Reconcile its durable
    # projection on every boot and abort startup if it cannot be loaded exactly.
    db_seed = await get_db()
    try:
        from safety_engine import seed_builtin_rules, validate_required_rules

        await seed_builtin_rules(db_seed)
        await validate_required_rules(db_seed)
    except Exception:
        logger.exception("Mandatory safety rules failed to initialize")
        raise
    finally:
        await db_seed.close()

    # AVCP (IVE's supply-chain guard) edits the user's shell rc files, so it is
    # opt-in: keep its block only while the setting is on, and remove a block
    # this installation wrote earlier when it is off. Best-effort; never blocks boot.
    try:
        from avcp_installer import install_avcp, uninstall_avcp, avcp_status
        db_avcp = await get_db()
        try:
            cur_avcp = await db_avcp.execute(
                "SELECT value FROM app_settings WHERE key = 'experimental_avcp_protection'"
            )
            avcp_row = await cur_avcp.fetchone()
        finally:
            await db_avcp.close()
        if avcp_row and avcp_row["value"] == "on":
            if not avcp_status()["installed_in"]:
                logger.info("AVCP: installing shell guard -> %s", install_avcp().get("installed"))
        else:
            removed = uninstall_avcp(only_this_install=True)["removed"]
            if removed:
                logger.info("AVCP: removed shell guard from %s (setting is off)", removed)
    except Exception:
        logger.exception("AVCP startup check failed (non-fatal)")

    # WS-5: periodically reap orphaned session-sandbox containers (a session that died but left its
    # `ive-sess-*` container). Conservative — only reaps containers whose session_id is absent from
    # the sessions table. Best-effort loop; no-op without the `container` CLI.
    async def _container_reconcile_loop():
        async def _live_ids():
            rdb = await get_db()
            try:
                cur = await rdb.execute("SELECT id FROM sessions")
                return [r["id"] for r in await cur.fetchall()]
            finally:
                await rdb.close()

        while True:
            if extension_host.available("sandbox"):
                try:
                    from container_registry import reconcile
                    res = await reconcile(_live_ids)
                    if res.get("reaped"):
                        logger.info("WS-5 container reconcile: %s", res)
                except Exception:
                    logger.debug("container reconcile pass failed", exc_info=True)
            # Secure runs: reap orphaned ive-secure-* nets+containers whose session is gone.
            # A secure run_id == its session_id, so the live session set is the live run set.
            if extension_host.edition() == "integrated-dev":
                try:
                    import secure_net
                    sres = await secure_net.reap_orphans(await _live_ids())
                    if sres.get("reaped"):
                        logger.info("Secure reconcile: reaped %s", sres["reaped"])
                except Exception:
                    logger.debug("secure reconcile pass failed", exc_info=True)
            await asyncio.sleep(600)

    if extension_host.available("sandbox") or extension_host.edition() == "integrated-dev":
        app["_container_reconcile_task"] = asyncio.create_task(_container_reconcile_loop())

    if extension_host.available("company"):
        await _company_start_services(app)

    # Hydrate os.environ with DB-stored API keys so in-process code that
    # reads env vars directly (peer_comms _build_workspace, ticket/knowledge
    # indexers, model libs) honors keys configured in the IVE settings UI
    # without each module having to call api_keys.resolve itself.
    try:
        import api_keys as _api_keys_startup
        env_overrides = await _api_keys_startup.resolve_env_overrides()
        for _k, _v in env_overrides.items():
            os.environ[_k] = _v
        if env_overrides:
            logger.info(
                "Hydrated %d API key(s) from app_settings into os.environ",
                len(env_overrides),
            )
    except Exception as e:
        logger.debug("API-key env hydration skipped: %s", e)

    pty_mgr.on_output(handle_pty_output)
    pty_mgr.on_output(capture_proc.process)
    pty_mgr.on_exit(handle_pty_exit)
    pty_mgr.on_input_error(handle_pty_input_error)

    # ── Dynamic model discovery ────────────────────────────────────
    global _discovered_models
    try:
        from model_discovery import (
            apply_codex_discovery, discover_all, discover_codex_default_model,
            discover_codex_models,
        )
        _discovered_models = await _asyncio.to_thread(discover_all)
        from cli_profiles import PROFILES
        for cli, models in _discovered_models.items():
            if models:
                logger.info("Discovered %d %s models dynamically", len(models), cli)
                if cli in PROFILES:
                    PROFILES[cli].available_models = models
        codex_default = await _asyncio.to_thread(discover_codex_default_model)
        codex_models = await _asyncio.to_thread(discover_codex_models)
        if "codex" in PROFILES:
            apply_codex_discovery(PROFILES["codex"], codex_models, codex_default)
            if codex_models:
                logger.info("Discovered %d Codex models from models_cache.json", len(codex_models))
        if codex_default and "codex" in PROFILES:
            logger.info("Resolved Codex default model from config: %s", codex_default)
            await _backfill_codex_default_model(codex_default)
    except Exception as e:
        logger.debug("Model discovery skipped: %s", e)

    asyncio.create_task(_ensure_commanders_for_all_workspaces())
    asyncio.create_task(_ensure_worker_board_for_all_workers())

    # ── CLI lifecycle hooks ──────────────────────────────────────────
    # The global lifecycle-hook switch may disable telemetry/capture hooks, but
    # it cannot disable the code-owned hard-deny boundary.
    from hook_installer import install_safety_gate_hooks
    install_safety_gate_hooks()

    from config import HOOKS_ENABLED
    if HOOKS_ENABLED:
        from hooks import set_broadcast_fn, set_capture_proc, set_pty_manager as hooks_set_pty
        from hook_installer import install_all
        set_broadcast_fn(broadcast)
        set_capture_proc(capture_proc)
        hooks_set_pty(pty_mgr)
        install_all()
        logger.info("CLI hooks installed and receiver ready")

        try:
            db_hooks = await get_db()
            try:
                cur_hooks = await db_hooks.execute(
                    "SELECT key, value FROM app_settings "
                    "WHERE key IN ('experimental_avcp_protection', 'experimental_safety_gate')"
                )
                hook_flags = {row["key"]: row["value"] for row in await cur_hooks.fetchall()}
            finally:
                await db_hooks.close()

            from hook_installer import install_avcp_hooks, uninstall_avcp_hooks
            if hook_flags.get("experimental_avcp_protection") == "on":
                install_avcp_hooks()
            else:
                uninstall_avcp_hooks()
        except Exception as e:
            logger.debug("Optional hook refresh skipped/failed: %s", e)

        try:
            from antigravity_runtime import ensure_mcp_config_valid as _ensure_agy_mcp_current
            _ensure_agy_mcp_current()
        except Exception as e:
            logger.debug("Antigravity MCP config refresh skipped/failed: %s", e)

    # ── Server-side cascade runner ──────────────────────────────────
    import cascade_runner
    cascade_runner.set_pty_manager(pty_mgr)
    cascade_runner.set_broadcast_fn(broadcast)
    await cascade_runner.recover_active_runs()
    logger.info("Cascade runner initialized")

    # ── Auto-exec: event-driven task dispatch ────────────────────────
    import auto_exec
    auto_exec.set_pty_manager(pty_mgr)
    auto_exec.set_broadcast_fn(broadcast)
    auto_exec.register_subscribers()

    if extension_host.edition() == "integrated-dev":
        # Independent research reviewer: annotate completed research with a novelty/
        # quality/gaps critique (annotate-only, runs detached). Subscribe before the
        # reconciliation below so it's live for any real completions that follow.
        bus.subscribe(CommanderEvent.RESEARCH_COMPLETED, _research_critic_on_completed)

        # Backstop: a previous process may have died mid-research, leaving entries
        # 'in_progress' and any task parked on them stranded. Fail those orphans now
        # (subscribers are registered above, so the un-park handler will fire).
        try:
            await _reconcile_orphaned_research()
        except Exception:
            logger.exception("orphaned-research reconciliation failed")

    # ── Worker queue: per-worker task auto-delivery ────────────────
    import worker_queue
    worker_queue.set_pty_manager(pty_mgr)
    worker_queue.set_broadcast_fn(broadcast)
    worker_queue.register_subscribers()

    # Ordinary idle notes/digests are IVE-owned. Installed products contribute
    # richer prompt bullets, but the hook-driven scheduler must work without them.
    import idle_reflection
    idle_reflection.set_pty_manager(pty_mgr)
    idle_reflection.set_broadcast_fn(broadcast)
    idle_reflection.register_subscribers()

    if extension_host.available("myelin"):
        await _myelin_start_indexes(app)

    if extension_host.available("forge"):
        await _forge_start_indexing(app)

    if extension_host.available("myelin"):
        await _myelin_start_fts(app)

    if extension_host.available("swarmlock"):
        await _swarmlock_start_hooks(app)

    if extension_host.edition() == "integrated-dev":
        # IVE-owned local task bookkeeping; no code graph is required.
        import board_doc_backstop
        board_doc_backstop.set_broadcast_fn(broadcast)
        await board_doc_backstop.start(app)
        app.on_cleanup.append(board_doc_backstop.stop)

    if extension_host.edition() == "integrated-dev":
        # ── Pipeline: implement → test → document loop ──────────────────
        import pipeline
        pipeline.set_pty_manager(pty_mgr)
        pipeline.set_broadcast_fn(broadcast)
        pipeline.set_pty_start_fn(_autostart_session_pty)
        pipeline.register_subscribers()

        # ── Pipeline Engine: configurable graph-based pipelines ──────────
        import pipeline_engine
        pipeline_engine.set_pty_manager(pty_mgr)
        pipeline_engine.set_broadcast_fn(broadcast)
        pipeline_engine.set_pty_start_fn(_autostart_session_pty)
        pipeline_engine.set_input_ready_fn(_wait_for_cli_input_ready)
        pipeline_engine.set_output_buffer_fn(capture_proc.get_buffer)
        pipeline_engine.register_subscribers()
        await pipeline_engine.ensure_presets()
        await pipeline_engine.recover_active_runs()

    # ── Demo runner: per-workspace stable preview build ─────────────
    _demo_runner.set_broadcast_fn(broadcast)

    if extension_host.edition() == "integrated-dev":
        # ── Research scheduler (cron-like recurring research) ───────────
        global _research_scheduler_task
        _research_scheduler_task = _asyncio.ensure_future(_research_scheduler_loop())
        logger.info("Research scheduler started")

    # ── Telemetry (anonymous startup + daily heartbeat) ─────────────
    import telemetry
    telemetry.start_background()

    # ── Session supervisor: PTY health monitor + auto-restart ───────
    import session_supervisor
    session_supervisor.set_pty_manager(pty_mgr)
    # Every spawn path shares one assembly — including restarts.
    _install_supervisor_spawn_hook()
    await session_supervisor.start(app)
    app.on_cleanup.append(session_supervisor.stop)

    if extension_host.available("company"):
        await _company_start_watcher(app)

    if extension_host.available("myelin"):
        await _myelin_start_learning(app)

    async def store_and_broadcast_capture(session_id: str, capture: dict):
        """Store capture in DB and broadcast via WebSocket."""
        db = await get_db()
        try:
            await db.execute(
                """INSERT INTO output_captures (session_id, capture_type, tool_name, raw_text, status)
                   VALUES (?, ?, ?, ?, ?)""",
                (session_id, capture.get("capture_type"), capture.get("tool_name"),
                 capture.get("raw_text"), capture.get("status", "pending")),
            )
            await db.commit()
        finally:
            await db.close()
        await broadcast({
            "type": "capture",
            "session_id": session_id,
            "capture": capture,
        })

        # Context-low pre-warning → dedicated event for the UI indicator.
        # Fired by output_capture when "Context left until auto-compact: N%"
        # crosses the warn threshold. Drives the same yellow/orange tab
        # indicator system as PreCompact/PostCompact hooks.
        if capture.get("capture_type") == "context_low":
            await broadcast({
                "type": "context_low",
                "session_id": session_id,
                "percent_left": capture.get("percent_left"),
            })

        if capture.get("capture_type") == "quota_suspected":
            await broadcast({
                "type": "quota_suspected",
                "session_id": session_id,
                "message": capture.get("raw_text", "Possible quota limit"),
                "reset_unix": capture.get("reset_unix"),
                "requires_operator_confirmation": True,
            })

        # Only independently verified live auth evidence can pause a session.
        # output_capture emits auth_suspected diagnostics for terminal text.
        if capture.get("capture_type") == "auth_failed":
            await _handle_auth_failed_capture(session_id, capture)

    capture_proc.on_capture(store_and_broadcast_capture)

    # Tighten permissions on secret-bearing data dirs (0700) — unconditional,
    # best-effort. See crypto.secure_data_dirs.
    try:
        import crypto
        crypto.secure_data_dirs()
    except Exception:
        logger.debug("secure_data_dirs failed", exc_info=True)

    if extension_host.edition() == "integrated-dev":
        # ── Observatory: automated ecosystem scanner ─────────────────────
        import observatory
        await observatory.scheduler.start()
        app["_observatory_started"] = True

    logger.info(f"IVE v{VERSION} backend on http://{_BIND_HOST or HOST}:{_BIND_PORT or PORT}")


async def _stop_all_ptys_expected() -> None:
    """Stop every PTY as an IVE-requested stop, never as a crash.

    A normal shutdown signals each CLI (exit code -1). Without the expected
    mark the exit handler classified every one of them as a crash: status
    'error', a "Session error" attention item per session and a crash log
    line each. Stopped this way they come back as ordinary idle sessions the
    next start resumes (``--resume`` via native_session_id).
    """
    import session_supervisor
    for session_id in pty_mgr.session_ids():
        session_supervisor.expect_exit(session_id)
    await pty_mgr.stop_all()


async def on_shutdown(app: web.Application):
    """Graceful shutdown, before aiohttp waits for open request handlers.

    The listener is already closed here. Open WebSockets would keep their
    handlers (and the "connected" state in every browser tab) alive until
    aiohttp's shutdown timeout, with the PTYs only killed at the very end.
    Close them first so tabs switch to reconnecting at once, then stop the
    PTYs without auto-restart or crash bookkeeping.
    """
    global _server_stopping
    _server_stopping = True
    import session_supervisor
    try:
        await session_supervisor.stop(app)
    except Exception:
        logger.debug("supervisor stop on shutdown failed", exc_info=True)
    clients = list(ws_clients)
    if clients:
        await asyncio.gather(
            *(
                asyncio.wait_for(
                    ws.close(code=aiohttp.WSCloseCode.GOING_AWAY, message=b"server shutdown"),
                    timeout=2,
                )
                for ws in clients
            ),
            return_exceptions=True,
        )
    await _stop_all_ptys_expected()
    await _settle_background_tasks()


async def on_cleanup(app: web.Application):
    await _stop_all_ptys_expected()
    reconcile_task = app.get("_container_reconcile_task")
    if reconcile_task is not None:
        reconcile_task.cancel()
        try:
            await reconcile_task
        except asyncio.CancelledError:
            pass
    if app.get("_observatory_started"):
        try:
            import observatory
            await observatory.scheduler.stop()
        except Exception:
            pass
    try:
        import preview_browser
        await preview_browser.shutdown()
    except Exception:
        pass
    try:
        await _demo_runner.shutdown_all()
    except Exception:
        pass
    proxy_session = app.get("preview_proxy_session")
    if proxy_session is not None:
        try:
            await proxy_session.close()
        except Exception:
            pass
    for ws in list(ws_clients):
        await ws.close()


# ─── REST: Agent Skills ───────────────────────────────────────────────────

async def list_agent_skills(request: web.Request) -> web.Response:
    """List available skills from the Agent Skills ecosystem."""
    from skills_client import fetch_skills_index
    skills = await fetch_skills_index()
    # Strip full content from index (keep it lightweight)
    return web.json_response([
        {k: v for k, v in s.items() if k != "content"} for s in skills
    ])


async def get_agent_skill(request: web.Request) -> web.Response:
    """Get a single skill's full content."""
    skill_path = request.match_info["path"]
    repo = request.query.get("repo", "anthropics/skills")
    from skills_client import fetch_skill_content
    skill = await fetch_skill_content(skill_path, repo=repo)
    if not skill:
        return web.json_response({"error": "skill not found"}, status=404)
    return web.json_response(skill)


async def install_agent_skill(request: web.Request) -> web.Response:
    """Install a skill to disk for native CLI discovery."""
    from skill_installer import install_skill
    body = await request.json()
    name = body.get("name", "").strip()
    content = body.get("content", "").strip()
    if not name or not content:
        return web.json_response({"error": "name and content required"}, status=400)

    # Determine workspace path from query or body
    workspace_path = body.get("workspace_path")
    if not workspace_path:
        # Try to get from active workspace
        ws_id = body.get("workspace_id")
        if ws_id:
            db = await get_db()
            try:
                cur = await db.execute("SELECT path FROM workspaces WHERE id = ?", (ws_id,))
                row = await cur.fetchone()
                if row:
                    workspace_path = row["path"]
            finally:
                await db.close()

    requested_cli_types = body.get("cli_types")
    if requested_cli_types is None:
        requested_cli_types = [profile.id for profile in active_profiles()]
    cli_types = [cli for cli in requested_cli_types if is_active_cli(cli)]
    scope = body.get("scope", "project")

    results = await install_skill(
        name=name,
        content=content,
        workspace_path=workspace_path,
        cli_types=cli_types,
        scope=scope,
        source_url=body.get("source_url", ""),
        repo=body.get("repo", ""),
        skill_path=body.get("skill_path", ""),
    )
    return web.json_response({"ok": True, "results": results}, status=201)


async def uninstall_agent_skill(request: web.Request) -> web.Response:
    """Remove a skill from disk."""
    from skill_installer import uninstall_skill
    body = await request.json()
    name = body.get("name", "").strip()
    if not name:
        return web.json_response({"error": "name required"}, status=400)

    workspace_path = body.get("workspace_path")
    if not workspace_path:
        ws_id = body.get("workspace_id")
        if ws_id:
            db = await get_db()
            try:
                cur = await db.execute("SELECT path FROM workspaces WHERE id = ?", (ws_id,))
                row = await cur.fetchone()
                if row:
                    workspace_path = row["path"]
            finally:
                await db.close()

    requested_cli_types = body.get("cli_types")
    if requested_cli_types is None:
        requested_cli_types = [profile.id for profile in active_profiles()]
    cli_types = [cli for cli in requested_cli_types if is_active_cli(cli)]
    scope = body.get("scope", "project")

    results = await uninstall_skill(
        name=name,
        workspace_path=workspace_path,
        cli_types=cli_types,
        scope=scope,
    )
    return web.json_response({"ok": True, "results": results})


async def list_installed_skills_handler(request: web.Request) -> web.Response:
    """List skills installed on disk for all CLIs."""
    from skill_installer import list_installed_skills

    workspace_path = request.query.get("workspace_path")
    if not workspace_path:
        ws_id = request.query.get("workspace_id")
        if ws_id:
            db = await get_db()
            try:
                cur = await db.execute("SELECT path FROM workspaces WHERE id = ?", (ws_id,))
                row = await cur.fetchone()
                if row:
                    workspace_path = row["path"]
            finally:
                await db.close()

    # Default to "all" so user-scope skills (e.g. installed via /api/skills/install
    # with scope=user) appear without forcing the caller to pass ?scope=user
    # explicitly (BUG H7). Project-scope still requires a workspace_path.
    scope = request.query.get("scope", "all")
    skills = list_installed_skills(workspace_path=workspace_path, scope=scope)
    return web.json_response(skills)


async def sync_agent_skill(request: web.Request) -> web.Response:
    """Sync a skill from one CLI to another."""
    from skill_installer import sync_skill
    body = await request.json()
    name = body.get("name", "").strip()
    from_cli = body.get("from_cli", "").strip()
    to_cli = body.get("to_cli", "").strip()
    if not name or not from_cli or not to_cli:
        return web.json_response({"error": "name, from_cli, to_cli required"}, status=400)

    workspace_path = body.get("workspace_path")
    if not workspace_path:
        ws_id = body.get("workspace_id")
        if ws_id:
            db = await get_db()
            try:
                cur = await db.execute("SELECT path FROM workspaces WHERE id = ?", (ws_id,))
                row = await cur.fetchone()
                if row:
                    workspace_path = row["path"]
            finally:
                await db.close()

    scope = body.get("scope", "project")
    result = await sync_skill(
        name=name, from_cli=from_cli, to_cli=to_cli,
        workspace_path=workspace_path, scope=scope,
    )
    return web.json_response(result)


