async def _log_tool_invocation(
    request: web.Request, tool: str, query: str, result_count: int | None = None
) -> None:
    """Record an agent-originated read-only tool call to tool_invocation_log.

    Gated on X-IVE-Session-Id: only MCP/agent calls carry it, so UI traffic is
    not logged. Read-only pull tools (search_memory) are GETs and thus invisible
    to audit_log; this is the only IVE-side telemetry for them. Best-effort —
    a logging failure must never break the actual search request.
    """
    sid = (request.headers.get("X-IVE-Session-Id") or "").strip()
    if not sid:
        return
    ws_id = (
        request.match_info.get("id")
        or (request.headers.get("X-IVE-Workspace-Id") or "").strip()
        or None
    )
    try:
        db = await get_db()
        try:
            await db.execute(
                "INSERT INTO tool_invocation_log "
                "(workspace_id, session_id, tool, query, result_count) "
                "VALUES (?, ?, ?, ?, ?)",
                (ws_id, sid, tool, (query or "")[:500], result_count),
            )
            await db.commit()
        finally:
            await db.close()
    except Exception:
        logger.debug("tool_invocation_log write failed", exc_info=True)




