# ─── Workflow / sweep run provenance ────────────────────────────────────
async def record_workflow_run(request: web.Request) -> web.Response:
    """Upsert a workflow/sweep provenance record.

    Insert-or-update by `id` so a sweep can POST once at start (status=running)
    and again at completion (status=completed/failed) without racing. Any subset
    of mutable fields may be sent per call; omitted fields are left untouched.
    dict/list values (subagents, params) are JSON-encoded transparently.
    """
    ws_id = request.match_info["id"]
    body = await request.json()
    run_id = (str(body.get("id") or "")).strip() or str(uuid.uuid4())
    session_id = body.get("session_id") or (request.headers.get("X-IVE-Session-Id") or "").strip() or None

    mutable = ("session_id", "kind", "label", "source", "runtime", "status",
               "agents_total", "agents_done", "subagents", "params", "result", "error")

    def _enc(v):
        return json.dumps(v) if isinstance(v, (dict, list)) else v

    db = await get_db()
    try:
        cur = await db.execute("SELECT id FROM workflow_runs WHERE id = ?", (run_id,))
        exists = await cur.fetchone() is not None
        if not exists:
            await db.execute(
                "INSERT INTO workflow_runs (id, workspace_id, session_id) VALUES (?, ?, ?)",
                (run_id, ws_id, session_id),
            )
        sets, vals = [], []
        for f in mutable:
            if f in body:
                sets.append(f"{f} = ?")
                vals.append(_enc(body[f]))
        if body.get("status") in ("completed", "failed", "cancelled"):
            sets.append("completed_at = datetime('now')")
        sets.append("updated_at = datetime('now')")
        vals.append(run_id)
        await db.execute(f"UPDATE workflow_runs SET {', '.join(sets)} WHERE id = ?", vals)
        await db.commit()
        cur = await db.execute("SELECT * FROM workflow_runs WHERE id = ?", (run_id,))
        row = await cur.fetchone()
        return web.json_response(dict(row))
    finally:
        await db.close()


async def list_workflow_runs(request: web.Request) -> web.Response:
    """List recent workflow/sweep runs for a workspace (newest first)."""
    ws_id = request.match_info["id"]
    status = request.query.get("status")
