# ─── REST: Demo runner ─────────────────────────────────────────────────
# Per-workspace long-lived dev server for testers/reviewers. Workers can
# hack freely without restarting it; operators promote new builds via the
# explicit pull-latest action. See backend/demo_runner.py.

import demo_runner as _demo_runner


async def _demo_load_workspace(request: web.Request) -> tuple[str, str] | tuple[None, web.Response]:
    ws_id = request.match_info["id"]
    ws_path = await _get_workspace_path(ws_id)
    if not ws_path:
        return None, web.json_response({"error": "workspace not found"}, status=404)
    return ws_id, ws_path


async def _demo_workspace_settings(workspace_id: str) -> dict:
    """Pull demo_* settings off the workspaces row (best-effort)."""
    db = await get_db()
    try:
        cur = await db.execute(
            "SELECT demo_command, demo_branch, demo_port FROM workspaces WHERE id = ?",
            (workspace_id,),
        )
        row = await cur.fetchone()
        if not row:
            return {}
        return {
            "command": row["demo_command"] or "npm run dev",
            "branch": row["demo_branch"] or "main",
            "port": int(row["demo_port"] or 0),
        }
    except Exception:
        return {}
    finally:
        await db.close()


async def get_demo(request: web.Request) -> web.Response:
    loaded = await _demo_load_workspace(request)
    if loaded[0] is None:
        return loaded[1]
    ws_id, _ws_path = loaded
    info = await _demo_runner.status(ws_id)
    if info is None:
        defaults = await _demo_workspace_settings(ws_id)
        return web.json_response({"workspace_id": ws_id, "status": "stopped", **defaults})
    return web.json_response(info)


async def start_demo(request: web.Request) -> web.Response:
    loaded = await _demo_load_workspace(request)
    if loaded[0] is None:
        return loaded[1]
    ws_id, ws_path = loaded
    body = {}
    try:
        body = await request.json()
    except Exception:
        body = {}
    if not isinstance(body, dict):
        body = {}
    defaults = await _demo_workspace_settings(ws_id)
    branch = body.get("branch") or defaults.get("branch") or "main"
    if not git_ops.is_safe_revision(str(branch)):
        # The branch reaches `git fetch/checkout/pull`; an option-shaped
        # value (e.g. --upload-pack=...) would run arbitrary commands.
        return web.json_response({"error": "invalid branch"}, status=400)
    ctx = request.get("auth")
    if body.get("command") and ctx is not None and not ctx.is_owner and not ctx.is_full:
        # A free-form shell command would bypass the Code-mode Bash allowlist;
        # Code joiners can only run the owner-configured demo command.
        return web.json_response(
            {"error": "Mode not allowed for a custom demo command.", "required": ["full"]},
            status=403,
        )
    command = body.get("command") or defaults.get("command") or "npm run dev"
    port = body.get("port") or defaults.get("port") or None
    if port == 0:
        port = None
    info = await _demo_runner.start(
        workspace_id=ws_id,
        workspace_path=ws_path,
        branch=branch,
        command=command,
        port=port,
    )
    return web.json_response(info)


async def stop_demo(request: web.Request) -> web.Response:
    loaded = await _demo_load_workspace(request)
    if loaded[0] is None:
        return loaded[1]
    ws_id, _ws_path = loaded
    info = await _demo_runner.stop(ws_id)
    return web.json_response(info)


async def pull_latest_demo(request: web.Request) -> web.Response:
    loaded = await _demo_load_workspace(request)
    if loaded[0] is None:
        return loaded[1]
    ws_id, _ws_path = loaded
    info = await _demo_runner.pull_latest(ws_id)
    return web.json_response(info)


async def list_demos(request: web.Request) -> web.Response:
    return web.json_response(await _demo_runner.list_all())


async def get_demo_log(request: web.Request) -> web.Response:
    loaded = await _demo_load_workspace(request)
    if loaded[0] is None:
        return loaded[1]
    ws_id, _ws_path = loaded
    info = await _demo_runner.status(ws_id)
    if info is None:
        return web.json_response({"workspace_id": ws_id, "lines": []})
    return web.json_response({"workspace_id": ws_id, "lines": info.get("build_log_tail", [])})




# Owned source contributions are selected after host services are defined.
def _core_memory_metadata(entries, prompt):
    return json.dumps({"count": len(entries) if entries else 0, "chars": len(prompt)}) if prompt else None


async def _session_memory_prompt(config, session_id, settings, max_chars, compact):
    """Render explicit notes unless an installed memory provider supplies context."""
    if extension_host.available("myelin"):
        context = await _myelin_session_memory(config, session_id, settings, max_chars)
        if context is not None:
            return context
    from memory_manager import memory_manager
    from prompt_context import mirrored_entry_ids
    workspace_id = config.get("workspace_id", "")
    entries = await memory_manager.list_entries(workspace_id=workspace_id)
    prompt = await memory_manager.export_for_prompt(
        workspace_id=workspace_id, max_chars=min(max_chars, 2000), compact=compact,
        mode="index", exclude_ids=mirrored_entry_ids(config, entries),
    )
    return prompt, _core_memory_metadata(entries, prompt)


# Owned source contributions are selected after host services are defined.
# They preserve existing server globals until explicit capability ports replace
# the compatibility bridge. No disabled product source is executed.
extension_host.load_legacy_fragments(globals(), "server")


def create_app() -> web.Application:
    global AUTH_TOKEN
    # There is deliberately no unauthenticated server mode.  Persisting the
    # generated token keeps ordinary single-user startup convenient while the
    # middleware still has a real credential to enforce on non-local callers.
    if not AUTH_TOKEN:
        AUTH_TOKEN = _generate_token()

    from middleware.rate_limiter import rate_limit_middleware
    from middleware.csp import csp_middleware
    from middleware.audit import audit_middleware
    from desktop_security import create_desktop_origin_guard
    # Order matters: correlation outermost, then CORS (so 429s still get CORS
    # headers), then rate-limit (so brute-force attempts at /api/invite/redeem are
    # rejected before token auth even runs), then token auth, then audit
    # (so it sees the resolved AuthContext), then CSP (so headers land
    # on every response that flows back through).
    # token_auth_middleware is always installed and AUTH_TOKEN is always
    # initialized above, including local single-user startup.
    middlewares = [
        correlation_middleware,
        create_desktop_origin_guard(
            _BIND_PORT or PORT,
            get_tunnel_url=lambda: (
                _runtime_tunnel_url
                if _tunnel_proc is not None and _tunnel_proc.returncode is None
                else None
            ),
        ),
        cors_middleware,
        rate_limit_middleware,
        token_auth_middleware,
    ]
    middlewares.append(audit_middleware)
    middlewares.append(csp_middleware)
    app = web.Application(middlewares=middlewares)
    import db as _phone_db
    app[_PHONE_SETUP] = PhoneSetup(_phone_db.DATA_DIR)
    app[_PHONE_AVAILABILITY] = PhoneAvailability(connected=lambda: bool(_tunnel_proc and _tunnel_proc.returncode is None))
    async def _stop_phone_availability(application):
        await application[_PHONE_AVAILABILITY].close()
    app.on_shutdown.append(_stop_phone_availability)
    app.on_startup.append(on_startup)
    app.on_shutdown.append(on_shutdown)
    app.on_cleanup.append(on_cleanup)

    # PR 3: mode-aware route guards. _g(handler, *modes) returns the
    # handler decorated with requires_mode(*modes). Owner-equivalent
    # actors (localhost / owner_legacy / owner_device / hook) bypass.
    import route_guards as _route_guards
    def _g(handler, *modes):
        return _route_guards.requires_mode(*modes)(handler)
    def _owner(handler):
        return _route_guards.owner_only(handler)

    # Trusted optional extensions contribute routes; core auth/mode guards stay
    # mandatory. No external product tree is imported just to enumerate plugins.
    extension_host.register_extensions(app, {
        "resolve_caller": _resolve_caller, "guard": _g,
        "owner_guard": _owner, "legacy_handler": lambda name: globals()[name],
        "get_db": lambda: get_db(),
        "oauth_account_for_auth": lambda *args, **kwargs: _oauth_account_for_auth(*args, **kwargs),
    })
    app.router.add_get("/api/extensions", extension_host.manifest_handler)

    # Visual annotations belong to IVE, including when no graph product is
    # installed. Optional graph products consume these same durable records.
    from canvas_annotations import register_canvas_routes
    register_canvas_routes(app)

    app.router.add_get("/ws", ws_handler)
    app.router.add_get("/ready", ready_handler)

    from sidechat import register_sidechat_routes
    register_sidechat_routes(app, context_reader=_sidechat_session_context)

    # Secure (offensive self-test) agent endpoints — provision/exec/scope/findings/teardown/kill.
    # Secure has not been source-extracted yet. Preserve integrated development
    # without loading the private assessment product in the workspace edition.
    if extension_host.edition() == "integrated-dev":
        from secure_api import register_secure_routes
        register_secure_routes(app)
    # /auth is always mounted — when AUTH_TOKEN is empty, the handler
    # itself short-circuits. Mounting unconditionally lets a runtime
    # tunnel-start (which auto-mints AUTH_TOKEN) immediately accept
    # logins from the public URL.
    app.router.add_post("/auth", auth_login)

    # Invite routes (access overhaul PR 1)
    # Mint + revoke are owner-only — joiners must never escalate themselves.
    # Redeem stays unauth (rate-limited) since the invite token IS the auth.
    app.router.add_post("/api/invite/create", _owner(create_invite_handler))
    app.router.add_get("/api/invites", _owner(list_invites_handler))
    app.router.add_post("/api/invite/{id}/revoke", _owner(revoke_invite_handler))
    app.router.add_post("/api/invite/redeem", redeem_invite_handler)
    app.router.add_get("/join", join_page_handler)
    # PR 2: per-row auth introspection / revocation
    app.router.add_get("/api/whoami", whoami_handler)
    app.router.add_get("/api/sessions/auth", list_auth_sessions_handler)
    app.router.add_post("/api/sessions/auth/{id}/revoke", revoke_auth_session_handler)
    app.router.add_post("/api/auth/logout", logout_handler)
